bool IsLocalPlayerCarryingTurretEntity(EntityId entityId)
{
    if (entityId == INVALID_ENTITYID || !ArkPlayer::GetInstancePtr())
        return false;

    unsigned carriedEntityId = INVALID_ENTITYID;
    return TryGuardedCall(
            "turret local carried entity id",
            []() -> unsigned
            {
                return ArkPlayer::GetInstance().m_interaction.m_playerCarry.m_pickedUpEntityId;
            },
            carriedEntityId,
            nullptr) &&
        carriedEntityId == entityId;
}

bool IsNativeFragmentNodeRange(uint32_t rangeKind)
{
    return
        rangeKind == static_cast<uint32_t>(CoopNativeFragmentPayload::PayloadRangeKind::NodeBlock) ||
        rangeKind == static_cast<uint32_t>(CoopNativeFragmentPayload::PayloadRangeKind::WriteNodeBlock);
}

uint32_t NativeFragmentPatchableV0Score(const CoopNativeFragmentPayload::ParsedPayload& payload)
{
    if (!payload.ok || payload.itemGroups == 0 || payload.inventoryRanges == 0)
        return 0;

    bool inventoryHasOnlyNodes = true;
    uint32_t inventoryRangeCount = 0;
    for (const CoopNativeFragmentPayload::PayloadRangeRecord& range : payload.ranges)
    {
        if (range.groupKind != static_cast<uint32_t>(CoopNativeFragmentPayload::PayloadGroupKind::Inventory))
            continue;

        ++inventoryRangeCount;
        if (!IsNativeFragmentNodeRange(range.rangeKind))
            inventoryHasOnlyNodes = false;
    }

    if (!inventoryHasOnlyNodes || inventoryRangeCount == 0)
        return 0;

    // Current same-shape V0 can preserve/rewrite existing read-store nodes and
    // item write-vectors, but it cannot transcode inventory backing vectors yet.
    // Prefer the fragment shape that keeps inventory as node-only materializer
    // input and carries the richest item subtrees.
    uint32_t score = 1000;
    score += std::min<uint32_t>(payload.itemRanges, 100) * 10;
    score += std::min<uint32_t>(payload.rawBytes / 40, 100);
    return score;
}

int NativeFragmentSemanticContentScore(const CoopNativeFragmentPayload::ParsedPayload& payload)
{
    if (!payload.ok)
        return std::numeric_limits<int>::min() / 2;

    int score = 0;
    score += static_cast<int>(std::min<uint32_t>(payload.itemGroups, 16u)) * 20;

    bool hasItemCount = false;
    bool hasItemArchetype = false;
    bool hasItemOwner = false;
    for (const CoopNativeFragmentPayload::PayloadAttrNameRecord& attr : payload.attrNames)
    {
        const bool itemRange =
            attr.rangeIndex < payload.ranges.size() &&
            payload.ranges[attr.rangeIndex].groupKind ==
                static_cast<uint32_t>(CoopNativeFragmentPayload::PayloadGroupKind::Item);
        if (!itemRange)
            continue;

        const std::string& name = attr.name;
        if (name == "m_count")
        {
            hasItemCount = true;
            score += 500;
        }
        else if (name == "selectedArchetype")
        {
            hasItemArchetype = true;
            score += 600;
        }
        else if (name == "ownerId")
        {
            hasItemOwner = true;
            score += 450;
        }
        else if (name == "junk" || name == "favorite" || name == "stackable")
        {
            score += 40;
        }
        else if (name == "m_aiTreeFilePath" || name == "trueCount" || name == "falseCount")
        {
            score -= 900;
        }
        else if (name == "flags2" || name == "pos" || name == "rot")
        {
            score -= 400;
        }
        else if (name == "entityDirection" || name == "aimDir" || name == "fireDir" ||
            name == "upDir" || name == "eyeDir")
        {
            score -= 650;
        }
        else if (name == "mass" || name == "sequenceNumber")
        {
            score -= 250;
        }
        else if (name == "UniqueId" || name == "name")
        {
            score -= 80;
        }
    }

    if (hasItemCount && hasItemArchetype && hasItemOwner)
        score += 1200;
    if (!hasItemCount && !hasItemArchetype && !hasItemOwner)
        score -= 500;

    return score;
}

bool ShouldPreferNativeFragmentPayload(
    const CoopNativeFragmentPayload::ParsedPayload& existing,
    const CoopNativeFragmentPayload::ParsedPayload& candidate)
{
    if (!candidate.ok)
        return false;
    if (!existing.ok)
        return true;
    if (candidate.payloadChecksum == existing.payloadChecksum &&
        candidate.rawByteChecksum == existing.rawByteChecksum &&
        candidate.contentHash == existing.contentHash &&
        candidate.totalBytes == existing.totalBytes)
    {
        return false;
    }

    const int existingSemanticScore = NativeFragmentSemanticContentScore(existing);
    const int candidateSemanticScore = NativeFragmentSemanticContentScore(candidate);
    if (candidateSemanticScore != existingSemanticScore)
        return candidateSemanticScore > existingSemanticScore;

    const uint32_t existingPatchableScore = NativeFragmentPatchableV0Score(existing);
    const uint32_t candidatePatchableScore = NativeFragmentPatchableV0Score(candidate);
    if (candidatePatchableScore != existingPatchableScore)
        return candidatePatchableScore > existingPatchableScore;
    if (candidatePatchableScore != 0)
    {
        if (candidate.itemRanges != existing.itemRanges)
            return candidate.itemRanges > existing.itemRanges;
        if (candidate.rawBytes != existing.rawBytes)
            return candidate.rawBytes > existing.rawBytes;
        if (candidate.totalBytes != existing.totalBytes)
            return candidate.totalBytes > existing.totalBytes;
    }

    if (candidate.backingRanges != existing.backingRanges)
        return candidate.backingRanges > existing.backingRanges;
    if (candidate.rangeRecords != existing.rangeRecords)
        return candidate.rangeRecords > existing.rangeRecords;
    if (candidate.itemRanges != existing.itemRanges)
        return candidate.itemRanges > existing.itemRanges;
    if (candidate.rawBytes != existing.rawBytes)
        return candidate.rawBytes > existing.rawBytes;
    if (candidate.totalBytes != existing.totalBytes)
        return candidate.totalBytes > existing.totalBytes;

    return candidate.contentHash != existing.contentHash ||
        candidate.payloadChecksum != existing.payloadChecksum ||
        candidate.rawByteChecksum != existing.rawByteChecksum;
}

bool ShouldPreferNativeFragmentPayload(
    const std::vector<uint8_t>& existingBytes,
    const CoopNativeFragmentPayload::ParsedPayload& candidate)
{
    if (existingBytes.empty())
        return candidate.ok;

    CoopNativeFragmentPayload::ParsedPayload existing =
        CoopNativeFragmentPayload::ParseInventoryPayload(existingBytes);
    if (!existing.ok && existing.reason.empty())
        existing.reason = "existing_payload_parse_failed";
    return ShouldPreferNativeFragmentPayload(existing, candidate);
}

bool CopyNativeFragmentPayloadToCapture(
    NativeSideBlobCaptureState& target,
    const CoopNativeFragmentPayload::ParsedPayload& parsed,
    const std::vector<uint8_t>& bytes)
{
    if (!ShouldPreferNativeFragmentPayload(target.nativeFragmentPayload, parsed))
        return false;

    target.hasNativeFragmentPayload = true;
    target.nativeFragmentPayloadVersion = parsed.version;
    target.nativeFragmentPayloadBytes = parsed.totalBytes;
    target.nativeFragmentPayloadChecksum = parsed.payloadChecksum;
    target.nativeFragmentPayloadRawChecksum = parsed.rawByteChecksum;
    target.nativeFragmentPayloadRanges = parsed.rangeRecords;
    target.nativeFragmentPayloadInventoryRanges = parsed.inventoryRanges;
    target.nativeFragmentPayloadItemGroups = parsed.itemGroups;
    target.nativeFragmentPayloadItemRanges = parsed.itemRanges;
    target.nativeFragmentPayloadRawBytes = parsed.rawBytes;
    target.nativeFragmentPayloadRunId = parsed.runId;
    target.nativeFragmentPayloadSchemaHash = parsed.schemaHash;
    target.nativeFragmentPayloadContentHash = parsed.contentHash;
    target.nativeFragmentPayload = bytes;
    return true;
}

uint32_t AppendNativeFragmentPayloadItemIds(
    const std::vector<uint8_t>& payloadBytes,
    std::vector<unsigned>& sourceIdOrder)
{
    if (payloadBytes.empty())
        return 0;

    const CoopNativeFragmentPayload::ParsedPayload payload =
        CoopNativeFragmentPayload::ParseInventoryPayload(payloadBytes);
    if (!payload.ok)
        return 0;

    uint32_t added = 0;
    for (const CoopNativeFragmentPayload::PayloadRangeRecord& range : payload.ranges)
    {
        if (range.groupKind != static_cast<uint32_t>(CoopNativeFragmentPayload::PayloadGroupKind::Item) ||
            range.entityId == 0)
        {
            continue;
        }

        if (std::find(sourceIdOrder.begin(), sourceIdOrder.end(), range.entityId) != sourceIdOrder.end())
            continue;

        sourceIdOrder.push_back(range.entityId);
        ++added;
    }

    return added;
}

