bool PlayerPosePacketsEquivalent(
    const CoopProtocol::PlayerPosePacket& lhs,
    const CoopProtocol::PlayerPosePacket& rhs)
{
    CoopProtocol::PlayerPosePacket comparableLhs = lhs;
    CoopProtocol::PlayerPosePacket comparableRhs = rhs;
    const auto quantize = [](float value, float step)
    {
        return std::isfinite(value) ? std::round(value / step) * step : 0.0f;
    };
    const auto quantizePose = [&](CoopProtocol::PlayerPosePacket& packet)
    {
        packet.px = quantize(packet.px, 0.01f);
        packet.py = quantize(packet.py, 0.01f);
        packet.pz = quantize(packet.pz, 0.01f);
        packet.qw = quantize(packet.qw, 0.002f);
        packet.qx = quantize(packet.qx, 0.002f);
        packet.qy = quantize(packet.qy, 0.002f);
        packet.qz = quantize(packet.qz, 0.002f);
        packet.vx = quantize(packet.vx, 0.05f);
        packet.vy = quantize(packet.vy, 0.05f);
        packet.vz = quantize(packet.vz, 0.05f);
        packet.aimDx = quantize(packet.aimDx, 0.01f);
        packet.aimDy = quantize(packet.aimDy, 0.01f);
        packet.aimDz = quantize(packet.aimDz, 0.01f);
        packet.psiImpactX = quantize(packet.psiImpactX, 0.01f);
        packet.psiImpactY = quantize(packet.psiImpactY, 0.01f);
        packet.psiImpactZ = quantize(packet.psiImpactZ, 0.01f);
        packet.mimicPx = quantize(packet.mimicPx, 0.01f);
        packet.mimicPy = quantize(packet.mimicPy, 0.01f);
        packet.mimicPz = quantize(packet.mimicPz, 0.01f);
        packet.mimicQw = quantize(packet.mimicQw, 0.002f);
        packet.mimicQx = quantize(packet.mimicQx, 0.002f);
        packet.mimicQy = quantize(packet.mimicQy, 0.002f);
        packet.mimicQz = quantize(packet.mimicQz, 0.002f);
        packet.mimicSx = quantize(packet.mimicSx, 0.002f);
        packet.mimicSy = quantize(packet.mimicSy, 0.002f);
        packet.mimicSz = quantize(packet.mimicSz, 0.002f);
    };
    comparableLhs.sequence = 0;
    comparableRhs.sequence = 0;
    quantizePose(comparableLhs);
    quantizePose(comparableRhs);
    return std::memcmp(&comparableLhs, &comparableRhs, sizeof(comparableLhs)) == 0;
}

