void TracePostLoadNativeHook(const char* name)
{
    if (!gMod ||
        !EnvFlagEnabled("COOP_TRACE_POSTLOAD_NATIVE_HOOKS") ||
        !gMod->IsPostLoadNativeQuarantineActive())
    {
        return;
    }

    static uint32_t s_postLoadNativeHookTraceCount = 0;
    ++s_postLoadNativeHookTraceCount;
    if (s_postLoadNativeHookTraceCount <= 512 || (s_postLoadNativeHookTraceCount % 128) == 0)
    {
        LogCoop(
            "post-load native hook enter " +
            std::string(name && name[0] ? name : "?") +
            " count=" + std::to_string(s_postLoadNativeHookTraceCount));
    }
}

