bool MatchesOptionalEnvSubstring(const char* envName, std::string_view value)
{
    const char* filter = std::getenv(envName);
    if (!filter || !filter[0])
        return true;

    return value.find(filter) != std::string_view::npos;
}

bool ShouldRunNativePerceptionLoadStartDuringTransition(const char* reason)
{
    return reason &&
        (std::strcmp(reason, "LEVEL_UNLOAD") == 0 ||
            std::strcmp(reason, "LEVEL_LOAD_START_LOADINGSCREEN") == 0);
}

bool IsGameReady()
{
    return gEnv && gEnv->pEntitySystem && ArkPlayer::GetInstancePtr() && ArkPlayer::GetInstance().GetEntity();
}

Vec3 GetOffsetFromPlayer(float metersForward)
{
    ArkPlayer& player = ArkPlayer::GetInstance();
    IEntity* playerEntity = player.GetEntity();
    const Quat playerRot = playerEntity->GetRotation();
    return playerEntity->GetWorldPos() + playerRot * Vec3(0.0f, metersForward, 0.0f);
}

// Player physics can briefly tilt the body on slopes, collisions or during a
// load. Spawned player bodies must remain upright while preserving horizontal
// facing; the independent view rotation is kept unchanged by callers.
Quat MakeUprightPlayerBodyRotation(const Quat& rotation)
{
    Vec3 forward = rotation.GetColumn1();
    forward.z = 0.0f;
    const float lengthSquared = forward.GetLengthSquared();
    if (!std::isfinite(lengthSquared) || lengthSquared < 0.000001f)
        return Quat::CreateIdentity();

    return Quat::CreateRotationZ(std::atan2(-forward.x, forward.y));
}

