std::string WinsockStatus(const char* prefix, int error)
{
    return std::string(prefix) + " (WSA " + std::to_string(error) + ")";
}

std::string StatusToken(std::string value)
{
    if (value.empty())
        return "-";

    for (char& ch : value)
    {
        const unsigned char uch = static_cast<unsigned char>(ch);
        if (std::isspace(uch) != 0 || ch == ';' || ch == '|' || ch == '=')
            ch = '_';
    }
    return value;
}

