std::string BuildRuntimeControlExceptionStatus(
    const std::string& action,
    const char* exceptionKind,
    const char* message)
{
    std::ostringstream out;
    out
        << "coop_status"
        << " statusException=1"
        << " statusStep=" << StatusToken(GetRuntimeControlStatusBreadcrumb())
        << " statusAction=" << StatusToken(action.empty() ? std::string("-") : action)
        << " statusExceptionKind=" << StatusToken(exceptionKind && exceptionKind[0] ? exceptionKind : "unknown")
        << " statusExceptionMessage=" << StatusToken(message && message[0] ? message : "-");
    return out.str();
}

std::string EncodeHexBytesForNativeSection(const std::vector<uint8_t>& bytes, size_t offset, size_t count)
{
    static constexpr char kHex[] = "0123456789ABCDEF";
    if (offset >= bytes.size())
        return {};

    const size_t end = std::min(bytes.size(), offset + count);
    std::string out;
    out.reserve((end - offset) * 2);
    for (size_t i = offset; i < end; ++i)
    {
        const uint8_t value = bytes[i];
        out.push_back(kHex[value >> 4]);
        out.push_back(kHex[value & 0x0F]);
    }
    return out;
}

int DecodeHexNibbleForNativeSection(char ch)
{
    if (ch >= '0' && ch <= '9')
        return ch - '0';
    if (ch >= 'a' && ch <= 'f')
        return ch - 'a' + 10;
    if (ch >= 'A' && ch <= 'F')
        return ch - 'A' + 10;
    return -1;
}

bool AppendHexBytesForNativeSection(std::string_view text, std::vector<uint8_t>& bytes)
{
    int highNibble = -1;
    for (char ch : text)
    {
        if (std::isspace(static_cast<unsigned char>(ch)) != 0)
            continue;

        const int value = DecodeHexNibbleForNativeSection(ch);
        if (value < 0)
            return false;

        if (highNibble < 0)
        {
            highNibble = value;
        }
        else
        {
            bytes.push_back(static_cast<uint8_t>((highNibble << 4) | value));
            highNibble = -1;
        }
    }

    return highNibble < 0;
}

std::string Hex32(uint32_t value)
{
    char buffer[16] = {};
    std::snprintf(buffer, sizeof(buffer), "0x%08X", value);
    return buffer;
}

std::string Hex64(uint64_t value)
{
    char buffer[32] = {};
    std::snprintf(buffer, sizeof(buffer), "0x%llX", static_cast<unsigned long long>(value));
    return buffer;
}

std::string PointerHex(const void* pointer)
{
    char buffer[32] = {};
    std::snprintf(buffer, sizeof(buffer), "0x%llX", static_cast<unsigned long long>(reinterpret_cast<std::uintptr_t>(pointer)));
    return buffer;
}

std::string FormatVec3Trace(const Vec3& value)
{
    std::ostringstream out;
    out << std::fixed << std::setprecision(3)
        << "(" << value.x << "," << value.y << "," << value.z << ")";
    return out.str();
}

std::string FormatAng3Degrees(const Ang3& value)
{
    constexpr float kRadToDeg = 180.0f / gf_PI;
    std::ostringstream out;
    out << std::fixed << std::setprecision(1)
        << "(" << value.x * kRadToDeg << "," << value.y * kRadToDeg << "," << value.z * kRadToDeg << ")";
    return out.str();
}

std::string FormatAabbTrace(const AABB& bounds)
{
    return FormatVec3Trace(bounds.min) + "-" + FormatVec3Trace(bounds.max);
}

struct GetEntitiesInBoxWarning
{
    unsigned requestedCells = 0;
    AABB queryBounds;
};

bool TryParseGetEntitiesInBoxWarning(const char* text, GetEntitiesInBoxWarning& warning)
{
    warning = {};
    if (!text || !text[0])
        return false;

    const char* marker = std::strstr(text, "Game (");
    if (!marker)
        return false;

    float minX = 0.0f;
    float minY = 0.0f;
    float minZ = 0.0f;
    float maxX = 0.0f;
    float maxY = 0.0f;
    float maxZ = 0.0f;
    if (std::sscanf(
            marker,
            "Game (%u, (%f,%f,%f)-(%f,%f,%f))",
            &warning.requestedCells,
            &minX,
            &minY,
            &minZ,
            &maxX,
            &maxY,
            &maxZ) != 7)
    {
        return false;
    }

    warning.queryBounds.min = Vec3(minX, minY, minZ);
    warning.queryBounds.max = Vec3(maxX, maxY, maxZ);
    return true;
}

bool IsFiniteVec3Trace(const Vec3& value)
{
    return std::isfinite(value.x) && std::isfinite(value.y) && std::isfinite(value.z);
}

bool IsHugePhysicsBounds(const Vec3& minBounds, const Vec3& maxBounds)
{
    if (!IsFiniteVec3Trace(minBounds) || !IsFiniteVec3Trace(maxBounds))
        return true;

    const Vec3 extents = maxBounds - minBounds;
    return extents.x > 50.0f || extents.y > 50.0f || extents.z > 50.0f;
}

bool IsUsablePhysicsRepairBounds(const AABB& bounds, float maxExtent)
{
    if (bounds.IsReset() ||
        !IsFiniteVec3Trace(bounds.min) ||
        !IsFiniteVec3Trace(bounds.max))
    {
        return false;
    }

    const Vec3 extents = bounds.max - bounds.min;
    return
        extents.x > 0.001f &&
        extents.y > 0.001f &&
        extents.z > 0.001f &&
        extents.x <= maxExtent &&
        extents.y <= maxExtent &&
        extents.z <= maxExtent;
}

bool TryComputeRenderLocalBoundsForPhysicsRepair(IEntity& entity, AABB& outBounds, std::string& detail)
{
    outBounds.Reset();
    detail.clear();

    int slotCount = 0;
    std::string reason;
    if (!TryGuardedCall("repair bounds IEntity::GetSlotCount", [&entity]() { return entity.GetSlotCount(); }, slotCount, &reason) ||
        slotCount <= 0)
    {
        detail = "render_bounds_no_slots reason_" + StatusToken(reason.empty() ? std::string("-") : reason);
        return false;
    }

    slotCount = std::min(slotCount, 64);
    uint32_t usedSlots = 0;
    uint32_t skippedSlots = 0;
    for (int slot = 0; slot < slotCount; ++slot)
    {
        IStatObj* statObj = nullptr;
        if (!TryGuardedCall("repair bounds IEntity::GetStatObj", [&entity, slot]() { return entity.GetStatObj(slot); }, statObj, &reason) ||
            !statObj ||
            !IsLikelyRuntimeCppObject(statObj))
        {
            ++skippedSlots;
            continue;
        }

        AABB statBounds(AABB::RESET);
        if (!TryGuardedCall("repair bounds IStatObj::GetAABB", [statObj]() { return statObj->GetAABB(); }, statBounds, &reason) ||
            !IsUsablePhysicsRepairBounds(statBounds, 30.0f))
        {
            ++skippedSlots;
            continue;
        }

        Matrix34 slotLocal = Matrix34::CreateIdentity();
        const bool haveSlotLocal = TryGuardedVoidCall(
            "repair bounds IEntity::GetSlotLocalTM",
            [&entity, slot, &slotLocal]() { slotLocal = entity.GetSlotLocalTM(slot, false); },
            &reason);

        const AABB localBounds = haveSlotLocal
            ? AABB::CreateTransformedAABB(slotLocal, statBounds)
            : statBounds;
        if (!IsUsablePhysicsRepairBounds(localBounds, 30.0f))
        {
            ++skippedSlots;
            continue;
        }

        outBounds.Add(localBounds);
        ++usedSlots;
    }

    if (!IsUsablePhysicsRepairBounds(outBounds, 30.0f))
    {
        detail =
            "render_bounds_unusable"
            "_slots_" + std::to_string(slotCount) +
            "_used_" + std::to_string(usedSlots) +
            "_skipped_" + std::to_string(skippedSlots);
        return false;
    }

    outBounds.Expand(Vec3(0.05f, 0.05f, 0.05f));
    detail =
        "render_bounds"
        "_slots_" + std::to_string(slotCount) +
        "_used_" + std::to_string(usedSlots) +
        "_skipped_" + std::to_string(skippedSlots) +
        "_bbox_" + StatusToken(FormatAabbTrace(outBounds));
    return true;
}

bool IsHugePhysicsBoundsRepairCandidateClass(const std::string& lowerClassName)
{
    if (lowerClassName.empty())
        return false;

    if (lowerClassName == "rigidbodyex")
        return true;

    return lowerClassName.find("arkcontainer") != std::string::npos ||
        lowerClassName.find("arkpickable") != std::string::npos;
}

bool IsHugePhysicsBoundsRepairBlockedClass(const std::string& lowerClassName)
{
    return lowerClassName.empty() ||
        lowerClassName == "player" ||
        lowerClassName.find("arkplayer") != std::string::npos ||
        lowerClassName.find("arkhuman") != std::string::npos ||
        lowerClassName.find("arknpc") != std::string::npos ||
        lowerClassName.find("arkmimic") != std::string::npos ||
        lowerClassName.find("arkphantom") != std::string::npos ||
        lowerClassName.find("arknightmare") != std::string::npos ||
        lowerClassName.find("arkoperator") != std::string::npos ||
        lowerClassName.find("arkweaver") != std::string::npos ||
        lowerClassName.find("arkcystoid") != std::string::npos ||
        lowerClassName.find("apextentacle") != std::string::npos ||
        lowerClassName.find("leveltransition") != std::string::npos ||
        lowerClassName.find("trigger") != std::string::npos ||
        lowerClassName.find("volume") != std::string::npos ||
        lowerClassName.find("flowgraph") != std::string::npos;
}

bool AabbCloseEnough(const AABB& a, const AABB& b, float tolerance)
{
    return (a.min - b.min).GetLengthSquared() <= tolerance * tolerance &&
        (a.max - b.max).GetLengthSquared() <= tolerance * tolerance;
}

std::string PathFileNameOnly(std::string value)
{
    if (value.empty())
        return "-";

    std::replace(value.begin(), value.end(), '\\', '/');
    const size_t slash = value.find_last_of('/');
    if (slash != std::string::npos)
        value.erase(0, slash + 1);
    return value.empty() ? std::string("-") : value;
}

std::uintptr_t RuntimeModuleBaseForPointer(const void* pointer)
{
    if (!pointer)
        return 0;

    HMODULE module = nullptr;
    if (GetModuleHandleExA(
            GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
            reinterpret_cast<LPCSTR>(pointer),
            &module) == FALSE)
    {
        return 0;
    }

    return reinterpret_cast<std::uintptr_t>(module);
}

std::string RuntimeRvaText(const void* pointer)
{
    const std::uintptr_t address = reinterpret_cast<std::uintptr_t>(pointer);
    const std::uintptr_t base = RuntimeModuleBaseForPointer(pointer);
    if (address == 0 || base == 0 || address < base)
        return "rva=-";
    return "rva=" + Hex64(address - base);
}

std::string DescribeRuntimeAddress(const void* pointer)
{
    return PointerHex(pointer) +
        " module=" + PathFileNameOnly(GetRuntimeModulePath(pointer)) +
        " " + RuntimeRvaText(pointer);
}

struct RuntimeVectorTriple
{
    std::uintptr_t begin = 0;
    std::uintptr_t end = 0;
    std::uintptr_t capacity = 0;
};

bool ReadRuntimeVectorTriple(const void* owner, size_t offset, RuntimeVectorTriple& out)
{
    if (!owner)
        return false;

    const auto base = reinterpret_cast<const std::byte*>(owner);
    return
        TryReadRuntimeValue(reinterpret_cast<const std::uintptr_t*>(base + offset), out.begin) &&
        TryReadRuntimeValue(reinterpret_cast<const std::uintptr_t*>(base + offset + sizeof(std::uintptr_t)), out.end) &&
        TryReadRuntimeValue(reinterpret_cast<const std::uintptr_t*>(base + offset + sizeof(std::uintptr_t) * 2), out.capacity);
}

std::string BuildVisualManagerRawVectorSnapshot(const ArkVisualPerceptionManager* manager, const char* reason)
{
    struct VectorField
    {
        const char* name = "";
        size_t offset = 0;
        size_t elementSize = 1;
    };

    static constexpr VectorField kFields[] = {
        {"perceiverPtrs", 0x250, 8},
        {"perceiverEntityIdsMaybe", 0x268, 4},
        {"perceiverVisionLocalAabbsMaybe", 0x280, 12},
        {"perceiverXAxisIntervalsMaybe", 0x298, 16},
        {"perceiverYAxisIntervalsMaybe", 0x2B0, 16},
        {"perceiverZAxisIntervalsMaybe", 0x2C8, 16},
        {"xAxisBounds", 0x3A0, 8},
        {"yAxisBounds", 0x3B8, 8},
        {"zAxisBounds", 0x3D0, 8},
    };

    std::ostringstream out;
    out << "visual manager raw reason=" << (reason ? reason : "unknown")
        << " manager=" << PointerHex(manager);

    if (!manager)
        return out.str() + " null";

    std::string guardReason;
    if (!PreflightRuntimePointer("visual manager raw manager", manager, sizeof(void*) * 2, RuntimeAccess::Read, &guardReason))
    {
        out << " managerGuard=" << StatusToken(guardReason);
        return out.str();
    }

    for (const VectorField& field : kFields)
    {
        RuntimeVectorTriple triple;
        bool ok = ReadRuntimeVectorTriple(manager, field.offset, triple);

        out << " " << field.name << "@+" << Hex64(field.offset) << "=";
        if (!ok)
        {
            out << "unreadable";
            continue;
        }

        const bool ordered = triple.begin <= triple.end && triple.end <= triple.capacity;
        const std::uintptr_t bytes = ordered ? triple.end - triple.begin : 0;
        const std::uintptr_t capBytes = ordered ? triple.capacity - triple.begin : 0;
        const bool aligned = field.elementSize != 0 && (bytes % field.elementSize) == 0 && (capBytes % field.elementSize) == 0;
        const uint64_t count = ordered && aligned ? static_cast<uint64_t>(bytes / field.elementSize) : 0;
        const uint64_t capCount = ordered && aligned ? static_cast<uint64_t>(capBytes / field.elementSize) : 0;
        std::string beginGuard;
        const bool readable =
            triple.begin == 0 ||
            PreflightRuntimePointer(
                "visual manager raw vector begin",
                reinterpret_cast<const void*>(triple.begin),
                field.elementSize,
                RuntimeAccess::Read,
                &beginGuard);

        out << PointerHex(reinterpret_cast<const void*>(triple.begin))
            << ".." << PointerHex(reinterpret_cast<const void*>(triple.end))
            << "/" << PointerHex(reinterpret_cast<const void*>(triple.capacity))
            << ":n=" << count
            << ":cap=" << capCount
            << ":ordered=" << (ordered ? 1 : 0)
            << ":aligned=" << (aligned ? 1 : 0)
            << ":read=" << (readable ? 1 : 0);
        if (!readable && !beginGuard.empty())
            out << ":guard=" << StatusToken(beginGuard);
    }

    return out.str();
}

bool ShouldTraceCrashException(DWORD code)
{
    switch (code)
    {
    case EXCEPTION_ACCESS_VIOLATION:
    case EXCEPTION_IN_PAGE_ERROR:
    case EXCEPTION_ILLEGAL_INSTRUCTION:
    case EXCEPTION_PRIV_INSTRUCTION:
    case EXCEPTION_STACK_OVERFLOW:
    case EXCEPTION_DATATYPE_MISALIGNMENT:
    case 0xE0667422:  // C++ EH (uncaught exception / abort raised by game code)
    case 0xC0000602:  // STATUS_FAST_FAIL_EXCEPTION (ucrtbase abort path)
        return true;
    default:
        return false;
    }
}

std::string AccessViolationText(const EXCEPTION_RECORD& record)
{
    if (record.ExceptionCode != EXCEPTION_ACCESS_VIOLATION &&
        record.ExceptionCode != EXCEPTION_IN_PAGE_ERROR)
    {
        return {};
    }

    const ULONG_PTR mode = record.NumberParameters > 0 ? record.ExceptionInformation[0] : 0;
    const ULONG_PTR address = record.NumberParameters > 1 ? record.ExceptionInformation[1] : 0;
    const char* operation = "access";
    if (mode == 0)
        operation = "read";
    else if (mode == 1)
        operation = "write";
    else if (mode == 8)
        operation = "execute";

    std::ostringstream out;
    out
        << "access=" << operation
        << " fault=" << DescribeRuntimeAddress(reinterpret_cast<const void*>(address));
    if (record.ExceptionCode == EXCEPTION_IN_PAGE_ERROR && record.NumberParameters > 2)
        out << " ntstatus=" << Hex64(static_cast<uint64_t>(record.ExceptionInformation[2]));
    return out.str();
}

void AppendFaultStack(std::ostringstream& out, EXCEPTION_POINTERS* pointers)
{
    out << "fault_stack:\n";

#if defined(_M_X64) || defined(__x86_64__)
    if (!pointers || !pointers->ContextRecord)
    {
        out << "  unavailable: no context\n";
        return;
    }

    CONTEXT context = *pointers->ContextRecord;
    for (size_t i = 0; i < 48 && context.Rip != 0; ++i)
    {
        const DWORD64 controlPc = context.Rip;
        out << "  #" << i << " " << DescribeRuntimeAddress(reinterpret_cast<const void*>(controlPc)) << "\n";

        DWORD64 imageBase = 0;
        PRUNTIME_FUNCTION functionEntry = RtlLookupFunctionEntry(controlPc, &imageBase, nullptr);
        if (functionEntry)
        {
            PVOID handlerData = nullptr;
            DWORD64 establisherFrame = 0;
            const DWORD64 previousRip = context.Rip;
            RtlVirtualUnwind(
                0,
                imageBase,
                controlPc,
                functionEntry,
                &context,
                &handlerData,
                &establisherFrame,
                nullptr);
            if (context.Rip == 0 || context.Rip == previousRip)
                break;
            continue;
        }

        DWORD64 returnAddress = 0;
        const void* stackPointer = reinterpret_cast<const void*>(context.Rsp);
        if (!IsReadableRuntimePointer(stackPointer, sizeof(returnAddress)))
        {
            out << "  stop: unreadable stack rsp=" << PointerHex(stackPointer) << "\n";
            break;
        }

        std::memcpy(&returnAddress, stackPointer, sizeof(returnAddress));
        context.Rsp += sizeof(returnAddress);
        context.Rip = returnAddress;
    }
#else
    void* frames[48] = {};
    const USHORT count = CaptureStackBackTrace(0, static_cast<DWORD>(std::size(frames)), frames, nullptr);
    for (USHORT i = 0; i < count; ++i)
        out << "  #" << i << " " << DescribeRuntimeAddress(frames[i]) << "\n";
#endif
}

std::string BuildCrashTracePath(LONG traceIndex)
{
    std::string directory = g_crashTraceDirectory;
    if (directory.empty())
        directory = ".";

    const char last = directory.empty() ? '\0' : directory.back();
    if (last != '\\' && last != '/')
        directory += "\\";

    SYSTEMTIME localTime = {};
    GetLocalTime(&localTime);

    char fileName[160] = {};
    std::snprintf(
        fileName,
        sizeof(fileName),
        "coop_crash_%04u%02u%02u_%02u%02u%02u_%lu_%lu_%ld.log",
        static_cast<unsigned>(localTime.wYear),
        static_cast<unsigned>(localTime.wMonth),
        static_cast<unsigned>(localTime.wDay),
        static_cast<unsigned>(localTime.wHour),
        static_cast<unsigned>(localTime.wMinute),
        static_cast<unsigned>(localTime.wSecond),
        static_cast<unsigned long>(GetCurrentProcessId()),
        static_cast<unsigned long>(GetCurrentThreadId()),
        static_cast<long>(traceIndex));

    return directory + fileName;
}

