bool IsCrossWorldReliablePayload(uint16_t payloadType)
{
    return payloadType == static_cast<uint16_t>(CoopProtocol::PacketType::WorldSync) ||
        payloadType == static_cast<uint16_t>(CoopProtocol::PacketType::SaveTransfer) ||
        payloadType == static_cast<uint16_t>(CoopProtocol::PacketType::PlayerStateTransfer) ||
        payloadType == static_cast<uint16_t>(CoopProtocol::PacketType::AreaJournalTransfer) ||
        payloadType == static_cast<uint16_t>(CoopProtocol::PacketType::AreaLease) ||
        // A joining client must consume the existing roster before gameplay is
        // ready. Deferring this packet leaves the reliable sequence frontier
        // parked ahead of the save/player-state transfer queued behind it.
        payloadType == static_cast<uint16_t>(CoopProtocol::PacketType::PeerPresence);
}

bool IsAreaScopedReliablePayload(uint16_t payloadType)
{
    switch (static_cast<CoopProtocol::PacketType>(payloadType))
    {
    case CoopProtocol::PacketType::RemotePlayerDamage:
    case CoopProtocol::PacketType::TestMimicSpawn:
    case CoopProtocol::PacketType::TestMimicState:
    case CoopProtocol::PacketType::EnemyDamageRequest:
    case CoopProtocol::PacketType::EnemyDeathPresentation:
    case CoopProtocol::PacketType::GooResult:
    case CoopProtocol::PacketType::EnemyAbilityFxEvent:
    case CoopProtocol::PacketType::EnemyMannequinAction:
    case CoopProtocol::PacketType::AreaObjectEvent:
    case CoopProtocol::PacketType::EnemyRoster:
    case CoopProtocol::PacketType::SharedDrop:
    case CoopProtocol::PacketType::SharedStorage:
    case CoopProtocol::PacketType::HazardEvent:
    case CoopProtocol::PacketType::CorpsePhantomRequest:
        return true;
    default:
        return false;
    }
}

bool IsReliableTransferStartPayload(uint16_t payloadType, const uint8_t* payload, uint16_t payloadSize, uint32_t& transferId)
{
    transferId = 0;
    if (!payload)
        return false;

    if (payloadType == static_cast<uint16_t>(CoopProtocol::PacketType::SaveTransfer))
    {
        if (payloadSize != sizeof(CoopProtocol::SaveTransferPacket))
            return false;

        CoopProtocol::SaveTransferPacket packet = {};
        std::memcpy(&packet, payload, sizeof(packet));
        if (static_cast<CoopProtocol::SaveTransferCommand>(packet.command) != CoopProtocol::SaveTransferCommand::Start)
            return false;

        transferId = packet.transferId;
        return transferId != 0;
    }

    if (payloadType == static_cast<uint16_t>(CoopProtocol::PacketType::PlayerStateTransfer))
    {
        if (payloadSize != sizeof(CoopProtocol::PlayerStateTransferPacket))
            return false;

        CoopProtocol::PlayerStateTransferPacket packet = {};
        std::memcpy(&packet, payload, sizeof(packet));
        const CoopProtocol::PlayerStateTransferCommand command =
            static_cast<CoopProtocol::PlayerStateTransferCommand>(packet.command);
        if (command != CoopProtocol::PlayerStateTransferCommand::Start &&
            command != CoopProtocol::PlayerStateTransferCommand::Request)
            return false;

        transferId = packet.transferId;
        return transferId != 0;
    }

    if (payloadType == static_cast<uint16_t>(CoopProtocol::PacketType::AreaJournalTransfer))
    {
        if (payloadSize != sizeof(CoopProtocol::AreaJournalTransferPacket))
            return false;

        CoopProtocol::AreaJournalTransferPacket packet = {};
        std::memcpy(&packet, payload, sizeof(packet));
        const CoopProtocol::AreaJournalTransferCommand command =
            static_cast<CoopProtocol::AreaJournalTransferCommand>(packet.command);
        if (command != CoopProtocol::AreaJournalTransferCommand::Start &&
            command != CoopProtocol::AreaJournalTransferCommand::Request)
            return false;

        transferId = packet.transferId;
        return transferId != 0;
    }

    return false;
}

uint32_t UpdateFnv1a(uint32_t checksum, const uint8_t* data, size_t size)
{
    if (!data)
        return checksum;

    for (size_t i = 0; i < size; ++i)
    {
        checksum ^= static_cast<uint32_t>(data[i]);
        checksum *= kFnv1aPrime;
    }
    return checksum;
}

bool GetFileSizeBytes(const std::string& path, uint32_t& outSize)
{
    std::ifstream stream(CoopFilesystem::FromUtf8(path), std::ios::binary | std::ios::ate);
    if (!stream)
        return false;

    const std::ifstream::pos_type size = stream.tellg();
    if (size < 0 || static_cast<unsigned long long>(size) > std::numeric_limits<uint32_t>::max())
        return false;

    outSize = static_cast<uint32_t>(size);
    return true;
}

bool ComputeFileChecksum(const std::string& path, uint32_t& outChecksum)
{
    std::ifstream stream(CoopFilesystem::FromUtf8(path), std::ios::binary);
    if (!stream)
        return false;

    std::array<uint8_t, 4096> buffer = {};
    uint32_t checksum = kFnv1aOffsetBasis;
    while (stream)
    {
        stream.read(reinterpret_cast<char*>(buffer.data()), static_cast<std::streamsize>(buffer.size()));
        const std::streamsize count = stream.gcount();
        if (count > 0)
            checksum = UpdateFnv1a(checksum, buffer.data(), static_cast<size_t>(count));
    }

    outChecksum = checksum;
    return true;
}

bool IsReadableFile(const std::filesystem::path& path, uint32_t* outSize = nullptr)
{
    std::error_code error;
    if (!std::filesystem::is_regular_file(path, error) || error)
        return false;

    const auto size = std::filesystem::file_size(path, error);
    if (error || size == 0 || size > std::numeric_limits<uint32_t>::max())
        return false;

    if (outSize)
        *outSize = static_cast<uint32_t>(size);
    return true;
}

bool ReadBinaryFileLimited(
    const std::string& path,
    uint64_t maxBytes,
    std::vector<uint8_t>& outBytes,
    uint32_t* outChecksum = nullptr)
{
    outBytes.clear();
    if (path.empty() || maxBytes == 0)
        return false;

    std::error_code error;
    const std::filesystem::path fsPath = CoopFilesystem::FromUtf8(path);
    if (!std::filesystem::is_regular_file(fsPath, error) || error)
        return false;

    const uint64_t fileSize = std::filesystem::file_size(fsPath, error);
    if (error || fileSize == 0 || fileSize > maxBytes || fileSize > static_cast<uint64_t>(std::numeric_limits<size_t>::max()))
        return false;

    std::ifstream input(fsPath, std::ios::binary);
    if (!input)
        return false;

    outBytes.resize(static_cast<size_t>(fileSize));
    input.read(reinterpret_cast<char*>(outBytes.data()), static_cast<std::streamsize>(outBytes.size()));
    if (!input || static_cast<size_t>(input.gcount()) != outBytes.size())
    {
        outBytes.clear();
        return false;
    }

    if (outChecksum)
        *outChecksum = UpdateFnv1a(kFnv1aOffsetBasis, outBytes.data(), outBytes.size());
    return true;
}

bool ParseIntegrityHash(std::string_view text, uint32_t& outHash)
{
    if (text.empty() || text.size() > 8)
        return false;

    uint32_t value = 0;
    for (const char ch : text)
    {
        value <<= 4;
        if (ch >= '0' && ch <= '9')
            value |= static_cast<uint32_t>(ch - '0');
        else if (ch >= 'a' && ch <= 'f')
            value |= static_cast<uint32_t>(10 + ch - 'a');
        else if (ch >= 'A' && ch <= 'F')
            value |= static_cast<uint32_t>(10 + ch - 'A');
        else
            return false;
    }

    outHash = value;
    return true;
}

bool ValidatePlayerStateIntegrityFile(
    const std::filesystem::path& path,
    uint32_t* outSize = nullptr,
    bool* outHasHash = nullptr,
    std::string* outReason = nullptr)
{
    if (outHasHash)
        *outHasHash = false;

    uint32_t fileSize = 0;
    if (!IsReadableFile(path, &fileSize))
    {
        if (outReason)
            *outReason = "not readable";
        return false;
    }

    std::ifstream input(path, std::ios::binary);
    if (!input)
    {
        if (outReason)
            *outReason = "open failed";
        return false;
    }

    std::ostringstream buffer;
    buffer << input.rdbuf();
    if (!input.good() && !input.eof())
    {
        if (outReason)
            *outReason = "read failed";
        return false;
    }

    const std::string text = buffer.str();
    size_t firstLineEnd = text.find('\n');
    if (firstLineEnd == std::string::npos)
        firstLineEnd = text.size();

    std::string_view firstLine(text.data(), firstLineEnd);
    if (!firstLine.empty() && firstLine.back() == '\r')
        firstLine.remove_suffix(1);

    constexpr std::string_view kIntegrityPrefix = "integrityHash=";
    if (firstLine.rfind(kIntegrityPrefix, 0) != 0)
    {
        const auto hasField = [&text](std::string_view field)
        {
            if (std::string_view(text).rfind(field, 0) == 0)
                return true;
            const std::string linePrefix = "\n" + std::string(field);
            return text.find(linePrefix) != std::string::npos;
        };
        if (!hasField("version=1") ||
            !hasField("username=") ||
            !hasField("health=") ||
            !hasField("inventoryCount="))
        {
            if (outReason)
                *outReason = "legacy malformed";
            return false;
        }
        if (outSize)
            *outSize = fileSize;
        if (outReason)
            *outReason = "legacy no hash";
        return true;
    }

    if (outHasHash)
        *outHasHash = true;

    uint32_t expectedHash = 0;
    if (!ParseIntegrityHash(firstLine.substr(kIntegrityPrefix.size()), expectedHash))
    {
        if (outReason)
            *outReason = "invalid hash header";
        return false;
    }

    const size_t payloadStart = firstLineEnd < text.size() ? firstLineEnd + 1 : firstLineEnd;
    const std::string_view payload(text.data() + payloadStart, text.size() - payloadStart);
    const uint32_t actualHash = UpdateFnv1a(
        kFnv1aOffsetBasis,
        reinterpret_cast<const uint8_t*>(payload.data()),
        payload.size());
    if (actualHash != expectedHash)
    {
        if (outReason)
            *outReason = "hash mismatch expected=" + Hex32(expectedHash) + " actual=" + Hex32(actualHash);
        return false;
    }

    if (outSize)
        *outSize = fileSize;
    if (outReason)
        *outReason = "hash ok";
    return true;
}

struct RecoveryStateMetadata
{
    uint64_t accountToken = 0;
    uint64_t revision = 0;
    std::string saveKey;
};

bool ReadRecoveryStateMetadata(
    const std::filesystem::path& path,
    RecoveryStateMetadata& metadata)
{
    metadata = {};
    bool hasHash = false;
    std::string reason;
    if (!ValidatePlayerStateIntegrityFile(path, nullptr, &hasHash, &reason) || !hasHash)
        return false;

    std::ifstream input(path, std::ios::binary);
    if (!input)
        return false;
    std::ostringstream buffer;
    buffer << input.rdbuf();
    if (!input.good() && !input.eof())
        return false;
    const std::string text = buffer.str();
    const size_t firstLineEnd = text.find('\n');
    if (firstLineEnd == std::string::npos)
        return false;
    std::istringstream payload(text.substr(firstLineEnd + 1));
    payload.imbue(std::locale::classic());
    bool accountPresent = false;
    bool revisionPresent = false;
    bool saveKeyPresent = false;
    std::string line;
    while (std::getline(payload, line))
    {
        if (line.rfind("recoveryAccount=", 0) == 0)
        {
            const std::string value = line.substr(std::strlen("recoveryAccount="));
            if (value.empty() || value.size() > 16)
                return false;
            metadata.accountToken = 0;
            for (const char ch : value)
            {
                metadata.accountToken <<= 4;
                if (ch >= '0' && ch <= '9')
                    metadata.accountToken |= static_cast<uint64_t>(ch - '0');
                else if (ch >= 'a' && ch <= 'f')
                    metadata.accountToken |= static_cast<uint64_t>(10 + ch - 'a');
                else if (ch >= 'A' && ch <= 'F')
                    metadata.accountToken |= static_cast<uint64_t>(10 + ch - 'A');
                else
                    return false;
            }
            accountPresent = metadata.accountToken != 0;
        }
        else if (line.rfind("recoverySaveKey=", 0) == 0)
        {
            metadata.saveKey = line.substr(std::strlen("recoverySaveKey="));
            saveKeyPresent = !metadata.saveKey.empty();
        }
        else if (line.rfind("recoveryRevision=", 0) == 0)
        {
            std::istringstream revision(line.substr(std::strlen("recoveryRevision=")));
            revision.imbue(std::locale::classic());
            revision >> metadata.revision;
            revisionPresent = !revision.fail() && metadata.revision != 0;
        }
    }
    return accountPresent && saveKeyPresent && revisionPresent;
}

bool WriteTextFileWithIntegrityHash(const std::filesystem::path& path, const std::string& payload)
{
    std::filesystem::path tempPath = path;
    tempPath += ".tmp";
    std::ofstream output(tempPath, std::ios::binary | std::ios::trunc);
    if (!output)
        return false;

    output.imbue(std::locale::classic());
    const uint32_t hash = UpdateFnv1a(
        kFnv1aOffsetBasis,
        reinterpret_cast<const uint8_t*>(payload.data()),
        payload.size());
    std::string hashText = Hex32(hash);
    if (hashText.rfind("0x", 0) == 0 || hashText.rfind("0X", 0) == 0)
        hashText = hashText.substr(2);
    output << "integrityHash=" << hashText << "\n";
    output.write(payload.data(), static_cast<std::streamsize>(payload.size()));
    output.close();
    if (!output)
        return false;

    std::error_code error;
    std::filesystem::rename(tempPath, path, error);
    if (!error)
        return true;

    error.clear();
    std::filesystem::copy_file(tempPath, path, std::filesystem::copy_options::overwrite_existing, error);
    std::error_code removeError;
    std::filesystem::remove(tempPath, removeError);
    return !error;
}

template<typename T>
bool WriteBinaryValue(std::ostream& stream, const T& value)
{
    stream.write(reinterpret_cast<const char*>(&value), sizeof(T));
    return !!stream;
}

template<typename T>
bool ReadBinaryValue(std::istream& stream, T& value)
{
    stream.read(reinterpret_cast<char*>(&value), sizeof(T));
    return !!stream;
}

