uint32_t GetProxyWeaponVisualMountClass(
    uint32_t weaponClass,
    bool crouched,
    bool lowCrouched,
    bool zeroG)
{
    // The Wrench's lowered, quarter-turned carry is tuned only for ordinary
    // standing/walking animations. The surrogate crouch, prone and Zero-G
    // frames place both hands at the pistol mount, so keep the Wrench model
    // but resolve its slot transform exactly like a pistol in those poses.
    if (weaponClass == CoopProtocol::kPlayerPoseWeaponClassWrench &&
        (crouched || lowCrouched || zeroG))
    {
        return CoopProtocol::kPlayerPoseWeaponClassPistol;
    }
    return weaponClass;
}

Vec3 GetProxyWeaponVisualOffsetForClass(
    uint32_t weaponClass,
    const Vec3& baseOffset,
    bool crouched,
    bool lowCrouched,
    bool zeroG)
{
    Vec3 offset = baseOffset;
    if (weaponClass == CoopProtocol::kPlayerPoseWeaponClassLaser)
    {
        offset.y -= 0.64f;
        offset.z += 0.20f;
    }
    else if (weaponClass == CoopProtocol::kPlayerPoseWeaponClassRecycler ||
        weaponClass == CoopProtocol::kPlayerPoseWeaponClassEmp ||
        weaponClass == CoopProtocol::kPlayerPoseWeaponClassNullwave ||
        weaponClass == CoopProtocol::kPlayerPoseWeaponClassLure)
    {
        offset.y += 0.18f;
        offset.z += 0.10f;
    }
    else if (weaponClass == CoopProtocol::kPlayerPoseWeaponClassWrench)
    {
        offset.x += 0.10f; //15
        offset.y -= 0.34f; //34
        offset.z -= 0.32f; //35
    }
    // Zero-G has higher presentation priority than every grounded stance.
    // Its validated pose needs only this fixed weapon correction; stale
    // crouch/crawl bits must not apply their grounded offsets as well.
    if (zeroG)
    {
        if (weaponClass == CoopProtocol::kPlayerPoseWeaponClassPistol)
            offset.x += 0.16f;
        offset.z -= 0.20f;
    }
    else if (lowCrouched)
        offset.z -= 1.18f;
    else if (crouched)
        offset.z -= 0.68f;
    return offset;
}

Ang3 GetProxyWeaponVisualAnglesForClass(uint32_t weaponClass, const Ang3& baseAngles)
{
    Ang3 angles = baseAngles;
    if (weaponClass == CoopProtocol::kPlayerPoseWeaponClassWrench)
        angles.x -= gf_PI * 0.5f;
    return angles;
}

