std::vector<ProxyWeaponMuzzleEffectLayer> GetProxyWeaponMuzzleEffectLayers(uint32_t weaponClass)
{
    const Vec3 baseOffset = GetProxyWeaponMuzzleEffectOffset(weaponClass);
    const float baseDuration = GetProxyWeaponMuzzleEffectDuration(weaponClass);
    const float baseScale = GetProxyWeaponMuzzleEffectScale(weaponClass);
    std::vector<ProxyWeaponMuzzleEffectLayer> layers;

    auto add = [&layers](
        const char* effectName,
        const Vec3& offset,
        float scale,
        float duration,
        bool attachToWeaponSlot,
        bool invertDirection = false,
        float directionalForwardOffset = 0.0f)
    {
        if (effectName && effectName[0])
            layers.push_back({ effectName, offset, scale, duration, attachToWeaponSlot, invertDirection, directionalForwardOffset });
    };

    switch (weaponClass)
    {
    case CoopProtocol::kPlayerPoseWeaponClassPistol:
        add("PlayerWeapons.Pistol.Muzzle.MuzzleFlash_00", baseOffset, baseScale, baseDuration, false);
        add("Characters.Robots.Turret.Main.light", baseOffset, 0.62f, 0.08f, false);
        break;
    case CoopProtocol::kPlayerPoseWeaponClassShotgun:
        add("PlayerWeapons.Shotgun.muzzle_flash", baseOffset, baseScale, 0.11f, true);
        add("Characters.Humans.Cinematic.Weapon.ShotgunMuzzleBlast_00.light", baseOffset, 0.75f, 0.10f, true);
        add("Characters.Robots.Turret.Main.light", baseOffset, 0.85f, 0.10f, true);
        break;
    case CoopProtocol::kPlayerPoseWeaponClassGooGun:
        add("LevelShared.Breakables.Paper.Paper_00", baseOffset, 0.7f, 0.12f, true);
        add("LevelShared.Breakables.Generic.Generic_Medium_00", baseOffset, 0.7f, 0.11f, true);
        add("LevelShared.Breakables.Ceramic.Ceramic_White_01.MeshObjects_00", baseOffset, 0.7f, 0.10f, true);
        add("Characters.Aliens.Beta.KineticProjectile_01.TailSpawn.ConnectedTails_00", Vec3(0.0f, 1.30f, 1.40f), 1.70f, 0.10f, false, true);
        break;
    case CoopProtocol::kPlayerPoseWeaponClassStunGun:
        add("PlayerWeapons.StunGun.Firing_00", baseOffset, 0.66f, 0.20f, true);
        add("PlayerWeapons.StunGun.Generic.Muzzle_00", baseOffset + Vec3(0.0f, 0.04f, 0.02f), 0.80f, 0.16f, true);
        add("Characters.Aliens.Nightmare.Fear.FearCastAOE_00.lightPop", baseOffset, 0.45f, 0.12f, true);
        break;
    case CoopProtocol::kPlayerPoseWeaponClassLaser:
        add("PlayerWeapons.InstaLaser.EndOfBeamGlow_00", baseOffset, 0.80f, baseDuration, true);
        add("LevelSpecific.Psychotronics.QLaserBeam_00", baseOffset + Vec3(0.0f, 0.08f, 0.00f), 0.85f, baseDuration, true, false, 0.77f);
        break;
    default:
        add(GetProxyWeaponMuzzleEffectName(weaponClass), baseOffset, baseScale, baseDuration, weaponClass != CoopProtocol::kPlayerPoseWeaponClassPistol);
        break;
    }

    return layers;
}

