uint16_t ClassifyPosePsiFxKind(EArkPsiPowers power)
{
    switch (power)
    {
    case EArkPsiPowers::kineticBlast:
        return CoopProtocol::kPlayerPosePsiFxKinetic;
    case EArkPsiPowers::kineticShield:
        return CoopProtocol::kPlayerPosePsiFxNullwave;
    case EArkPsiPowers::thermalBlast:
        return CoopProtocol::kPlayerPosePsiFxThermal;
    case EArkPsiPowers::electrostaticBurst:
    case EArkPsiPowers::cyberkinesis:
        return CoopProtocol::kPlayerPosePsiFxElectric;
    case EArkPsiPowers::lift:
        return CoopProtocol::kPlayerPosePsiFxKinetic;
    case EArkPsiPowers::remoteManipulation:
        return CoopProtocol::kPlayerPosePsiFxMind;
    case EArkPsiPowers::fear:
    case EArkPsiPowers::mindBlast:
    case EArkPsiPowers::hypnosis:
        return CoopProtocol::kPlayerPosePsiFxMind;
    case EArkPsiPowers::shift:
    case EArkPsiPowers::smokeForm:
        return CoopProtocol::kPlayerPosePsiFxShift;
    case EArkPsiPowers::mimic:
        return CoopProtocol::kPlayerPosePsiFxMimic;
    case EArkPsiPowers::combatFocus:
    case EArkPsiPowers::createPhantom:
        return CoopProtocol::kPlayerPosePsiFxNullwave;
    default:
        return CoopProtocol::kPlayerPosePsiFxGeneric;
    }
}

