bool ShouldEmitPosePsiImpact(uint16_t psiFxKind)
{
    return
        psiFxKind == CoopProtocol::kPlayerPosePsiFxKinetic ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxThermal ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxElectric ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxMind ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxShift ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxNullwave ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxMimic ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxThermalTrigger ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxShiftDuplicate ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxShiftArrive;
}

float ResolvePosePsiImpactImpulseSeconds(uint16_t psiFxKind)
{
    if (psiFxKind == CoopProtocol::kPlayerPosePsiFxThermal ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxThermalTrigger)
    {
        return 1.15f;
    }
    if (psiFxKind == CoopProtocol::kPlayerPosePsiFxShift ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxShiftDuplicate ||
        psiFxKind == CoopProtocol::kPlayerPosePsiFxShiftArrive)
    {
        return 0.85f;
    }
    if (psiFxKind == CoopProtocol::kPlayerPosePsiFxElectric)
        return 0.80f;
    return 0.65f;
}

Vec3 NormalizeDirectionOr(const Vec3& value, const Vec3& fallback)
{
    const float lengthSq = value.GetLengthSquared();
    if (lengthSq <= 0.0001f)
        return fallback;

    return value * (1.0f / std::sqrt(lengthSq));
}

Vec3 GetProxyLocalMuzzleDirection(IEntity& proxyEntity, const Vec3* worldAimDirection)
{
    if (!worldAimDirection)
        return Vec3(0.0f, 1.0f, 0.0f);

    const Vec3 normalizedWorldDirection = NormalizeDirectionOr(*worldAimDirection, Vec3(0.0f, 1.0f, 0.0f));
    const Vec3 localDirection = proxyEntity.GetWorldRotation().GetInverted() * normalizedWorldDirection;
    return NormalizeDirectionOr(localDirection, Vec3(0.0f, 1.0f, 0.0f));
}

float ClampProxyFxDuration(float duration)
{
    return std::clamp(duration, 0.02f, 3.0f);
}

