class ModMain::CoopEntitySystemSink final : public IEntitySystemSink
{
public:
    explicit CoopEntitySystemSink(ModMain& owner)
        : m_owner(owner)
    {
    }

    bool OnBeforeSpawn(SEntitySpawnParams& params) override
    {
        return !m_owner.ShouldRejectCoopRuntimeEntitySpawn(params);
    }

    void OnSpawn(IEntity* entity, SEntitySpawnParams& params) override
    {
        if (entity)
            m_owner.OnCoopRuntimeEntitySpawned(*entity, params, "IEntitySystemSink::OnSpawn");
    }

    bool OnRemove(IEntity* entity) override
    {
        if (entity)
            m_owner.OnCoopRuntimeEntityRemoved(*entity);

        return true;
    }

    void OnReused(IEntity* entity, SEntitySpawnParams& params) override
    {
        if (entity)
            m_owner.OnCoopRuntimeEntitySpawned(*entity, params, "IEntitySystemSink::OnReused");
    }

    void OnEvent(IEntity* entity, SEntityEvent& event) override
    {
        if (entity)
            m_owner.OnCoopRuntimeEntityEvent(*entity, event);
    }

private:
    ModMain& m_owner;
};

