void ModMain::AppendEnemySyncTrace(const char* channel, const std::string& event)
{
    std::ostringstream out;
    out
        << "#" << (++m_enemySyncTraceSerial)
        << ":" << (channel && channel[0] ? channel : "-")
        << ":" << StatusToken(event.empty() ? std::string("-") : event);

    m_enemySyncTrace.push_back(out.str());
    while (m_enemySyncTrace.size() > 256)
        m_enemySyncTrace.pop_front();
}

void ModMain::RecordRuntimeLogEmission()
{
    m_runtimeLogEmissions.fetch_add(1, std::memory_order_relaxed);
}

void ModMain::RecordRuntimeTransformHook(bool rewritten)
{
    if (rewritten)
        ++m_runtimeTransformRewrites;
    else
        ++m_runtimeTransformHookCalls;
}

void ModMain::RecordRuntimeEntityScan(uint64_t candidatesVisited, uint64_t elapsedMicroseconds)
{
    ++m_runtimeEntityScanCalls;
    m_runtimeEntityScanCandidates += candidatesVisited;
    m_runtimeEntityScanTotalMicroseconds += elapsedMicroseconds;
    m_runtimeEntityScanMaxMicroseconds = std::max(m_runtimeEntityScanMaxMicroseconds, elapsedMicroseconds);
}

void ModMain::ResetRuntimeCostTelemetry()
{
    CoopRuntimeLog::ResetRateLimits();
    m_runtimeLogEmissions.store(0, std::memory_order_relaxed);
    m_runtimeTransformHookCalls = 0;
    m_runtimeTransformRewrites = 0;
    m_runtimeEntityScanCalls = 0;
    m_runtimeEntityScanCandidates = 0;
    m_runtimeEntityScanTotalMicroseconds = 0;
    m_runtimeEntityScanMaxMicroseconds = 0;
}

std::string ModMain::BuildRuntimeCostReport() const
{
    std::ostringstream out;
    out << "logs=" << m_runtimeLogEmissions.load(std::memory_order_relaxed)
        << ",logSuppressed=" << CoopRuntimeLog::SuppressedCount()
        << ",xformHooks=" << m_runtimeTransformHookCalls
        << ",xformRewrites=" << m_runtimeTransformRewrites
        << ",entityScans=" << m_runtimeEntityScanCalls
        << ",scanCandidates=" << m_runtimeEntityScanCandidates
        << ",scanUs=" << m_runtimeEntityScanTotalMicroseconds
        << ",scanMaxUs=" << m_runtimeEntityScanMaxMicroseconds
        << ",boxHooks=" << m_physicalWorldBoxHookCalls
        << ",boxHuge=" << m_physicalWorldBoxHookHugeQueries
        << ",mannequin=" << m_npcMannequinConstructTraceCount
        << ",semantic=" << m_npcSemanticTraceCount;

    // Windows-only cost centers: guarded callbacks (SEH + VirtualQuery) and
    // per-hook self-profiling. See the issue #2 investigation notes.
    const CoopRuntimeGuards::GuardTelemetryTotals guardTotals =
        CoopRuntimeGuards::GetGuardTelemetryTotals();
    out << ",guardCallsNs=" << guardTotals.guardedCallTotalNs
        << ",virtualQueries=" << guardTotals.virtualQueryCalls;

    const std::string hookStats = CoopHookStats::BuildReport();
    if (!hookStats.empty())
        out << ",hookStats=" << hookStats;
    return out.str();
}

void ModMain::ClearEnemySyncTrace(const char* reason)
{
    m_enemySyncTrace.clear();
    m_enemySyncTraceSerial = 0;
    m_lastEnemyMannequinStateEvent =
        std::string("enemy_trace_reset reason=") +
        StatusToken(reason && reason[0] ? std::string(reason) : std::string("-"));
}

std::string ModMain::BuildEnemySyncTraceTail(size_t maxEntries) const
{
    if (m_enemySyncTrace.empty())
        return "-";

    maxEntries = std::max<size_t>(1, std::min<size_t>(maxEntries, m_enemySyncTrace.size()));
    const size_t first = m_enemySyncTrace.size() - maxEntries;

    std::string out;
    for (size_t i = first; i < m_enemySyncTrace.size(); ++i)
    {
        if (!out.empty())
            out += "|";
        out += m_enemySyncTrace[i];
    }
    return out.empty() ? std::string("-") : out;
}

void ModMain::RecordNpcSemanticTrace(
    const char* stage,
    ArkNpc* npc,
    uint64_t contextId,
    EntityId targetId,
    uint32_t flags,
    const char* detail)
{
    if (!IsSessionGameplayReady())
        return;

    EntityId entityId = INVALID_ENTITYID;
    const char* entityName = "-";
    std::string guardReason;

    if (npc && CoopRuntimeGuards::IsLikelyRuntimeCppObject(npc, sizeof(void*) * 4))
    {
        TryGuardedCall("npc semantic GetEntityId", [npc]() { return npc->GetEntityId(); }, entityId, &guardReason);
    }

    if (gEnv && gEnv->pEntitySystem && entityId != INVALID_ENTITYID)
    {
        if (IEntity* entity = gEnv->pEntitySystem->GetEntity(entityId))
        {
            if (entity->GetName())
                entityName = entity->GetName();
        }
    }

    if (entityId == INVALID_ENTITYID)
        ++m_npcSemanticTraceFailures;
    else
        ++m_npcSemanticTraceCount;

    std::ostringstream out;
    out
        << "npc_semantic"
        << " stage=" << (stage && stage[0] ? stage : "-")
        << " entity=" << entityId
        << " entityName=" << (entityName && entityName[0] ? entityName : "-")
        << " context=" << contextId
        << " target=" << targetId
        << " flags=" << flags;
    if (detail && detail[0])
        out << " detail=" << StatusToken(detail);
    if (!guardReason.empty())
        out << " guard=" << StatusToken(guardReason);

    m_lastNpcSemanticTraceEvent = out.str();
    AppendEnemySyncTrace("semantic", m_lastNpcSemanticTraceEvent);
    if (EnvFlagEnabled("COOP_TRACE_NPC_SEMANTIC_LOGS"))
        LogCoop(m_lastNpcSemanticTraceEvent);

    if (!gEnv || !gEnv->pEntitySystem || entityId == INVALID_ENTITYID)
        return;

    IEntity* entity = gEnv->pEntitySystem->GetEntity(entityId);
    if (!entity || !EntityUtils::GetArkNpc(entity))
        return;

    const std::string_view stageView(stage && stage[0] ? stage : "");
    const bool beforeStage = stageView.find(":before") != std::string_view::npos;
    const bool afterStage = stageView.find(":after") != std::string_view::npos;
    const bool tryPerformAbilityContext =
        contextId != 0 &&
        stageView.find("TryPerformAbilityContext") != std::string_view::npos;
    if (tryPerformAbilityContext && (beforeStage || afterStage))
    {
        EnemyAuthorityState& state = EnsureEnemyAuthorityState(*entity);
        const bool localIsAuthority =
            (m_networkMode == CoopNetworkMode::Host &&
                (!state.remoteLocomotionAuthority || state.localAttentionClaimed)) ||
            (m_networkMode == CoopNetworkMode::Client && state.localAttentionClaimed);
        if (localIsAuthority)
        {
            uint8_t variant = 0;
            if (stageView.find("TryPerformAbilityContext1") != std::string_view::npos)
                variant = 1;
            else if (stageView.find("TryPerformAbilityContext2") != std::string_view::npos)
                variant = 2;
            else if (stageView.find("TryPerformAbilityContext3") != std::string_view::npos)
                variant = 3;

            const float nowSeconds = gEnv && gEnv->pTimer
                ? gEnv->pTimer->GetAsyncCurTime()
                : 0.0f;
            const auto armPendingContext = [&]()
            {
                state.pendingSemanticContextId = contextId;
                state.pendingSemanticTargetEntityId = targetId;
                state.pendingSemanticVariant = variant;
                state.pendingSemanticObservedAtSeconds = nowSeconds;
                state.pendingSemanticAction = nullptr;
                state.pendingSemanticFragmentId = -1;
            };
            const auto clearPendingContext = [&]()
            {
                state.pendingSemanticContextId = 0;
                state.pendingSemanticTargetEntityId = INVALID_ENTITYID;
                state.pendingSemanticVariant = 0;
                state.pendingSemanticObservedAtSeconds = -1000.0f;
                state.pendingSemanticAction = nullptr;
                state.pendingSemanticFragmentId = -1;
            };

            if (beforeStage)
            {
                // Arm before entering Vanilla so synchronous actions bind to
                // the fragment they actually start. Nested overload wrappers
                // preserve the outermost variant/target instead of rearming.
                const bool nestedSameContext =
                    state.pendingSemanticContextId == contextId &&
                    nowSeconds - state.pendingSemanticObservedAtSeconds >= -0.01f &&
                    nowSeconds - state.pendingSemanticObservedAtSeconds <= 0.10f;
                if (!nestedSameContext)
                    armPendingContext();
                AppendEnemySyncTrace(
                    "semantic_context",
                    "authority_semantic_context_armed net=" + std::to_string(state.netId) +
                        " entity=" + std::to_string(entityId) +
                        " context=" + std::to_string(contextId) +
                        " variant=" + std::to_string(state.pendingSemanticVariant) +
                        " target=" + std::to_string(state.pendingSemanticTargetEntityId));
            }
            else if (flags == 0)
            {
                if (state.pendingSemanticContextId == contextId)
                    clearPendingContext();
            }
            else
            {
                const bool boundSynchronously =
                    state.localSemanticContextId == contextId &&
                    state.localSemanticSequence != 0 &&
                    nowSeconds - state.localSemanticBoundAtSeconds >= -0.01f &&
                    nowSeconds - state.localSemanticBoundAtSeconds <= 0.10f;
                if (boundSynchronously)
                {
                    if (state.pendingSemanticContextId == contextId)
                        clearPendingContext();
                }
                else if (state.pendingSemanticContextId != contextId)
                {
                    // Some abilities queue their Mannequin action after the
                    // wrapper returns. Keep a short pending envelope for that
                    // asynchronous native start.
                    armPendingContext();
                }
                if (!boundSynchronously &&
                    state.pendingSemanticContextId == contextId &&
                    contextId == CoopProtocol::kEnemyAbilityContextMilitaryOperatorSwipe)
                {
                    // Extracted/runtime-proven Operator Swipe owns a native
                    // laser helper but no Mannequin action.
                    state.pendingSemanticFragmentId = kPendingSemanticExactNoFragment;
                }
                AppendEnemySyncTrace(
                    "semantic_context",
                    std::string(boundSynchronously
                        ? "authority_semantic_context_bound_during_call net="
                        : "authority_semantic_context_pending net=") +
                        std::to_string(state.netId) +
                        " entity=" + std::to_string(entityId) +
                        " context=" + std::to_string(contextId) +
                        " variant=" + std::to_string(boundSynchronously
                            ? state.localSemanticVariant
                            : state.pendingSemanticVariant) +
                        " target=" + std::to_string(targetId));
            }
        }
    }

    const bool failedAfterStage = afterStage && flags == 0 &&
        (stageView.find("TryPerformAbilityContext") != std::string_view::npos ||
            stageView.find("TryEvaluateAndPerformAbilityContext") != std::string_view::npos ||
            stageView.find("MimicEntity") != std::string_view::npos ||
            stageView.find("EndMimicry") != std::string_view::npos);
    if (failedAfterStage)
        return;

    if (afterStage && flags != 0 &&
        (stageView.find("PerformUnanimatedAbility") != std::string_view::npos ||
            stageView.find("PerformHitReactShift") != std::string_view::npos))
    {
        EnemyAuthorityState& state = EnsureEnemyAuthorityState(*entity);
        const bool localIsAuthority =
            (m_networkMode == CoopNetworkMode::Host &&
                (!state.remoteLocomotionAuthority || state.localAttentionClaimed)) ||
            (m_networkMode == CoopNetworkMode::Client && state.localAttentionClaimed);
        if (localIsAuthority && state.pendingSemanticContextId != 0)
        {
            // Vanilla completed a body-state ability without constructing a
            // Mannequin action. Mark that native outcome explicitly so the
            // exact context can be sent on the next state tick.
            state.pendingSemanticFragmentId =
                stageView.find("PerformHitReactShift") != std::string_view::npos
                    ? kPendingSemanticExactHitReactShiftBody
                    : kPendingSemanticExactUnanimatedBody;
            AppendEnemySyncTrace(
                "semantic_context",
                "authority_native_fragmentless_confirmed net=" + std::to_string(state.netId) +
                    " entity=" + std::to_string(entityId) +
                    " context=" + std::to_string(state.pendingSemanticContextId) +
                    " variant=" + std::to_string(state.pendingSemanticVariant) +
                    " stage=" + std::string(stageView));
        }
        return;
    }

    if (CoopEnemyIntentGate::IsAuthorityLocomotionAbilityContext(contextId))
    {
        // These contexts select Vanilla movement (for example the Operator
        // strafe contexts 1005/1006). They must never be replayed through
        // the observer's ability manager because that would create a second AI
        // path. Preserve the exact authority decision as a short presentation
        // envelope when it did not already construct a concrete Mannequin
        // action, so the mirror can prove and consume the same action identity.
        if (tryPerformAbilityContext && afterStage && flags != 0)
        {
            EnemyAuthorityState& state = EnsureEnemyAuthorityState(*entity);
            const bool localIsAuthority =
                (m_networkMode == CoopNetworkMode::Host &&
                    (!state.remoteLocomotionAuthority || state.localAttentionClaimed)) ||
                (m_networkMode == CoopNetworkMode::Client && state.localAttentionClaimed);
            uint8_t variant = 0;
            if (stageView.find("TryPerformAbilityContext1") != std::string_view::npos)
                variant = 1;
            else if (stageView.find("TryPerformAbilityContext2") != std::string_view::npos)
                variant = 2;
            else if (stageView.find("TryPerformAbilityContext3") != std::string_view::npos)
                variant = 3;

            const float nowSeconds = gEnv && gEnv->pTimer
                ? gEnv->pTimer->GetAsyncCurTime()
                : 0.0f;
            const bool concreteActionBound =
                state.localSemanticContextId == contextId &&
                state.localSemanticSequence != 0 &&
                nowSeconds - state.localSemanticBoundAtSeconds >= -0.01f &&
                nowSeconds - state.localSemanticBoundAtSeconds <= 0.15f;
            const bool outermostSuccessfulCall =
                state.pendingSemanticContextId == contextId &&
                state.pendingSemanticVariant == variant;
            if (localIsAuthority && !concreteActionBound && outermostSuccessfulCall)
            {
                state.localLocomotionSemanticSequence =
                    CoopSerialSequence::Advance(state.localAuthoritySemanticSequence);
                state.localLocomotionSemanticContextId = contextId;
                state.localLocomotionSemanticVariant = variant;
                state.localLocomotionSemanticSeconds = 0.55f;
                state.localLocomotionSemanticLastContextId = contextId;
                state.localLocomotionSemanticLastSequence = state.localLocomotionSemanticSequence;
                state.localLocomotionSemanticLastVariant = variant;
                state.pendingSemanticContextId = 0;
                state.pendingSemanticTargetEntityId = INVALID_ENTITYID;
                state.pendingSemanticVariant = 0;
                state.pendingSemanticObservedAtSeconds = -1000.0f;
                state.pendingSemanticAction = nullptr;
                state.pendingSemanticFragmentId = -1;
                AppendEnemySyncTrace(
                    "semantic_locomotion",
                    "authority_locomotion_semantic net=" + std::to_string(state.netId) +
                        " entity=" + std::to_string(entityId) +
                        " context=" + std::to_string(contextId) +
                        " variant=" + std::to_string(variant) +
                        " seq=" + std::to_string(state.localLocomotionSemanticSequence) +
                        " route=presentation_only");
            }
        }
        m_lastEnemyMannequinStateEvent =
            "semantic_authority_locomotion_context entity=" + std::to_string(entityId) +
            " context=" + std::to_string(contextId) +
            " stage=" + std::string(stageView) +
            " reason=movement_desire_and_mannequin_hooks_own_replication";
        AppendEnemySyncTrace("authority_mannequin", m_lastEnemyMannequinStateEvent);
        return;
    }

    // Semantic callbacks are metadata only. The observer mirrors the exact
    // authority-created native action through its Start/Exit lifecycle; it must
    // never translate a callback name into a guessed fragment or invoke a
    // second local AI/ability path.
}

