// Some streamed ArkDoor instances are not returned by QueryExtension after a
// save load even though their native door hooks remain active. Keep the exact
// complete object observed by those hooks so GUID-targeted replay can still
// resolve that authored door (notably Arboretum's Loading Bay door).
static std::unordered_map<EntityId, ArkDoor*> s_observedArkDoors;

static void RememberObservedArkDoor(ArkDoor* door)
{
    if (!door)
        return;
    IEntity* entity = nullptr;
    EntityId entityId = INVALID_ENTITYID;
    if (TryGuardedCall("remember observed ArkDoor entity", [door]() { return door->GetEntity(); }, entity, nullptr) &&
        entity &&
        TryGuardedCall("remember observed ArkDoor id", [entity]() { return entity->GetId(); }, entityId, nullptr) &&
        entityId != INVALID_ENTITYID)
    {
        s_observedArkDoors[entityId] = door;
    }
}
