using PhysicalWorldGetEntitiesInBoxFn = int (*)(IPhysicalWorld* world, Vec3 ptmin, Vec3 ptmax, IPhysicalEntity**& pList, int objtypes, int szListPrealloc);
constexpr size_t kIPhysicalWorldGetEntitiesInBoxVtableIndex = 34;
static_assert(kIPhysicalWorldGetEntitiesInBoxVtableIndex < CoopVTableHook::kHookableMethodCount);
static CoopVTableHook s_physicalWorldVTableHook;
static IPhysicalWorld* s_hookedPhysicalWorld = nullptr;
static PhysicalWorldGetEntitiesInBoxFn s_originalPhysicalWorldGetEntitiesInBox = nullptr;

static int PhysicalWorld_GetEntitiesInBox_Hook(
    IPhysicalWorld* world,
    Vec3 ptmin,
    Vec3 ptmax,
    IPhysicalEntity**& pList,
    int objtypes,
    int szListPrealloc)
{
    if (gMod)
        gMod->OnPhysicalWorldGetEntitiesInBoxHook(ptmin, ptmax, objtypes, szListPrealloc);

    if (s_originalPhysicalWorldGetEntitiesInBox)
        return s_originalPhysicalWorldGetEntitiesInBox(world, ptmin, ptmax, pList, objtypes, szListPrealloc);

    return 0;
}

static EntityId ResolveNpcEntityIdForLifecycleTrace(ArkNpc* npc)
{
    if (!npc)
        return INVALID_ENTITYID;

    IEntity* entity = nullptr;
    std::string reason;
    if (!TryGuardedCall("native lifecycle ArkNpc::GetEntity", [npc]() -> IEntity* { return npc->GetEntity(); }, entity, &reason) ||
        !entity)
    {
        return INVALID_ENTITYID;
    }

    EntityId entityId = INVALID_ENTITYID;
    if (!TryGuardedCall("native lifecycle ArkNpc entity GetId", [entity]() { return entity->GetId(); }, entityId, &reason))
        return INVALID_ENTITYID;
    return entityId;
}

static EntityId ResolveRecyclerGrenadeEntityId(CArkProjectileRecyclerGrenade* grenade)
{
    if (!grenade)
        return INVALID_ENTITYID;

    IEntity* entity = nullptr;
    std::string reason;
    if (!TryGuardedCall("recycler grenade GetEntity", [grenade]() -> IEntity* { return grenade->GetEntity(); }, entity, &reason) ||
        !entity)
    {
        return INVALID_ENTITYID;
    }

    EntityId entityId = INVALID_ENTITYID;
    if (!TryGuardedCall("recycler grenade entity GetId", [entity]() { return entity->GetId(); }, entityId, &reason))
        return INVALID_ENTITYID;
    return entityId;
}

static EntityId ResolveProjectileEntityId(CArkProjectile* projectile, const char* label)
{
    if (!projectile)
        return INVALID_ENTITYID;

    IEntity* entity = nullptr;
    std::string reason;
    if (!TryGuardedCall(label && label[0] ? label : "projectile GetEntity", [projectile]() -> IEntity* { return projectile->GetEntity(); }, entity, &reason) ||
        !entity)
    {
        return INVALID_ENTITYID;
    }

    EntityId entityId = INVALID_ENTITYID;
    if (!TryGuardedCall("projectile entity GetId", [entity]() { return entity->GetId(); }, entityId, &reason))
        return INVALID_ENTITYID;
    return entityId;
}

static std::string BuildGooSpawnParametersDetail(const CArkProjectileGoo::ArkGooSpawnParameters& params, const char* extra)
{
    std::ostringstream detail;
    if (extra && extra[0])
        detail << extra << ' ';
    detail
        << "projectile=" << params.m_projectileId
        << " spawner=" << params.m_spawnerId
        << " owner=" << params.m_ownerId
        << " weapon=" << StatusToken(params.m_weaponClassName.c_str())
        << " hitPhys=" << params.m_hitPhysicsId
        << " attachedPhys=" << params.m_attachedPhysicsId
        << " part=" << params.m_partId
        << " surface=" << params.m_surfaceIndex
        << " terrain=" << (params.m_bTerrain ? 1 : 0)
        << " final=" << StatusToken(FormatVec3Trace(params.m_finalPoint))
        << " dir=" << StatusToken(FormatVec3Trace(params.m_spawnDirection))
        << " size=" << params.m_spawnSize
        << " speedScale=" << params.m_speedScale;
    return detail.str();
}

static std::string BuildGooProjectileDetail(CArkProjectileGoo* goo, const char* extra)
{
    std::ostringstream detail;
    if (extra && extra[0])
        detail << extra;

    if (goo)
    {
        std::string reason;
        uint32_t state = 0;
        Vec3 finalPosition(ZERO);
        float currentScale = 0.0f;
        int staticPhysicsId = -1;
        int attachedPhysicsId = -1;
        int attachedPartId = -1;
        int surfaceIndex = -1;
        int gooNetworkId = -1;
        bool isStatic = false;
        bool attachedTerrain = false;
        if (TryGuardedCall("goo projectile read state", [goo]() -> uint32_t { return static_cast<uint32_t>(goo->m_state); }, state, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "state=" << state;
        if (TryGuardedCall("goo projectile read final position", [goo]() -> Vec3 { return goo->m_finalPosition; }, finalPosition, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "final=" << StatusToken(FormatVec3Trace(finalPosition));
        if (TryGuardedCall("goo projectile read scale", [goo]() -> float { return goo->m_currentScale; }, currentScale, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "scale=" << currentScale;
        if (TryGuardedCall("goo projectile read static physics id", [goo]() -> int { return goo->m_staticPhysicsId; }, staticPhysicsId, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "staticPhys=" << staticPhysicsId;
        if (TryGuardedCall("goo projectile read attached physics id", [goo]() -> int { return goo->m_attachedPhysicsId; }, attachedPhysicsId, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "attachedPhys=" << attachedPhysicsId;
        if (TryGuardedCall("goo projectile read attached part", [goo]() -> int { return goo->m_attachedPartId; }, attachedPartId, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "part=" << attachedPartId;
        if (TryGuardedCall("goo projectile read surface", [goo]() -> int { return goo->m_surfaceIndex; }, surfaceIndex, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "surface=" << surfaceIndex;
        if (TryGuardedCall("goo projectile read network id", [goo]() -> int { return goo->m_gooNetworkId; }, gooNetworkId, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "gooNet=" << gooNetworkId;
        if (TryGuardedCall("goo projectile read is static", [goo]() -> bool { return goo->m_bIsStatic; }, isStatic, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "isStatic=" << (isStatic ? 1 : 0);
        if (TryGuardedCall("goo projectile read terrain", [goo]() -> bool { return goo->m_bAttachedTerrain; }, attachedTerrain, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "terrain=" << (attachedTerrain ? 1 : 0);
        if (!reason.empty())
            detail << (detail.tellp() > 0 ? " " : "") << "guard=" << StatusToken(reason);
    }

    return detail.str();
}

static void ForceEntityRenderable(IEntity& entity)
{
    entity.Hide(false);
    entity.Invisible(false);

    const int slotCount = entity.GetSlotCount();
    for (int slot = 0; slot < slotCount; ++slot)
    {
        if (!entity.IsSlotValid(slot))
            continue;

        const uint32_t flags = entity.GetSlotFlags(slot);
        entity.SetSlotFlags(slot, flags | static_cast<uint32_t>(ENTITY_SLOT_RENDER));
    }
}

static void ForceGooEntityRenderable(IEntity* entity)
{
    if (!entity)
        return;

    ForceEntityRenderable(*entity);
}

static bool IsValidGooSpawnParameters(const CArkProjectileGoo::ArkGooSpawnParameters& params)
{
    return IsFiniteVec3Trace(params.m_finalPoint) &&
        IsFiniteVec3Trace(params.m_spawnDirection) &&
        params.m_spawnSize > 0.001f;
}

static std::string BuildGooBallDetail(CArkProjectileGooBall* ball, const char* extra)
{
    std::ostringstream detail;
    if (extra && extra[0])
        detail << extra;

    if (ball)
    {
        std::string reason;
        bool spawnGoo = false;
        int numBounces = 0;
        int numBouncesAllowed = 0;
        int modelNum = 0;
        bool pooled = false;
        EntityId ownerId = INVALID_ENTITYID;
        CArkProjectileGoo::ArkGooSpawnParameters params;

        if (TryGuardedCall("goo ball read spawn flag", [ball]() -> bool { return ball->m_bSpawnGoo; }, spawnGoo, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "spawnGoo=" << (spawnGoo ? 1 : 0);
        if (TryGuardedCall("goo ball read bounces", [ball]() -> int { return ball->m_numBounces; }, numBounces, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "bounces=" << numBounces;
        if (TryGuardedCall("goo ball read bounces allowed", [ball]() -> int { return ball->m_numBouncesAllowed; }, numBouncesAllowed, &reason))
            detail << "/" << numBouncesAllowed;
        if (TryGuardedCall("goo ball read model", [ball]() -> int { return ball->m_modelNum; }, modelNum, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "model=" << modelNum;
        if (TryGuardedCall("goo ball read pooled", [ball]() -> bool { return ball->m_bAmmoIsPooled; }, pooled, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "pooled=" << (pooled ? 1 : 0);
        if (TryGuardedCall("goo ball read owner", [ball]() -> EntityId { return static_cast<EntityId>(ball->m_ownerId); }, ownerId, &reason))
            detail << (detail.tellp() > 0 ? " " : "") << "owner=" << ownerId;
        if (TryGuardedCall("goo ball read params", [ball]() -> CArkProjectileGoo::ArkGooSpawnParameters { return ball->m_spawnParameters; }, params, &reason))
        {
            detail
                << (detail.tellp() > 0 ? " " : "")
                << "valid=" << (IsValidGooSpawnParameters(params) ? 1 : 0)
                << " params=" << StatusToken(BuildGooSpawnParametersDetail(params, nullptr));
        }
        if (!reason.empty())
            detail << (detail.tellp() > 0 ? " " : "") << "guard=" << StatusToken(reason);
    }

    return detail.str();
}

static void MaybeQueueGooBallResult(CArkProjectileGooBall* ball, const char* reason)
{
    if (!gMod || !ball)
        return;

    bool spawnGoo = false;
    CArkProjectileGoo::ArkGooSpawnParameters params;
    std::string guardReason;
    const bool readOk =
        TryGuardedCall("goo ball queue read spawn flag", [ball]() -> bool { return ball->m_bSpawnGoo; }, spawnGoo, &guardReason) &&
        TryGuardedCall("goo ball queue read params", [ball]() -> CArkProjectileGoo::ArkGooSpawnParameters { return ball->m_spawnParameters; }, params, &guardReason);

    const EntityId projectileId = ResolveProjectileEntityId(ball, "goo ball result GetEntity");
    if (!readOk || !spawnGoo || !IsValidGooSpawnParameters(params))
    {
        if (EnvFlagEnabled("COOP_TRACE_GOO_PROJECTILE_ALL"))
        {
            const std::string detail =
                BuildGooBallDetail(ball, (std::string(reason && reason[0] ? reason : "-") +
                    " queue=skip" +
                    (guardReason.empty() ? std::string() : " guard=" + StatusToken(guardReason))).c_str());
            gMod->RecordGooProjectileTrace(
                "GooBall queue skip",
                projectileId,
                params.m_ownerId,
                spawnGoo ? 1u : 0u,
                detail.c_str());
        }
        return;
    }

    EntityId sourceProjectileId = projectileId;
    if (sourceProjectileId == INVALID_ENTITYID && params.m_projectileId != 0)
        sourceProjectileId = static_cast<EntityId>(params.m_projectileId);
    if (sourceProjectileId == INVALID_ENTITYID)
    {
        gMod->RecordGooProjectileTrace(
            "GooBall result skipped",
            INVALID_ENTITYID,
            params.m_ownerId,
            0u,
            "missing projectile entity id");
        return;
    }

    if (!CoopRuntimeConfig::UnsafeFlag("COOP_ENABLE_GOO_RESULT_FROM_GOOBALL"))
    {
        if (EnvFlagEnabled("COOP_TRACE_GOO_PROJECTILE_ALL"))
        {
            gMod->RecordGooProjectileTrace(
                "GooBall result skipped",
                sourceProjectileId,
                static_cast<EntityId>(params.m_ownerId),
                params.m_bTerrain ? 1u : 0u,
                "reason=waiting_for_native_try_to_spawn");
        }
        return;
    }

    EntityId ownerId = static_cast<EntityId>(params.m_ownerId);
    if (ownerId == INVALID_ENTITYID || ownerId == 0)
        ownerId = static_cast<EntityId>(ball->m_ownerId);

    if (EnvFlagEnabled("COOP_DISABLE_GOO_RESULT_FROM_GOOBALL"))
    {
        if (EnvFlagEnabled("COOP_TRACE_GOO_PROJECTILE_ALL"))
        {
            gMod->RecordGooProjectileTrace(
                "GooBall result skipped",
                sourceProjectileId,
                ownerId,
                params.m_bTerrain ? 1u : 0u,
                "reason=disabled_by_env");
        }
        return;
    }

    if (!gMod->MarkLocalGooResultSource(sourceProjectileId, reason))
        return;

    gMod->RecordGooProjectileTrace(
        "GooBall result",
        sourceProjectileId,
        ownerId,
        params.m_bTerrain ? 1u : 0u,
        BuildGooBallDetail(ball, reason).c_str());
    gMod->QueueLocalGooResultForHook(
        sourceProjectileId,
        ownerId,
        params.m_finalPoint,
        params.m_spawnDirection,
        params.m_spawnSize,
        params.m_hitPhysicsId,
        params.m_attachedPhysicsId,
        params.m_partId,
        params.m_surfaceIndex,
        params.m_bTerrain ? CoopProtocol::kGooResultFlagTerrain : 0u,
        reason);
}

static CArkProjectileGoo* FindNearestProjectileGooForCoop(
    const Vec3& position,
    const float maxDistance,
    EntityId* outEntityId,
    std::string* outDetail)
{
    if (outEntityId)
        *outEntityId = INVALID_ENTITYID;
    if (!gEnv || !gEnv->pEntitySystem || !IsFiniteVec3Trace(position))
    {
        if (outDetail)
            *outDetail = "nearest_goo_unavailable";
        return nullptr;
    }

    IEntityIt* rawIterator = nullptr;
    std::string guardReason;
    if (!TryGuardedCall("nearest goo GetEntityIterator", []() { return gEnv->pEntitySystem->GetEntityIterator(); }, rawIterator, &guardReason) ||
        !rawIterator)
    {
        if (outDetail)
            *outDetail = "nearest_goo_iterator_failed_" + StatusToken(guardReason);
        return nullptr;
    }

    IEntityItPtr iterator = rawIterator;
    TryGuardedVoidCall("nearest goo MoveFirst", [&iterator]() { iterator->MoveFirst(); }, nullptr);

    CArkProjectileGoo* bestGoo = nullptr;
    EntityId bestEntityId = INVALID_ENTITYID;
    float bestDistanceSq = maxDistance * maxDistance;
    uint32_t scanned = 0;
    uint32_t gooCandidates = 0;
    while (true)
    {
        bool isEnd = false;
        if (TryGuardedCall("nearest goo IsEnd", [&iterator]() { return iterator->IsEnd(); }, isEnd, &guardReason) && isEnd)
            break;

        IEntity* entity = nullptr;
        if (!TryGuardedCall("nearest goo Next", [&iterator]() { return iterator->Next(); }, entity, &guardReason) ||
            !entity)
        {
            break;
        }

        ++scanned;
        EntityId entityId = INVALID_ENTITYID;
        TryGuardedCall("nearest goo entity id", [entity]() { return entity->GetId(); }, entityId, nullptr);
        if (entityId == INVALID_ENTITYID)
            continue;

        CArkProjectileGoo* goo = CArkProjectileGoo::GetProjectileGooFromEntityId(entityId);
        if (!goo)
            continue;

        ++gooCandidates;
        Vec3 gooPosition = entity->GetWorldPos();
        TryGuardedCall("nearest goo final position", [goo]() -> Vec3 { return goo->m_finalPosition; }, gooPosition, nullptr);
        if (!IsFiniteVec3Trace(gooPosition))
            gooPosition = entity->GetWorldPos();

        const float distanceSq = (gooPosition - position).GetLengthSquared();
        if (distanceSq <= bestDistanceSq)
        {
            bestDistanceSq = distanceSq;
            bestEntityId = entityId;
            bestGoo = goo;
        }
    }

    if (outEntityId)
        *outEntityId = bestEntityId;
    if (outDetail)
    {
        std::ostringstream detail;
        detail
            << "nearest_goo scanned=" << scanned
            << " candidates=" << gooCandidates
            << " best=" << bestEntityId
            << " dist=" << (bestGoo ? std::sqrt(std::max(0.0f, bestDistanceSq)) : -1.0f)
            << " pos=" << StatusToken(FormatVec3Trace(position));
        *outDetail = detail.str();
    }
    return bestGoo;
}

static std::string BuildRecyclerGrenadeDetail(CArkProjectileRecyclerGrenade* grenade, const char* extra)
{
    std::ostringstream detail;
    if (extra && extra[0])
        detail << extra;

    if (grenade)
    {
        std::string reason;
        uint32_t state = 0;
        if (TryGuardedCall(
                "recycler grenade read state",
                [grenade]() -> uint32_t { return static_cast<uint32_t>(grenade->m_state); },
                state,
                &reason))
        {
            if (detail.tellp() > 0)
                detail << " ";
            detail << "state=" << state;
        }
        else if (!reason.empty())
        {
            if (detail.tellp() > 0)
                detail << " ";
            detail << "guard=" << StatusToken(reason);
        }
    }

    return detail.str();
}

