static void* GetArkInteractiveObjectExtensionFromEntity(IEntity* entity)
{
    if (!entity || !gEnv || !gEnv->pGame)
        return nullptr;
    IGameFramework* framework = gEnv->pGame->GetIGameFramework();
    if (!framework)
        return nullptr;

    IGameObject* gameObject = nullptr;
    std::string reason;
    if (!TryGuardedCall(
            "interactive object extension GetGameObject",
            [framework, entity]() { return framework->GetGameObject(entity->GetId()); },
            gameObject,
            &reason) || !gameObject)
    {
        return nullptr;
    }

    IGameObjectExtension* extension = nullptr;
    IGameObjectSystem::ExtensionID extensionId = 0;
    if (TryGuardedCall(
            "interactive object extension GetExtensionId",
            [gameObject]() { return gameObject->GetExtensionId("ArkInteractiveObject"); },
            extensionId,
            &reason) && extensionId != 0 &&
        TryGuardedCall(
            "interactive object extension QueryExtension id",
            [gameObject, extensionId]() { return gameObject->QueryExtension(extensionId); },
            extension,
            &reason) && extension)
    {
        if (CoopPtrHygiene::Enabled())
        {
            char extra[96];
            std::snprintf(extra, sizeof(extra), "gameObject=0x%016llX",
                static_cast<unsigned long long>(reinterpret_cast<std::uintptr_t>(gameObject)));
            CoopPtrHygiene::LogPtrWith("interactive_ext", extension, extra);
            CoopPtrHygiene::CheckAbove32("interactive_ext", extension);
            CoopPtrHygiene::CheckAbove32("interactive_ext_gameobject", gameObject);
        }
        return extension;
    }

    extension = nullptr;
    if (TryGuardedCall(
            "interactive object extension QueryExtension name",
            [gameObject]() { return gameObject->QueryExtension("ArkInteractiveObject"); },
            extension,
            &reason) && extension)
    {
        if (CoopPtrHygiene::Enabled())
        {
            char extra[96];
            std::snprintf(extra, sizeof(extra), "gameObject=0x%016llX",
                static_cast<unsigned long long>(reinterpret_cast<std::uintptr_t>(gameObject)));
            CoopPtrHygiene::LogPtrWith("interactive_ext", extension, extra);
            CoopPtrHygiene::CheckAbove32("interactive_ext", extension);
            CoopPtrHygiene::CheckAbove32("interactive_ext_gameobject", gameObject);
        }
        return extension;
    }
    return nullptr;
}

static bool TryReadArkInteractiveObjectState(
    void* interactiveObject,
    size_t offset,
    bool& value,
    const char* label,
    std::string* reason)
{
    value = false;
    if (!interactiveObject || (offset != 0x50 && offset != 0x51))
        return false;
    uint8_t raw = 0;
    const bool ok = TryGuardedCall(
        label,
        [interactiveObject, offset]()
        {
            return *reinterpret_cast<const uint8_t*>(reinterpret_cast<uintptr_t>(interactiveObject) + offset);
        },
        raw,
        reason);
    value = raw != 0;
    return ok;
}

static IEntity* TryGetArkInteractiveObjectEntity(void* interactiveObject, const char* label, std::string* reason)
{
    IEntity* entity = nullptr;
    if (!interactiveObject)
        return nullptr;
    TryGuardedCall(
        label,
        [interactiveObject]()
        {
            return *reinterpret_cast<IEntity* const*>(reinterpret_cast<uintptr_t>(interactiveObject) + 0x38);
        },
        entity,
        reason);
    return entity;
}

static void* FindNearestArkInteractiveObjectForCoop(
    EntityId* outEntityId,
    uint64_t* outGuid,
    float* outDistance,
    std::string* outDetail)
{
    if (outEntityId)
        *outEntityId = INVALID_ENTITYID;
    if (outGuid)
        *outGuid = 0;
    if (outDistance)
        *outDistance = -1.0f;
    if (!gEnv || !gEnv->pEntitySystem || !ArkPlayer::GetInstancePtr() || !ArkPlayer::GetInstance().GetEntity())
        return nullptr;

    IEntityIt* rawIterator = nullptr;
    std::string reason;
    if (!TryGuardedCall(
            "nearest interactive object GetEntityIterator",
            []() { return gEnv->pEntitySystem->GetEntityIterator(); },
            rawIterator,
            &reason) || !rawIterator)
    {
        return nullptr;
    }

    IEntityItPtr iterator = rawIterator;
    TryGuardedVoidCall("nearest interactive object MoveFirst", [&iterator]() { iterator->MoveFirst(); }, nullptr);
    const Vec3 playerPos = ArkPlayer::GetInstance().GetEntity()->GetWorldPos();
    void* best = nullptr;
    EntityId bestEntityId = INVALID_ENTITYID;
    uint64_t bestGuid = 0;
    float bestDistanceSq = std::numeric_limits<float>::max();
    uint32_t scanned = 0;
    uint32_t candidates = 0;
    while (true)
    {
        bool isEnd = false;
        if (TryGuardedCall("nearest interactive object IsEnd", [&iterator]() { return iterator->IsEnd(); }, isEnd, &reason) && isEnd)
            break;
        IEntity* entity = nullptr;
        if (!TryGuardedCall("nearest interactive object Next", [&iterator]() { return iterator->Next(); }, entity, &reason) || !entity)
            break;
        ++scanned;
        void* interactiveObject = GetArkInteractiveObjectExtensionFromEntity(entity);
        if (!interactiveObject)
            continue;
        uint64_t guid = 0;
        TryGuardedCall("nearest interactive object GetGuid", [entity]() { return entity->GetGuid(); }, guid, nullptr);
        if (guid == 0)
            continue;
        ++candidates;
        const float distanceSq = (entity->GetWorldPos() - playerPos).GetLengthSquared();
        if (distanceSq >= bestDistanceSq)
            continue;
        bestDistanceSq = distanceSq;
        best = interactiveObject;
        bestGuid = guid;
        TryGuardedCall("nearest interactive object GetId", [entity]() { return entity->GetId(); }, bestEntityId, nullptr);
    }

    if (outEntityId)
        *outEntityId = bestEntityId;
    if (outGuid)
        *outGuid = bestGuid;
    if (outDistance)
        *outDistance = best ? std::sqrt(std::max(0.0f, bestDistanceSq)) : -1.0f;
    if (outDetail)
    {
        *outDetail =
            "nearest_interactive_object_scanned_" + std::to_string(scanned) +
            "_candidates_" + std::to_string(candidates) +
            "_id_" + std::to_string(bestEntityId) +
            "_guid_" + std::to_string(bestGuid);
    }
    return best;
}

