static EntityId ResolveAuthoredCargoDockingStationId(IEntity* cargoEntity, std::string* outReason = nullptr)
{
    if (!cargoEntity || !gEnv || !gEnv->pEntitySystem)
        return INVALID_ENTITYID;

    std::string localReason;
    std::string& reason = outReason ? *outReason : localReason;
    const EntityId cargoEntityId = cargoEntity->GetId();
    IEntityIt* rawIterator = nullptr;
    if (!TryGuardedCall(
            "cargo station resolver GetEntityIterator",
            []() { return gEnv->pEntitySystem->GetEntityIterator(); },
            rawIterator,
            &reason) ||
        !rawIterator)
    {
        return INVALID_ENTITYID;
    }

    IEntityItPtr iterator = rawIterator;
    TryGuardedVoidCall("cargo station resolver MoveFirst", [&iterator]() { iterator->MoveFirst(); }, &reason);
    while (true)
    {
        bool atEnd = false;
        if (!TryGuardedCall("cargo station resolver IsEnd", [&iterator]() { return iterator->IsEnd(); }, atEnd, &reason) || atEnd)
            break;

        IEntity* candidate = nullptr;
        if (!TryGuardedCall("cargo station resolver Next", [&iterator]() { return iterator->Next(); }, candidate, &reason) || !candidate)
            break;

        IEntityClass* entityClass = nullptr;
        const char* className = nullptr;
        if (!TryGuardedCall("cargo station resolver GetClass", [candidate]() { return candidate->GetClass(); }, entityClass, &reason) ||
            !entityClass ||
            !TryGuardedCall("cargo station resolver class GetName", [entityClass]() { return entityClass->GetName(); }, className, &reason) ||
            !className || std::strcmp(className, "ArkDockingStation") != 0)
        {
            continue;
        }

        if (ArkDockingStation* station = GetArkDockingStationExtensionFromEntity(candidate))
        {
            size_t containerCount = 0;
            if (TryGuardedCall(
                    "cargo station resolver container count",
                    [station]() { return station->m_containers.size(); },
                    containerCount,
                    &reason))
            {
                containerCount = std::min<size_t>(containerCount, 256);
                for (size_t index = 0; index < containerCount; ++index)
                {
                    EntityId linkedContainerId = INVALID_ENTITYID;
                    if (!TryGuardedCall(
                            "cargo station resolver container id",
                            [station, index]() { return station->m_containers[index]; },
                            linkedContainerId,
                            &reason))
                    {
                        break;
                    }
                    if (linkedContainerId == cargoEntityId)
                        return candidate->GetId();
                }
            }
        }

        IEntityLink* link = nullptr;
        if (!TryGuardedCall("cargo station resolver GetEntityLinks", [candidate]() { return candidate->GetEntityLinks(); }, link, &reason))
            continue;

        for (uint32_t linkIndex = 0; link && linkIndex < 64; ++linkIndex)
        {
            EntityId linkedEntityId = INVALID_ENTITYID;
            IEntityLink* next = nullptr;
            if (!TryGuardedCall("cargo station resolver link entity", [link]() { return link->entityId; }, linkedEntityId, &reason) ||
                !TryGuardedCall("cargo station resolver link next", [link]() { return link->next; }, next, &reason))
            {
                break;
            }
            if (linkedEntityId == cargoEntityId)
                return candidate->GetId();
            link = next;
        }
    }

    return INVALID_ENTITYID;
}

