static ArkDoor* GetArkDoorExtensionFromEntity(IEntity* entity)
{
    if (!entity || !gEnv || !gEnv->pGame)
        return nullptr;

    IGameFramework* framework = gEnv->pGame->GetIGameFramework();
    if (!framework)
        return nullptr;

    IGameObject* gameObject = nullptr;
    std::string reason;
    if (!TryGuardedCall(
            "door extension GetGameObject",
            [framework, entity]() { return framework->GetGameObject(entity->GetId()); },
            gameObject,
            &reason) ||
        !gameObject)
    {
        return nullptr;
    }

    IGameObjectExtension* extension = nullptr;
    IGameObjectSystem::ExtensionID extensionId = 0;
    if (TryGuardedCall(
            "door extension GetExtensionId",
            [gameObject]() { return gameObject->GetExtensionId("ArkDoor"); },
            extensionId,
            &reason) &&
        extensionId != 0 &&
        TryGuardedCall(
            "door extension QueryExtension id",
            [gameObject, extensionId]() { return gameObject->QueryExtension(extensionId); },
            extension,
            &reason) &&
        extension)
    {
        return static_cast<ArkDoor*>(extension);
    }

    extension = nullptr;
    if (TryGuardedCall(
            "door extension QueryExtension name",
            [gameObject]() { return gameObject->QueryExtension("ArkDoor"); },
            extension,
            &reason) &&
        extension)
    {
        return static_cast<ArkDoor*>(extension);
    }

    EntityId entityId = INVALID_ENTITYID;
    TryGuardedCall("door observed fallback GetId", [entity]() { return entity->GetId(); }, entityId, nullptr);
    const auto observed = s_observedArkDoors.find(entityId);
    if (observed != s_observedArkDoors.end() && observed->second)
    {
        IEntity* observedEntity = nullptr;
        if (TryGuardedCall(
                "door observed fallback GetEntity",
                [door = observed->second]() { return door->GetEntity(); },
                observedEntity,
                nullptr) &&
            observedEntity == entity)
        {
            return observed->second;
        }
        s_observedArkDoors.erase(observed);
    }

    return nullptr;
}

static ArkDoor* FindNearestArkDoorForCoop(
    EntityId* outEntityId,
    uint64_t* outGuid,
    float* outDistance,
    std::string* outDetail,
    bool requireIdle = false)
{
    if (outEntityId)
        *outEntityId = INVALID_ENTITYID;
    if (outGuid)
        *outGuid = 0;
    if (outDistance)
        *outDistance = -1.0f;

    if (!gEnv || !gEnv->pEntitySystem || !ArkPlayer::GetInstancePtr() || !ArkPlayer::GetInstance().GetEntity())
    {
        if (outDetail)
            *outDetail = "nearest_door_unavailable";
        return nullptr;
    }

    IEntityIt* rawIterator = nullptr;
    std::string reason;
    if (!TryGuardedCall("nearest door GetEntityIterator", []() { return gEnv->pEntitySystem->GetEntityIterator(); }, rawIterator, &reason) ||
        !rawIterator)
    {
        if (outDetail)
            *outDetail = "nearest_door_iterator_failed_" + StatusToken(reason.empty() ? std::string("-") : reason);
        return nullptr;
    }

    const Vec3 playerPos = ArkPlayer::GetInstance().GetEntity()->GetWorldPos();
    IEntityItPtr iterator = rawIterator;
    TryGuardedVoidCall("nearest door MoveFirst", [&iterator]() { iterator->MoveFirst(); }, nullptr);

    ArkDoor* bestDoor = nullptr;
    EntityId bestEntityId = INVALID_ENTITYID;
    uint64_t bestGuid = 0;
    float bestDistanceSq = std::numeric_limits<float>::max();
    uint32_t scanned = 0;
    uint32_t candidates = 0;
    while (true)
    {
        bool isEnd = false;
        if (TryGuardedCall("nearest door IsEnd", [&iterator]() { return iterator->IsEnd(); }, isEnd, &reason) && isEnd)
            break;

        IEntity* entity = nullptr;
        if (!TryGuardedCall("nearest door Next", [&iterator]() { return iterator->Next(); }, entity, &reason) ||
            !entity)
        {
            break;
        }

        ++scanned;
        ArkDoor* door = GetArkDoorExtensionFromEntity(entity);
        if (!door)
            continue;

        bool forceClosed = false;
        bool areaTriggered = false;
        size_t areaEntities = 0;
        float closeDuration = 0.0f;
        if (requireIdle &&
            (!TryGuardedCall("idle door force closed", [door]() { return door->m_bForceClosed; }, forceClosed, &reason) ||
                !TryGuardedCall("idle door IsAreaTriggered", [door]() { return door->IsAreaTriggered(); }, areaTriggered, &reason) ||
                !TryGuardedCall("idle door area entities", [door]() { return door->m_entitiesInArea.size(); }, areaEntities, &reason) ||
                !TryGuardedCall("idle door close duration", [door]() { return door->m_openTimer.GetDuration(); }, closeDuration, &reason) ||
                forceClosed || areaTriggered || areaEntities != 0 || closeDuration <= 0.0f))
        {
            continue;
        }

        const Vec3 pos = entity->GetWorldPos();
        const float distanceSq = (pos - playerPos).GetLengthSquared();
        if (requireIdle && distanceSq < 225.0f)
            continue;
        ++candidates;
        if (distanceSq < bestDistanceSq)
        {
            bestDistanceSq = distanceSq;
            bestDoor = door;
            TryGuardedCall("nearest door GetId", [entity]() { return entity->GetId(); }, bestEntityId, nullptr);
            TryGuardedCall("nearest door GetGuid", [entity]() { return entity->GetGuid(); }, bestGuid, nullptr);
        }
    }

    if (outEntityId)
        *outEntityId = bestEntityId;
    if (outGuid)
        *outGuid = bestGuid;
    if (outDistance)
        *outDistance = bestDoor ? std::sqrt(std::max(0.0f, bestDistanceSq)) : -1.0f;
    if (outDetail)
    {
        std::ostringstream detail;
        detail
            << "nearest_door scanned=" << scanned
            << " candidates=" << candidates
            << " id=" << bestEntityId
            << " guid=" << bestGuid
            << " idle=" << (requireIdle ? 1 : 0)
            << " dist=" << (bestDoor ? std::sqrt(std::max(0.0f, bestDistanceSq)) : -1.0f);
        *outDetail = detail.str();
    }
    return bestDoor;
}

static bool TryProbeArkDoorCenterCollision(ArkDoor* door, bool& blockedByDoor, std::string* reason)
{
    blockedByDoor = false;
    if (!door || !gEnv || !gEnv->pPhysicalWorld)
        return false;
    IEntity* entity = nullptr;
    if (!TryGuardedCall("door collision probe GetEntity", [door]() { return door->GetEntity(); }, entity, reason) || !entity)
        return false;
    IPhysicalEntity* doorPhysics = nullptr;
    AABB localBounds;
    Matrix34 worldTransform;
    if (!TryGuardedCall("door collision probe GetPhysics", [entity]() { return entity->GetPhysics(); }, doorPhysics, reason) ||
        !doorPhysics ||
        !TryGuardedVoidCall("door collision probe GetLocalBounds", [entity, &localBounds]() { entity->GetLocalBounds(localBounds); }, reason) ||
        !TryGuardedCall("door collision probe GetWorldTM", [entity]() { return entity->GetWorldTM(); }, worldTransform, reason))
    {
        return false;
    }

    const Vec3 size = localBounds.max - localBounds.min;
    const Vec3 localCenter = (localBounds.min + localBounds.max) * 0.5f;
    const Vec3 localNormal = size.x <= size.y ? Vec3(1.0f, 0.0f, 0.0f) : Vec3(0.0f, 1.0f, 0.0f);
    const float halfLength = std::max(1.5f, (size.x <= size.y ? size.x : size.y) * 0.5f + 1.0f);
    const Vec3 center = worldTransform.TransformPoint(localCenter);
    const Vec3 normal = worldTransform.TransformVector(localNormal).GetNormalizedSafe(Vec3(1.0f, 0.0f, 0.0f));
    const Vec3 origin = center - normal * halfLength;

    ray_hit hit;
    std::memset(&hit, 0, sizeof(hit));
    int hitCount = 0;
    const bool rayOk = TryGuardedCall(
        "door collision probe RayWorldIntersection",
        [&]() -> int
        {
            return gEnv->pPhysicalWorld->RayWorldIntersection(
                origin,
                normal * (halfLength * 2.0f),
                ent_static | ent_sleeping_rigid | ent_rigid | ent_independent,
                rwi_stop_at_pierceable | rwi_ignore_noncolliding |
                    rwi_colltype_any(geom_colltype_player),
                &hit,
                1,
                nullptr,
                0,
                nullptr,
                0,
                "CoopDoorCollisionProbe");
        },
        hitCount,
        reason);
    blockedByDoor = rayOk && hitCount > 0 && hit.pCollider == doorPhysics;
    return rayOk;
}

