    IEntity* entity = nullptr;
    std::string reason;
    if (!TryGuardedCall("interactive machine GetEntity", [machine]() { return machine->GetEntity(); }, entity, &reason) ||
        !entity)
    {
        if (outDetail)
            *outDetail = "interactive_machine_missing_entity_" + StatusToken(reason.empty() ? std::string("-") : reason);
        return 0;
    }

    uint64_t guid = 0;
    TryGuardedCall("interactive machine GetGuid", [entity]() { return entity->GetGuid(); }, guid, &reason);
