static ArkInteractiveMachine* FindNearestArkInteractiveMachineForCoop(EntityId* outEntityId, uint64_t* outGuid, float* outDistance, std::string* outDetail)
{
    if (outEntityId)
        *outEntityId = INVALID_ENTITYID;
    if (outGuid)
        *outGuid = 0;
    if (outDistance)
        *outDistance = -1.0f;

    if (!gEnv || !gEnv->pEntitySystem || !ArkPlayer::GetInstancePtr() || !ArkPlayer::GetInstance().GetEntity())
    {
        if (outDetail)
            *outDetail = "nearest_interactive_machine_unavailable";
        return nullptr;
    }

    IEntityIt* rawIterator = nullptr;
    std::string reason;
    if (!TryGuardedCall("nearest interactive machine GetEntityIterator", []() { return gEnv->pEntitySystem->GetEntityIterator(); }, rawIterator, &reason) ||
        !rawIterator)
    {
        if (outDetail)
            *outDetail = "nearest_interactive_machine_iterator_failed_" + StatusToken(reason.empty() ? std::string("-") : reason);
        return nullptr;
    }

    const Vec3 playerPos = ArkPlayer::GetInstance().GetEntity()->GetWorldPos();
    IEntityItPtr iterator = rawIterator;
    TryGuardedVoidCall("nearest interactive machine MoveFirst", [&iterator]() { iterator->MoveFirst(); }, nullptr);

    ArkInteractiveMachine* bestMachine = nullptr;
    EntityId bestEntityId = INVALID_ENTITYID;
    uint64_t bestGuid = 0;
    float bestDistanceSq = std::numeric_limits<float>::max();
    uint32_t scanned = 0;
    uint32_t candidates = 0;
    std::string bestName = "-";
    while (true)
    {
        bool isEnd = false;
        if (TryGuardedCall("nearest interactive machine IsEnd", [&iterator]() { return iterator->IsEnd(); }, isEnd, &reason) && isEnd)
            break;

        IEntity* entity = nullptr;
        if (!TryGuardedCall("nearest interactive machine Next", [&iterator]() { return iterator->Next(); }, entity, &reason) ||
            !entity)
        {
            break;
        }

        ++scanned;
        ArkInteractiveMachine* machine = GetArkInteractiveMachineExtensionFromEntity(entity);
        if (!machine)
            continue;

        uint64_t guid = 0;
        TryGuardedCall("nearest interactive machine GetGuid", [entity]() { return entity->GetGuid(); }, guid, nullptr);
        if (guid == 0)
            continue;

        ++candidates;
        const Vec3 pos = entity->GetWorldPos();
        const float distanceSq = (pos - playerPos).GetLengthSquared();
        if (distanceSq < bestDistanceSq)
        {
            bestDistanceSq = distanceSq;
            bestMachine = machine;
            bestGuid = guid;
            TryGuardedCall("nearest interactive machine GetId", [entity]() { return entity->GetId(); }, bestEntityId, nullptr);
            const char* rawName = nullptr;
            if (TryGuardedCall("nearest interactive machine GetName", [entity]() { return entity->GetName(); }, rawName, nullptr) && rawName)
                bestName = rawName;
        }
    }

    if (outEntityId)
        *outEntityId = bestEntityId;
    if (outGuid)
        *outGuid = bestGuid;
    if (outDistance)
        *outDistance = bestMachine ? std::sqrt(std::max(0.0f, bestDistanceSq)) : -1.0f;
    if (outDetail)
    {
        std::ostringstream detail;
        detail
            << "nearest_interactive_machine scanned=" << scanned
            << " candidates=" << candidates
            << " id=" << bestEntityId
            << " guid=" << bestGuid
            << " name=" << StatusToken(bestName)
            << " dist=" << (bestMachine ? std::sqrt(std::max(0.0f, bestDistanceSq)) : -1.0f);
        *outDetail = detail.str();
    }
    return bestMachine;
}

