static ArkKiosk* GetArkKioskExtensionFromEntity(IEntity* entity)
{
    if (!entity || !gEnv || !gEnv->pGame)
        return nullptr;
    IGameFramework* framework = gEnv->pGame->GetIGameFramework();
    if (!framework)
        return nullptr;
    IGameObject* gameObject = nullptr;
    std::string reason;
    if (!TryGuardedCall(
            "kiosk extension GetGameObject",
            [framework, entity]() { return framework->GetGameObject(entity->GetId()); },
            gameObject,
            &reason) || !gameObject)
    {
        return nullptr;
    }

    IGameObjectExtension* extension = nullptr;
    IGameObjectSystem::ExtensionID extensionId = 0;
    if (TryGuardedCall(
            "kiosk extension GetExtensionId",
            [gameObject]() { return gameObject->GetExtensionId("ArkKiosk"); },
            extensionId,
            &reason) && extensionId != 0 &&
        TryGuardedCall(
            "kiosk extension QueryExtension id",
            [gameObject, extensionId]() { return gameObject->QueryExtension(extensionId); },
            extension,
            &reason) && extension)
    {
        return static_cast<ArkKiosk*>(extension);
    }

    extension = nullptr;
    if (TryGuardedCall(
            "kiosk extension QueryExtension name",
            [gameObject]() { return gameObject->QueryExtension("ArkKiosk"); },
            extension,
            &reason) && extension)
    {
        return static_cast<ArkKiosk*>(extension);
    }
    return nullptr;
}

static bool TryReadArkKioskButtonState(
    ArkKiosk* kiosk,
    int button,
    EArkKioskButtonState& state,
    bool* visible,
    const char* label,
    std::string* reason)
{
    if (!kiosk || button < 0 || button >= static_cast<int>(kiosk->m_buttons.size()))
        return false;
    const bool stateOk = TryGuardedCall(
        label,
        [kiosk, button]() { return kiosk->m_buttons[static_cast<size_t>(button)].m_state; },
        state,
        reason);
    if (!visible)
        return stateOk;
    return stateOk && TryGuardedCall(
        label,
        [kiosk, button]() { return kiosk->m_buttons[static_cast<size_t>(button)].m_bVisible; },
        *visible,
        reason);
}

