static thread_local EntityId s_livePropImpulseSourceEntityId = INVALID_ENTITYID;

class ScopedLivePropImpulseSource
{
public:
    explicit ScopedLivePropImpulseSource(EntityId sourceEntityId)
        : m_previousSourceEntityId(s_livePropImpulseSourceEntityId)
    {
        if (sourceEntityId != INVALID_ENTITYID && sourceEntityId != 0)
            s_livePropImpulseSourceEntityId = sourceEntityId;
    }

    ~ScopedLivePropImpulseSource()
    {
        s_livePropImpulseSourceEntityId = m_previousSourceEntityId;
    }

private:
    EntityId m_previousSourceEntityId = INVALID_ENTITYID;
};

static EntityId ResolveLivePropWeaponOwner(const CArkWeapon* weapon)
{
    if (!weapon)
        return s_livePropImpulseSourceEntityId;

    EntityId ownerEntityId = INVALID_ENTITYID;
    TryGuardedCall(
        "live prop weapon impulse owner",
        [weapon]() { return static_cast<EntityId>(weapon->m_ownerId); },
        ownerEntityId,
        nullptr);
    return ownerEntityId != INVALID_ENTITYID && ownerEntityId != 0
        ? ownerEntityId
        : s_livePropImpulseSourceEntityId;
}

