static CArkProjectile* ArkProjectile_SpawnProjectile_Hook(
    IEntityArchetype* const archetype,
    const Vec3& position,
    const Vec3& direction,
    const unsigned ownerId,
    const string weaponClassName,
    const bool critical,
    const bool pooled,
    const unsigned extendedFlags,
    const unsigned groupId,
    const bool spawnFromCamera)
{
    const bool looksLikeGoo = ToLowerAscii(weaponClassName.c_str()).find("goo") != std::string::npos;
    IEntity* ownerEntity = nullptr;
    bool ownerIsTurret = false;
    if (ownerId != 0 && gEnv && gEnv->pEntitySystem)
    {
        ownerEntity = gEnv->pEntitySystem->GetEntity(static_cast<EntityId>(ownerId));
        ownerIsTurret = ownerEntity && EntityUtils::GetArkTurret(ownerEntity) != nullptr;
    }

    // Only the current turret claimant may create a damaging projectile. During
    // Host fallback, a Client's first suppressed shot becomes its ordered claim
    // request; after the grant, that Client is the sole native damage source.
    if (gMod && ownerIsTurret &&
        gMod->SuppressClientTurretProjectileForHook(
            static_cast<EntityId>(ownerId),
            "CArkProjectile::SpawnProjectile turret client replica"))
    {
        return nullptr;
    }

    CArkProjectile* projectile = s_hookArkProjectileSpawnProjectile.InvokeOrig(
        archetype,
        position,
        direction,
        ownerId,
        weaponClassName,
        critical,
        pooled,
        extendedFlags,
        groupId,
        spawnFromCamera);

    if (gMod && projectile && ownerId != 0 && !EnvFlagEnabled("COOP_DISABLE_TURRET_EVENT_HOOKS"))
    {
        if (ownerIsTurret)
        {
            uint64_t ownerArchetypeId = 0;
            if (const IEntityArchetype* ownerArchetype = ownerEntity->GetArchetype())
                ownerArchetypeId = ownerArchetype->GetId();
            gMod->QueueLocalTurretFireEventForHook(
                static_cast<EntityId>(ownerId),
                ownerArchetypeId,
                position,
                direction,
                INVALID_ENTITYID,
                "CArkProjectile::SpawnProjectile turret_owner");
        }
    }

    if (gMod && looksLikeGoo)
    {
        uint64_t archetypeId = 0;
        const char* archetypeName = "-";
        std::string reason;
        if (archetype)
        {
            TryGuardedCall("goo spawn archetype id", [archetype]() { return archetype->GetId(); }, archetypeId, &reason);
            TryGuardedCall("goo spawn archetype name", [archetype]() { return archetype->GetName(); }, archetypeName, &reason);
        }
        const EntityId projectileId = ResolveProjectileEntityId(projectile, "goo base projectile GetEntity");
        std::ostringstream detail;
        detail
            << "weapon=" << StatusToken(weaponClassName.c_str())
            << " archetype=" << archetypeId
            << "/" << StatusToken(archetypeName ? archetypeName : "-")
            << " owner=" << ownerId
            << " pos=" << StatusToken(FormatVec3Trace(position))
            << " dir=" << StatusToken(FormatVec3Trace(direction))
            << " critical=" << (critical ? 1 : 0)
            << " pooled=" << (pooled ? 1 : 0)
            << " flags=0x" << std::hex << extendedFlags << std::dec
            << " group=" << groupId
            << " camera=" << (spawnFromCamera ? 1 : 0);
        gMod->RecordGooProjectileTrace("CArkProjectile::SpawnProjectile after", projectileId, INVALID_ENTITYID, extendedFlags, detail.str().c_str());
    }

    if (gMod && projectile && !ownerIsTurret)
    {
        const EntityId projectileId = ResolveProjectileEntityId(projectile, "enemy projectile GetEntity");
        gMod->QueueLocalEnemyProjectileEventForHook(
            projectileId,
            static_cast<EntityId>(ownerId),
            archetype,
            position,
            direction,
            weaponClassName.c_str(),
            critical,
            pooled,
            extendedFlags,
            groupId,
            spawnFromCamera);
    }

    return projectile;
}

