static void ArkProjectileGoo_SendOutMaxGooPackage_Hook(CArkProjectileGoo* goo, const float scale)
{
    const EntityId projectileId = ResolveProjectileEntityId(goo, "goo SendOutMaxGooPackage GetEntity");
    if (gMod)
    {
        std::ostringstream detail;
        detail << "scaleArg=" << scale << " " << BuildGooProjectileDetail(goo, "before");
        gMod->RecordGooProjectileTrace("SendOutMaxGooPackage before", projectileId, INVALID_ENTITYID, 0u, detail.str().c_str());
    }

    s_hookArkProjectileGooSendOutMaxGooPackage.InvokeOrig(goo, scale);

    if (!gMod || !goo)
        return;

    std::ostringstream detail;
    detail << "scaleArg=" << scale << " " << BuildGooProjectileDetail(goo, "after");
    gMod->RecordGooProjectileTrace("SendOutMaxGooPackage after", projectileId, INVALID_ENTITYID, CoopProtocol::kGooResultFlagGooStatic, detail.str().c_str());

    if (gMod->TryCorrectRemoteGooFinalTransform(goo, projectileId, "SendOutMaxGooPackage after"))
        return;

    if (EnvFlagEnabled("COOP_DISABLE_GOO_RESULT_FROM_MAX_GOO_COMMIT") ||
        projectileId == INVALID_ENTITYID)
    {
        return;
    }

    Vec3 resultPosition(ZERO);
    Vec3 resultDirection(0.0f, 1.0f, 0.0f);
    float resultScale = scale;
    int resultHitPhysicsId = 0;
    int resultAttachedPhysicsId = 0;
    int resultPartId = 0;
    int resultSurfaceIndex = 0;
    bool resultTerrain = false;
    std::string resultReason;
    TryGuardedCall(
        "max goo result read final position",
        [goo]() -> Vec3 { return goo ? goo->m_finalPosition : Vec3(ZERO); },
        resultPosition,
        &resultReason);
    TryGuardedCall(
        "max goo result read initial normal",
        [goo]() -> Vec3 { return goo ? goo->GetWorldInitialNormal() : Vec3(0.0f, 1.0f, 0.0f); },
        resultDirection,
        &resultReason);
    TryGuardedCall(
        "max goo result read current scale",
        [goo]() -> float { return goo ? goo->m_currentScale : 0.0f; },
        resultScale,
        &resultReason);
    TryGuardedCall(
        "max goo result read static physics",
        [goo]() -> int { return goo ? goo->m_staticPhysicsId : 0; },
        resultHitPhysicsId,
        &resultReason);
    TryGuardedCall(
        "max goo result read attached physics",
        [goo]() -> int { return goo ? goo->m_attachedPhysicsId : 0; },
        resultAttachedPhysicsId,
        &resultReason);
    TryGuardedCall(
        "max goo result read attached part",
        [goo]() -> int { return goo ? goo->m_attachedPartId : 0; },
        resultPartId,
        &resultReason);
    TryGuardedCall(
        "max goo result read surface",
        [goo]() -> int { return goo ? goo->m_surfaceIndex : 0; },
        resultSurfaceIndex,
        &resultReason);
    TryGuardedCall(
        "max goo result read terrain",
        [goo]() -> bool { return goo ? goo->m_bAttachedTerrain : false; },
        resultTerrain,
        &resultReason);
    Vec3 initialSpawnPosition = resultPosition;
    ModMain::GooSpawnContext spawnContext;
    if (gMod->TryGetLocalGooSpawnContext(projectileId, spawnContext))
    {
        if (IsFiniteVec3Trace(spawnContext.position))
            initialSpawnPosition = spawnContext.position;
        if (IsFiniteVec3Trace(spawnContext.direction))
            resultDirection = spawnContext.direction;
        resultHitPhysicsId = spawnContext.hitPhysicsId;
        resultAttachedPhysicsId = spawnContext.attachedPhysicsId;
        resultPartId = spawnContext.partId;
        resultSurfaceIndex = spawnContext.surfaceIndex;
        resultTerrain = spawnContext.terrain;
    }

    if (!IsFiniteVec3Trace(resultPosition))
        return;
    if (!IsFiniteVec3Trace(resultDirection))
        resultDirection = Vec3(0.0f, 1.0f, 0.0f);
    if (resultScale <= 0.0f)
        resultScale = 1.0f;
    const float minHardCommitScale = ResolveEnvSeconds("COOP_GOO_MIN_HARD_COMMIT_SCALE", 0.25f, 0.01f, 2.0f);
    if (resultScale < minHardCommitScale)
    {
        std::ostringstream skipDetail;
        skipDetail
            << "scale=" << resultScale
            << " min=" << minHardCommitScale
            << " pos=" << StatusToken(FormatVec3Trace(resultPosition));
        gMod->RecordGooProjectileTrace(
            "SendOutMaxGooPackage skipped tiny hard commit",
            projectileId,
            INVALID_ENTITYID,
            CoopProtocol::kGooResultFlagGooStatic,
            skipDetail.str().c_str());
        return;
    }

    gMod->QueueLocalGooResultForHook(
        projectileId,
        INVALID_ENTITYID,
        initialSpawnPosition,
        resultDirection,
        resultScale,
        resultHitPhysicsId,
        resultAttachedPhysicsId,
        resultPartId,
        resultSurfaceIndex,
        CoopProtocol::kGooResultFlagGooStatic | (resultTerrain ? CoopProtocol::kGooResultFlagTerrain : 0u),
        "SendOutMaxGooPackage after",
        &resultPosition);
}

