static void ArkProjectileGoo_Destroy_Hook(CArkProjectileGoo* goo, const bool deleting, const bool destroyImmediate)
{
    const EntityId projectileId = ResolveProjectileEntityId(goo, "goo Destroy GetEntity");
    if (gMod)
    {
        std::string detail;
        if (GooProjectileTraceEnabled())
        {
            detail = BuildGooProjectileDetail(
                goo,
                (std::string("deleting=") + (deleting ? "1" : "0") + " immediate=" + (destroyImmediate ? "1" : "0")).c_str());
            gMod->RecordGooProjectileTrace(
                "Destroy before",
                projectileId,
                INVALID_ENTITYID,
                (deleting ? 1u : 0u) | (destroyImmediate ? 2u : 0u),
                detail.c_str());
        }
        if (gMod->IsNetworkOriginatedGooDestroyActive(projectileId))
        {
            if (GooProjectileTraceEnabled())
            {
                gMod->RecordGooProjectileTrace(
                    "Destroy network echo suppressed",
                    projectileId,
                    INVALID_ENTITYID,
                    0u,
                    detail.c_str());
            }
        }
        else if (EnvFlagEnabled("COOP_GOO_DESTROY_FROM_PROJECTILE_DESTROY"))
        {
            gMod->QueueLocalGooDestroyForHook(projectileId, INVALID_ENTITYID, "Destroy before");
        }
    }
    s_hookArkProjectileGooDestroy.InvokeOrig(goo, deleting, destroyImmediate);
    if (gMod && GooProjectileTraceEnabled())
    {
        gMod->RecordGooProjectileTrace(
            "Destroy after",
            projectileId,
            INVALID_ENTITYID,
            (deleting ? 1u : 0u) | (destroyImmediate ? 2u : 0u),
            deleting ? "deleting=1" : "deleting=0");
    }
}

