static void ArkProjectileGooBall_PostInit_Hook(CArkProjectileGooBall* ball, IGameObject* gameObject)
{
    s_hookArkProjectileGooBallPostInit.InvokeOrig(ball, gameObject);
    if (gMod && ball && GooProjectileTraceEnabled())
    {
        bool spawnGoo = false;
        CArkProjectileGoo::ArkGooSpawnParameters params;
        std::string reason;
        TryGuardedCall("goo ball PostInit read spawn flag", [ball]() -> bool { return ball->m_bSpawnGoo; }, spawnGoo, &reason);
        TryGuardedCall("goo ball PostInit read params", [ball]() -> CArkProjectileGoo::ArkGooSpawnParameters { return ball->m_spawnParameters; }, params, &reason);
        if (!EnvFlagEnabled("COOP_TRACE_GOO_PROJECTILE_ALL") &&
            !spawnGoo &&
            params.m_projectileId == 0 &&
            params.m_ownerId == 0 &&
            params.m_weaponClassName.empty())
        {
            return;
        }

        const EntityId projectileId = ResolveProjectileEntityId(ball, "goo ball PostInit GetEntity");
        const std::string detail = BuildGooBallDetail(ball, "postinit");
        gMod->RecordGooProjectileTrace("GooBall PostInit after", projectileId, params.m_ownerId, spawnGoo ? 1u : 0u, detail.c_str());
    }
}

