static void ArkProjectileGooPhysicsManager_AddGooOnDynamicEntity_Hook(
    CArkProjectileGooPhysicsManager* manager,
    const unsigned dynamicEntityId,
    const unsigned gooId,
    const bool isEntityStatic,
    const bool isGooStatic,
    const float mass,
    const float gooMass,
    const unsigned attachedEntityId)
{
    s_hookArkProjectileGooPhysicsManagerAddGooOnDynamicEntity.InvokeOrig(
        manager,
        dynamicEntityId,
        gooId,
        isEntityStatic,
        isGooStatic,
        mass,
        gooMass,
        attachedEntityId);

    if (!gMod)
        return;

    if (GooProjectileTraceEnabled())
    {
        IEntity* dynamicEntity = nullptr;
        IEntity* attachedEntity = nullptr;
        if (gEnv && gEnv->pEntitySystem)
        {
            dynamicEntity = gEnv->pEntitySystem->GetEntity(static_cast<EntityId>(dynamicEntityId));
            attachedEntity = gEnv->pEntitySystem->GetEntity(static_cast<EntityId>(attachedEntityId));
        }

        std::ostringstream detail;
        detail
            << "dynamic=" << dynamicEntityId
            << "/" << StatusToken(dynamicEntity && dynamicEntity->GetName() ? dynamicEntity->GetName() : "-")
            << " goo=" << gooId
            << " attached=" << attachedEntityId
            << "/" << StatusToken(attachedEntity && attachedEntity->GetName() ? attachedEntity->GetName() : "-")
            << " entityStatic=" << (isEntityStatic ? 1 : 0)
            << " gooStatic=" << (isGooStatic ? 1 : 0)
            << " mass=" << mass
            << " gooMass=" << gooMass;
        gMod->RecordGooProjectileTrace(
            "GooPhysics AddGooOnDynamicEntity after",
            static_cast<EntityId>(gooId),
            static_cast<EntityId>(dynamicEntityId),
            (isEntityStatic ? 1u : 0u) | (isGooStatic ? 2u : 0u),
            detail.str().c_str());
    }
    gMod->QueueLocalGooDynamicAttachForHook(
        static_cast<EntityId>(dynamicEntityId),
        static_cast<EntityId>(gooId),
        isEntityStatic,
        isGooStatic,
        mass,
        gooMass,
        static_cast<EntityId>(attachedEntityId),
        "GooPhysics AddGooOnDynamicEntity after");
}

static void QueueGooDestroyFromNativeRemove(unsigned gooId, unsigned relatedEntityId, const char* stage, uint32_t flags)
{
    if (!gMod || gooId == 0 || gooId == INVALID_ENTITYID)
        return;
    if (gMod->IsNetworkOriginatedGooDestroyActive(static_cast<EntityId>(gooId)))
    {
        if (GooProjectileTraceEnabled())
        {
            std::ostringstream suppressedDetail;
            suppressedDetail
                << "goo=" << gooId
                << " related=" << relatedEntityId
                << " stage=" << StatusToken(stage && stage[0] ? stage : "-");
            gMod->RecordGooProjectileTrace(
                "Goo remove network echo suppressed",
                static_cast<EntityId>(gooId),
                static_cast<EntityId>(relatedEntityId),
                flags,
                suppressedDetail.str().c_str());
        }
        return;
    }

    if (GooProjectileTraceEnabled())
    {
        std::ostringstream detail;
        detail
            << "goo=" << gooId
            << " related=" << relatedEntityId
            << " stage=" << StatusToken(stage && stage[0] ? stage : "-");
        gMod->RecordGooProjectileTrace(
            stage && stage[0] ? stage : "Goo remove",
            static_cast<EntityId>(gooId),
            static_cast<EntityId>(relatedEntityId),
            flags,
            detail.str().c_str());
    }
    gMod->QueueLocalGooDestroyForHook(
        static_cast<EntityId>(gooId),
        static_cast<EntityId>(relatedEntityId),
        stage && stage[0] ? stage : "Goo remove");
}

