static thread_local uint32_t s_playerGrenadeDetonationHookDepth = 0;

static void ArkProjectileGrenade_DoDetonation_Hook(CArkProjectileGrenade* grenade)
{
    const bool outermost = s_playerGrenadeDetonationHookDepth++ == 0;
    if (outermost && gMod)
        gMod->OnNativePlayerGrenadeDetonated(grenade, "CArkProjectileGrenade::DoDetonation");
    s_hookArkProjectileGrenadeDoDetonation.InvokeOrig(grenade);
    --s_playerGrenadeDetonationHookDepth;
}

