struct ScopedCoopFireAndForgetWorldParticle
{
    bool previousActive = false;
    float previousTtlSeconds = 0.0f;
    const char* previousReason = nullptr;

    ScopedCoopFireAndForgetWorldParticle(float ttlSeconds, const char* reason)
    {
        previousActive = s_coopScopedFireAndForgetWorldParticle;
        previousTtlSeconds = s_coopScopedFireAndForgetTtlSeconds;
        previousReason = s_coopScopedFireAndForgetReason;
        s_coopScopedFireAndForgetWorldParticle = true;
        s_coopScopedFireAndForgetTtlSeconds = std::clamp(ttlSeconds, 0.05f, 30.0f);
        s_coopScopedFireAndForgetReason = reason;
    }

    ~ScopedCoopFireAndForgetWorldParticle()
    {
        s_coopScopedFireAndForgetWorldParticle = previousActive;
        s_coopScopedFireAndForgetTtlSeconds = previousTtlSeconds;
        s_coopScopedFireAndForgetReason = previousReason;
    }
};

static std::string GetParticleEffectTraceName(IParticleEffect* effect);
static bool ShouldTraceNativeParticleEffect(const std::string& effectName);

static std::string SafeCryNameTrace(const CCryName* name, const char* operation)
{
    if (!name)
        return "-";

    const char* text = nullptr;
    std::string reason;
    if (!TryGuardedCall(
            operation && operation[0] ? operation : "cryname c_str",
            [name]() -> const char* { return name->c_str(); },
            text,
            &reason) ||
        !text)
    {
        return "guard_" + StatusToken(reason.empty() ? std::string("failed") : reason);
    }

    std::string safeText = ReadRuntimeCString(text, 96);
    if (safeText.empty())
        safeText = "-";
    return safeText;
}

static IParticleEmitter* ParticleEffectSpawnSlot_Hook(
    IParticleEffect* effect,
    const ParticleLoc& location,
    int spawnFlags,
    const SpawnParams* spawnParams)
{
    IParticleEmitter* emitter = s_hookParticleEffectSpawnSlot.InvokeOrig(effect, location, spawnFlags, spawnParams);
    if (gMod && s_coopScopedFireAndForgetWorldParticle)
    {
        const float ttlSeconds = s_coopScopedFireAndForgetTtlSeconds > 0.0f
            ? s_coopScopedFireAndForgetTtlSeconds
            : 3.0f;
        gMod->RecordPsiFxSniper(
            "ff_spawn_capture result=" + PointerHex(emitter) +
            " effect=" + StatusToken(GetParticleEffectTraceName(effect)) +
            " pos=" + StatusToken(FormatVec3Trace(location.t)) +
            " scale=" + std::to_string(location.s) +
            " flags=" + std::to_string(spawnFlags) +
            " ttl=" + std::to_string(ttlSeconds) +
            " params=" + StatusToken(spawnParams ? FormatSpawnParamsTrace(*spawnParams) : std::string("-")) +
            " reason=" + StatusToken(s_coopScopedFireAndForgetReason ? std::string(s_coopScopedFireAndForgetReason) : std::string("-")));
        if (emitter)
        {
            gMod->TrackManagedWorldParticleEmitter(
                emitter,
                location.t,
                ttlSeconds,
                s_coopScopedFireAndForgetReason,
                "fire_and_forget_spawn_capture");
        }
    }
    return emitter;
}

static bool EnsureParticleEffectSpawnSlotHook(IParticleEffect* effect)
{
    if (!effect)
        return false;

    void* spawnSlotAddress = nullptr;
    std::string guardReason;
    if (!TryGuardedCall(
            "particle effect spawn slot read",
            [effect]() -> void*
            {
                void** vtable = *reinterpret_cast<void***>(effect);
                return vtable ? vtable[5] : nullptr;
            },
            spawnSlotAddress,
            &guardReason) ||
        !spawnSlotAddress)
    {
        if (gMod)
        {
            gMod->RecordPsiFxSniper(
                "ff_spawn_hook_slot_failed reason=" +
                StatusToken(!guardReason.empty() ? guardReason : std::string("missing_slot")));
        }
        return false;
    }

    if (s_hookParticleEffectSpawnSlot.IsHooked())
    {
        if (s_particleEffectSpawnSlotAddress != spawnSlotAddress && gMod)
        {
            gMod->RecordPsiFxSniper(
                "ff_spawn_hook_different_slot observed=" + PointerHex(spawnSlotAddress) +
                " hooked=" + PointerHex(s_particleEffectSpawnSlotAddress));
        }
        return s_particleEffectSpawnSlotAddress == spawnSlotAddress;
    }

    if (s_particleEffectSpawnSlotHookAttempted && s_particleEffectSpawnSlotAddress == spawnSlotAddress)
        return false;

    s_particleEffectSpawnSlotHookAttempted = true;
    s_particleEffectSpawnSlotAddress = spawnSlotAddress;
    try
    {
        HookTransaction transaction;
        s_hookParticleEffectSpawnSlot.InstallHook(
            reinterpret_cast<ParticleEffectSpawnSlotFn*>(spawnSlotAddress),
            &ParticleEffectSpawnSlot_Hook);
        transaction.Commit();
        if (gMod)
            gMod->RecordPsiFxSniper("ff_spawn_hook_installed slot=" + PointerHex(spawnSlotAddress));
        return true;
    }
    catch (const std::exception& e)
    {
        if (gMod)
        {
            gMod->RecordPsiFxSniper(
                "ff_spawn_hook_install_failed slot=" + PointerHex(spawnSlotAddress) +
                " error=" + StatusToken(e.what() ? std::string(e.what()) : std::string("-")));
        }
        return false;
    }
}

static void ArkFireAndForgetEffect_Start_Hook(const ArkFireAndForgetEffect* fireAndForget, const QuatTS& location)
{
    TracePostLoadNativeHook("ArkFireAndForgetEffect::Start");
    IParticleEffect* nativeEffect = nullptr;
    SpawnParams nativeSpawnParams = {};
    bool hasNativeSpawnParams = false;
    std::string nativeEffectReason;
    if (fireAndForget)
    {
        TryGuardedCall(
            "ff start effect pointer",
            [fireAndForget]() -> IParticleEffect* { return fireAndForget->m_pEffect.get(); },
            nativeEffect,
            &nativeEffectReason);
        hasNativeSpawnParams = TryGuardedCall(
            "ff start spawn params",
            [fireAndForget]() -> SpawnParams { return fireAndForget->m_spawnParams; },
            nativeSpawnParams,
            &nativeEffectReason);
    }
    const std::string nativeEffectName = GetParticleEffectTraceName(nativeEffect);
    if (gMod && ShouldTraceNativeParticleEffect(nativeEffectName))
    {
        gMod->RecordPsiFxSniper(
            "native_ff_start effect=" + StatusToken(nativeEffectName) +
            " ptr=" + PointerHex(fireAndForget) +
            " effectPtr=" + PointerHex(nativeEffect) +
            " pos=" + StatusToken(FormatVec3Trace(location.t)) +
            " scale=" + std::to_string(location.s) +
            " params=" + StatusToken(hasNativeSpawnParams ? FormatSpawnParamsTrace(nativeSpawnParams) : std::string("-")) +
            " reason=" + StatusToken(nativeEffectReason.empty() ? std::string("-") : nativeEffectReason));
    }
    if (gMod && s_coopScopedFireAndForgetWorldParticle)
    {
        const bool spawnHookReady =
            !EnvFlagEnabled("COOP_DISABLE_FF_SPAWN_CAPTURE_HOOK") &&
            EnsureParticleEffectSpawnSlotHook(nativeEffect);
        gMod->RecordPsiFxSniper(
            "ff_start_hook scoped=1 ptr=" + PointerHex(fireAndForget) +
            " effect=" + StatusToken(nativeEffectName) +
            " pos=" + StatusToken(FormatVec3Trace(location.t)) +
            " ttl=" + std::to_string(s_coopScopedFireAndForgetTtlSeconds) +
            " spawnHook=" + std::to_string(spawnHookReady ? 1 : 0) +
            " ttlHijack=" + std::to_string(EnvFlagEnabled("COOP_WORLD_PARTICLE_TTL_HIJACK") ? 1 : 0) +
            " hijackDisabled=" + std::to_string(EnvFlagEnabled("COOP_WORLD_PARTICLE_DISABLE_TTL_HIJACK") ? 1 : 0) +
            " reason=" + StatusToken(s_coopScopedFireAndForgetReason ? std::string(s_coopScopedFireAndForgetReason) : std::string("-")));
    }
    if (s_coopScopedFireAndForgetWorldParticle &&
        gMod &&
        EnvFlagEnabled("COOP_WORLD_PARTICLE_TTL_HIJACK") &&
        !EnvFlagEnabled("COOP_WORLD_PARTICLE_DISABLE_TTL_HIJACK"))
    {
        const float ttlSeconds = s_coopScopedFireAndForgetTtlSeconds > 0.0f
            ? s_coopScopedFireAndForgetTtlSeconds
            : 3.0f;
        if (gMod->StartManagedWorldParticleFromFireAndForget(
                fireAndForget,
                location,
                ttlSeconds,
                s_coopScopedFireAndForgetReason))
        {
            gMod->RecordPsiFxSniper("ff_start_hook hijack_ok");
            return;
        }

        gMod->RecordPsiFxSniper("ff_start_hook hijack_failed fallback=" + std::to_string(EnvFlagEnabled("COOP_WORLD_PARTICLE_ALLOW_UNMANAGED_FALLBACK") ? 1 : 0));
        if (!EnvFlagEnabled("COOP_WORLD_PARTICLE_ALLOW_UNMANAGED_FALLBACK"))
            return;
    }

    if (gMod && s_coopScopedFireAndForgetWorldParticle)
        gMod->RecordPsiFxSniper("ff_start_hook native_passthrough");
    s_hookArkFireAndForgetEffectStart.InvokeOrig(fireAndForget, location);
}

static EArkPsiPowers ResolvePsiPowerFromComponent(const ArkPsiPowerComponent* component)
{
    if (!component)
        return EArkPsiPowers::empty;

    EArkPsiPowers selectedPower = EArkPsiPowers::empty;
    EArkPsiPowers equippedPower = EArkPsiPowers::empty;
    TryGuardedVoidCall(
        "psi resolve component power",
        [&]()
        {
            selectedPower = component->m_selectedPower;
            equippedPower = component->m_equippedPower;
        },
        nullptr);
    if (selectedPower != EArkPsiPowers::empty &&
        selectedPower != EArkPsiPowers::firstPower)
    {
        return selectedPower;
    }
    return equippedPower;
}

static bool IsValidPsiPowerForTrace(EArkPsiPowers power)
{
    return power != EArkPsiPowers::empty && power != EArkPsiPowers::firstPower;
}

static EArkPsiPowers ResolvePsiPowerFromPowerObject(const IArkPsiPower* power, EArkPsiPowers fallback, const char* context, std::string* outReason = nullptr)
{
    EArkPsiPowers resolved = fallback;
    std::string reason;
    if (power)
    {
        TryGuardedCall(
            context && context[0] ? context : "psi power GetEnum",
            [power]() -> EArkPsiPowers { return power->GetEnum(); },
            resolved,
            &reason);
    }
    if (outReason)
        *outReason = reason;
    return IsValidPsiPowerForTrace(resolved) ? resolved : fallback;
}

static std::string BuildPsiComponentStateTrace(const ArkPsiPowerComponent* component)
{
    if (!component)
        return "component=0";

    EArkPsiPowers selectedPower = EArkPsiPowers::empty;
    EArkPsiPowers equippedPower = EArkPsiPowers::empty;
    EArkPsiPowers resolvedPower = EArkPsiPowers::empty;
    bool active = false;
    bool targeting = false;
    std::string reason;
    TryGuardedVoidCall(
        "psi component state trace",
        [&]()
        {
            selectedPower = component->m_selectedPower;
            equippedPower = component->m_equippedPower;
            resolvedPower = ResolvePsiPowerFromComponent(component);
            if (IsValidPsiPowerForTrace(resolvedPower))
            {
                active = component->IsPowerActive(resolvedPower);
                targeting = component->IsPowerTargeting(resolvedPower);
            }
        },
        &reason);

    return
        "selected=" + std::to_string(static_cast<int>(selectedPower)) +
        " equipped=" + std::to_string(static_cast<int>(equippedPower)) +
        " resolved=" + std::to_string(static_cast<int>(resolvedPower)) +
        " active=" + std::to_string(active ? 1 : 0) +
        " targeting=" + std::to_string(targeting ? 1 : 0) +
        " reason=" + StatusToken(reason.empty() ? std::string("-") : reason);
}

static std::string GetParticleEffectTraceName(IParticleEffect* effect)
{
    if (!effect)
        return "-";

    stack_string fullName;
    std::string reason;
    if (TryGuardedCall(
            "particle effect GetFullName",
            [effect]() -> stack_string { return effect->GetFullName(); },
            fullName,
            &reason))
    {
        const char* text = fullName.c_str();
        if (text && text[0])
            return text;
    }

    const char* shortName = nullptr;
    reason.clear();
    if (TryGuardedCall(
            "particle effect GetName",
            [effect]() -> const char* { return effect->GetName(); },
            shortName,
            &reason) &&
        shortName &&
        shortName[0])
    {
        return shortName;
    }

    return "ptr_" + PointerHex(effect) + "_reason_" + StatusToken(reason.empty() ? std::string("-") : reason);
}

static bool ShouldTraceNativeParticleEffect(const std::string& effectName)
{
    if (EnvFlagEnabled("COOP_PSIFX_TRACE_ALL_NATIVE_EFFECTS"))
        return true;

    const std::string lower = ToLowerAscii(effectName);
    return
        lower.find("psi") != std::string::npos ||
        lower.find("power") != std::string::npos ||
        lower.find("kinetic") != std::string::npos ||
        lower.find("thermal") != std::string::npos ||
        lower.find("psychoshock") != std::string::npos ||
        lower.find("remote") != std::string::npos ||
        lower.find("mimic") != std::string::npos ||
        lower.find("phantom") != std::string::npos ||
        lower.find("shift") != std::string::npos ||
        lower.find("fear") != std::string::npos ||
        lower.find("hypnosis") != std::string::npos ||
        lower.find("lift") != std::string::npos ||
        lower.find("electro") != std::string::npos ||
        lower.find("emp") != std::string::npos ||
        lower.find("ether") != std::string::npos ||
        lower.find("alien") != std::string::npos;
}

static void RecordNativePsiStartDerived(const char* label, const IArkPsiPower* powerObject, EArkPsiPowers fallbackPower, bool result, float impulseSeconds)
{
    if (!gMod)
        return;

    std::string reason;
    const EArkPsiPowers power = ResolvePsiPowerFromPowerObject(
        powerObject,
        fallbackPower,
        label && label[0] ? label : "psi start derived GetEnum",
        &reason);

    gMod->RecordPsiFxSniper(
        "native_start_derived label=" + StatusToken(label && label[0] ? std::string(label) : std::string("-")) +
        " result=" + std::to_string(result ? 1 : 0) +
        " power=" + std::to_string(static_cast<int>(power)) +
        " reason=" + StatusToken(reason.empty() ? std::string("-") : reason));
    if (result)
    {
        gMod->QueueNativePsiCastForHook(
            power,
            impulseSeconds,
            label && label[0] ? label : "native Start_Derived");
    }
}

