static bool ArkPsiCorpsePhantom_Update_Hook(ArkPsiCorpsePhantom* corpsePhantom, float frameTime)
{
    EntityId corpseEntityId = INVALID_ENTITYID;
    EntityId previousPhantomEntityId = INVALID_ENTITYID;
    uint64_t phantomArchetypeId = 0;
    uint64_t sourceEnemyNetId = 0;
    uint64_t sourceStableEnemyId = 0;
    if (gMod && corpsePhantom)
    {
        TryGuardedCall("corpse phantom source id", [corpsePhantom]() { return corpsePhantom->m_corpseEntityId; }, corpseEntityId, nullptr);
        TryGuardedCall("corpse phantom previous id", [corpsePhantom]() { return corpsePhantom->m_phantomEntityId; }, previousPhantomEntityId, nullptr);
        TryGuardedCall("corpse phantom archetype", [corpsePhantom]() { return corpsePhantom->m_phantomArchetypeId; }, phantomArchetypeId, nullptr);
        sourceStableEnemyId = gMod->CaptureNativeCorpsePhantomSourceStableId(corpseEntityId, &sourceEnemyNetId);
    }

    const bool completed = s_hookArkPsiCorpsePhantomUpdate.InvokeOrig(corpsePhantom, frameTime);
    if (gMod && corpsePhantom)
    {
        EntityId phantomEntityId = INVALID_ENTITYID;
        TryGuardedCall("corpse phantom result id", [corpsePhantom]() { return corpsePhantom->m_phantomEntityId; }, phantomEntityId, nullptr);
        gMod->OnNativeCorpsePhantomUpdateResult(
            corpseEntityId,
            previousPhantomEntityId,
            phantomEntityId,
            phantomArchetypeId,
            sourceEnemyNetId,
            sourceStableEnemyId,
            completed);
    }
    return completed;
}

