static void ArkPsiPowerShift_SpawnDuplicate_Hook(ArkPsiPowerShift* shift)
{
    Vec3 duplicatePosition = Vec3(ZERO);
    bool hasDuplicatePosition = false;
    if (gMod)
    {
        IEntity* playerEntity = ArkPlayer::GetInstance().GetEntity();
        if (playerEntity)
        {
            duplicatePosition = playerEntity->GetWorldPos();
            hasDuplicatePosition = true;
        }
        if (shift)
        {
            duplicatePosition = shift->m_initialPosition.GetLengthSquared() > 0.0001f ? shift->m_initialPosition : duplicatePosition;
            hasDuplicatePosition = true;
        }
    }

    s_hookArkPsiPowerShiftSpawnDuplicate.InvokeOrig(shift);
    if (!gMod || !hasDuplicatePosition)
        return;

    if (shift && gEnv && gEnv->pEntitySystem)
    {
        unsigned duplicateEntityId = 0;
        std::string reason;
        if (TryGuardedCall(
                "shift duplicate GetDuplicateEntityId",
                [shift]() -> unsigned { return shift->GetDuplicateEntityId(); },
                duplicateEntityId,
                &reason) &&
            duplicateEntityId != 0)
        {
            IEntity* duplicateEntity = gEnv->pEntitySystem->GetEntity(duplicateEntityId);
            if (duplicateEntity)
            {
                duplicatePosition = duplicateEntity->GetWorldPos();
                hasDuplicatePosition = true;
            }
        }
    }

    gMod->RecordPsiFxSniper(
        "native_shift_spawn_duplicate pos=" + StatusToken(FormatVec3Trace(duplicatePosition)) +
        " has=" + std::to_string(hasDuplicatePosition ? 1 : 0));
    gMod->QueueNativePsiCastForHook(
        EArkPsiPowers::shift,
        0.55f,
        "native Shift SpawnDuplicate cast");
    gMod->QueueNativePsiImpactForHook(
        CoopProtocol::kPlayerPosePsiFxShiftDuplicate,
        static_cast<int>(EArkPsiPowers::shift),
        duplicatePosition,
        "native Shift SpawnDuplicate duplicate");
}

static bool ArkPsiPowerShift_PerformShift_Hook(ArkPsiPowerShift* shift)
{
    Vec3 desiredPosition = Vec3(ZERO);
    bool hasDesiredPosition = false;
    if (shift)
    {
        desiredPosition = shift->m_desiredPosition.GetLengthSquared() > 0.0001f ? shift->m_desiredPosition : shift->m_initialPosition;
        hasDesiredPosition = desiredPosition.GetLengthSquared() > 0.0001f;
    }

    const bool result = s_hookArkPsiPowerShiftPerformShift.InvokeOrig(shift);
    if (gMod)
    {
        gMod->RecordPsiFxSniper(
            "native_shift_perform result=" + std::to_string(result ? 1 : 0) +
            " desired=" + StatusToken(FormatVec3Trace(desiredPosition)) +
            " hasDesired=" + std::to_string(hasDesiredPosition ? 1 : 0));
    }
    if (!result || !gMod)
        return result;

    Vec3 arrivalPosition = desiredPosition;
    bool hasArrivalPosition = hasDesiredPosition;
    IEntity* playerEntity = ArkPlayer::GetInstance().GetEntity();
    if (playerEntity)
    {
        arrivalPosition = playerEntity->GetWorldPos();
        hasArrivalPosition = true;
    }

    if (hasArrivalPosition)
    {
        gMod->QueueNativePsiImpactForHook(
            CoopProtocol::kPlayerPosePsiFxShiftArrive,
            static_cast<int>(EArkPsiPowers::shift),
            arrivalPosition,
            "native Shift PerformShift arrival");
    }
    return result;
}

