static std::string BuildNativeNpcSpawnDetail(
    const char* source,
    IEntityArchetype& archetype,
    const Vec3& position,
    unsigned fromStartGameEntityId)
{
    std::ostringstream detail;
    detail
        << (source ? source : "spawn")
        << " fromStart=" << fromStartGameEntityId
        << " pos=" << position.x << "," << position.y << "," << position.z;

    uint64_t archetypeId = 0;
    const char* archetypeName = nullptr;
    IEntityClass* archetypeClass = nullptr;
    const char* className = nullptr;
    std::string reason;
    if (TryGuardedCall("native npc spawn archetype GetId", [&archetype]() { return archetype.GetId(); }, archetypeId, &reason))
        detail << " archetype=" << archetypeId;
    if (TryGuardedCall("native npc spawn archetype GetName", [&archetype]() { return archetype.GetName(); }, archetypeName, &reason))
        detail << " archetypeName=" << StatusToken(ReadRuntimeCString(archetypeName, 96));
    if (TryGuardedCall("native npc spawn archetype GetClass", [&archetype]() { return archetype.GetClass(); }, archetypeClass, &reason) &&
        archetypeClass &&
        TryGuardedCall("native npc spawn archetype class GetName", [archetypeClass]() { return archetypeClass->GetName(); }, className, &reason))
    {
        detail << " archetypeClass=" << StatusToken(ReadRuntimeCString(className, 64));
    }
    if (!reason.empty())
        detail << " guard=" << StatusToken(reason);

    return detail.str();
}

