static IEntity* ArkNpcSpawnManager_CreateNpcCorpse0_SpawnTrace_Hook(
    IEntityArchetype& archetype,
    Vec3 const& position,
    Quat const& rotation,
    const char* poseAnimationName,
    bool rigorMortis,
    unsigned fromStartGameEntityId)
{
    // Zustand vor InvokeOrig merken. Der Originalcall kann reentrant
    // Load-/Transition-Zustände verändern.
    const bool suppressInstrumentationBefore =
        !gMod ||
        gMod->ShouldSuppressNativeSpawnInstrumentation();

    // Der originale Engine-Call bleibt notwendig.
    IEntity* entity =
        s_hookArkNpcSpawnManagerCreateNpcCorpse0.InvokeOrig(
            archetype,
            position,
            rotation,
            poseAnimationName,
            rigorMortis,
            fromStartGameEntityId);

    // Sowohl Eintrittszustand als auch Zustand nach InvokeOrig prüfen.
    if (suppressInstrumentationBefore ||
        !gMod ||
        gMod->ShouldSuppressNativeSpawnInstrumentation() ||
        !gMod->ShouldTraceNativeNpcSpawn())
    {
        return entity;
    }

    std::string detail =
        BuildNativeNpcSpawnDetail(
            "CreateNpcCorpse/pose",
            archetype,
            position,
            fromStartGameEntityId);

    detail +=
        " pose=" +
        StatusToken(ReadRuntimeCString(poseAnimationName, 64));

    detail +=
        " rigor=" +
        std::to_string(rigorMortis ? 1 : 0);

    gMod->RecordNativeNpcSpawnTrace(
        "ArkNpcSpawnManager::CreateNpcCorpse pose after",
        entity,
        detail.c_str());

    return entity;
}

static void CEntitySystem_OnEntityEvent_TransitionListenerGuard_Hook(
    CEntitySystem* entitySystem,
    CEntity* entity,
    SEntityEvent& event)
{
    const EntityId entityId = entity ? entity->m_nID : INVALID_ENTITYID;
    if (gMod &&
        gMod->IsRuntimeTransitionCleanupPrepared() &&
        event.event == ENTITY_EVENT_DONE &&
        entityId != INVALID_ENTITYID &&
        entitySystem &&
        entitySystem->m_eventListenerBeingProcessedRefCount == 0)
    {
        // Entity proxies/components have already received DONE. Inventory
        // listeners can invalidate themselves there while leaving their raw
        // CEntitySystem registration behind; remove only those dead entries
        // immediately before the native raw-listener loop dereferences them.
        auto& listeners = entitySystem->m_eventListeners[ENTITY_EVENT_DONE];
        auto range = listeners.equal_range(entityId);
        uint32_t pruned = 0;
        static const std::array<std::uintptr_t, 4> purecallAddresses = []()
        {
            std::array<std::uintptr_t, 4> addresses{};
            constexpr const char* modules[] = {
                "vcruntime140.dll",
                "ucrtbase.dll",
                "msvcrt.dll",
                "api-ms-win-crt-runtime-l1-1-0.dll",
            };
            for (size_t i = 0; i < addresses.size(); ++i)
            {
                const HMODULE runtime = GetModuleHandleA(modules[i]);
                addresses[i] = reinterpret_cast<std::uintptr_t>(
                    runtime ? GetProcAddress(runtime, "_purecall") : nullptr);
            }
            return addresses;
        }();
        for (auto it = range.first; it != range.second;)
        {
            IEntityEventListener* listener = it->second;
            const void* vtableAddress = nullptr;
            const void* callback = nullptr;
            bool callable =
                listener &&
                IsLikelyRuntimeCppObject(listener) &&
                TryReadRuntimeValue(
                    reinterpret_cast<const void* const*>(listener),
                    vtableAddress) &&
                vtableAddress &&
                TryReadRuntimeValue(
                    reinterpret_cast<const void* const*>(vtableAddress) + 1,
                    callback) &&
                callback &&
                CoopRuntimeGuards::IsExecutableRuntimePointer(callback);
            if (callable)
            {
                const auto isKnownPurecall = [](const void* target)
                {
                    const auto address = reinterpret_cast<std::uintptr_t>(target);
                    return address != 0 &&
                        std::find(purecallAddresses.begin(), purecallAddresses.end(), address) !=
                            purecallAddresses.end();
                };

                bool purecallTarget = isKnownPurecall(callback);
                uint16_t thunkOpcode = 0;
                int32_t thunkDisplacement = 0;
                if (!purecallTarget &&
                    TryReadRuntimeValue(reinterpret_cast<const uint16_t*>(callback), thunkOpcode) &&
                    thunkOpcode == 0x25ff &&
                    TryReadRuntimeValue(
                        reinterpret_cast<const int32_t*>(
                            reinterpret_cast<const std::byte*>(callback) + sizeof(uint16_t)),
                        thunkDisplacement))
                {
                    const auto* importSlot =
                        reinterpret_cast<const std::byte*>(callback) + 6 + thunkDisplacement;
                    const void* importTarget = nullptr;
                    if (TryReadRuntimeValue(
                            reinterpret_cast<const void* const*>(importSlot),
                            importTarget))
                    {
                        purecallTarget = isKnownPurecall(importTarget);
                    }
                }
                callable = !purecallTarget;
            }
            if (!callable)
            {
                it = listeners.erase(it);
                ++pruned;
            }
            else
            {
                ++it;
            }
        }
        if (pruned != 0)
        {
            LogCoop(
                "pruned invalid native DONE listener before raw dispatch count=" +
                std::to_string(pruned) +
                " entity=" + std::to_string(entityId));
        }
    }

    s_hookCEntitySystemOnEntityEvent.InvokeOrig(entitySystem, entity, event);
}

