    const bool result = s_hookArkNpcMimicEntitySemantic.InvokeOrig(npc, targetEntity, reason, ignorePsi);
    --s_npcMimicRequestDepth;
    s_npcMimicRequestIgnorePsi = previousIgnorePsi;
