static bool ArkNpc_TryPerformAnyAbility_SemanticTrace_Hook(ArkNpc* npc, unsigned targetEntityId)
{
    const EntityId requestedTargetId = static_cast<EntityId>(targetEntityId);
    const EntityId effectiveTargetId = gMod
        ? gMod->ResolveRemoteDrivenEnemyLocalCombatTarget(
            npc,
            "ArkNpc::TryPerformAnyAbility",
            0,
            requestedTargetId)
        : requestedTargetId;

    if (gMod)
    {
        const std::string detail =
            "requested=" + std::to_string(requestedTargetId) +
            " selectionTarget=" + std::to_string(effectiveTargetId);
        gMod->RecordNpcSemanticTrace(
            "ArkNpc::TryPerformAnyAbility:before",
            npc,
            0,
            effectiveTargetId,
            0,
            detail.c_str());
    }

    // This is Vanilla's ability-selection entry, before a concrete context is
    // chosen. Give it the process-local player instead of the authority
    // owner's proxy; the native prerequisites still choose the exact attack,
    // turn or positioning ability. Later gates suppress only local root motion.
    const bool result = s_hookArkNpcTryPerformAnyAbilitySemantic.InvokeOrig(
        npc,
        static_cast<unsigned>(effectiveTargetId));
    if (gMod)
    {
        const std::string detail =
            "result=" + std::to_string(result ? 1 : 0) +
            " requested=" + std::to_string(requestedTargetId);
        gMod->RecordNpcSemanticTrace(
            "ArkNpc::TryPerformAnyAbility:after",
            npc,
            0,
            effectiveTargetId,
            result ? 1u : 0u,
            detail.c_str());
    }
    return result;
}

static bool ArkNpc_TryPerformAbilityContext0_SemanticTrace_Hook(
    ArkNpc* npc,
    uint64_t contextId,
    const IEntity* targetEntity,
    const IEntity* useEntity)
{
    const EntityId requestedTargetId = ReadSemanticTraceEntityId(targetEntity);
    EntityId targetId = gMod
        ? gMod->ResolveRemoteDrivenEnemyLocalCombatTarget(
            npc,
            "ArkNpc::TryPerformAbilityContext0",
            contextId,
            requestedTargetId)
        : requestedTargetId;
    const IEntity* effectiveTargetEntity = targetEntity;
    if (targetId != requestedTargetId && gEnv && gEnv->pEntitySystem)
    {
        if (const IEntity* resolvedTarget = gEnv->pEntitySystem->GetEntity(targetId))
            effectiveTargetEntity = resolvedTarget;
        else
            targetId = requestedTargetId;
    }
    const EntityId useId = ReadSemanticTraceEntityId(useEntity);
    const bool consumeLocalAuthorityAbility = ShouldConsumeLocalAuthorityAbility(npc, contextId);
    if (gMod && !consumeLocalAuthorityAbility && gMod->ShouldBlockRemoteDrivenEnemyIntent(
            npc,
            "ArkNpc::TryPerformAbilityContext0",
            contextId,
            targetId,
            CoopProtocol::kEnemyLocomotionFlagAttacking))
    {
        return false;
    }

    if (gMod)
    {
        const std::string detail = "use=" + std::to_string(useId);
        gMod->RecordNpcSemanticTrace("ArkNpc::TryPerformAbilityContext0:before", npc, contextId, targetId, 0, detail.c_str());
    }
    const bool nativeResult = s_hookArkNpcTryPerformAbilityContext0Semantic.InvokeOrig(
        npc,
        contextId,
        effectiveTargetEntity,
        useEntity);
    // A pure authority-owned positioning branch is a completed no-op on this
    // observer. This releases Vanilla from SideStep/Shift retry state while a
    // mixed movement/attack context remains unavailable because no local
    // attack was performed.
    const bool result = consumeLocalAuthorityAbility
        ? CompleteConsumedLocalAuthorityDecision(contextId)
        : nativeResult;
    if (gMod)
    {
        const std::string detail =
            "result=" + std::to_string(result ? 1 : 0) +
            " nativeResult=" + std::to_string(nativeResult ? 1 : 0) +
            " consumedAuthorityAbility=" + std::to_string(consumeLocalAuthorityAbility ? 1 : 0) +
            " use=" + std::to_string(useId);
        gMod->RecordNpcSemanticTrace(
            "ArkNpc::TryPerformAbilityContext0:after",
            npc,
            contextId,
            targetId,
            result ? 1u : 0u,
            detail.c_str());
        if (result)
            gMod->StartLocalFocusedOperatorCombatForHook(npc, contextId, targetId);
    }
    return result;
}

