static std::uintptr_t ArkNpcAbility_Perform_SemanticTrace_Hook(
    std::uintptr_t abilityRaw,
    std::uintptr_t npcRaw,
    std::uintptr_t contextIdRaw,
    std::uintptr_t paramsRaw,
    std::uintptr_t abilityInstanceRaw)
{
    // This is the only path that calls the trampoline. Its return type remains
    // uintptr_t throughout, so the complete native RAX value is preserved.
    const auto invokeOriginal = [&]() -> std::uintptr_t
    {
        return s_hookArkNpcAbilityPerformSemantic.InvokeOrig(
            abilityRaw,
            npcRaw,
            contextIdRaw,
            paramsRaw,
            abilityInstanceRaw);
    };

    // During load/restore, perform no object inspection, no entity lookup,
    // no tracing and no authority decision. Remain a transparent ABI bridge.
    if (!gMod || gMod->ShouldBypassArkNpcAbilityPerformHook())
        return invokeOriginal();

    const auto* ability =
        reinterpret_cast<const ArkNpcAbility*>(abilityRaw);

    auto* npc =
        reinterpret_cast<ArkNpc*>(npcRaw);

    const auto* params =
        reinterpret_cast<const ArkNpcAbilityParams*>(paramsRaw);

    auto* abilityInstance =
        reinterpret_cast<ArkNpcAbilityInstance*>(abilityInstanceRaw);

    const std::uint64_t contextId =
        static_cast<std::uint64_t>(contextIdRaw);

    // An aliased or incorrectly identified call through this RVA may have a
    // completely different argument shape. Never interpret it as Perform
    // unless every required argument has a credible runtime representation.
    const bool plausiblePerformCall =
        ability != nullptr &&
        npc != nullptr &&
        params != nullptr &&
        abilityInstance != nullptr &&
        IsLikelyRuntimeCppObject(
            ability,
            sizeof(void*)) &&
        IsLikelyRuntimeCppObject(
            npc,
            sizeof(void*) * 4) &&
        IsReadableRuntimePointer(
            params,
            sizeof(void*)) &&
        IsReadableRuntimePointer(
            abilityInstance,
            sizeof(void*));

    if (!plausiblePerformCall)
        return invokeOriginal();

    EntityId npcEntityId = INVALID_ENTITYID;
    IEntity* npcEntity = nullptr;
    ArkNpc* npcFromEntity = nullptr;

    const bool npcResolved =
        TryGuardedCall(
            "npc ability perform GetEntityId",
            [npc]()
            {
                return npc->GetEntityId();
            },
            npcEntityId,
            nullptr) &&
        npcEntityId != INVALID_ENTITYID &&
        npcEntityId != 0 &&
        gEnv != nullptr &&
        gEnv->pEntitySystem != nullptr &&
        TryGuardedCall(
            "npc ability perform entity lookup",
            [npcEntityId]() -> IEntity*
            {
                return gEnv && gEnv->pEntitySystem
                    ? gEnv->pEntitySystem->GetEntity(npcEntityId)
                    : nullptr;
            },
            npcEntity,
            nullptr) &&
        npcEntity != nullptr &&
        TryGuardedCall(
            "npc ability perform verify ArkNpc",
            [npcEntity]() -> ArkNpc*
            {
                return EntityUtils::GetArkNpc(npcEntity);
            },
            npcFromEntity,
            nullptr) &&
        npcFromEntity == npc;

    // If this call does not resolve back to the exact ArkNpc passed in RDX,
    // treat it as another ABI user of the same RVA and preserve it unchanged.
    if (!npcResolved ||
        gMod->ShouldBypassArkNpcAbilityPerformHook())
    {
        return invokeOriginal();
    }

    constexpr std::uintptr_t kResultFailed =
        static_cast<std::uintptr_t>(
            EArkNpcAbilityPerformanceResult::failed);

    constexpr std::uintptr_t kResultCompleted =
        static_cast<std::uintptr_t>(
            EArkNpcAbilityPerformanceResult::completed);

    constexpr std::uintptr_t kResultInProgress =
        static_cast<std::uintptr_t>(
            EArkNpcAbilityPerformanceResult::inProgress);

    bool consumeAuthorityBody = false;
    bool blockIntent = false;

    try
    {
        consumeAuthorityBody =
            ShouldConsumeLocalAuthorityAbility(
                npc,
                contextId);

        if (!consumeAuthorityBody)
        {
            blockIntent =
                gMod->ShouldBlockRemoteDrivenEnemyIntent(
                    npc,
                    "ArkNpcAbility::Perform",
                    contextId,
                    npcEntityId,
                    CoopProtocol::kEnemyLocomotionFlagAttacking);
        }
    }
    catch (...)
    {
        // No C++ exception may escape through a native engine boundary.
        return invokeOriginal();
    }

    if (consumeAuthorityBody)
    {
        try
        {
            gMod->RecordNpcSemanticTrace(
                "ArkNpcAbility::Perform:consumed-authority-body",
                npc,
                contextId,
                npcEntityId,
                static_cast<std::uint32_t>(
                    EArkNpcAbilityPerformanceResult::completed),
                "native prerequisites passed; local authority-owned action "
                "completed as no-op; authority presentation retained");
        }
        catch (...)
        {
            // Tracing must never affect native behavior.
        }

        // Returned as a full-width uintptr_t. Numerically this is still the
        // expected enum value 1 for genuine Perform callers.
        return kResultCompleted;
    }

    if (blockIntent)
    {
        // Full-width return, numerically the expected enum value 0.
        return kResultFailed;
    }

    try
    {
        const std::string chain =
            CaptureMannequinCallChainTrace(
                "ArkNpcAbility::Perform");

        std::ostringstream detail;
        detail
            << "abilityPtr=0x"
            << std::hex
            << abilityRaw
            << std::dec
            << chain;

        const std::string detailString = detail.str();

        gMod->RecordNpcSemanticTrace(
            "ArkNpcAbility::Perform:before",
            npc,
            contextId,
            npcEntityId,
            0,
            detailString.c_str());
    }
    catch (...)
    {
        // Continue into Vanilla even if diagnostic allocation fails.
    }

    // Never assign this directly to EArkNpcAbilityPerformanceResult.
    const std::uintptr_t rawResult =
        invokeOriginal();

    // The load/transition state may have changed inside the native call.
    if (!gMod ||
        gMod->ShouldBypassArkNpcAbilityPerformHook())
    {
        return rawResult;
    }

    // Only interpret the value as an enum after proving it is in the enum
    // domain. Anything else may be a pointer or another aliased return value.
    if (rawResult <= kResultInProgress)
    {
        const auto resultForTrace =
            static_cast<EArkNpcAbilityPerformanceResult>(
                static_cast<std::uint32_t>(rawResult));

        try
        {
            std::ostringstream detail;
            detail
                << "abilityPtr=0x"
                << std::hex
                << abilityRaw
                << std::dec
                << " result="
                << static_cast<int>(resultForTrace);

            const std::string detailString = detail.str();

            gMod->RecordNpcSemanticTrace(
                "ArkNpcAbility::Perform:after",
                npc,
                contextId,
                npcEntityId,
                static_cast<std::uint32_t>(resultForTrace),
                detailString.c_str());
        }
        catch (...)
        {
            // Preserve the native result even if tracing fails.
        }
    }

    // Crucially, return the original full-width RAX value. Do not return the
    // enum-shaped resultForTrace.
    return rawResult;
}

void ModMain::RegisterOperatorLaserHelperForHook(
    ArkOperatorLaserHelper* helper,
    ArkNpc* npc,
    float damagePerSecond)
{
    if (!helper || !npc)
        return;

    EntityId entityId = INVALID_ENTITYID;
    if (!TryGuardedCall(
            "operator laser register GetEntityId",
            [npc]() { return npc->GetEntityId(); },
            entityId,
            nullptr) ||
        entityId == INVALID_ENTITYID)
    {
        return;
    }

    const auto [it, inserted] = m_operatorLaserBindings.try_emplace(helper);
    OperatorLaserBinding& binding = it->second;
    binding.helper = helper;
    binding.npc = npc;
    binding.entityId = entityId;
    binding.damagePerSecond = damagePerSecond;
    if (inserted)
        ++m_operatorLaserHelperRegistrations;
}

void ModMain::UnregisterOperatorLaserHelperForHook(ArkOperatorLaserHelper* helper)
{
    if (!helper)
        return;
    m_operatorLaserBindings.erase(helper);
}

void ModMain::OnNativeOperatorLaserStartForHook(
    ArkOperatorLaserHelper* helper,
    ArkNpc* npc,
    float chargeDuration)
{
    if (!helper || !npc)
        return;
    if (m_operatorLaserBindings.find(helper) == m_operatorLaserBindings.end())
        RegisterOperatorLaserHelperForHook(helper, npc, helper->m_laserDamagePerSecond);
    ++m_operatorLaserNativeStarts;
    m_lastOperatorLaserEvent =
        "native_start_entity_" + std::to_string(npc->GetEntityId()) +
        "_charge_" + std::to_string(chargeDuration);
}

void ModMain::OnNativeOperatorLaserTurnOffForHook(
    ArkOperatorLaserHelper* helper,
    ArkNpc* npc)
{
    if (!helper)
        return;
    ++m_operatorLaserNativeStops;
    const auto it = m_operatorLaserBindings.find(helper);
    if (it != m_operatorLaserBindings.end() && it->second.localCombatActive)
    {
        it->second.localCombatActive = false;
        ++m_operatorLaserLocalStops;
    }
    m_lastOperatorLaserEvent =
        "native_stop_entity_" + std::to_string(npc ? npc->GetEntityId() : INVALID_ENTITYID);
}

bool ModMain::ShouldDeferLocalFocusedOperatorTurnOffForHook(
    ArkOperatorLaserHelper* helper,
    ArkNpc* npc)
{
    if (!helper || !npc)
        return false;

    const auto it = m_operatorLaserBindings.find(helper);
    if (it == m_operatorLaserBindings.end() ||
        !it->second.localCombatActive ||
        it->second.npc != npc)
    {
        return false;
    }

    OperatorLaserBinding& binding = it->second;
    if (m_networkMode == CoopNetworkMode::Off ||
        !IsSessionGameplayReady() ||
        !gEnv ||
        !gEnv->pEntitySystem)
    {
        return false;
    }

    IEntity* entity = gEnv->pEntitySystem->GetEntity(binding.entityId);
    const auto netIt = m_enemyNetIdsByEntity.find(binding.entityId);
    EnemyAuthorityState* state = netIt == m_enemyNetIdsByEntity.end()
        ? nullptr
        : FindEnemyAuthorityByNetId(netIt->second);
    if (!entity || !state)
        return false;

    const CoopEnemyControlPolicy::Context controlContext =
        BuildLocalEnemyControlPolicyContext(*state, *entity);
    const CoopEnemyControlPolicy::Decision decision =
        CoopEnemyControlPolicy::Evaluate(controlContext);
    if (!controlContext.localHasAttention ||
        decision.mode != CoopEnemyControlPolicy::EnemyControlMode::LocalTargetRemoteOwner ||
        !decision.preserveLocalCombat)
    {
        return false;
    }

    constexpr float kMinimumLocalLaserLifetimeSeconds = 1.25f;
    if (binding.localCombatSeconds >= kMinimumLocalLaserLifetimeSeconds)
        return false;

    // Strafe locomotion is authority-owned, so the observer-side Vanilla
    // ability can request shutdown before its native 0.5 s charge completes.
    // Preserve the exact helper only long enough to produce a real beam pulse;
    // TickLocalFocusedOperatorCombat honors this pending native stop afterward.
    binding.nativeTurnOffPending = true;
    ++m_operatorLaserDeferredStops;
    m_lastOperatorLaserEvent =
        "local_defer_native_stop_entity_" + std::to_string(binding.entityId) +
        "_context_" + std::to_string(binding.localContextId) +
        "_seconds_" + std::to_string(binding.localCombatSeconds);
    return true;
}

void ModMain::OnNativeOperatorLaserDamageForHook(ArkNpc* npc)
{
    ++m_operatorLaserDamageCalls;
    if (m_operatorLaserDamageCalls <= 4 || (m_operatorLaserDamageCalls % 120u) == 0)
    {
        EntityId entityId = INVALID_ENTITYID;
        if (npc)
        {
            TryGuardedCall(
                "operator laser damage trace GetEntityId",
                [npc]() { return npc->GetEntityId(); },
                entityId,
                nullptr);
        }
        m_lastOperatorLaserEvent =
            "native_damage_entity_" + std::to_string(entityId) +
            "_calls_" + std::to_string(m_operatorLaserDamageCalls);
    }
}

void ModMain::OnNativeOperatorLaserUpdateForHook(
    ArkOperatorLaserHelper* helper,
    ArkNpc* npc)
{
    if (!helper || !npc)
        return;
    auto it = m_operatorLaserBindings.find(helper);
    if (it == m_operatorLaserBindings.end())
    {
        RegisterOperatorLaserHelperForHook(helper, npc, helper->m_laserDamagePerSecond);
        it = m_operatorLaserBindings.find(helper);
    }
    if (it != m_operatorLaserBindings.end())
        it->second.lastNativeUpdateSeconds = GetNowSeconds();
}

void ModMain::StartLocalFocusedOperatorCombatForHook(
    ArkNpc* npc,
    uint64_t contextId,
    EntityId targetEntityId)
{
    if (!npc ||
        (contextId != 1004 && contextId != 1005 && contextId != 1006) ||
        m_networkMode == CoopNetworkMode::Off ||
        !IsSessionGameplayReady() ||
        !gEnv ||
        !gEnv->pEntitySystem)
    {
        return;
    }

    ArkPlayer* player = ArkPlayer::GetInstancePtr();
    IEntity* playerEntity = player ? player->GetEntity() : nullptr;
    if (!playerEntity || targetEntityId != playerEntity->GetId())
        return;

    EntityId entityId = INVALID_ENTITYID;
    if (!TryGuardedCall(
            "operator local start GetEntityId",
            [npc]() { return npc->GetEntityId(); },
            entityId,
            nullptr) ||
        entityId == INVALID_ENTITYID)
    {
        return;
    }

    IEntity* entity = gEnv->pEntitySystem->GetEntity(entityId);
    const auto netIt = m_enemyNetIdsByEntity.find(entityId);
    EnemyAuthorityState* state = netIt == m_enemyNetIdsByEntity.end()
        ? nullptr
        : FindEnemyAuthorityByNetId(netIt->second);
    if (!entity || !state)
        return;

    const CoopEnemyControlPolicy::Context controlContext =
        BuildLocalEnemyControlPolicyContext(*state, *entity);
    const CoopEnemyControlPolicy::Decision decision =
        CoopEnemyControlPolicy::Evaluate(controlContext);
    if (!controlContext.localHasAttention ||
        decision.mode != CoopEnemyControlPolicy::EnemyControlMode::LocalTargetRemoteOwner ||
        !decision.preserveLocalCombat)
    {
        return;
    }

    const float expectedDamagePerSecond = contextId == 1004 ? 200.0f : 400.0f;
    OperatorLaserBinding* selected = nullptr;
    float selectedDifference = std::numeric_limits<float>::max();
    for (auto& entry : m_operatorLaserBindings)
    {
        OperatorLaserBinding& binding = entry.second;
        if (binding.npc != npc || binding.entityId != entityId)
            continue;
        const float difference = std::fabs(binding.damagePerSecond - expectedDamagePerSecond);
        if (!selected || difference < selectedDifference)
        {
            selected = &binding;
            selectedDifference = difference;
        }
    }
    if (!selected || selectedDifference > 1.0f)
    {
        m_lastOperatorLaserEvent =
            "local_start_missing_helper_entity_" + std::to_string(entityId) +
            "_context_" + std::to_string(contextId) +
            "_bindings_" + std::to_string(m_operatorLaserBindings.size());
        return;
    }

    if (selected->localCombatActive)
    {
        selected->localTargetEntityId = targetEntityId;
        return;
    }

    for (auto& entry : m_operatorLaserBindings)
    {
        OperatorLaserBinding& other = entry.second;
        if (&other == selected || other.npc != npc || !other.localCombatActive)
            continue;
        if (other.helper && other.npc)
        {
            TryGuardedVoidCall(
                "operator local replace TurnOffLaser",
                [&other]() { s_hookArkOperatorLaserTurnOff.InvokeOrig(other.helper, *other.npc); },
                nullptr);
        }
        other.localCombatActive = false;
        ++m_operatorLaserLocalStops;
    }

    ArkOperatorLaserHelper::Stage stage = ArkOperatorLaserHelper::Stage::Off;
    if (!CoopRuntimeGuards::TryReadRuntimeValue(&selected->helper->m_stage, stage))
        return;
    if (stage == ArkOperatorLaserHelper::Stage::Off)
    {
        if (!TryGuardedVoidCall(
                "operator local StartChargingLaser",
                [selected]()
                {
                    s_hookArkOperatorLaserStart.InvokeOrig(selected->helper, *selected->npc, 0.5f);
                },
                nullptr))
        {
            m_lastOperatorLaserEvent = "local_start_failed_entity_" + std::to_string(entityId);
            return;
        }
    }

    selected->localCombatSeconds = 0.0f;
    selected->localContextId = contextId;
    selected->localTargetEntityId = targetEntityId;
    selected->nativeTurnOffPending = false;
    selected->localCombatActive = true;
    ++m_operatorLaserLocalStarts;
    m_lastOperatorLaserEvent =
        "local_start_net_" + std::to_string(state->netId) +
        "_entity_" + std::to_string(entityId) +
        "_context_" + std::to_string(contextId) +
        "_dps_" + std::to_string(selected->damagePerSecond);
}

void ModMain::TickLocalFocusedOperatorCombat(float frameTime)
{
    const float elapsedTime = std::clamp(frameTime, 0.0f, 0.1f);
    const float now = GetNowSeconds();
    for (auto& entry : m_operatorLaserBindings)
    {
        OperatorLaserBinding& binding = entry.second;
        if (!binding.localCombatActive)
            continue;

        auto stopLocalCombat = [&](const char* reason)
        {
            if (binding.helper && binding.npc)
            {
                ArkOperatorLaserHelper::Stage stage = ArkOperatorLaserHelper::Stage::Off;
                if (CoopRuntimeGuards::TryReadRuntimeValue(&binding.helper->m_stage, stage) &&
                    stage != ArkOperatorLaserHelper::Stage::Off)
                {
                    TryGuardedVoidCall(
                        "operator local TurnOffLaser",
                        [&binding]()
                        {
                            s_hookArkOperatorLaserTurnOff.InvokeOrig(binding.helper, *binding.npc);
                        },
                        nullptr);
                }
            }
            binding.localCombatActive = false;
            ++m_operatorLaserLocalStops;
            m_lastOperatorLaserEvent =
                "local_stop_entity_" + std::to_string(binding.entityId) +
                "_context_" + std::to_string(binding.localContextId) +
                "_reason_" + (reason && reason[0] ? std::string(reason) : std::string("-"));
        };

        if (!binding.helper ||
            !binding.npc ||
            !CoopRuntimeGuards::IsLikelyRuntimeCppObject(binding.npc, sizeof(void*) * 4) ||
            !CoopRuntimeGuards::IsLikelyRuntimeCppObject(binding.helper, sizeof(void*) * 4) ||
            !gEnv ||
            !gEnv->pEntitySystem ||
            m_networkMode == CoopNetworkMode::Off ||
            !IsSessionGameplayReady())
        {
            stopLocalCombat("runtime_unavailable");
            continue;
        }

        EntityId currentEntityId = INVALID_ENTITYID;
        if (!TryGuardedCall(
                "operator local tick GetEntityId",
                [&binding]() { return binding.npc->GetEntityId(); },
                currentEntityId,
                nullptr) ||
            currentEntityId != binding.entityId)
        {
            stopLocalCombat("entity_changed");
            continue;
        }

        IEntity* entity = gEnv->pEntitySystem->GetEntity(binding.entityId);
        const auto netIt = m_enemyNetIdsByEntity.find(binding.entityId);
        EnemyAuthorityState* state = netIt == m_enemyNetIdsByEntity.end()
            ? nullptr
            : FindEnemyAuthorityByNetId(netIt->second);
        if (!entity || !state)
        {
            stopLocalCombat("state_missing");
            continue;
        }

        const CoopEnemyControlPolicy::Context controlContext =
            BuildLocalEnemyControlPolicyContext(*state, *entity);
        const CoopEnemyControlPolicy::Decision decision =
            CoopEnemyControlPolicy::Evaluate(controlContext);
        if (!controlContext.localHasAttention ||
            decision.mode != CoopEnemyControlPolicy::EnemyControlMode::LocalTargetRemoteOwner ||
            !decision.preserveLocalCombat)
        {
            stopLocalCombat("local_focus_lost");
            continue;
        }

        binding.localCombatSeconds += elapsedTime;
        constexpr float kMinimumLocalLaserLifetimeSeconds = 1.25f;
        if (binding.nativeTurnOffPending &&
            binding.localCombatSeconds >= kMinimumLocalLaserLifetimeSeconds)
        {
            stopLocalCombat("native_stop_after_minimum_pulse");
            continue;
        }
        // Native ability cleanup normally turns the helper off. This cap is
        // only a fail-safe for a movement callback that was deliberately
        // filtered while authority-owned locomotion remained in control.
        if (binding.localCombatSeconds > 7.5f)
        {
            stopLocalCombat("failsafe_timeout");
            continue;
        }

        ArkOperatorLaserHelper::Stage stage = ArkOperatorLaserHelper::Stage::Off;
        if (!CoopRuntimeGuards::TryReadRuntimeValue(&binding.helper->m_stage, stage) ||
            stage == ArkOperatorLaserHelper::Stage::Off)
        {
            stopLocalCombat("native_off");
            continue;
        }

        const float nativeUpdateWindow = std::max(0.05f, elapsedTime * 2.0f);
        if (now - binding.lastNativeUpdateSeconds <= nativeUpdateWindow)
            continue;

        RetargetLocalFocusedOperatorLaserForHook(binding.helper, binding.npc);
        if (!TryGuardedVoidCall(
                "operator local UpdateLaser",
                [&binding, elapsedTime]()
                {
                    s_hookArkOperatorLaserUpdate.InvokeOrig(binding.helper, *binding.npc, elapsedTime);
                },
                nullptr))
        {
            stopLocalCombat("update_failed");
            continue;
        }
        ++m_operatorLaserLocalTicks;
    }
}

void ModMain::ResetLocalFocusedOperatorCombat(const char* reason)
{
    for (auto& entry : m_operatorLaserBindings)
    {
        OperatorLaserBinding& binding = entry.second;
        if (!binding.localCombatActive)
            continue;
        if (binding.helper && binding.npc)
        {
            ArkOperatorLaserHelper::Stage stage = ArkOperatorLaserHelper::Stage::Off;
            if (CoopRuntimeGuards::TryReadRuntimeValue(&binding.helper->m_stage, stage) &&
                stage != ArkOperatorLaserHelper::Stage::Off)
            {
                TryGuardedVoidCall(
                    "operator local reset TurnOffLaser",
                    [&binding]()
                    {
                        s_hookArkOperatorLaserTurnOff.InvokeOrig(binding.helper, *binding.npc);
                    },
                    nullptr);
            }
        }
        binding.localCombatActive = false;
        ++m_operatorLaserLocalStops;
    }
    if (reason && reason[0])
        m_lastOperatorLaserEvent = std::string("local_reset_") + reason;
}

static void ArkOperatorLaserHelper_Initialize_Hook(
    ArkOperatorLaserHelper* helper,
    ArkNpc& npc,
    float damagePerSecond)
{
    s_hookArkOperatorLaserInitialize.InvokeOrig(helper, npc, damagePerSecond);
    if (gMod)
        gMod->RegisterOperatorLaserHelperForHook(helper, &npc, damagePerSecond);
}

static void ArkOperatorLaserHelper_Destroy_Hook(ArkOperatorLaserHelper* helper)
{
    if (gMod)
        gMod->UnregisterOperatorLaserHelperForHook(helper);
    s_hookArkOperatorLaserDestroy.InvokeOrig(helper);
}

static void ArkOperatorLaserHelper_StartCharging_Hook(
    ArkOperatorLaserHelper* helper,
    ArkNpc& npc,
    float chargeDuration)
{
    s_hookArkOperatorLaserStart.InvokeOrig(helper, npc, chargeDuration);
    if (gMod)
        gMod->OnNativeOperatorLaserStartForHook(helper, &npc, chargeDuration);
}

static void ArkOperatorLaserHelper_TurnOff_Hook(
    ArkOperatorLaserHelper* helper,
    ArkNpc& npc)
{
    if (gMod && gMod->ShouldDeferLocalFocusedOperatorTurnOffForHook(helper, &npc))
        return;
    s_hookArkOperatorLaserTurnOff.InvokeOrig(helper, npc);
    if (gMod)
        gMod->OnNativeOperatorLaserTurnOffForHook(helper, &npc);
}

static void ArkOperatorLaserHelper_UpdateLaser_Hook(
    ArkOperatorLaserHelper* helper,
    ArkNpc& npc,
    float elapsedTime)
{
    if (gMod)
    {
        gMod->OnNativeOperatorLaserUpdateForHook(helper, &npc);
        std::string guardReason;
        TryGuardedVoidCall(
            "operator laser focused target override",
            [&]() { gMod->RetargetLocalFocusedOperatorLaserForHook(helper, &npc); },
            &guardReason);
    }

    s_hookArkOperatorLaserUpdate.InvokeOrig(helper, npc, elapsedTime);
}

static void ArkOperatorLaserHelper_DoDamage_Hook(
    ArkOperatorLaserHelper* helper,
    ArkNpc& npc,
    const float frameTime,
    const EventPhysCollision& collision)
{
    if (gMod && gMod->ShouldSuppressRemoteOperatorLaserDamage(&npc))
        return;
    if (gMod)
        gMod->OnNativeOperatorLaserDamageForHook(&npc);
    s_hookArkOperatorLaserDamage.InvokeOrig(helper, npc, frameTime, collision);
}

static CoopHookStats::Slot* s_hookStatMannequinStoreAction = CoopHookStats::Register("Mannequin::StoreAction");
static void ArkNpcBodyState_StoreAction_Hook(void* stateSlot, void* transitionPayload)
{
    CoopHookStats::Scoped hookStatScope(s_hookStatMannequinStoreAction);
    const std::string callChain = CaptureMannequinCallChainTrace("ArkNpcBodyState::StoreAction");
    if (gMod)
        gMod->RecordNpcMannequinStoreAction(
            "ArkNpcBodyState::StoreAction:before",
            stateSlot,
            transitionPayload,
            callChain.c_str());
    s_hookArkNpcBodyStateStoreAction.InvokeOrig(stateSlot, transitionPayload);
    if (gMod)
        gMod->RecordNpcMannequinStoreAction(
            "ArkNpcBodyState::StoreAction:after",
            stateSlot,
            transitionPayload,
            callChain.c_str());
}

static CoopHookStats::Slot* s_hookStatSetPosRotScale = CoopHookStats::Register("CEntity::SetPosRotScale");
static void CEntity_SetPosRotScale_RemoteEnemyTransform_Hook(
    CEntity* entity,
    Vec3 const& position,
    Quat const& rotation,
    Vec3 const& scale,
    int whyFlags)
{
    CoopHookStats::Scoped hookStatScope(s_hookStatSetPosRotScale);
    TracePostLoadNativeHook("CEntity::SetPosRotScale");
    if (gMod)
        gMod->RecordRuntimeTransformHook(false);
    if (gMod && gMod->ShouldBlockRemoteProxyTransformWrite(entity, "CEntity::SetPosRotScale"))
    {
        gMod->RecordRuntimeTransformHook(true);
        return;
    }
    auto invokeOrig = [&](Vec3 const& safePosition, Quat const& safeRotation)
    {
        if (gMod && gMod->IsPostLoadNativeQuarantineActive())
        {
            std::string guardReason;
            if (!TryGuardedVoidCall(
                    "post-load CEntity::SetPosRotScale orig",
                    [&]() { s_hookCEntitySetPosRotScale.InvokeOrig(entity, safePosition, safeRotation, scale, whyFlags); },
                    &guardReason))
            {
                LogCoop("post-load skipped crashing CEntity::SetPosRotScale reason=" + StatusToken(guardReason.empty() ? std::string("-") : guardReason));
            }
            return;
        }

        s_hookCEntitySetPosRotScale.InvokeOrig(entity, safePosition, safeRotation, scale, whyFlags);
    };

    Vec3 rewrittenPosition = position;
    Quat rewrittenRotation = rotation;
    if (gMod &&
        gMod->TryGetRemoteDrivenEnemyTransformOverride(
            entity,
            "CEntity::SetPosRotScale",
            true,
            true,
            rewrittenPosition,
            rewrittenRotation))
    {
        gMod->RecordRuntimeTransformHook(true);
        invokeOrig(rewrittenPosition, rewrittenRotation);
        return;
    }

    invokeOrig(position, rotation);
}

static CoopHookStats::Slot* s_hookStatSetWorldTM = CoopHookStats::Register("CEntity::SetWorldTM");
static void CEntity_SetWorldTM_RemoteEnemyTransform_Hook(
    CEntity* entity,
    Matrix34 const& tm,
    int whyFlags)
{
    CoopHookStats::Scoped hookStatScope(s_hookStatSetWorldTM);
    TracePostLoadNativeHook("CEntity::SetWorldTM");
    if (gMod)
        gMod->RecordRuntimeTransformHook(false);
    if (gMod && gMod->ShouldBlockRemoteProxyTransformWrite(entity, "CEntity::SetWorldTM"))
    {
        gMod->RecordRuntimeTransformHook(true);
        return;
    }
    auto invokeOrig = [&](Matrix34 const& safeTm)
    {
        if (gMod && gMod->IsPostLoadNativeQuarantineActive())
        {
            std::string guardReason;
            if (!TryGuardedVoidCall(
                    "post-load CEntity::SetWorldTM orig",
                    [&]() { s_hookCEntitySetWorldTM.InvokeOrig(entity, safeTm, whyFlags); },
                    &guardReason))
            {
                LogCoop("post-load skipped crashing CEntity::SetWorldTM reason=" + StatusToken(guardReason.empty() ? std::string("-") : guardReason));
            }
            return;
        }

        s_hookCEntitySetWorldTM.InvokeOrig(entity, safeTm, whyFlags);
    };

    Matrix34 rewrittenTm = tm;
    const Vec3 originalPosition = tm.GetTranslation();
    Quat originalRotation(tm);
    originalRotation.Normalize();
    Vec3 rewrittenPosition = originalPosition;
    Quat rewrittenRotation = originalRotation;
    if (gMod &&
        gMod->TryGetRemoteDrivenEnemyTransformOverride(
            entity,
            "CEntity::SetWorldTM",
            true,
            true,
            rewrittenPosition,
            rewrittenRotation))
    {
        gMod->RecordRuntimeTransformHook(true);
        const bool positionChanged = (rewrittenPosition - originalPosition).GetLengthSquared() > 0.000001f;
        const bool rotationChanged = std::fabs(originalRotation | rewrittenRotation) < 0.999999f;
        if (rotationChanged)
            rewrittenTm = Matrix34::Create(tm.GetScale(), rewrittenRotation, positionChanged ? rewrittenPosition : originalPosition);
        else if (positionChanged)
            rewrittenTm.SetTranslation(rewrittenPosition);

        invokeOrig(rewrittenTm);
        return;
    }

    invokeOrig(tm);
}

