static bool CryAction_SaveGame_Hook(
    CCryAction* action,
    const char* path,
    bool quick,
    bool forceImmediate,
    ESaveGameReason reason,
    bool ignoreDelay,
    const char* checkPointName)
{
    std::string redirectedPath;
    const char* effectivePath = path;
    if (gMod)
    {
        redirectedPath = gMod->GetSaveGamePathOverrideForHook(path, quick, static_cast<int>(reason), checkPointName);
        if (!redirectedPath.empty())
            effectivePath = redirectedPath.c_str();

        gMod->OnCryActionSaveGameRequested(
            effectivePath,
            quick,
            forceImmediate,
            static_cast<int>(reason),
            ignoreDelay,
            checkPointName);
    }

    const bool result = s_hookCryActionSaveGame.InvokeOrig(action, effectivePath, quick, forceImmediate, reason, ignoreDelay, checkPointName);
    if (gMod)
    {
        gMod->OnCryActionSaveGameReturned(
            effectivePath,
            quick,
            forceImmediate,
            static_cast<int>(reason),
            ignoreDelay,
            checkPointName,
            result);
    }
    return result;
}

