static bool ActiveSave_WriteComplete_Hook(void* activeSave, const char* saveName, void* fileHandleRef)
{
    if (gMod && NativeSaveInstrumentationEnabled())
    {
        gMod->BeginNativeFinalStreamCapture(saveName);
        gMod->InjectNativeWriteCompleteSections(
            reinterpret_cast<ISaveGame*>(activeSave),
            saveName);
    }

    const bool result = s_hookActiveSaveWriteComplete.InvokeOrig(activeSave, saveName, fileHandleRef);
    if (gMod)
        gMod->OnActiveSaveWriteComplete(activeSave, saveName, fileHandleRef, result);
    return result;
}

void ModMain::InjectNativeWriteCompleteSections(ISaveGame* saveGame, const char* saveName)
{
    if (!saveGame)
        return;

    const std::string safeSaveName = ReadRuntimeCString(saveName, 260);

    if (EnvFlagEnabled("COOP_NATIVE_WRITE_COMPLETE_ADDSECTION_PROBE"))
    {
        std::string probeReason;
        const bool probeOk = TryWriteNativeSideBlobSection(
            saveGame,
            kNativeWriteCompleteProbeSection,
            "native write-complete AddSection probe",
            [](TSerialize& serializer)
            {
                int marker = 0x2340C001;
                int version = 1;
                serializer.Value("marker", marker);
                serializer.Value("version", version);
            },
            &probeReason);
        LogCoop(
            std::string("native_write_complete_addsection_probe result=") +
            (probeOk ? "1" : "0") +
            " save=" + StatusToken(safeSaveName) +
            (probeReason.empty() ? std::string() : " guard=" + StatusToken(probeReason)));
    }

    if (!EnvFlagEnabled("COOP_NATIVE_WRITE_COMPLETE_FRAGMENT_SECTION"))
        return;

    std::vector<uint8_t> selectedPayloadBytes;
    CoopNativeFragmentPayload::ParsedPayload selectedPayload;
    std::string selectedPayloadSource = "active_capture";

    if (EnvFlagEnabled("COOP_NATIVE_WRITE_COMPLETE_REMOTE_PLAYER_SECTION"))
    {
        TryLoadHostRemoteNativeFragmentPayloadForWriteComplete(
            selectedPayloadBytes,
            selectedPayload,
            selectedPayloadSource);
    }

    const bool hasObservedCapture =
        m_nativeSideBlobCapture.active ||
        m_nativeSideBlobCapture.sawPlayerWrite ||
        m_nativeSideBlobCapture.sawInventoryWrite ||
        m_nativeSideBlobCapture.sawItemWrite;
    if (hasObservedCapture && !m_nativeSideBlobCapture.hasNativeFragmentPayload)
        TryAttachNativeFragmentPayload(m_nativeSideBlobCapture, "ActiveSave::WriteComplete pre-section");

    if (selectedPayloadBytes.empty() &&
        m_nativeSideBlobCapture.hasNativeFragmentPayload &&
        !m_nativeSideBlobCapture.nativeFragmentPayload.empty())
    {
        selectedPayloadBytes = m_nativeSideBlobCapture.nativeFragmentPayload;
        selectedPayload = CoopNativeFragmentPayload::ParseInventoryPayload(selectedPayloadBytes);
        selectedPayloadSource = "active_capture";
        if (!selectedPayload.ok)
            selectedPayloadBytes.clear();
    }

    if (selectedPayloadBytes.empty() || !selectedPayload.ok)
    {
        LogCoop(
            "native_write_complete_fragment_section skipped_no_payload save=" +
            StatusToken(safeSaveName) +
            " source=" + StatusToken(selectedPayloadSource));
        return;
    }

    const std::vector<uint8_t>& payloadBytes = selectedPayloadBytes;
    const uint32_t chunkBytes = static_cast<uint32_t>(kNativeWriteCompleteFragmentPayloadHexBytesPerChunk);
    const uint32_t chunkCount = static_cast<uint32_t>(
        (payloadBytes.size() + kNativeWriteCompleteFragmentPayloadHexBytesPerChunk - 1) /
        kNativeWriteCompleteFragmentPayloadHexBytesPerChunk);

    std::string fragmentReason;
    const bool fragmentOk = TryWriteNativeSideBlobSection(
        saveGame,
        kNativeWriteCompleteFragmentPayloadSection,
        "native write-complete fragment payload section",
        [&payloadBytes, &selectedPayload, chunkBytes, chunkCount](TSerialize& serializer)
        {
            int version = 1;
            int payloadVersion = static_cast<int>(selectedPayload.version);
            uint32_t totalBytes = selectedPayload.totalBytes;
            uint32_t payloadCrc = selectedPayload.payloadChecksum;
            uint32_t rawCrc = selectedPayload.rawByteChecksum;
            uint32_t ranges = selectedPayload.rangeRecords;
            uint32_t inventoryRanges = selectedPayload.inventoryRanges;
            uint32_t itemGroups = selectedPayload.itemGroups;
            uint32_t itemRanges = selectedPayload.itemRanges;
            uint32_t rawBytes = selectedPayload.rawBytes;
            uint64_t runId = selectedPayload.runId;
            uint64_t schemaHash = selectedPayload.schemaHash;
            uint64_t contentHash = selectedPayload.contentHash;
            uint32_t chunkSize = chunkBytes;
            uint32_t chunks = chunkCount;

            serializer.Value("version", version);
            serializer.Value("payloadVersion", payloadVersion);
            serializer.Value("totalBytes", totalBytes);
            serializer.Value("payloadCrc", payloadCrc);
            serializer.Value("rawCrc", rawCrc);
            serializer.Value("ranges", ranges);
            serializer.Value("inventoryRanges", inventoryRanges);
            serializer.Value("itemGroups", itemGroups);
            serializer.Value("itemRanges", itemRanges);
            serializer.Value("rawBytes", rawBytes);
            serializer.Value("runId", runId);
            serializer.Value("schemaHash", schemaHash);
            serializer.Value("contentHash", contentHash);
            serializer.Value("chunkBytes", chunkSize);
            serializer.Value("chunkCount", chunks);

            for (uint32_t i = 0; i < chunkCount; ++i)
            {
                const size_t offset = static_cast<size_t>(i) * kNativeWriteCompleteFragmentPayloadHexBytesPerChunk;
                const std::string key = "chunk" + std::to_string(i);
                string hex = EncodeHexBytesForNativeSection(
                    payloadBytes,
                    offset,
                    kNativeWriteCompleteFragmentPayloadHexBytesPerChunk).c_str();
                serializer.Value(key.c_str(), hex);
            }
        },
        &fragmentReason);

    LogCoop(
        std::string("native_write_complete_fragment_section result=") +
        (fragmentOk ? "1" : "0") +
        " save=" + StatusToken(safeSaveName) +
        " bytes=" + std::to_string(payloadBytes.size()) +
        " chunks=" + std::to_string(chunkCount) +
        " source=" + StatusToken(selectedPayloadSource) +
        " schema=" + Hex64(selectedPayload.schemaHash) +
        " content=" + Hex64(selectedPayload.contentHash) +
        (fragmentReason.empty() ? std::string() : " guard=" + StatusToken(fragmentReason)));
}

bool ModMain::TryLoadHostRemoteNativeFragmentPayloadForWriteComplete(
    std::vector<uint8_t>& outPayloadBytes,
    CoopNativeFragmentPayload::ParsedPayload& outParsed,
    std::string& outSource)
{
    outPayloadBytes.clear();
    outParsed = {};
    outSource = "remote_player_unavailable";

    if (m_networkMode != CoopNetworkMode::Host || !m_hasRemoteEndpoint)
        return false;

    const std::string username = GetRemoteUsernameOrFallback();
    const uint64_t accountToken = GetRemoteAccountToken();
    const std::string saveKey = !m_currentHostSaveStateKey.empty()
        ? m_currentHostSaveStateKey
        : BuildHostSaveStateKey(m_lastSaveLoadPath);

    std::vector<std::pair<std::string, std::string>> candidates;
    const std::string scopedPath = GetHostPlayerStatePathForAccountAndSave(accountToken, saveKey);
    if (!scopedPath.empty())
        candidates.emplace_back(scopedPath, "remote_scoped_" + saveKey);
    const std::string latestPath = GetHostPlayerStatePathForAccount(accountToken);
    if (!latestPath.empty())
        candidates.emplace_back(latestPath, "remote_latest");
    const std::string legacyScopedPath = GetHostPlayerStatePathForUsernameAndSave(username, saveKey);
    if (!legacyScopedPath.empty())
        candidates.emplace_back(legacyScopedPath, "remote_legacy_scoped_" + saveKey);
    const std::string legacyLatestPath = GetHostPlayerStatePathForUsername(username);
    if (!legacyLatestPath.empty())
        candidates.emplace_back(legacyLatestPath, "remote_legacy_latest");

    bool foundCandidate = false;
    std::string lastReason = "missing";
    for (const auto& candidate : candidates)
    {
        PlayerSidecarState state;
        if (!LoadPlayerSidecarFromPath(candidate.first, state))
        {
            lastReason = "load_failed_" + candidate.second;
            continue;
        }

        if (!state.nativeCapture.hasNativeFragmentPayload ||
            state.nativeCapture.nativeFragmentPayload.empty())
        {
            lastReason = "no_native_payload_" + candidate.second;
            continue;
        }

        CoopNativeFragmentPayload::ParsedPayload parsed =
            CoopNativeFragmentPayload::ParseInventoryPayload(state.nativeCapture.nativeFragmentPayload);
        if (!parsed.ok)
        {
            lastReason = "parse_failed_" + candidate.second + "_" + parsed.reason;
            continue;
        }

        foundCandidate = true;
        if (outPayloadBytes.empty() || ShouldPreferNativeFragmentPayload(outPayloadBytes, parsed))
        {
            outPayloadBytes = state.nativeCapture.nativeFragmentPayload;
            outParsed = parsed;
            outSource = candidate.second;
        }
    }

    if (!outPayloadBytes.empty() && outParsed.ok)
    {
        m_lastNativeFragmentPayloadEvent =
            "native write-complete selected remote payload " +
            StatusToken(outSource) + " " +
            CoopNativeFragmentPayload::BuildStatus(outParsed);
        LogCoop(m_lastNativeFragmentPayloadEvent);
        return true;
    }

    outSource = foundCandidate ? "remote_player_payload_not_preferred" : lastReason;
    return false;
}

bool ModMain::TryReadNativeWriteCompleteFragmentPayloadSection(ILoadGame* loadGame, const char* reason)
{
    ++m_nativeLoadFragmentSectionReads;

    const std::string safeReason = reason && reason[0] ? reason : "load notify";
    if (!loadGame)
    {
        ++m_nativeLoadFragmentSectionFailures;
        m_lastNativeLoadFragmentSectionEvent =
            "native_load_fragment_section failed null_load reason=" + StatusToken(safeReason);
        LogCoop(m_lastNativeLoadFragmentSectionEvent);
        return false;
    }

    if (!IsLikelyRuntimeCppObject(loadGame))
    {
        ++m_nativeLoadFragmentSectionFailures;
        m_lastNativeLoadFragmentSectionEvent =
            "native_load_fragment_section failed unreadable_load reason=" + StatusToken(safeReason);
        LogCoop(m_lastNativeLoadFragmentSectionEvent);
        return false;
    }

    std::string guardReason;
    bool haveSection = false;
    if (!TryGuardedCall(
            "native write-complete fragment HaveSection",
            [&]() -> bool
            {
                return loadGame->HaveSection(kNativeWriteCompleteFragmentPayloadSection);
            },
            haveSection,
            &guardReason))
    {
        ++m_nativeLoadFragmentSectionFailures;
        m_lastNativeLoadFragmentSectionEvent =
            "native_load_fragment_section failed have_guard=" +
            StatusToken(guardReason.empty() ? std::string("unknown") : guardReason) +
            " reason=" + StatusToken(safeReason);
        LogCoop(m_lastNativeLoadFragmentSectionEvent);
        return false;
    }

    if (!haveSection)
    {
        m_lastNativeLoadFragmentSectionEvent =
            "native_load_fragment_section missing reason=" + StatusToken(safeReason);
        LogCoop(m_lastNativeLoadFragmentSectionEvent);
        return false;
    }

    std::unique_ptr<TSerialize> section;
    if (!TryGuardedCall(
            "native write-complete fragment GetSection",
            [&]() -> std::unique_ptr<TSerialize>
            {
                std::unique_ptr<TSerialize> result;
                loadGame->GetSection(&result, kNativeWriteCompleteFragmentPayloadSection);
                return result;
            },
            section,
            &guardReason) ||
        !section)
    {
        ++m_nativeLoadFragmentSectionFailures;
        m_lastNativeLoadFragmentSectionEvent =
            "native_load_fragment_section failed get_guard=" +
            StatusToken(guardReason.empty() ? std::string("null_section") : guardReason) +
            " reason=" + StatusToken(safeReason);
        LogCoop(m_lastNativeLoadFragmentSectionEvent);
        return false;
    }

    int version = 0;
    int payloadVersion = 0;
    uint32_t totalBytes = 0;
    uint32_t payloadCrc = 0;
    uint32_t rawCrc = 0;
    uint32_t ranges = 0;
    uint32_t inventoryRanges = 0;
    uint32_t itemGroups = 0;
    uint32_t itemRanges = 0;
    uint32_t rawBytes = 0;
    uint64_t runId = 0;
    uint64_t schemaHash = 0;
    uint64_t contentHash = 0;
    uint32_t chunkBytes = 0;
    uint32_t chunkCount = 0;
    std::vector<uint8_t> payloadBytes;
    bool hexOk = true;
    bool readOk = false;

    if (!TryGuardedCall(
            "native write-complete fragment read",
            [&]() -> bool
            {
                section->Value("version", version);
                section->Value("payloadVersion", payloadVersion);
                section->Value("totalBytes", totalBytes);
                section->Value("payloadCrc", payloadCrc);
                section->Value("rawCrc", rawCrc);
                section->Value("ranges", ranges);
                section->Value("inventoryRanges", inventoryRanges);
                section->Value("itemGroups", itemGroups);
                section->Value("itemRanges", itemRanges);
                section->Value("rawBytes", rawBytes);
                section->Value("runId", runId);
                section->Value("schemaHash", schemaHash);
                section->Value("contentHash", contentHash);
                section->Value("chunkBytes", chunkBytes);
                section->Value("chunkCount", chunkCount);

                static constexpr uint32_t kMaxNativeFragmentPayloadBytes = 16u * 1024u * 1024u;
                if (version != 1 ||
                    chunkBytes == 0 ||
                    chunkBytes > 16u * 1024u ||
                    totalBytes > kMaxNativeFragmentPayloadBytes)
                {
                    return false;
                }

                const uint32_t expectedChunks =
                    (totalBytes + chunkBytes - 1u) / chunkBytes;
                if (chunkCount != expectedChunks ||
                    chunkCount > (kMaxNativeFragmentPayloadBytes / 2u))
                {
                    return false;
                }

                payloadBytes.reserve(totalBytes);
                for (uint32_t i = 0; i < chunkCount; ++i)
                {
                    const std::string key = "chunk" + std::to_string(i);
                    string hex;
                    section->Value(key.c_str(), hex);
                    if (!AppendHexBytesForNativeSection(std::string_view(hex.c_str()), payloadBytes))
                    {
                        hexOk = false;
                        return false;
                    }
                }

                return section->Ok();
            },
            readOk,
            &guardReason) ||
        !readOk ||
        !hexOk)
    {
        ++m_nativeLoadFragmentSectionFailures;
        m_lastNativeLoadFragmentSectionEvent =
            "native_load_fragment_section failed read_guard=" +
            StatusToken(guardReason.empty()
                ? (hexOk ? std::string("serializer_not_ok") : std::string("invalid_hex"))
                : guardReason) +
            " reason=" + StatusToken(safeReason);
        LogCoop(m_lastNativeLoadFragmentSectionEvent);
        return false;
    }

    if (payloadBytes.size() != totalBytes)
    {
        ++m_nativeLoadFragmentSectionFailures;
        m_lastNativeLoadFragmentSectionEvent =
            "native_load_fragment_section failed size_mismatch expected=" +
            std::to_string(totalBytes) +
            " got=" + std::to_string(payloadBytes.size()) +
            " reason=" + StatusToken(safeReason);
        LogCoop(m_lastNativeLoadFragmentSectionEvent);
        return false;
    }

    CoopNativeFragmentPayload::ParsedPayload parsed =
        CoopNativeFragmentPayload::ParseInventoryPayload(payloadBytes);
    const bool metadataMatches =
        parsed.ok &&
        (payloadVersion == 0 || payloadVersion == static_cast<int>(parsed.version)) &&
        (payloadCrc == 0 || payloadCrc == parsed.payloadChecksum) &&
        (rawCrc == 0 || rawCrc == parsed.rawByteChecksum) &&
        (ranges == 0 || ranges == parsed.rangeRecords) &&
        (inventoryRanges == 0 || inventoryRanges == parsed.inventoryRanges) &&
        (itemGroups == 0 || itemGroups == parsed.itemGroups) &&
        (itemRanges == 0 || itemRanges == parsed.itemRanges) &&
        (rawBytes == 0 || rawBytes == parsed.rawBytes) &&
        (runId == 0 || runId == parsed.runId) &&
        (schemaHash == 0 || schemaHash == parsed.schemaHash) &&
        (contentHash == 0 || contentHash == parsed.contentHash);
    if (!metadataMatches)
    {
        ++m_nativeLoadFragmentSectionFailures;
        m_lastNativeLoadFragmentSectionEvent =
            "native_load_fragment_section failed validate=" +
            StatusToken(CoopNativeFragmentPayload::BuildStatus(parsed)) +
            " reason=" + StatusToken(safeReason);
        LogCoop(m_lastNativeLoadFragmentSectionEvent);
        return false;
    }

    const bool adopted = ShouldPreferNativeFragmentPayload(m_lastNativeFragmentImportPayload, parsed);
    if (adopted)
    {
        m_lastNativeFragmentImportPayload = payloadBytes;
        m_lastNativeFragmentPayloadEvent =
            "native load section payload adopted " +
            CoopNativeFragmentPayload::BuildStatus(parsed);
    }
    else
    {
        m_lastNativeFragmentPayloadEvent =
            "native load section payload validated kept_existing " +
            CoopNativeFragmentPayload::BuildStatus(parsed);
    }

    ++m_nativeLoadFragmentSectionSuccesses;
    m_nativeLoadFragmentSectionBytes = parsed.totalBytes;
    m_lastNativeLoadFragmentSectionEvent =
        std::string("native_load_fragment_section ok adopted=") +
        (adopted ? "1" : "0") +
        " " + CoopNativeFragmentPayload::BuildStatus(parsed) +
        " chunks=" + std::to_string(chunkCount) +
        " reason=" + StatusToken(safeReason);
    LogCoop(m_lastNativeLoadFragmentSectionEvent);
    return true;
}

