static std::unique_ptr<TSerialize> ArkSaveLoad_Load_GetSection_Hook(::Load* loadGame, const char* sectionName)
{
    const bool inspectSection = gMod && NativeSaveInstrumentationEnabled();
    uint64_t atlasSeq = 0;
    if (inspectSection)
    {
        const std::string safeSection = ReadRuntimeCString(sectionName, 160);
        atlasSeq = gMod->BeginSaveStateTracePhase(
            CoopSaveStateBridge::TracePhase::LoadGetSectionEnter,
            CoopSaveStateBridge::ClassifySectionName(safeSection),
            "Load::GetSection",
            loadGame,
            nullptr,
            safeSection.c_str());
    }
    std::unique_ptr<TSerialize> serializer = s_hookArkSaveLoadLoadGetSection.InvokeOrig(loadGame, sectionName);
    if (inspectSection)
    {
        if (serializer)
        {
            const auto event = gMod->ObserveSaveStateBridgeSection(
                CoopSaveStateBridge::SectionApi::LegacyLoad,
                "Load::GetSection",
                sectionName,
                serializer.get(),
                true,
                static_cast<int>(eST_SaveGame),
                false);
            gMod->OnSaveStateBridgeSectionEvent(event);
            gMod->EndSaveStateTracePhase(
                atlasSeq,
                CoopSaveStateBridge::TracePhase::LoadGetSectionExit,
                event.gameState ? CoopSaveStateBridge::SchemaSemantic::GameState :
                event.persistentState ? CoopSaveStateBridge::SchemaSemantic::PersistentState :
                CoopSaveStateBridge::SchemaSemantic::Section,
                "Load::GetSection",
                loadGame,
                event.fingerprint.impl,
                event.sectionName.c_str(),
                event.reading,
                event.target,
                event.ok);
        }
        else
        {
            const auto event = gMod->ObserveSaveStateBridgeSection(
                CoopSaveStateBridge::SectionApi::LegacyLoad,
                "Load::GetSection",
                sectionName,
                nullptr,
                true,
                static_cast<int>(eST_SaveGame),
                false);
            gMod->OnSaveStateBridgeSectionEvent(event);
            gMod->EndSaveStateTracePhase(
                atlasSeq,
                CoopSaveStateBridge::TracePhase::LoadGetSectionExit,
                event.gameState ? CoopSaveStateBridge::SchemaSemantic::GameState :
                event.persistentState ? CoopSaveStateBridge::SchemaSemantic::PersistentState :
                CoopSaveStateBridge::SchemaSemantic::Section,
                "Load::GetSection",
                loadGame,
                nullptr,
                event.sectionName.c_str(),
                event.reading,
                event.target,
                event.ok);
        }
    }
    return serializer;
}

static std::unique_ptr<TSerialize>* ActiveLoad_GetSection_Hook(
    ILoadGame* loadGame,
    std::unique_ptr<TSerialize>* outResult,
    const char* const sectionName)
{
    uint64_t atlasSeq = 0;
    if (gMod)
    {
        const std::string safeSection = ReadRuntimeCString(sectionName, 160);
        atlasSeq = gMod->BeginSaveStateTracePhase(
            CoopSaveStateBridge::TracePhase::LoadGetSectionEnter,
            CoopSaveStateBridge::ClassifySectionName(safeSection),
            "ActiveILoadGame::GetSection",
            loadGame,
            outResult,
            safeSection.c_str());
    }
    std::unique_ptr<TSerialize>* const returned = s_hookActiveLoadGetSection.InvokeOrig(loadGame, outResult, sectionName);
    if (gMod)
    {
        std::unique_ptr<TSerialize>* const serializerOwner = returned ? returned : outResult;
        const auto event = gMod->ObserveSaveStateBridgeLoadUniquePtrSection(
            CoopSaveStateBridge::SectionApi::ActiveLoad,
            "ActiveILoadGame::GetSection",
            sectionName,
            serializerOwner);
        if (event.gameState && event.reading && event.target == eST_SaveGame)
        {
            gMod->MergeCoopSaveForLoadedSection(
                event,
                serializerOwner,
                "ActiveILoadGame::GetSection GameState");
        }
        gMod->OnSaveStateBridgeSectionEvent(event);
        gMod->EndSaveStateTracePhase(
            atlasSeq,
            CoopSaveStateBridge::TracePhase::LoadGetSectionExit,
            event.gameState ? CoopSaveStateBridge::SchemaSemantic::GameState :
            event.persistentState ? CoopSaveStateBridge::SchemaSemantic::PersistentState :
            CoopSaveStateBridge::SchemaSemantic::Section,
            "ActiveILoadGame::GetSection",
            loadGame,
            event.fingerprint.impl,
            event.sectionName.c_str(),
            event.reading,
            event.target,
            event.ok);
    }
    return returned;
}

