class NativeInventorySerializeScopeGuard final
{
public:
    NativeInventorySerializeScopeGuard(
        ModMain* owner,
        ArkInventory* inventory,
        const void* serializerPtr,
        bool localPlayerInventory,
        bool reading,
        int target,
        const std::string& sectionName)
        : m_owner(owner)
    {
        if (m_owner)
            m_scopeSeq = m_owner->EnterNativeInventorySerializeScope(inventory, serializerPtr, localPlayerInventory, reading, target, sectionName);
    }

    ~NativeInventorySerializeScopeGuard()
    {
        if (m_owner && m_scopeSeq != 0)
            m_owner->ExitNativeInventorySerializeScope(m_scopeSeq);
    }

    NativeInventorySerializeScopeGuard(const NativeInventorySerializeScopeGuard&) = delete;
    NativeInventorySerializeScopeGuard& operator=(const NativeInventorySerializeScopeGuard&) = delete;

private:
    ModMain* m_owner = nullptr;
    uint64_t m_scopeSeq = 0;
};

class NativeItemSerializeScopeGuard final
{
public:
    NativeItemSerializeScopeGuard(
        ModMain* owner,
        CArkItem* item,
        unsigned itemEntityId,
        const void* serializerPtr,
        bool localPlayerInventoryItem,
        bool reading,
        int target,
        const std::string& sectionName)
        : m_owner(owner)
    {
        if (m_owner)
            m_scopeSeq = m_owner->EnterNativeItemSerializeScope(item, itemEntityId, serializerPtr, localPlayerInventoryItem, reading, target, sectionName);
    }

    ~NativeItemSerializeScopeGuard()
    {
        if (m_owner && m_scopeSeq != 0)
            m_owner->ExitNativeItemSerializeScope(m_scopeSeq);
    }

    NativeItemSerializeScopeGuard(const NativeItemSerializeScopeGuard&) = delete;
    NativeItemSerializeScopeGuard& operator=(const NativeItemSerializeScopeGuard&) = delete;

private:
    ModMain* m_owner = nullptr;
    uint64_t m_scopeSeq = 0;
};

static void ArkInventory_FullSerialize_Hook(ArkInventory* inventory, TSerialize serializer)
{
    const bool reading = serializer.IsReading();
    const int target = static_cast<int>(serializer.GetSerializationTarget());
    ArkPlayer* player = ArkPlayer::GetInstancePtr();
    const bool localPlayerInventory = player && inventory && inventory == player->m_pInventory;
    if (!NativeSaveInstrumentationEnabled())
    {
        s_hookArkInventoryFullSerialize.InvokeOrig(inventory, serializer);
        if (gMod)
            gMod->OnArkInventorySerializeHook(inventory, "FullSerialize", reading, target, serializer.Ok());
        return;
    }

    const std::string serializerSection = gMod ? gMod->FindSaveStateBridgeSectionForSerializer(serializer) : std::string();
    const std::string serializerSectionToken = serializerSection.empty() ? std::string("-") : serializerSection;
    const CoopSaveStateBridge::SchemaSemantic semantic = localPlayerInventory
        ? CoopSaveStateBridge::SchemaSemantic::PlayerInventory
        : CoopSaveStateBridge::SchemaSemantic::Inventory;
    const std::string atlasDetail =
        std::string("reading=") + (reading ? "1" : "0") +
        " target=" + std::to_string(target) +
        " local=" + (localPlayerInventory ? "1" : "0") +
        " section=" + StatusToken(serializerSectionToken);
    uint64_t atlasSeq = 0;
    if (gMod)
    {
        atlasSeq = gMod->BeginSaveStateTracePhase(
            CoopSaveStateBridge::TracePhase::ArkInventorySerializeEnter,
            semantic,
            "ArkInventory::FullSerialize",
            inventory,
            GetImpl(serializer),
            atlasDetail.c_str(),
            reading,
            target,
            serializer.Ok());
    }
    if (gMod)
        gMod->OnArkInventorySnapshotHook(inventory, "FullSerialize:before", reading, target);

    const SerializerFingerprint serializerFingerprint = BuildSerializerFingerprint(serializer);
    const char* traceSource = localPlayerInventory
        ? "ArkInventory::FullSerialize(local-player)"
        : "ArkInventory::FullSerialize";
    const bool traceSerializer =
        gMod &&
        gMod->ShouldTraceLevelStateSerializerSource(traceSource) &&
        localPlayerInventory &&
        serializerFingerprint.impl != nullptr &&
        target == eST_SaveGame;
    const bool probeSerializer =
        gMod &&
        localPlayerInventory &&
        serializerFingerprint.impl != nullptr &&
        target == eST_SaveGame &&
        gMod->ShouldProbeSerializerNodeContext(traceSource);
    const NativeSideBlobCaptureState* overlayCapture =
        gMod &&
        localPlayerInventory &&
        reading &&
        target == eST_SaveGame &&
        serializerFingerprint.impl != nullptr &&
        CoopSaveStateBridge::IsGameStateSection(serializerSection)
        ? gMod->GetPendingNativeGameStatePlayerCapture()
        : nullptr;
    if (gMod &&
        localPlayerInventory &&
        target == eST_SaveGame &&
        serializerFingerprint.impl != nullptr &&
        CoopSaveStateBridge::IsGameStateSection(serializerSection))
    {
        if (!reading)
            gMod->RememberLocalPlayerInventoryItemIds(inventory, "GameState write pre-item-scope");

        gMod->RecordNativeGameStateFragmentCandidate(
            traceSource,
            "inventory-fragment",
            inventory,
            serializerFingerprint.impl,
            reading,
            target,
            serializerSection);
    }
    NativeInventorySerializeScopeGuard nativeInventoryScopeGuard(
        gMod,
        inventory,
        serializerFingerprint.impl,
        localPlayerInventory,
        reading,
        target,
        serializerSection);
    std::string serializerTraceDetail = serializerFingerprint.text;
    serializerTraceDetail += "/section=" + StatusToken(serializerSectionToken);
    if (traceSerializer || overlayCapture || probeSerializer)
    {
        ISerialize* invokeSerializer = serializerFingerprint.impl;
        std::unique_ptr<CoopNativeGameStateOverlay::InventorySerialize> overlaySerialize;
        std::unique_ptr<CoopSerializerTrace::TracingSerialize> tracingSerialize;

        if (traceSerializer || probeSerializer)
        {
            if (traceSerializer)
            {
                gMod->RecordLevelStateSerializerTraceOp(
                    traceSource,
                    "call-begin",
                    localPlayerInventory ? "local-player-inventory" : "inventory",
                    "-",
                    reading,
                    0,
                    serializerTraceDetail.c_str());
            }
            tracingSerialize = std::make_unique<CoopSerializerTrace::TracingSerialize>(
                gMod,
                invokeSerializer,
                traceSource);
            invokeSerializer = tracingSerialize.get();
        }

        if (overlayCapture)
        {
            overlaySerialize = std::make_unique<CoopNativeGameStateOverlay::InventorySerialize>(
                invokeSerializer,
                overlayCapture);
            invokeSerializer = overlaySerialize.get();
        }

        TSerialize wrappedSerializer(invokeSerializer);
        s_hookArkInventoryFullSerialize.InvokeOrig(inventory, wrappedSerializer);

        if (traceSerializer)
        {
            gMod->RecordLevelStateSerializerTraceOp(
                traceSource,
                "call-end",
                localPlayerInventory ? "local-player-inventory" : "inventory",
                "-",
                reading,
                0,
                serializerTraceDetail.c_str());
        }

        if (overlaySerialize)
        {
            const auto& stats = overlaySerialize->Stats();
            LogCoop(
                "native game-state inventory overlay " +
                std::string(stats.compatible ? "compatible" : "blocked") +
                " captured=" + std::to_string(stats.capturedItems) +
                " hostCells=" + std::to_string(stats.hostCells) +
                " patchedValues=" + std::to_string(stats.patchedCells) +
                (stats.requiresEntityGraphPatch ? " needsGameStateEntityGraphPatch=1" : " needsGameStateEntityGraphPatch=0"));
        }
    }
    else
    {
        s_hookArkInventoryFullSerialize.InvokeOrig(inventory, serializer);
    }

    if (gMod &&
        reading &&
        target == eST_SaveGame &&
        serializerFingerprint.impl != nullptr &&
        CoopSaveStateBridge::IsGameStateSection(serializerSection))
    {
        gMod->ObserveNativeGameStateInventoryReferences(
            inventory,
            localPlayerInventory,
            serializerFingerprint.impl,
            traceSource);
    }

    if (gMod)
    {
        gMod->OnArkInventorySerializeHook(inventory, "FullSerialize", reading, target, serializer.Ok());
        gMod->EndSaveStateTracePhase(
            atlasSeq,
            CoopSaveStateBridge::TracePhase::ArkInventorySerializeExit,
            semantic,
            "ArkInventory::FullSerialize",
            inventory,
            GetImpl(serializer),
            (std::string(serializer.Ok() ? "ok=1" : "ok=0") + " section=" + StatusToken(serializerSectionToken)).c_str(),
            reading,
            target,
            serializer.Ok());
    }
}

