static void ArkPlayer_FullSerialize_Hook(ArkPlayer* player, TSerialize serializer)
{
    const bool reading = serializer.IsReading();
    const int target = static_cast<int>(serializer.GetSerializationTarget());
    const bool localPlayer = player && ArkPlayer::GetInstancePtr() == player;
    if (!NativeSaveInstrumentationEnabled())
    {
        s_hookArkPlayerFullSerialize.InvokeOrig(player, serializer);
        if (gMod)
            gMod->OnArkPlayerSerializeHook(player, "ArkPlayer::FullSerialize", reading, target, serializer.Ok());
        return;
    }

    const std::string serializerSection = gMod ? gMod->FindSaveStateBridgeSectionForSerializer(serializer) : std::string();
    const std::string serializerSectionToken = serializerSection.empty() ? std::string("-") : serializerSection;
    const std::string atlasDetail =
        std::string("reading=") + (reading ? "1" : "0") +
        " target=" + std::to_string(target) +
        " local=" + (localPlayer ? "1" : "0") +
        " section=" + StatusToken(serializerSectionToken);
    uint64_t atlasSeq = 0;
    if (gMod)
    {
        atlasSeq = gMod->BeginSaveStateTracePhase(
            CoopSaveStateBridge::TracePhase::ArkPlayerSerializeEnter,
            CoopSaveStateBridge::SchemaSemantic::PlayerCore,
            "ArkPlayer::FullSerialize",
            player,
            GetImpl(serializer),
            atlasDetail.c_str(),
            reading,
            target,
            serializer.Ok());
    }
    const SerializerFingerprint serializerFingerprint = BuildSerializerFingerprint(serializer);
    const bool traceSerializer =
        gMod &&
        gMod->ShouldTraceLevelStateSerializerSource("ArkPlayer::FullSerialize") &&
        localPlayer &&
        serializerFingerprint.impl != nullptr &&
        target == eST_SaveGame;
    const bool probeSerializer =
        gMod &&
        localPlayer &&
        serializerFingerprint.impl != nullptr &&
        target == eST_SaveGame &&
        gMod->ShouldProbeSerializerNodeContext("ArkPlayer::FullSerialize");
    if (gMod &&
        localPlayer &&
        target == eST_SaveGame &&
        serializerFingerprint.impl != nullptr &&
        CoopSaveStateBridge::IsGameStateSection(serializerSection))
    {
        gMod->RecordNativeGameStateFragmentCandidate(
            "ArkPlayer::FullSerialize",
            "player-fragment",
            player,
            serializerFingerprint.impl,
            reading,
            target,
            serializerSection);
    }
    std::string serializerTraceDetail = serializerFingerprint.text;
    serializerTraceDetail += "/section=" + StatusToken(serializerSectionToken);
    if (traceSerializer || probeSerializer)
    {
        if (traceSerializer)
        {
            gMod->RecordLevelStateSerializerTraceOp(
                "ArkPlayer::FullSerialize",
                "call-begin",
                localPlayer ? "local-player" : "player",
                "-",
                reading,
                0,
                serializerTraceDetail.c_str());
        }
        CoopSerializerTrace::TracingSerialize tracingSerialize(
            gMod,
            serializerFingerprint.impl,
            "ArkPlayer::FullSerialize");
        TSerialize tracedSerializer(&tracingSerialize);
        s_hookArkPlayerFullSerialize.InvokeOrig(player, tracedSerializer);
        if (traceSerializer)
        {
            gMod->RecordLevelStateSerializerTraceOp(
                "ArkPlayer::FullSerialize",
                "call-end",
                localPlayer ? "local-player" : "player",
                "-",
                reading,
                0,
                serializerTraceDetail.c_str());
        }
    }
    else
    {
        s_hookArkPlayerFullSerialize.InvokeOrig(player, serializer);
    }

    if (gMod)
    {
        gMod->OnArkPlayerSerializeHook(player, "ArkPlayer::FullSerialize", reading, target, serializer.Ok());
        gMod->EndSaveStateTracePhase(
            atlasSeq,
            CoopSaveStateBridge::TracePhase::ArkPlayerSerializeExit,
            CoopSaveStateBridge::SchemaSemantic::PlayerCore,
            "ArkPlayer::FullSerialize",
            player,
            GetImpl(serializer),
            (std::string(serializer.Ok() ? "ok=1" : "ok=0") + " section=" + StatusToken(serializerSectionToken)).c_str(),
            reading,
            target,
            serializer.Ok());
    }
}

