static void CArkItem_FullSerialize_Hook(CArkItem* item, TSerialize serializer)
{
    const bool reading = serializer.IsReading();
    const int target = static_cast<int>(serializer.GetSerializationTarget());
    const unsigned itemEntityId = item ? item->GetEntityId() : 0;
    const SerializerFingerprint serializerFingerprint = BuildSerializerFingerprint(serializer);
    const std::string serializerSection = gMod ? gMod->FindSaveStateBridgeSectionForSerializer(serializer) : std::string();
    const bool scopeLocalPlayerItem =
        gMod &&
        gMod->IsNativeLocalPlayerInventorySerializeScopeActive(
            serializerFingerprint.impl,
            reading,
            target,
            serializerSection);
    const bool trackedLocalPlayerItem = gMod && gMod->IsTrackedLocalPlayerInventoryItemId(itemEntityId);
    const bool capturedLocalPlayerItem =
        gMod &&
        !reading &&
        target == eST_SaveGame &&
        (gMod->IsActiveNativeSideBlobCaptureItem(itemEntityId) ||
            gMod->IsActiveNativeSideBlobCapturePlayerOwnedItem(item, itemEntityId));
    const bool localPlayerInventoryItem = scopeLocalPlayerItem || trackedLocalPlayerItem || capturedLocalPlayerItem;
    std::string effectiveSerializerSection = serializerSection;
    if (effectiveSerializerSection.empty() && scopeLocalPlayerItem && gMod)
        effectiveSerializerSection = gMod->GetNativeInventorySerializeScopeSection();
    if (effectiveSerializerSection.empty() && capturedLocalPlayerItem)
        effectiveSerializerSection = "GameState";
    const bool targetNativeFragmentItemCandidate =
        gMod &&
        gMod->ShouldCaptureNativeFragmentTarget(
            reading,
            target,
            effectiveSerializerSection);
    const bool nativeFragmentItemCandidate =
        localPlayerInventoryItem ||
        targetNativeFragmentItemCandidate;
    const bool gameStateItemContext =
        serializerFingerprint.impl != nullptr &&
        target == eST_SaveGame &&
        (scopeLocalPlayerItem ||
            capturedLocalPlayerItem ||
            targetNativeFragmentItemCandidate ||
            CoopSaveStateBridge::IsGameStateSection(effectiveSerializerSection));
    const char* traceSource = nativeFragmentItemCandidate
        ? "CArkItem::FullSerialize(player-inventory-item)"
        : "CArkItem::FullSerialize";
    const bool traceSerializer =
        gMod &&
        nativeFragmentItemCandidate &&
        gMod->ShouldTraceLevelStateSerializerSource(traceSource) &&
        serializerFingerprint.impl != nullptr &&
        target == eST_SaveGame;
    const bool probeSerializer =
        gMod &&
        nativeFragmentItemCandidate &&
        serializerFingerprint.impl != nullptr &&
        target == eST_SaveGame &&
        gMod->ShouldProbeSerializerNodeContext(traceSource);
    const NativeCapturedItemState* overlayItem =
        gMod &&
        trackedLocalPlayerItem &&
        reading &&
        target == eST_SaveGame &&
        serializerFingerprint.impl != nullptr
        ? gMod->GetPendingNativeGameStateItemForEntity(itemEntityId)
        : nullptr;
    if (gMod &&
        nativeFragmentItemCandidate &&
        gameStateItemContext)
    {
        gMod->RecordNativeGameStateFragmentCandidate(
            traceSource,
            "item-fragment",
            item,
            serializerFingerprint.impl,
            reading,
            target,
            effectiveSerializerSection);
    }
    NativeItemSerializeScopeGuard nativeItemScopeGuard(
        gMod,
        item,
        itemEntityId,
        serializerFingerprint.impl,
        nativeFragmentItemCandidate && gameStateItemContext,
        reading,
        target,
        effectiveSerializerSection);

    if (traceSerializer || overlayItem || probeSerializer)
    {
        std::string traceDetail = serializerFingerprint.text;
        traceDetail += "/section=" + StatusToken(effectiveSerializerSection.empty() ? std::string("-") : effectiveSerializerSection);
        traceDetail += "/entityId=" + std::to_string(itemEntityId);
        traceDetail += "/scope=" + std::to_string(scopeLocalPlayerItem ? 1 : 0);
        traceDetail += "/capture=" + std::to_string(capturedLocalPlayerItem ? 1 : 0);
        ISerialize* invokeSerializer = serializerFingerprint.impl;
        std::unique_ptr<CoopNativeGameStateOverlay::ItemSerialize> overlaySerialize;
        std::unique_ptr<CoopSerializerTrace::TracingSerialize> tracingSerialize;

        if (traceSerializer || probeSerializer)
        {
            if (traceSerializer)
            {
                gMod->RecordLevelStateSerializerTraceOp(
                    traceSource,
                    "call-begin",
                    "player-inventory-item",
                    "-",
                    reading,
                    0,
                    traceDetail.c_str());
            }
            tracingSerialize = std::make_unique<CoopSerializerTrace::TracingSerialize>(
                gMod,
                invokeSerializer,
                traceSource);
            invokeSerializer = tracingSerialize.get();
        }

        if (overlayItem)
        {
            overlaySerialize = std::make_unique<CoopNativeGameStateOverlay::ItemSerialize>(
                invokeSerializer,
                overlayItem,
                gMod->GetNativeGameStateOverlayOwnerId());
            invokeSerializer = overlaySerialize.get();
        }

        TSerialize wrappedSerializer(invokeSerializer);
        s_hookCArkItemFullSerialize.InvokeOrig(item, wrappedSerializer);

        if (traceSerializer)
        {
            gMod->RecordLevelStateSerializerTraceOp(
                traceSource,
                "call-end",
                "player-inventory-item",
                "-",
                reading,
                0,
                traceDetail.c_str());
        }

        if (overlaySerialize)
        {
            LogCoop(
                "native game-state item overlay entity=" + std::to_string(itemEntityId) +
                " arch=" + std::to_string(overlayItem->archetypeId) +
                " count=" + std::to_string(overlayItem->count) +
                " patchedValues=" + std::to_string(overlaySerialize->Stats().patchedValues));
        }
    }
    else
    {
        s_hookCArkItemFullSerialize.InvokeOrig(item, serializer);
    }

    if (gMod)
        gMod->OnArkItemSerializeHook(item, "FullSerialize", reading, target, serializer.Ok());
}

