static void ArkNpc_OnHit_Hook(ArkNpc* npc, const HitInfo& hitInfo, ArkSignalSystem::Package const* package)
{
    const EntityId entityId = npc ? npc->GetEntityId() : INVALID_ENTITYID;
    const uint64_t damagePackageId = package ? package->m_id : 0;
    std::ostringstream traceDetail;
    traceDetail
        << "shooter=" << hitInfo.shooterId
        << " target=" << hitInfo.targetId
        << " weapon=" << hitInfo.weaponId
        << " projectile=" << hitInfo.projectileId
        << " unique=" << hitInfo.uniqueId
        << " group=" << hitInfo.groupId
        << " damage=" << hitInfo.damage
        << " damageMin=" << hitInfo.damageMin
        << " type=" << hitInfo.type
        << " bulletType=" << hitInfo.bulletType
        << " material=" << hitInfo.material
        << " part=" << hitInfo.partId
        << " remote=" << (hitInfo.remote ? 1 : 0)
        << " proxy=" << (hitInfo.hitViaProxy ? 1 : 0)
        << " explosion=" << (hitInfo.explosion ? 1 : 0)
        << " forceLocalKill=" << (hitInfo.forceLocalKill ? 1 : 0)
        << " critical=" << (hitInfo.critical ? 1 : 0)
        << " package=" << (package ? 1 : 0);
    if (gMod && entityId != INVALID_ENTITYID && gMod->ShouldTraceNativeEntityLifecycle(entityId))
        traceDetail << CaptureNativeHitCallChainTrace();
    const std::string traceDetailText = traceDetail.str();

    if (gMod && entityId != INVALID_ENTITYID)
        gMod->RecordNativeEntityLifecycleTrace("ArkNpc::OnHit entry", entityId, npc, traceDetailText.c_str());
    if (gMod && entityId != INVALID_ENTITYID && gMod->ShouldSuppressArkNpcHit(entityId, hitInfo))
    {
        gMod->RecordNativeEntityLifecycleTrace("ArkNpc::OnHit suppressed", entityId, npc, traceDetailText.c_str());
        gMod->OnArkNpcHitPost(entityId, hitInfo, damagePackageId);
        return;
    }

    HitInfo sanitizedHitInfo = hitInfo;
    if (gMod && entityId != INVALID_ENTITYID)
        gMod->SanitizeArkNpcHitForOriginal(entityId, sanitizedHitInfo);

    s_hookArkNpcOnHit.InvokeOrig(npc, sanitizedHitInfo, package);

    if (gMod && entityId != INVALID_ENTITYID)
    {
        gMod->RecordNativeEntityLifecycleTrace("ArkNpc::OnHit return", entityId, npc, traceDetailText.c_str());
        gMod->OnArkNpcHitPost(entityId, sanitizedHitInfo, damagePackageId);
    }
}

