static int ScriptBindEntity_GotoState_Hook(
    CScriptBind_Entity* scriptBind,
    IFunctionHandler* handler,
    const char* stateName)
{
    IEntity* entity = nullptr;
    IEntityScriptProxy* scriptProxy = nullptr;
    bool switchEntity = false;
    bool beforeOn = false;
    std::string reason;
    if (scriptBind && handler && stateName &&
        TryGuardedCall(
            "ArkSwitch GotoState resolve entity",
            [scriptBind, handler]() { return s_funcScriptBindEntityGetEntity(scriptBind, handler); },
            entity,
            &reason) &&
        entity)
    {
        IEntityClass* entityClass = nullptr;
        const char* className = nullptr;
        switchEntity =
            TryGuardedCall("ArkSwitch GotoState GetClass", [entity]() { return entity->GetClass(); }, entityClass, &reason) &&
            entityClass &&
            TryGuardedCall("ArkSwitch GotoState class GetName", [entityClass]() { return entityClass->GetName(); }, className, &reason) &&
            className && std::strcmp(className, "ArkSwitch") == 0;
        if (switchEntity)
        {
            IEntityProxy* proxy = nullptr;
            if (TryGuardedCall(
                    "ArkSwitch GotoState GetProxy",
                    [entity]() { return entity->GetProxy(ENTITY_PROXY_SCRIPT); },
                    proxy,
                    &reason) &&
                proxy)
            {
                scriptProxy = static_cast<IEntityScriptProxy*>(proxy);
                TryGuardedCall(
                    "ArkSwitch GotoState IsInState before",
                    [scriptProxy]() { return scriptProxy->IsInState("On"); },
                    beforeOn,
                    &reason);
            }
        }
    }

    const int result = s_hookScriptBindEntityGotoState.InvokeOrig(scriptBind, handler, stateName);
    if (gMod && switchEntity && scriptProxy &&
        (std::strcmp(stateName, "On") == 0 || std::strcmp(stateName, "Off") == 0))
    {
        bool afterOn = std::strcmp(stateName, "On") == 0;
        const bool afterOk = TryGuardedCall(
            "ArkSwitch GotoState IsInState after",
            [scriptProxy]() { return scriptProxy->IsInState("On"); },
            afterOn,
            &reason);
        gMod->OnLocalAreaObjectSwitchStateChanged(
            entity,
            afterOn,
            afterOk && beforeOn != afterOn,
            "ArkSwitch::GotoState");
    }
    return result;
}

