static CArkFlowGraphManager* GetStoryFlowGraphManagerForCoop()
{
    return g_pGame ? g_pGame->m_pArkFlowGraphManager.get() : nullptr;
}

static bool ActivateRegisteredMainLiftOutageRemoteEvent(std::string& reason)
{
    CArkFlowGraphManager* manager = GetStoryFlowGraphManagerForCoop();
    IFlowSystem* flowSystem =
        gEnv && gEnv->pSystem ? gEnv->pSystem->GetIFlowSystem() : nullptr;
    if (!manager || !flowSystem)
    {
        reason = manager ? "missing_flow_system" : "missing_flow_graph_manager";
        return false;
    }

    for (const CArkFlowGraphManager::ConsoleEvent& registered : manager->m_remoteEvents)
    {
        IFlowGraph* graph = nullptr;
        const char* nodeType = nullptr;
        const TFlowInputData* eventInput = nullptr;
        string serializedEventId;
        std::string guardReason;
        bool resolved = false;
        const bool matched = TryGuardedCall(
            "main lift outage resolve registered RemoteEvent",
            [flowSystem, &registered, &graph, &nodeType, &eventInput,
                &serializedEventId]()
            {
                graph = flowSystem->GetGraphById(registered.m_graphID);
                if (!graph)
                    return false;
                nodeType = graph->GetNodeTypeName(registered.m_nodeID);
                if (!nodeType || std::strcmp(nodeType, "Ark:RemoteEvent") != 0)
                    return false;
                eventInput = graph->GetInputValue(registered.m_nodeID, 0);
                return eventInput &&
                    eventInput->GetValueWithConversion(serializedEventId);
            },
            resolved,
            &guardReason) && resolved;
        if (!matched)
            continue;

        uint64_t eventId = 0;
        if (!TryParseUint64(serializedEventId.c_str(), eventId) ||
            eventId != kCoopMainLiftOutageRemoteEventId)
        {
            continue;
        }

        // Ark:RemoteEvent has one output named Out. Activating that registered
        // node's output is the engine's exact local presentation boundary: all
        // authored downstream gates, outage visuals and NPC spawning remain
        // vanilla, while the wire only carries the semantic event identity.
        const bool activated = TryGuardedVoidCall(
            "main lift outage activate registered RemoteEvent output",
            [graph, &registered]()
            {
                graph->ActivatePort(
                    SFlowAddress(registered.m_nodeID, 0, true),
                    SFlowSystemVoid());
            },
            &guardReason);
        if (activated)
        {
            reason =
                "graph_" + std::to_string(registered.m_graphID) +
                "_node_" + std::to_string(registered.m_nodeID);
            return true;
        }
        reason = guardReason.empty() ? "remote_event_output_activation_failed" : guardReason;
        return false;
    }

    reason = "registered_main_lift_remote_event_not_found";
    return false;
}

static bool ActivateRegisteredStoryRemoteEventById(
    uint64_t eventId,
    std::string& reason)
{
    CArkFlowGraphManager* manager = GetStoryFlowGraphManagerForCoop();
    IFlowSystem* flowSystem =
        gEnv && gEnv->pSystem ? gEnv->pSystem->GetIFlowSystem() : nullptr;
    if (!manager || !flowSystem)
    {
        reason = manager ? "missing_flow_system" : "missing_flow_graph_manager";
        return false;
    }

    uint32_t activatedCount = 0;
    for (const CArkFlowGraphManager::ConsoleEvent& registered : manager->m_remoteEvents)
    {
        IFlowGraph* graph = nullptr;
        uint64_t registeredEventId = 0;
        std::string guardReason;
        bool resolved = false;
        const bool matched = TryGuardedCall(
            "story resolve registered RemoteEvent",
            [flowSystem, &registered, &graph, &registeredEventId]()
            {
                graph = flowSystem->GetGraphById(registered.m_graphID);
                if (!graph)
                    return false;
                const char* nodeType =
                    graph->GetNodeTypeName(registered.m_nodeID);
                if (!nodeType ||
                    std::strcmp(nodeType, "Ark:RemoteEvent") != 0)
                {
                    return false;
                }

                const TFlowInputData* eventInput =
                    graph->GetInputValue(registered.m_nodeID, 0);
                string serializedEventId;
                return eventInput &&
                    eventInput->GetValueWithConversion(serializedEventId) &&
                    TryParseUint64(
                        serializedEventId.c_str(),
                        registeredEventId);
            },
            resolved,
            &guardReason) &&
            resolved && registeredEventId == eventId;
        if (!matched)
            continue;

        const bool activated = TryGuardedVoidCall(
            "story activate registered RemoteEvent output",
            [graph, &registered]()
            {
                graph->ActivatePort(
                    SFlowAddress(registered.m_nodeID, 0, true),
                    SFlowSystemVoid());
            },
            &guardReason);
        if (!activated)
        {
            reason = guardReason.empty()
                ? "remote_event_output_activation_failed"
                : guardReason;
            return false;
        }
        ++activatedCount;
    }

    reason = activatedCount != 0
        ? "activated_nodes_" + std::to_string(activatedCount)
        : "registered_story_remote_event_not_found";
    return activatedCount != 0;
}

