static ArkConversation*
ArkSpeakerBase_TriggerRule_CoopHook(
    ArkSpeakerBase* speaker,
    uint64_t ruleId,
    bool ignoreVoiceRequirement,
    const char* concept,
    ArkResponseQuery* query,
    int paChannel,
    bool isLiveAudio,
    int priority)
{
    bool remoteContinuation = false;

    if (gMod && speaker)
    {
        gMod->RememberDialogueSpeakerForHook(
            speaker,
            "ArkSpeakerBase::TriggerRule");

        ArkConversation* currentConversation = nullptr;
        uint64_t currentRuntimeId = 0;

        if (TryGuardedCall(
                "dialogue TriggerRule current conversation",
                [speaker]()
                {
                    return speaker->m_pCurrentConversation;
                },
                currentConversation,
                nullptr) &&
            currentConversation)
        {
            TryGuardedCall(
                "dialogue TriggerRule current runtime id",
                [currentConversation]()
                {
                    return currentConversation->m_conversationId;
                },
                currentRuntimeId,
                nullptr);
        }

        remoteContinuation =
            gMod->IsReplayingRemoteDialogue() ||
            gMod->IsRemoteDialogueRuntimeId(
                currentRuntimeId);

        if (currentConversation &&
            gMod->IsRemoteDialogueRuntimeId(
                currentRuntimeId) &&
            gMod->ShouldSuppressRemoteDialogueRetrigger(
                ruleId))
        {
            return currentConversation;
        }
    }

    ArkConversation* conversation =
        s_hookArkSpeakerBaseTriggerRule.InvokeOrig(
            speaker,
            ruleId,
            ignoreVoiceRequirement,
            concept,
            query,
            paChannel,
            isLiveAudio,
            priority);

    uint64_t resultRuntimeId = 0;

    if (conversation)
    {
        TryGuardedCall(
            "dialogue TriggerRule result runtime id",
            [conversation]()
            {
                return conversation->m_conversationId;
            },
            resultRuntimeId,
            nullptr);
    }

    ArkConversation* currentConversationAfter = nullptr;

    if (speaker)
    {
        TryGuardedCall(
            "dialogue TriggerRule current conversation after",
            [speaker]()
            {
                return speaker->m_pCurrentConversation;
            },
            currentConversationAfter,
            nullptr);
    }

    const bool completedInline =
        conversation &&
        resultRuntimeId != 0 &&
        currentConversationAfter == nullptr;

    if (conversation &&
        gMod &&
        !remoteContinuation &&
        !gMod->IsReplayingRemoteDialogue() &&
        !gMod->IsRemoteDialogueRuntimeId(
            resultRuntimeId))
    {
        gMod->ObserveLocalDialogueTrigger(
            speaker,
            conversation,
            ruleId,
            ignoreVoiceRequirement,
            concept,
            query,
            paChannel,
            isLiveAudio,
            priority);

        if (completedInline)
        {
            const uint64_t storyId =
                gMod->ResolveDialogueStoryId(
                    resultRuntimeId);

            gMod->OnLocalDialogueCompleted(
                storyId,
                true,
                "ArkSpeakerBase::TriggerRule inline completion");

            gMod->ForgetDialogueRuntimeId(
                resultRuntimeId);
        }
    }

    return conversation;
}
ArkConversation* ModMain::InvokeOriginalDialogueTrigger(
    ArkSpeakerBase* speaker,
    uint64_t ruleId,
    bool ignoreVoiceRequirement,
    const char* concept,
    ArkResponseQuery* query,
    int paChannel,
    bool isLiveAudio,
    int priority)
{
    return s_hookArkSpeakerBaseTriggerRule.InvokeOrig(
        speaker,
        ruleId,
        ignoreVoiceRequirement,
        concept,
        query,
        paChannel,
        isLiveAudio,
        priority);
}

static bool ArkSpeakerBase_PlayResponse_Hook(
    ArkSpeakerBase* speaker,
    ArkResponseRule& rule,
    ArkConversation* conversation,
    float currentTime,
    bool useRuleVoice,
    int paChannel)
{
    if (gMod && speaker)
    {
        gMod->RememberDialogueSpeakerForHook(
            speaker,
            "ArkSpeakerBase::PlayResponse");
    }

    ArkResponseManager* manager =
        g_pGame
            ? g_pGame->m_pArkResponseManager.get()
            : nullptr;

    uint64_t ruleId = 0;
    bool ruleUsedBefore = false;
    bool ruleIdOk = false;
    std::string reason;

    if (manager)
    {
        ruleIdOk = TryGuardedCall(
            "story response rule id before",
            [&rule]() { return rule.m_id; },
            ruleId,
            &reason) &&
            ruleId != 0;

        if (ruleIdOk)
        {
            TryReadStoryResponseUsage(
                manager,
                CoopProtocol::kStoryEventResponseRuleUsed,
                ruleId,
                ruleUsedBefore,
                nullptr,
                "story response rule used before",
                &reason);
        }
    }

    const bool result =
        s_hookArkSpeakerBasePlayResponse.InvokeOrig(
            speaker,
            rule,
            conversation,
            currentTime,
            useRuleVoice,
            paChannel);

    if (!result || !gMod || !manager || !ruleIdOk)
        return result;

    const ArkResponse* response = nullptr;
    uint64_t responseId = 0;

    TryGuardedCall(
        "story response current response ptr",
        [speaker]()
        {
            return speaker
                ? speaker->m_pCurrentResponse
                : nullptr;
        },
        response,
        &reason);

    if (response)
    {
        TryGuardedCall(
            "story response id",
            [response]()
            {
                return response->m_id;
            },
            responseId,
            &reason);
    }

    // The input argument may be null even though PlayResponse has now
    // created or joined an active runtime conversation.
    ArkConversation* activeConversation = conversation;

    if (!activeConversation && speaker)
    {
        TryGuardedCall(
            "dialogue active conversation after PlayResponse",
            [speaker]()
            {
                return speaker->m_pCurrentConversation;
            },
            activeConversation,
            &reason);
    }

    uint64_t runtimeConversationId = 0;

    if (activeConversation)
    {
        TryGuardedCall(
            "dialogue runtime conversation id",
            [activeConversation]()
            {
                return activeConversation->m_conversationId;
            },
            runtimeConversationId,
            &reason);
    }

    if (runtimeConversationId == 0 && speaker)
    {
        TryGuardedCall(
            "dialogue speaker runtime conversation id",
            [speaker]()
            {
                return speaker->m_conversationId;
            },
            runtimeConversationId,
            &reason);
    }

    if (gMod->IsReplayingRemoteDialogue() ||
        gMod->IsRemoteDialogueRuntimeId(
            runtimeConversationId))
    {
        return result;
    }

    // ruleId is the persistent/story identity used by conversation status.
    const uint64_t storyConversationId = ruleId;

    if (gMod && storyConversationId != 0)
    {
        gMod->m_lastActiveStoryConversationId = storyConversationId;
    }

    if (runtimeConversationId != 0 && storyConversationId != 0)
    {
        gMod->BindDialogueRuntimeId(
            runtimeConversationId,
            storyConversationId);
    }

    gMod->ObserveLocalDialogueActivity(
        storyConversationId,
        responseId,
        "ArkSpeakerBase::PlayResponse");

    if (ruleUsedBefore)
        return result;

    const uint16_t flags =
        BuildStoryResponseUsageFlags(&rule, response);

    if (flags == 0)
        return result;

    gMod->OnLocalStoryResponseUsageChanged(
        manager,
        CoopProtocol::kStoryEventResponseRuleUsed,
        ruleId,
        flags,
        true,
        "ArkSpeakerBase::PlayResponse",
        speaker,
        paChannel);

    if (responseId != 0)
    {
        gMod->OnLocalStoryResponseUsageChanged(
            manager,
            CoopProtocol::kStoryEventResponseUsed,
            responseId,
            flags,
            true,
            "ArkSpeakerBase::PlayResponse");
    }

    return result;
}

static void ArkConversation_OnComplete_Hook(
    ArkConversation* conversation,
    bool complete)
{
    uint64_t runtimeConversationId = 0;

    if (conversation)
    {
        TryGuardedCall(
            "dialogue complete runtime conversation id",
            [conversation]()
            {
                return conversation->m_conversationId;
            },
            runtimeConversationId,
            nullptr);
    }

    const bool remoteReplay =
        gMod &&
        (gMod->IsReplayingRemoteDialogue() ||
            gMod->IsRemoteDialogueRuntimeId(
                runtimeConversationId));

    s_hookArkConversationOnComplete.InvokeOrig(
        conversation,
        complete);

    if (!gMod || runtimeConversationId == 0)
        return;

    if (remoteReplay)
    {
        gMod->ForgetDialogueRuntimeId(
            runtimeConversationId);
        return;
    }

    const uint64_t storyConversationId =
        gMod->ResolveDialogueStoryId(
            runtimeConversationId);

    gMod->OnLocalDialogueCompleted(
        storyConversationId,
        complete,
        "ArkConversation::OnComplete");

    gMod->ForgetDialogueRuntimeId(
        runtimeConversationId);
}

static void ArkGlobalFacts_OnGameTokenEvent_Hook(
    ArkGlobalFacts* facts,
    EGameTokenEvent event,
    IGameToken* token)
{
    s_hookArkGlobalFactsOnGameTokenEvent.InvokeOrig(facts, event, token);

    if (!gMod || !facts || !token || event != EGAMETOKEN_EVENT_CHANGE)
        return;

    int tokenId = 0;
    std::string reason;
    if (!TryGuardedCall(
            "story global token change GetId",
            [token]() { return token->GetId(); },
            tokenId,
            &reason))
    {
        return;
    }

    if (IsWhitelistedStoryGlobalBoolTokenId(tokenId))
    {
        bool value = false;
        if (TryReadStoryGlobalBoolToken(token, value, "story global bool token change", &reason))
        {
            gMod->OnLocalStoryGlobalBoolChanged(
                token,
                value,
                true,
                "ArkGlobalFacts::OnGameTokenEvent");
        }
    }
    else if (IsWhitelistedStoryGlobalIntTokenId(tokenId))
    {
        int32_t value = 0;
        if (TryReadStoryGlobalIntToken(token, value, "story global int token change", &reason))
        {
            gMod->OnLocalStoryGlobalIntChanged(
                token,
                value,
                true,
                "ArkGlobalFacts::OnGameTokenEvent");
        }
    }
    else if (IsWhitelistedStoryGlobalStringTokenId(tokenId))
    {
        std::string value;
        if (TryReadStoryGlobalStringToken(token, value, "story global string token change", &reason))
        {
            gMod->OnLocalStoryGlobalStringChanged(
                token,
                value,
                true,
                "ArkGlobalFacts::OnGameTokenEvent");
        }
    }

    const uint16_t areaEventKind = GetWhitelistedAreaGameTokenKind(tokenId);
    if (areaEventKind != 0)
    {
        uint16_t boolValue = 0;
        int32_t intValue = 0;
        std::string stringValue;
        if (TryReadAreaGameToken(
                token,
                areaEventKind,
                boolValue,
                intValue,
                stringValue,
                "area token change",
                &reason))
        {
            gMod->OnLocalAreaGameTokenChanged(
                token,
                areaEventKind,
                boolValue,
                intValue,
                stringValue,
                "ArkGlobalFacts::OnGameTokenEvent");
        }
    }
}

static void ArkGameStateConditionManager_ExecuteCondition_Hook(
    ArkGameStateConditionManager* manager,
    const ArkGameStateCondition& condition)
{
    uint64_t conditionId = 0;
    std::string reason;
    TryGuardedCall(
        "story condition ExecuteCondition id before",
        [&condition]() { return condition.m_ID; },
        conditionId,
        &reason);

    int before = 0;
    if (conditionId != 0)
    {
        TryReadStoryConditionExecutionCount(
            manager,
            conditionId,
            before,
            "story condition execution count before",
            &reason);
    }

    s_hookArkGameStateConditionManagerExecuteCondition.InvokeOrig(manager, condition);

    if (!gMod || !manager || conditionId == 0)
        return;

    int after = before;
    TryReadStoryConditionExecutionCount(
        manager,
        conditionId,
        after,
        "story condition execution count after",
        &reason);
    gMod->OnLocalStoryConditionStateChanged(
        manager,
        CoopProtocol::kStoryEventConditionExecuted,
        conditionId,
        after,
        after != before,
        "ArkGameStateConditionManager::ExecuteCondition");
}

