static void CArkFlowGraphManager_ExecuteRemoteEvent_Hook(
    const CArkFlowGraphManager* manager,
    const string& eventName)
{
    const StoryRemoteEventWhitelistEntry* entry = nullptr;
    uint64_t eventId = 0;
    std::string reason;
    TryGuardedCall(
        "story remote event whitelist lookup",
        [&eventName]() { return FindStoryRemoteEventByName(eventName.c_str()); },
        entry,
        &reason);

    if (manager && manager->m_remoteEventIdLookupFn)
    {
        TryGuardedCall(
            "story remote event id lookup",
            [manager, &eventName]()
            {
                return manager->m_remoteEventIdLookupFn(eventName.c_str());
            },
            eventId,
            &reason);
    }
    if (!entry && eventId != 0)
        entry = FindStoryRemoteEventById(eventId);

    // Observe before vanilla dispatch. The Lobby graph can synchronously spawn
    // the ambush NPC, so the deterministic identity capture must already be
    // armed when the local FlowGraph starts.
    if (gMod && eventId == kCoopMainLiftOutageRemoteEventId &&
        !gMod->OnLocalMainLiftOutageRemoteEvent(eventId, eventName.c_str()))
    {
        // The ambush is a passenger-local presentation. A peer elsewhere in
        // Lobby still mirrors the native lift trip, but must not receive the
        // outage, blackout or FlowGraph spawn merely because another player
        // entered the shaft.
        return;
    }

    s_hookCArkFlowGraphManagerExecuteRemoteEvent.InvokeOrig(manager, eventName);

    if (gMod && entry)
        gMod->OnLocalStoryRemoteEventTriggered(
            entry->id,
            "CArkFlowGraphManager::ExecuteRemoteEvent");
}

