static int ArkTimeScaleManager_OverrideTimeScale_Hook(ArkTimeScaleManager* manager, unsigned timers, float scale)
{
    const int handle = s_hookArkTimeScaleOverride.InvokeOrig(manager, timers, scale);
    const bool neutralized = gMod && gMod->ShouldNeutralizeNativeTimeScale(scale);
    if (neutralized && manager)
        s_hookArkTimeScaleClear.InvokeOrig(manager, handle);

    if (gMod)
        gMod->RecordTimeScaleOverride(timers, scale, handle, neutralized);
    if (gMod && !neutralized)
        gMod->OnNativeTimeScaleOverride(manager, timers, scale, handle);
    return handle;
}

static void ArkTimeScaleManager_ClearTimeScaleOverride_Hook(ArkTimeScaleManager* manager, const int handle)
{
    if (gMod)
        gMod->OnNativeTimeScaleClear(manager, handle);
    if (gMod)
        gMod->RecordTimeScaleClear(handle);

    s_hookArkTimeScaleClear.InvokeOrig(manager, handle);
}

static void ArkTimeScaleManager_UpdateTimeScaleOverride_Hook(ArkTimeScaleManager* manager, const int handle, const float scale)
{
    TracePostLoadNativeHook("ArkTimeScaleManager::UpdateTimeScaleOverride");
    const bool neutralized = gMod && gMod->ShouldNeutralizeNativeTimeScale(scale);
    if (gMod)
        gMod->RecordTimeScaleUpdate(handle, scale, neutralized);

    if (gMod && gMod->IsPostLoadNativeQuarantineActive() && EnvFlagEnabled("COOP_TRACE_POSTLOAD_NATIVE_HOOKS"))
        LogCoop("post-load native hook before ArkTimeScaleManager::UpdateTimeScaleOverride");
    s_hookArkTimeScaleUpdate.InvokeOrig(manager, handle, neutralized ? 1.0f : scale);
    if (gMod && !neutralized)
        gMod->OnNativeTimeScaleUpdate(manager, handle, scale);
    if (gMod && gMod->IsPostLoadNativeQuarantineActive() && EnvFlagEnabled("COOP_TRACE_POSTLOAD_NATIVE_HOOKS"))
        LogCoop("post-load native hook after ArkTimeScaleManager::UpdateTimeScaleOverride");
}

