static void ArkVisualPerceptionManager_AcquireAllPerceivableInfo_Hook(ArkVisualPerceptionManager* manager)
{
    TracePostLoadNativeHook("ArkVisualPerceptionManager::AcquireAllPerceivableInfo");
    if (gMod)
        gMod->OnArkVisualPerceptionAcquireAllEntered(manager);

    if (EnvFlagEnabled("COOP_TRACE_VISUAL_MANAGER_RAW"))
        LogCoop(BuildVisualManagerRawVectorSnapshot(manager, "AcquireAll enter"));
    if (EnvFlagEnabled("COOP_TRACE_VISUAL_PERCEIVER_DETAILS") &&
        gMod &&
        gMod->ShouldSuppressArkVisualPerceptionAcquireAll(manager))
    {
        LogCoop(BuildVisualPerceiverDetailsSnapshot(manager, "AcquireAll transition enter"));
    }

    if (gMod && gMod->ShouldSuppressArkVisualPerceptionAcquireAll(manager))
    {
        if (EnvFlagEnabled("COOP_REPAIR_BAD_VISUAL_PERCEIVERS_DURING_LOAD_GUARD"))
        {
            std::string invalidDetail;
            if (FindInvalidVisualPerceiverReturn(manager, invalidDetail))
            {
                LogCoop("visual perceiver repair needed before AcquireAll detail=" + invalidDetail);

                std::string repairReason;
                bool repaired = NullInvalidVisualPerceiverSlots(manager, repairReason);
                LogCoop(
                    "visual perceiver repair null bad slots ok=" +
                    std::to_string(repaired ? 1 : 0) +
                    (repairReason.empty() ? std::string() : " detail=" + repairReason));

                if (EnvFlagEnabled("COOP_MANUAL_CLEAR_VISUAL_MANAGER_WORK_VECTORS_DURING_LOAD_GUARD"))
                {
                    repaired = ClearVisualManagerWorkVectorEnds(manager, repairReason);
                    LogCoop(
                        "visual perceiver repair manual vector clear ok=" +
                        std::to_string(repaired ? 1 : 0) +
                        (repairReason.empty() ? std::string() : " detail=" + repairReason));
                }
                else if (!repaired && EnvFlagEnabled("COOP_NATIVE_RESET_VISUAL_MANAGER_DURING_LOAD_GUARD"))
                {
                    repaired = TryGuardedVoidCall(
                        "ArkVisualPerceptionManager::OnLevelLoadStart repair before AcquireAll",
                        [manager]() { ArkVisualPerceptionManagerOnLevelLoadStart(manager); },
                        &repairReason);

                    LogCoop(
                        "visual perceiver repair OnLevelLoadStart ok=" +
                        std::to_string(repaired ? 1 : 0) +
                        (repairReason.empty() ? std::string() : " reason=" + repairReason));
                }

                if (EnvFlagEnabled("COOP_TRACE_VISUAL_MANAGER_RAW"))
                    LogCoop(BuildVisualManagerRawVectorSnapshot(manager, "AcquireAll after visual repair"));
                if (EnvFlagEnabled("COOP_TRACE_VISUAL_PERCEIVER_DETAILS"))
                    LogCoop(BuildVisualPerceiverDetailsSnapshot(manager, "AcquireAll after visual repair"));
            }
        }

        if (!CoopRuntimeConfig::UnsafeFlag("COOP_ALLOW_VISUAL_ACQUIRE_DURING_LOAD_GUARD") ||
            EnvFlagEnabled("COOP_SKIP_VISUAL_ACQUIRE_DURING_LOAD_GUARD"))
        {
            gMod->OnArkVisualPerceptionAcquireAllSkipped(
                manager,
                EnvFlagEnabled("COOP_SKIP_VISUAL_ACQUIRE_DURING_LOAD_GUARD") ?
                    "COOP_SKIP_VISUAL_ACQUIRE_DURING_LOAD_GUARD" :
                    "transition load guard visual acquire deferred");
            return;
        }

        if (EnvFlagEnabled("COOP_UNGUARDED_VISUAL_ACQUIRE_DURING_LOAD_GUARD"))
        {
            if (EnvFlagEnabled("COOP_TRACE_VISUAL_ACQUIRE_GUARD"))
                LogCoop("before unguarded ArkVisualPerceptionManager::AcquireAllPerceivableInfo invoke manager=" + PointerHex(manager));
            s_hookArkVisualPerceptionManagerAcquireAllPerceivableInfo.InvokeOrig(manager);
            if (EnvFlagEnabled("COOP_TRACE_VISUAL_ACQUIRE_GUARD"))
                LogCoop("after unguarded ArkVisualPerceptionManager::AcquireAllPerceivableInfo invoke");
            return;
        }

        std::string guardReason;
        if (EnvFlagEnabled("COOP_TRACE_VISUAL_ACQUIRE_GUARD"))
            LogCoop("before guarded ArkVisualPerceptionManager::AcquireAllPerceivableInfo invoke manager=" + PointerHex(manager));
        const bool ok = TryGuardedVoidCall(
            "ArkVisualPerceptionManager::AcquireAllPerceivableInfo guarded transition",
            [manager]() { s_hookArkVisualPerceptionManagerAcquireAllPerceivableInfo.InvokeOrig(manager); },
            &guardReason);
        if (EnvFlagEnabled("COOP_TRACE_VISUAL_ACQUIRE_GUARD"))
            LogCoop(
                "after guarded ArkVisualPerceptionManager::AcquireAllPerceivableInfo invoke ok=" +
                std::to_string(ok ? 1 : 0) +
                (guardReason.empty() ? std::string() : " reason=" + guardReason));
        gMod->OnArkVisualPerceptionAcquireAllGuarded(manager, ok, guardReason.c_str());
        return;
    }

    s_hookArkVisualPerceptionManagerAcquireAllPerceivableInfo.InvokeOrig(manager);
}

