static std::string ReadFirstUiStringArgument(const SUIArguments& args)
{
    // Prey's SUIArguments starts with a Cry DynArray. Its allocation stores the
    // element count immediately before the first SUIData; the first TUIData
    // string pointer is 16 bytes into that element. Keep this native-menu shim
    // guarded and fail closed if the engine layout is not the expected build.
    const auto* const* listSlot = reinterpret_cast<const uint8_t* const*>(&args);
    if (!IsReadableRuntimePointer(listSlot, sizeof(*listSlot)))
        return {};

    const uint8_t* first = *listSlot;
    if (!first ||
        !IsReadableRuntimePointer(first - sizeof(uint32_t), sizeof(uint32_t)) ||
        !IsReadableRuntimePointer(first, 24))
    {
        return {};
    }

    const uint32_t count = *reinterpret_cast<const uint32_t*>(first - sizeof(uint32_t)) & 0x7fffffffu;
    if (count == 0)
        return {};

    const char* value = *reinterpret_cast<const char* const*>(first + 16);
    if (!value || !IsReadableRuntimePointer(value, 1))
        return {};

    size_t length = 0;
    while (length < 64 && IsReadableRuntimePointer(value + length, 1) && value[length] != '\0')
        ++length;
    if (length == 0 || length == 64)
        return {};
    return std::string(value, length);
}

