static void ArkSaveLoadSystem_SaveCurrentLevelState_Hook(ArkSaveLoadSystem* saveLoadSystem, CGameSerialize& gameSerialize)
{
    uint64_t atlasSeq = 0;
    if (gMod && NativeSaveInstrumentationEnabled())
    {
        atlasSeq = gMod->BeginSaveStateTracePhase(
            CoopSaveStateBridge::TracePhase::ArkSaveCurrentLevelStateEnter,
            CoopSaveStateBridge::SchemaSemantic::LevelState,
            "ArkSaveLoadSystem::SaveCurrentLevelState",
            saveLoadSystem,
            nullptr,
            "reading=0",
            false,
            eST_SaveGame,
            true);
    }
    if (gMod)
        gMod->OnArkSaveLoadSaveCurrentLevelState(saveLoadSystem, true);

    s_hookArkSaveLoadSystemSaveCurrentLevelState.InvokeOrig(saveLoadSystem, gameSerialize);

    if (gMod)
    {
        gMod->OnArkSaveLoadSaveCurrentLevelState(saveLoadSystem, false);
        if (NativeSaveInstrumentationEnabled())
        {
            gMod->EndSaveStateTracePhase(
                atlasSeq,
                CoopSaveStateBridge::TracePhase::ArkSaveCurrentLevelStateExit,
                CoopSaveStateBridge::SchemaSemantic::LevelState,
                "ArkSaveLoadSystem::SaveCurrentLevelState",
                saveLoadSystem,
                nullptr,
                nullptr,
                false,
                eST_SaveGame,
                true);
        }
    }
}

