static void ArkGame_SerializeForLevelState_Hook(const ArkGame* game, TSerialize serializer)
{
    const bool reading = serializer.IsReading();
    const int target = static_cast<int>(serializer.GetSerializationTarget());
    if (!NativeSaveInstrumentationEnabled())
    {
        if (gMod)
            gMod->OnArkGameSerializeForLevelStateHook(
                const_cast<ArkGame*>(game),
                "before",
                reading,
                target,
                serializer.Ok(),
                "",
                0,
                0);

        s_hookArkGameSerializeForLevelState.InvokeOrig(game, serializer);

        if (gMod)
            gMod->OnArkGameSerializeForLevelStateHook(
                const_cast<ArkGame*>(game),
                "after",
                reading,
                target,
                serializer.Ok(),
                "",
                0,
                0);
        return;
    }

    const SerializerFingerprint serializerFingerprint = BuildSerializerFingerprint(serializer);
    if (gMod)
        gMod->OnArkGameSerializeForLevelStateHook(
            const_cast<ArkGame*>(game),
            "before",
            reading,
            target,
            serializer.Ok(),
            serializerFingerprint.text.c_str(),
            reinterpret_cast<std::uintptr_t>(serializerFingerprint.impl),
            reinterpret_cast<std::uintptr_t>(serializerFingerprint.vtable));

    const bool traceSerializer =
        gMod &&
        gMod->ShouldTraceLevelStateSerializerSource("ArkGame::SerializeForLevelState") &&
        serializerFingerprint.impl != nullptr &&
        target == eST_SaveGame;

    if (traceSerializer)
    {
        std::string traceLevelName = "unknown";
        if (gEnv && gEnv->pGame && gEnv->pGame->GetIGameFramework())
        {
            const char* levelName = gEnv->pGame->GetIGameFramework()->GetLevelName();
            if (levelName && levelName[0])
            {
                traceLevelName = levelName;
                std::replace(traceLevelName.begin(), traceLevelName.end(), '\\', '/');
                std::transform(
                    traceLevelName.begin(),
                    traceLevelName.end(),
                    traceLevelName.begin(),
                    [](unsigned char ch) { return static_cast<char>(std::tolower(ch)); });
            }
        }
        gMod->RecordLevelStateSerializerTraceOp(
            "ArkGame::SerializeForLevelState",
            "call-begin",
            traceLevelName.c_str(),
            "-",
            reading,
            0,
            serializerFingerprint.text.c_str());
        CoopSerializerTrace::TracingSerialize tracingSerialize(
            gMod,
            serializerFingerprint.impl,
            "ArkGame::SerializeForLevelState");
        TSerialize tracedSerializer(&tracingSerialize);
        s_hookArkGameSerializeForLevelState.InvokeOrig(game, tracedSerializer);
        gMod->RecordLevelStateSerializerTraceOp(
            "ArkGame::SerializeForLevelState",
            "call-end",
            traceLevelName.c_str(),
            "-",
            reading,
            0,
            serializerFingerprint.text.c_str());
    }
    else
    {
        s_hookArkGameSerializeForLevelState.InvokeOrig(game, serializer);
    }

    if (gMod)
        gMod->OnArkGameSerializeForLevelStateHook(
            const_cast<ArkGame*>(game),
            "after",
            reading,
            target,
            serializer.Ok(),
            serializerFingerprint.text.c_str(),
            reinterpret_cast<std::uintptr_t>(serializerFingerprint.impl),
            reinterpret_cast<std::uintptr_t>(serializerFingerprint.vtable));
}

static void ArkSaveLoadSystem_SerializePersistentState_Hook(ArkSaveLoadSystem* saveLoadSystem, TSerialize serializer)
{
    const bool reading = serializer.IsReading();
    const int target = static_cast<int>(serializer.GetSerializationTarget());
    const SerializerFingerprint serializerFingerprint = BuildSerializerFingerprint(serializer);
    uint64_t atlasSeq = 0;
    if (gMod)
    {
        atlasSeq = gMod->BeginSaveStateTracePhase(
            CoopSaveStateBridge::TracePhase::ArkSerializePersistentStateEnter,
            CoopSaveStateBridge::SchemaSemantic::PersistentState,
            "ArkSaveLoadSystem::SerializePersistentState",
            saveLoadSystem,
            serializerFingerprint.impl,
            serializerFingerprint.text.c_str(),
            reading,
            target,
            serializer.Ok());
    }
    if (gMod)
        gMod->OnArkSaveLoadSerializePersistentStateHook(
            saveLoadSystem,
            "before",
            reading,
            target,
            serializer.Ok(),
            serializerFingerprint.text.c_str(),
            reinterpret_cast<std::uintptr_t>(serializerFingerprint.impl),
            reinterpret_cast<std::uintptr_t>(serializerFingerprint.vtable));

    s_hookArkSaveLoadSystemSerializePersistentState.InvokeOrig(saveLoadSystem, serializer);

    if (gMod)
        gMod->OnArkSaveLoadSerializePersistentStateHook(
            saveLoadSystem,
            "after",
            reading,
            target,
            serializer.Ok(),
            serializerFingerprint.text.c_str(),
            reinterpret_cast<std::uintptr_t>(serializerFingerprint.impl),
            reinterpret_cast<std::uintptr_t>(serializerFingerprint.vtable));

    if (gMod)
    {
        gMod->EndSaveStateTracePhase(
            atlasSeq,
            CoopSaveStateBridge::TracePhase::ArkSerializePersistentStateExit,
            CoopSaveStateBridge::SchemaSemantic::PersistentState,
            "ArkSaveLoadSystem::SerializePersistentState",
            saveLoadSystem,
            serializerFingerprint.impl,
            serializer.Ok() ? "ok=1" : "ok=0",
            reading,
            target,
            serializer.Ok());
    }
}

void ModMain::RegisterSystemEventListener()
{
    if (m_systemEventListenerRegistered || !gEnv || !gEnv->pSystem)
        return;

    ISystemEventDispatcher* dispatcher = gEnv->pSystem->GetISystemEventDispatcher();
    if (!dispatcher)
        return;

    if (!m_systemEventListener)
        m_systemEventListener = std::make_unique<SystemEventListener>(*this);

    m_systemEventListenerRegistered = dispatcher->RegisterListener(m_systemEventListener.get());
}

void ModMain::UnregisterSystemEventListener()
{
    if (!m_systemEventListenerRegistered || !m_systemEventListener || !gEnv || !gEnv->pSystem)
    {
        m_systemEventListenerRegistered = false;
        return;
    }

    if (ISystemEventDispatcher* dispatcher = gEnv->pSystem->GetISystemEventDispatcher())
        dispatcher->RemoveListener(m_systemEventListener.get());

    m_systemEventListenerRegistered = false;
}

void ModMain::RegisterCoopEntitySystemSink()
{
    if (m_entitySystemSinkRegistered || !gEnv || !gEnv->pEntitySystem)
        return;

    if (!m_entitySystemSink)
        m_entitySystemSink = std::make_unique<CoopEntitySystemSink>(*this);

    const uint64_t areaStateEvents =
        (uint64_t{1} << ENTITY_EVENT_XFORM) |
        (uint64_t{1} << ENTITY_EVENT_COLLISION) |
        (uint64_t{1} << ENTITY_EVENT_DONE) |
        (uint64_t{1} << ENTITY_EVENT_HIDE) |
        (uint64_t{1} << ENTITY_EVENT_UNHIDE) |
        (uint64_t{1} << ENTITY_EVENT_ENABLE_PHYSICS) |
        (uint64_t{1} << ENTITY_EVENT_PHYSICS_CHANGE_STATE);

    gEnv->pEntitySystem->AddSink(
        m_entitySystemSink.get(),
        IEntitySystem::OnBeforeSpawn | IEntitySystem::OnSpawn | IEntitySystem::OnRemove | IEntitySystem::OnReused | IEntitySystem::OnEvent,
        areaStateEvents);
    m_entitySystemSinkRegistered = true;
    m_lastRuntimeSaveGuardEvent = "entity sink registered";
}

void ModMain::UnregisterCoopEntitySystemSink()
{
    if (!m_entitySystemSinkRegistered || !m_entitySystemSink || !gEnv || !gEnv->pEntitySystem)
    {
        m_entitySystemSinkRegistered = false;
        return;
    }

    gEnv->pEntitySystem->RemoveSink(m_entitySystemSink.get());
    m_entitySystemSinkRegistered = false;
    m_lastRuntimeSaveGuardEvent = "entity sink unregistered";
}

bool ModMain::ShouldRejectCoopRuntimeEntitySpawn(const SEntitySpawnParams& params)
{
    if (!m_saveLoadGuardActive && !m_waitingForPostLoadContinue && !m_pendingPostLoadResync)
        return false;

    const char* rawName = params.sName ? params.sName : "";
    const std::string spawnName = SanitizeUsername(rawName);
    bool reject = IsCoopRuntimeEntityName(rawName);

    const IEntityArchetype* archetype = params.pArchetype;
    uint64_t archetypeId = 0;
    std::string guardReason;
    if (archetype && TryGuardedCall("SEntitySpawnParams::pArchetype::GetId", [archetype]() { return archetype->GetId(); }, archetypeId, &guardReason))
    {
        if (archetypeId == kProxyArchetype)
        {
            // A saved Bellamy proxy can come back with a level/save-specific
            // entity name rather than "Player2". During native load we reject
            // the proxy archetype broadly; runtime proxy bodies are recreated
            // after the session gate is ready.
            reject = true;
        }
    }

    if (!reject)
        return false;

    // IEntitySystem treats an OnBeforeSpawn rejection while restoring a save
    // as a fatal load error. Let the saved body materialize, then quarantine
    // it in OnSpawn; the normal post-load stale-runtime pass retires it before
    // a fresh remote-player proxy is created.
    m_lastRuntimeSaveGuardEvent =
        "allowed saved coop runtime spawn for post-spawn quarantine: " +
        (spawnName.empty() ? std::string(rawName) : spawnName) +
        " archetype=" + std::to_string(archetypeId);
    LogCoop(m_lastRuntimeSaveGuardEvent);
    return false;
}

void ModMain::OnCoopRuntimeEntitySpawned(IEntity& entity, SEntitySpawnParams& params, const char* stage)
{
    EntityId coverageEntityId = INVALID_ENTITYID;
    IEntityClass* coverageClass = nullptr;
    const char* coverageClassName = nullptr;
    std::string coverageReason;
    TryGuardedCall("coverage spawn GetId", [&entity]() { return entity.GetId(); }, coverageEntityId, &coverageReason);
    if (TryGuardedCall("coverage spawn GetClass", [&entity]() { return entity.GetClass(); }, coverageClass, &coverageReason) &&
        coverageClass)
    {
        TryGuardedCall("coverage spawn class GetName", [coverageClass]() { return coverageClass->GetName(); }, coverageClassName, &coverageReason);
    }
    m_coverageDiscovery.RecordEntitySpawn(
        static_cast<uint32_t>(coverageEntityId),
        ReadRuntimeCString(coverageClassName, 96));

    const bool enemyReplicationCandidate =
        m_networkMode != CoopNetworkMode::Off && IsEnemyReplicationCandidate(entity);
    if (enemyReplicationCandidate &&
        m_mainLiftOutageEnemyCaptureSeconds > 0.0f &&
        m_mainLiftOutageEnemyEntityId == INVALID_ENTITYID &&
        m_mainLiftOutageEnemyStableId != 0 &&
        NormalizeLevelName(GetCurrentLevelName()) == "campaign/research/lobby")
    {
        const IEntityArchetype* outageArchetype = entity.GetArchetype();
        const char* outageArchetypeName = nullptr;
        const bool outagePhantom =
            outageArchetype &&
            TryGuardedCall(
                "main lift outage enemy archetype name",
                [outageArchetype]() { return outageArchetype->GetName(); },
                outageArchetypeName,
                nullptr) &&
            outageArchetypeName &&
            std::strstr(outageArchetypeName, ".Phantoms.BasePhantom") != nullptr;
        const Vec3 position = entity.GetWorldPos();
        Vec3 finalPosition = position;
        bool relocatedIntoCabin = false;
        const Vec3 liftCenter(318.45361f, 715.73431f, 584.0f);
        const Vec3 delta = position - liftCenter;
        if (outagePhantom &&
            delta.x * delta.x + delta.y * delta.y <= 80.0f * 80.0f &&
            position.z >= 430.0f && position.z <= 760.0f)
        {
            const EntityId liftId = gEnv && gEnv->pEntitySystem
                ? gEnv->pEntitySystem->FindEntityByGuid(
                    static_cast<EntityGUID>(kCoopLobbyMainLiftGuid))
                : INVALID_ENTITYID;
            IEntity* liftEntity =
                liftId != INVALID_ENTITYID && gEnv && gEnv->pEntitySystem
                ? gEnv->pEntitySystem->GetEntity(liftId)
                : nullptr;
            Vec3 currentLiftPosition(ZERO);
            const bool liftPositionOk = liftEntity && TryGuardedCall(
                "main lift outage enemy lift position",
                [liftEntity]() { return liftEntity->GetWorldPos(); },
                currentLiftPosition,
                nullptr);
            const bool belowCurrentCabin =
                liftPositionOk &&
                std::fabs(position.x - currentLiftPosition.x) <= 5.0f &&
                std::fabs(position.y - currentLiftPosition.y) <= 5.0f &&
                position.z < currentLiftPosition.z - 3.0f &&
                position.z >= currentLiftPosition.z - 30.0f;
            if (belowCurrentCabin)
            {
                const Vec3 cabinPosition(
                    position.x,
                    position.y,
                    currentLiftPosition.z + 0.01f);
                relocatedIntoCabin = TryGuardedVoidCall(
                    "main lift outage enemy move into cabin",
                    [&entity, cabinPosition]()
                    {
                        entity.SetPos(cabinPosition, 0, true, true);
                    },
                    nullptr);
                if (relocatedIntoCabin)
                {
                    finalPosition = entity.GetWorldPos();
                    ++m_mainLiftOutageEnemyRelocations;
                }
            }

            // Every peer runs the authored outage FlowGraph locally, so each
            // one also receives a local dynamic NPC body. Bind those bodies to
            // the one semantic outage identity before the enemy registry sees
            // them; the ordinary Enemy Authority policy owns the NPC after it
            // has converged.
            m_enemyStableSpawnIdsByEntity[entity.GetId()] =
                m_mainLiftOutageEnemyStableId;
            m_mainLiftOutageEnemyEntityId = entity.GetId();
            m_mainLiftOutageEnemyCaptureSeconds = 0.0f;
            m_lastMainLiftOutageEvent =
                "bound local outage enemy entity=" +
                std::to_string(entity.GetId()) +
                " stable=" + std::to_string(m_mainLiftOutageEnemyStableId) +
                " position=" + FormatVec3Trace(finalPosition) +
                " authoredPosition=" + FormatVec3Trace(position) +
                " cabinRelocated=" +
                std::to_string(relocatedIntoCabin ? 1 : 0);
            LogCoop(m_lastMainLiftOutageEvent);
        }
    }

    if (enemyReplicationCandidate)
    {
        m_pendingEnemyRegistryEntityIds.insert(entity.GetId());
    }

    if (m_nativeNpcSpawnTraceEnabled || EnvFlagEnabled("COOP_TRACE_NATIVE_NPC_SPAWN"))
    {
        std::ostringstream detail;
        detail << "paramsName=" << StatusToken(ReadRuntimeCString(params.sName, 80));
        const IEntityArchetype* paramArchetype = params.pArchetype;
        if (paramArchetype)
        {
            std::string reason;
            uint64_t paramArchetypeId = 0;
            const char* paramArchetypeName = nullptr;
            if (TryGuardedCall("native npc spawn params archetype GetId", [paramArchetype]() { return paramArchetype->GetId(); }, paramArchetypeId, &reason))
                detail << " paramArchetype=" << paramArchetypeId;
            if (TryGuardedCall("native npc spawn params archetype GetName", [paramArchetype]() { return paramArchetype->GetName(); }, paramArchetypeName, &reason))
                detail << " paramArchetypeName=" << StatusToken(ReadRuntimeCString(paramArchetypeName, 96));
            if (!reason.empty())
                detail << " guard=" << StatusToken(reason);
        }
        RecordNativeNpcSpawnTrace(stage ? stage : "IEntitySystemSink::OnSpawn", &entity, detail.str().c_str());
    }

    if (!m_saveLoadGuardActive && !m_waitingForPostLoadContinue && !m_pendingPostLoadResync)
        return;

    bool shouldQuarantine = false;
    std::string guardReason;
    const char* entityName = nullptr;
    if (TryGuardedCall("IEntity::GetName load quarantine", [&entity]() { return entity.GetName(); }, entityName, &guardReason))
        shouldQuarantine = IsCoopRuntimeEntityName(entityName);

    if (!shouldQuarantine)
    {
        IEntityArchetype* archetype = nullptr;
        uint64_t archetypeId = 0;
        if (TryGuardedCall("IEntity::GetArchetype load quarantine", [&entity]() { return entity.GetArchetype(); }, archetype, &guardReason) &&
            archetype &&
            TryGuardedCall("IEntityArchetype::GetId load quarantine", [archetype]() { return archetype->GetId(); }, archetypeId, &guardReason) &&
            archetypeId == kProxyArchetype)
        {
            shouldQuarantine = true;
        }
    }

    if (!shouldQuarantine)
        return;

    MarkCoopRuntimeEntity(entity, false);
    entity.Hide(true);
    entity.Invisible(true);
    m_quarantinedSavedCoopRuntimeEntityIds.insert(entity.GetId());
    ++m_quarantinedSavedCoopRuntimeSpawns;
    m_lastRuntimeSaveGuardEvent =
        "quarantined saved coop runtime entity id=" +
        std::to_string(entity.GetId());
    LogCoop(m_lastRuntimeSaveGuardEvent);
}

void ModMain::OnCoopRuntimeEntityRemoved(IEntity& entity)
{
    EntityId removedEntityId = INVALID_ENTITYID;
    std::string removeTraceReason;
    if (TryGuardedCall("native lifecycle sink OnRemove GetId", [&entity]() { return entity.GetId(); }, removedEntityId, &removeTraceReason))
    {
        m_quarantinedSavedCoopRuntimeEntityIds.erase(removedEntityId);
        m_coverageDiscovery.RecordEntityRemoved(static_cast<uint32_t>(removedEntityId));
        m_pendingEnemyRegistryEntityIds.erase(removedEntityId);
        OnSharedDropEntityRemoved(removedEntityId);
        m_enemyRaisedFromCorpseSourcesByEntity.erase(removedEntityId);
        // CryEntitySystem recycles EntityIds immediately. Etheric lifecycle
        // metadata belongs to the removed child, not to the next entity that
        // happens to receive the same numeric id. Retaining it caused that
        // replacement to be announced as a second Doppelganger for the same
        // cast generation after the real ten-second child disappeared.
        m_enemyEthericDoppelgangerSourcesByEntity.erase(removedEntityId);
        m_enemyEthericDoppelgangerGenerationsByEntity.erase(removedEntityId);
        m_enemyEthericDoppelgangerRequestsSentByEntity.erase(removedEntityId);
        m_pendingEthericDoppelgangerInitFrames.erase(removedEntityId);
        RecordNativeEntityLifecycleTrace("IEntitySystemSink::OnRemove", removedEntityId, nullptr, nullptr);
        m_sentLocalHazardEntityIds.erase(removedEntityId);
        m_remoteHazardEntityIds.erase(removedEntityId);
        m_proxyReviveInteractionEntityIds.erase(removedEntityId);
        m_proxyReviveInteractionRegistered = !m_proxyReviveInteractionEntityIds.empty();
        m_proxyReviveInteractionEntityId = m_proxyReviveInteractionRegistered
            ? *m_proxyReviveInteractionEntityIds.begin()
            : INVALID_ENTITYID;
        for (auto& entry : m_remotePeers)
        {
            if (entry.second.proxyEntityId == removedEntityId)
            {
                entry.second.proxyEntityId = INVALID_ENTITYID;
                ClearRemotePeerPoseSmoothing(entry.second);
                entry.second.poseAnimationClip.clear();
            }
        }
        if (m_proxyEntityId == removedEntityId)
            m_proxyEntityId = INVALID_ENTITYID;

        // Entity ids are recycled by CryEntitySystem. Retaining an enemy
        // binding after OnRemove can therefore hand remote locomotion to an
        // unrelated NPC which later receives the same id.
        const auto netIt = m_enemyNetIdsByEntity.find(removedEntityId);
        if (netIt != m_enemyNetIdsByEntity.end())
        {
            const uint64_t enemyNetId = netIt->second;
            m_enemyNetIdsByEntity.erase(netIt);
            m_enemyStableSpawnIdsByEntity.erase(removedEntityId);
            ClearRemoteEnemyMovementDesire(enemyNetId, "enemy entity removed");

            if (const auto authorityIt = m_enemyAuthorities.find(enemyNetId);
                authorityIt != m_enemyAuthorities.end() && authorityIt->second.entityId == removedEntityId)
            {
                authorityIt->second.entityId = INVALID_ENTITYID;
                authorityIt->second.hasLastPosition = false;
                authorityIt->second.remoteLocomotionAuthority = false;
                authorityIt->second.remoteAuthorityHasAttention = false;
                authorityIt->second.authorityAttentionLevel = CoopEnemyAuthorityPolicy::kUnknownAttention;
                authorityIt->second.attentionCandidates.clear();
                authorityIt->second.remoteTargetAccountToken = 0;
                authorityIt->second.remoteTransformNeedsAuthoritySnap = true;
            }

            if (const auto puppetIt = m_enemyPuppets.find(enemyNetId);
                puppetIt != m_enemyPuppets.end() && puppetIt->second.entityId == removedEntityId)
            {
                m_enemyPuppets.erase(puppetIt);
            }

            m_lastEnemyLocomotionEvent =
                "cleared removed enemy binding net=" + std::to_string(enemyNetId) +
                " entity=" + std::to_string(removedEntityId);
            AppendEnemySyncTrace("roster", m_lastEnemyLocomotionEvent);
        }
    }

    if (!IsGameReady() ||
        m_saveLoadGuardActive ||
        m_waitingForPostLoadContinue ||
        m_pendingPostLoadResync ||
        m_arkLevelTransitionLoadActive ||
        m_runtimeTransitionCleanupPrepared ||
        m_areaOverlayApplyActive ||
        m_applyingRemoteCorpsePhantomResult)
    {
        return;
    }

    const std::string levelName = NormalizeLevelName(GetCurrentLevelName());
    if (levelName.empty() || levelName == "unknown")
        return;

    m_areaStateJournal.NoteEntityRemoved(levelName, entity);
}

void ModMain::OnCoopRuntimeEntityEvent(IEntity& entity, SEntityEvent& event)
{
    EntityId coverageEntityId = INVALID_ENTITYID;
    std::string coverageReason;
    if (TryGuardedCall("coverage event GetId", [&entity]() { return entity.GetId(); }, coverageEntityId, &coverageReason))
        m_coverageDiscovery.RecordEntityEvent(static_cast<uint32_t>(coverageEntityId), event.event);

    if (!IsGameReady() ||
        m_saveLoadGuardActive ||
        m_waitingForPostLoadContinue ||
        m_pendingPostLoadResync ||
        m_arkLevelTransitionLoadActive ||
        m_runtimeTransitionCleanupPrepared ||
        m_areaOverlayApplyActive)
    {
        return;
    }

    const std::string levelName = NormalizeLevelName(GetCurrentLevelName());
    if (levelName.empty() || levelName == "unknown")
        return;

    m_areaStateJournal.NoteEntityEvent(levelName, entity, event);
    if (event.event == ENTITY_EVENT_COLLISION)
        HandleLivePropCollisionEvent(entity, event);

    if (event.event == ENTITY_EVENT_XFORM ||
        event.event == ENTITY_EVENT_HIDE ||
        event.event == ENTITY_EVENT_UNHIDE)
    {
        const bool traceEvents = m_livePropTraceEvents || m_livePropOpenEventFilter || EnvFlagEnabled("COOP_LIVE_PROP_TRACE_EVENTS");
        const bool openEventFilter = m_livePropOpenEventFilter || EnvFlagEnabled("COOP_LIVE_PROP_OPEN_EVENT_FILTER");
        if (traceEvents)
        {
            ++m_livePropEventTraceTotal;
            ++m_livePropEventTraceWindowTotal;
            if (event.event == ENTITY_EVENT_XFORM)
            {
                ++m_livePropEventTraceXform;
                ++m_livePropEventTraceWindowXform;
            }
            else if (event.event == ENTITY_EVENT_HIDE)
            {
                ++m_livePropEventTraceHide;
                ++m_livePropEventTraceWindowHide;
            }
            else if (event.event == ENTITY_EVENT_UNHIDE)
            {
                ++m_livePropEventTraceUnhide;
                ++m_livePropEventTraceWindowUnhide;
            }
        }

        bool shouldQueueLiveProp = false;
        bool eventWasCarried = false;
        bool eventWasKnown = false;
        bool eventWasOpened = false;
        bool eventWasContactDiscovered = false;
        bool eventWasAuthoredMover = false;
        uint64_t eventGuid = 0;
        EntityId entityId = INVALID_ENTITYID;
        std::string livePropReason;
        if (TryGuardedCall("live prop event IEntity::GetId", [&entity]() { return entity.GetId(); }, entityId, &livePropReason) &&
            entityId != INVALID_ENTITYID &&
            ArkPlayer::GetInstancePtr())
        {
            unsigned carriedEntityId = INVALID_ENTITYID;
            if (TryGuardedCall(
                    "live prop event local carried entity id",
                    []() -> unsigned
                    {
                        return ArkPlayer::GetInstance().m_interaction.m_playerCarry.m_pickedUpEntityId;
                    },
                    carriedEntityId,
                    &livePropReason) &&
                carriedEntityId == entityId)
            {
                shouldQueueLiveProp = true;
                eventWasCarried = true;
            }
        }

        if (!shouldQueueLiveProp)
        {
            if (TryGuardedCall("live prop event IEntity::GetGuid", [&entity]() { return entity.GetGuid(); }, eventGuid, &livePropReason) &&
                eventGuid != 0 &&
                m_liveProps.find(eventGuid) != m_liveProps.end())
            {
                shouldQueueLiveProp = true;
                eventWasKnown = true;
            }
        }

        if (event.event == ENTITY_EVENT_XFORM && eventGuid == 0)
        {
            TryGuardedCall(
                "authored mover event IEntity::GetGuid",
                [&entity]() { return entity.GetGuid(); },
                eventGuid,
                &livePropReason);
        }
        if (event.event == ENTITY_EVENT_XFORM &&
            (m_networkMode == CoopNetworkMode::Host || IsClientAreaAuthorityActive()) &&
            (eventGuid == 5389049150946449579ULL ||
                eventGuid == 5114921584089089230ULL ||
                eventGuid == 5617616201710343076ULL))
        {
            // Hardware Labs' grenade-machine movers and Lobby's main lift are
            // script-controlled authored movers. Area Authority mirrors their
            // transforms through the existing bounded LiveProp lane; observer
            // peers must not execute the mission FlowGraph themselves.
            shouldQueueLiveProp = true;
            eventWasAuthoredMover = true;
        }

        if (!shouldQueueLiveProp && openEventFilter)
        {
            shouldQueueLiveProp = true;
            eventWasOpened = true;
        }

        if (!shouldQueueLiveProp && event.event == ENTITY_EVENT_XFORM)
        {
            eventWasContactDiscovered = QueueLivePropXformContactAuthority(entity, "xform carried contact");
            if (!eventWasContactDiscovered)
                eventWasContactDiscovered = QueueLivePropXformLocalPlayerAuthority(entity, "xform local player contact");
        }

        if (traceEvents)
        {
            if (eventWasCarried)
            {
                ++m_livePropEventTraceCarried;
                ++m_livePropEventTraceWindowCarried;
            }
            if (eventWasKnown)
            {
                ++m_livePropEventTraceKnown;
                ++m_livePropEventTraceWindowKnown;
            }
            if (eventWasOpened)
            {
                ++m_livePropEventTraceOpened;
                ++m_livePropEventTraceWindowOpened;
            }
            if (shouldQueueLiveProp || eventWasContactDiscovered)
            {
                ++m_livePropEventTraceQueueAttempts;
                ++m_livePropEventTraceWindowQueueAttempts;
            }
            else
            {
                ++m_livePropEventTraceRejected;
                ++m_livePropEventTraceWindowRejected;
            }
        }

        if (shouldQueueLiveProp)
        {
            uint64_t debugGuid = 0;
            TryGuardedCall("live prop debug event guid", [&entity]() { return entity.GetGuid(); }, debugGuid, &livePropReason);
            const auto debugIt = debugGuid != 0 ? m_liveProps.find(debugGuid) : m_liveProps.end();
            const LivePropState* debugState = debugIt != m_liveProps.end() ? &debugIt->second : nullptr;
            const char* eventName =
                event.event == ENTITY_EVENT_XFORM ? "xform" :
                event.event == ENTITY_EVENT_HIDE ? "hide" :
                event.event == ENTITY_EVENT_UNHIDE ? "unhide" :
                "other";
            const std::string detail =
                std::string("event=") + eventName +
                " carried=" + std::to_string(eventWasCarried ? 1 : 0) +
                " known=" + std::to_string(eventWasKnown ? 1 : 0) +
                " opened=" + std::to_string(eventWasOpened ? 1 : 0) +
                " authoredMover=" + std::to_string(eventWasAuthoredMover ? 1 : 0);
            AppendLivePropDebugTrace("event.queue", debugGuid, entityId, debugState, detail.c_str());
            QueueLivePropTransform(entity, false, "tracked entity event");
            if (eventWasAuthoredMover && eventGuid != 0)
            {
                auto moverIt = m_liveProps.find(eventGuid);
                if (moverIt != m_liveProps.end())
                {
                    // Script movers do not expose physical velocity. Keep only
                    // a short send-rate boost refreshed by each authored XFORM;
                    // do not misclassify them as ballistic physics.
                    moverIt->second.forceSendUntilTime =
                        std::max(moverIt->second.forceSendUntilTime, GetNowSeconds() + 0.20f);
                    moverIt->second.dirty = true;
                    if (eventGuid == 5617616201710343076ULL)
                    {
                        // The lift's native physics velocity belongs only to
                        // Area Authority. Observers consume exact parent poses;
                        // forwarding that velocity would make them continue
                        // past the authored floor after the authority stops.
                        moverIt->second.velocity = Vec3(ZERO);
                        moverIt->second.angularVelocity = Vec3(ZERO);
                        moverIt->second.releaseVelocity = Vec3(ZERO);
                        moverIt->second.releaseAngularVelocity = Vec3(ZERO);
                        moverIt->second.flags &=
                            ~CoopProtocol::kLivePropTransformFlagImpulse;
                        moverIt->second.flags |=
                            CoopProtocol::kLivePropTransformFlagActive;
                        moverIt->second.activelyMoving = true;
                        moverIt->second.activeUntilTime =
                            GetNowSeconds() + 0.20f;
                    }
                }
            }
        }

        if (traceEvents)
        {
            const float now = gEnv && gEnv->pTimer ? gEnv->pTimer->GetAsyncCurTime() : 0.0f;
            if (m_livePropEventTraceLastLogTime <= 0.0f)
                m_livePropEventTraceLastLogTime = now;
            if (now - m_livePropEventTraceLastLogTime >= 1.0f)
            {
                m_livePropEventTraceLastLogTime = now;

                std::string sample;
                const char* rawName = nullptr;
                const char* rawClassName = nullptr;
                uint64_t guid = 0;
                Vec3 pos(ZERO);
                TryGuardedCall("live prop trace IEntity::GetGuid", [&entity]() { return entity.GetGuid(); }, guid, &livePropReason);
                TryGuardedCall("live prop trace IEntity::GetWorldPos", [&entity]() { return entity.GetWorldPos(); }, pos, &livePropReason);
                TryGuardedCall("live prop trace IEntity::GetName", [&entity]() { return entity.GetName(); }, rawName, &livePropReason);
                IEntityClass* entityClass = nullptr;
                if (TryGuardedCall("live prop trace IEntity::GetClass", [&entity]() { return entity.GetClass(); }, entityClass, &livePropReason) &&
                    IsLikelyRuntimeCppObject(entityClass))
                {
                    TryGuardedCall("live prop trace IEntityClass::GetName", [entityClass]() { return entityClass->GetName(); }, rawClassName, &livePropReason);
                }

                sample =
                    " sample_id=" + std::to_string(entityId) +
                    " sample_guid=" + std::to_string(guid) +
                    " sample_class=" + StatusToken(ReadRuntimeCString(rawClassName, 80)) +
                    " sample_name=" + StatusToken(ReadRuntimeCString(rawName, 80)) +
                    " sample_pos=" + std::to_string(pos.x) + "," + std::to_string(pos.y) + "," + std::to_string(pos.z);

                m_lastLivePropEventTrace =
                    "live_prop_event_trace"
                    " open=" + std::to_string(openEventFilter ? 1 : 0) +
                    " window_total=" + std::to_string(m_livePropEventTraceWindowTotal) +
                    " xform=" + std::to_string(m_livePropEventTraceWindowXform) +
                    " hide=" + std::to_string(m_livePropEventTraceWindowHide) +
                    " unhide=" + std::to_string(m_livePropEventTraceWindowUnhide) +
                    " carried=" + std::to_string(m_livePropEventTraceWindowCarried) +
                    " known=" + std::to_string(m_livePropEventTraceWindowKnown) +
                    " opened=" + std::to_string(m_livePropEventTraceWindowOpened) +
                    " queueAttempts=" + std::to_string(m_livePropEventTraceWindowQueueAttempts) +
                    " rejected=" + std::to_string(m_livePropEventTraceWindowRejected) +
                    sample;
                LogCoop(m_lastLivePropEventTrace);

                m_livePropEventTraceWindowTotal = 0;
                m_livePropEventTraceWindowXform = 0;
                m_livePropEventTraceWindowHide = 0;
                m_livePropEventTraceWindowUnhide = 0;
                m_livePropEventTraceWindowCarried = 0;
                m_livePropEventTraceWindowKnown = 0;
                m_livePropEventTraceWindowOpened = 0;
                m_livePropEventTraceWindowQueueAttempts = 0;
                m_livePropEventTraceWindowRejected = 0;
            }
        }
    }
}

void ModMain::PurgeCoopRuntimeEntitiesForSave(const char* reason)
{
    ++m_saveRuntimePurgeCount;
    m_lastRuntimeSaveGuardEvent = std::string("save hook guarded, runtime entities kept no-save: ") + (reason ? reason : "unknown");
    LogCoop(m_lastRuntimeSaveGuardEvent);
}

const char* ModMain::GetSystemEventName(int event) const
{
    switch (static_cast<ESystemEvent>(event))
    {
    case ESYSTEM_EVENT_LEVEL_LOAD_RESUME_GAME:
        return "LEVEL_LOAD_RESUME_GAME";
    case ESYSTEM_EVENT_LEVEL_LOAD_PREPARE:
        return "LEVEL_LOAD_PREPARE";
    case ESYSTEM_EVENT_LEVEL_LOAD_START_LOADINGSCREEN:
        return "LEVEL_LOAD_START_LOADINGSCREEN";
    case ESYSTEM_EVENT_LEVEL_LOAD_START:
        return "LEVEL_LOAD_START";
    case ESYSTEM_EVENT_LEVEL_LOAD_END:
        return "LEVEL_LOAD_END";
    case ESYSTEM_EVENT_LEVEL_LOAD_ERROR:
        return "LEVEL_LOAD_ERROR";
    case ESYSTEM_EVENT_LEVEL_GAMEPLAY_START:
        return "LEVEL_GAMEPLAY_START";
    case ESYSTEM_EVENT_LEVEL_UNLOAD:
        return "LEVEL_UNLOAD";
    case ESYSTEM_EVENT_LEVEL_POST_UNLOAD:
        return "LEVEL_POST_UNLOAD";
    case ESYSTEM_EVENT_TRANSITION_GAME_STATE_LOADED:
        return "TRANSITION_GAME_STATE_LOADED";
    case ESYSTEM_EVENT_ENTITY_UNLOAD:
        return "ENTITY_UNLOAD";
    case ESYSTEM_EVENT_LOAD_SAVE_STARTED:
        return "LOAD_SAVE_STARTED";
    case ESYSTEM_EVENT_QUICKLOAD_SAVE_FINISHED:
        return "QUICKLOAD_SAVE_FINISHED";
    default:
        return "system event";
    }
}

void ModMain::ResetRuntimeWorldRefsForLoad(const char* reason)
{
    ++m_loadGuardRuntimeResetCount;

    // Do not call ArkPlayer/attention release APIs while a native load is
    // reconstructing the player and level entities. The old runtime state is
    // invalid at this point; clear our bookkeeping and let the new player start
    // from the level/save state.
    ResetWorldPresentationForLoad(reason, false);
    // Native conversation ids and speaker pointers are scoped to the loaded
    // world. Keeping replay classifications across a reload can make a newly
    // allocated local conversation look like an old remote replay and block
    // its continuation lines.
    ResetDialogueLeaseState(reason);
    m_localDownedAttentionObjectDisabled = false;
    m_localDownedInputDisabled = false;
    m_localDownedWeaponDisabled = false;
    m_localDownedEquipmentWritesDisabled = false;
    m_localDownedSavedPsiPowers = false;

    m_proxyEntityId = INVALID_ENTITYID;
    for (auto& entry : m_remotePeers)
    {
        entry.second.proxyEntityId = INVALID_ENTITYID;
        ClearRemotePeerPoseSmoothing(entry.second);
        entry.second.poseAnimationClip.clear();
    }
    ResetProxyLifecycleRuntimeState(reason);
    m_mimicEntityId = INVALID_ENTITYID;
    m_animationTestProxyEntityId = INVALID_ENTITYID;
    ClearAllRemoteEnemyMovementDesires("reset runtime world refs");
    m_enemyNetIdsByEntity.clear();
    m_enemyStableSpawnIdsByEntity.clear();
    m_enemyRaisedFromCorpseSourcesByEntity.clear();
    m_enemyEthericDoppelgangerSourcesByEntity.clear();
    m_enemyEthericDoppelgangerGenerationsByEntity.clear();
    m_enemyEthericDoppelgangerRequestsSentByEntity.clear();
    m_pendingEthericDoppelgangerInitFrames.clear();
    m_pendingRemoteCorpsePhantomResults.clear();
    m_pendingCorpsePhantomSpawnRequests.clear();
    m_pendingEnemyRegistryEntityIds.clear();
    if (!m_remoteEnemyPhysicsSnapshots.empty())
    {
        m_remoteEnemyPhysicsDrops += static_cast<uint32_t>(m_remoteEnemyPhysicsSnapshots.size());
        m_lastRemoteEnemyPhysicsEvent =
            "load_detach_dropped=" + std::to_string(m_remoteEnemyPhysicsSnapshots.size()) +
            " reason=" + StatusToken(reason && reason[0] ? std::string(reason) : std::string("-"));
    }
    m_remoteEnemyPhysicsSnapshots.clear();
    m_remoteEnemyPhysicsTouchedEntities.clear();
    m_enemyAuthorities.clear();
    m_enemyRosterByNetId.clear();
    m_enemyPuppets.clear();
    m_pendingEnemyDeathCommits.clear();
    m_enemyDeathPresentations.clear();
    m_pendingEnemyDamageSignals.clear();
    m_enemyDeathPresentationLastSequences.clear();
    m_enemyLocomotionLastSequences.clear();
    m_lastEnemyLocomotionEvent = std::string("reset for load: ") + (reason ? reason : "-");
    ResetLivePropSyncState(reason);
    ResetLocalPlayerFallRecovery(reason);
    m_nextEnemyNetId = 100;
    m_proxyTickAccumulator = 0.0f;
    m_mimicStateTickAccumulator = 0.0f;
    m_enemyRegistryScanAccumulator = 0.0f;
    m_clientEnemyCullAccumulator = 0.0f;
    m_enemyRegistryNeedsScan = true;
    m_clientEnemyCullNeedsScan = true;
    m_proxyCombatStimulusAccumulator = 0.0f;
    m_remoteDownedRecoveryAccumulator = 0.0f;
    m_localDownedAttentionClearAccumulator = 0.0f;
    m_localDownedFocusCleanupAccumulator = 0.0f;
    m_localDownedAttentionScanCursor = 0;
    m_mimicDeathCommitRepeatsRemaining = 0;
    m_proxyWasConfigured = false;
    m_mimicIsPuppet = false;
    m_hadAuthoritativeMimic = false;
    m_sentMimicDeadState = false;
    m_mimicHealthAvailable = false;
    m_proxyHealthAvailable = false;
    m_hasProxyHealthBaseline = false;
    m_hasLastMimicAuthorityPos = false;
    m_hasLastLocalPlayerPos = false;
    m_localPlayerDowned = false;
    m_remotePlayerDowned = false;
    m_teamWipe = false;
    m_nativeDeathFeedbackActive = false;
    m_pendingForceLocalDown = false;
    m_pendingReviveLocal = false;
    m_pendingReviveLocalHealth = 0.0f;
    m_pendingReviveLocalMaxHealth = 0.0f;
    m_pendingReviveRemote = false;
    m_pendingUnstuckToRemote = false;
    m_remoteRevivePromptActive = false;
    m_remoteReviveHoldSeconds = 0.0f;
    m_remoteReviveHoldProgress = 0.0f;
    m_remoteReviveDistance = 0.0f;
    m_localDownedInputDisabled = false;
    m_localDownedWeaponDisabled = false;
    m_localDownedAttentionObjectDisabled = false;
    m_localDownedSavedPsiPowers = false;
    m_proxyDownedSideEffectsDisabled = false;
    m_remoteProxySlotVisualsDisabled = false;
    m_proxyReviveInteractionEntityId = INVALID_ENTITYID;
    m_proxyReviveInteractionRegistered = false;
    m_proxyReviveInteractionEntityIds.clear();
    m_proxyComplexAttentionEntityId = INVALID_ENTITYID;
    m_proxyComplexAttentionRegistered = false;
    m_proxyComplexVisualRegistered = false;
    m_proxyComplexAuralRegistered = false;
    m_proxyComplexRoomRegistered = false;
    m_lastProxyHealth = 0.0f;
    m_lastProxyMaxHealth = 0.0f;
    m_lastMimicHealth = 0.0f;
    m_lastMimicMaxHealth = 0.0f;
    m_lastMimicDamage = 0.0f;
    m_lastAppliedDamage = 0.0f;
    m_damageDedupeEntries.clear();
    m_damageDedupeHealthSignals = 0;
    m_pendingLocalDamageSignal = {};
    m_applyingRemotePlayerDamage = false;
    m_lastDamageDedupeEvent = "reset for load";
    m_lastPlayerSignalDamageEvent = "reset for load";
    m_lastArkUIHUD = nullptr;
    m_lastArkUIHUDPointer = 0;
    m_uiDebugTargetId = -1;
    m_uiDebugStatus = "reset for load";
    m_postFxDebugStatus = "reset for load";
    m_runtimeExtractor.ResetRuntimeRefs(reason);
    m_lastRuntimeCleanupLevelName.clear();
    m_lastRuntimeCleanupRemoteUsername.clear();
    m_lastRuntimeCleanupRemoteAccountToken = 0;
    m_sessionGameplayReady = false;
    m_sessionTickAccumulator = kSessionTickSeconds;
    m_networkTickAccumulator = 0.0f;
    m_lastSaveLoadEvent = std::string("runtime refs reset: ") + (reason ? reason : "unknown");
    m_clientAreaAuthorityActive = false;
    m_lastRequestedServerAreaStateLevel.clear();
    m_pendingRemoteAreaHandoffRequestLevel.clear();
    m_clientLocalAreaEnteredByTransitionLevel.clear();
    m_areaOverlayApplyActive = false;
    m_lastAreaAuthorityEvent = "reset for load";
}

void ModMain::DetachRuntimeEntitiesForIncomingWorldReset(const char* reason)
{
    std::vector<EntityId> trackedIds;
    AddRemoteProxyEntityIds(trackedIds);
    auto addTracked = [&trackedIds](EntityId entityId)
    {
        if (entityId != INVALID_ENTITYID &&
            std::find(trackedIds.begin(), trackedIds.end(), entityId) == trackedIds.end())
        {
            trackedIds.push_back(entityId);
        }
    };
    addTracked(m_mimicEntityId);
    AddRuntimeEnemyEntityIds(trackedIds);
    const uint32_t trackedBefore = static_cast<uint32_t>(trackedIds.size());

    m_lastRuntimePerceptionEvent = BuildRuntimePerceptionSnapshot(reason ? reason : "incoming world reset");
    LogCoop(m_lastRuntimePerceptionEvent);

    m_lastRuntimeTransitionCleanupEvent =
        "incoming world reset detach reason=" + std::string(reason ? reason : "unknown") +
        " trackedBefore=" + std::to_string(trackedBefore) +
        " nativeRemove=0" +
        " note=refs_detached_level_load_owns_entities";
    LogCoop(m_lastRuntimeTransitionCleanupEvent);

    ResetRuntimeWorldRefsForLoad(reason ? reason : "incoming world reset");
    m_sessionGameplayReady = false;
    m_networkStatus = "waiting for host world reset";
}

void ModMain::SetTransitionPhase(const char* phase, const char* reason)
{
    const std::string phaseName = phase && phase[0] ? phase : "unknown";
    const std::string reasonName = reason && reason[0] ? reason : "-";
    std::string event =
        "transition phase #" + std::to_string(++m_transitionPhaseSerial) +
        " " + phaseName +
        " reason=" + reasonName +
        " loadGuard=" + std::to_string(m_saveLoadGuardActive ? 1 : 0) +
        " waitContinue=" + std::to_string(m_waitingForPostLoadContinue ? 1 : 0) +
        " pendingResync=" + std::to_string(m_pendingPostLoadResync ? 1 : 0) +
        " arkTransition=" + std::to_string(m_arkLevelTransitionLoadActive ? 1 : 0) +
        " sessionReady=" + std::to_string(m_sessionGameplayReady ? 1 : 0) +
        " localLevel=" + NormalizeLevelName(GetCurrentLevelName());

    if (event == m_lastTransitionPhaseEvent)
        return;

    m_lastTransitionPhaseEvent = std::move(event);
    if (EnvFlagEnabled("COOP_TRACE_TRANSITION_PHASES"))
        LogCoop(m_lastTransitionPhaseEvent);
}

void ModMain::RefreshCoopRuntimeEntitySaveFlags(const char* reason)
{
    if (!gEnv || !gEnv->pEntitySystem)
        return;

    uint32_t touched = 0;
    auto refreshOne = [this, &touched](EntityId id, bool puppet)
    {
        if (id == INVALID_ENTITYID || !gEnv || !gEnv->pEntitySystem)
            return;
        IEntity* entity = gEnv->pEntitySystem->GetEntity(id);
        if (!entity)
            return;
        MarkCoopRuntimeEntity(*entity, puppet);
        ++touched;
    };

    std::vector<EntityId> proxyIds;
    AddRemoteProxyEntityIds(proxyIds);
    for (EntityId proxyId : proxyIds)
        refreshOne(proxyId, false);
    refreshOne(m_mimicEntityId, m_mimicIsPuppet);
    std::vector<EntityId> runtimeEnemyIds;
    AddRuntimeEnemyEntityIds(runtimeEnemyIds);
    for (EntityId enemyId : runtimeEnemyIds)
        refreshOne(enemyId, true);

    m_lastRuntimeEntityFlagsEvent =
        "refreshed coop runtime save flags reason=" + std::string(reason ? reason : "unknown") +
        " touched=" + std::to_string(touched);
    LogCoop(m_lastRuntimeEntityFlagsEvent);
}

std::string ModMain::BuildRuntimeEntityFlagSnapshot(const char* reason) const
{
    struct RuntimeEntityRef
    {
        EntityId id = INVALID_ENTITYID;
        bool puppet = false;
        const char* label = "-";
    };

    std::vector<RuntimeEntityRef> refs;
    auto addRef = [&refs](EntityId id, bool puppet, const char* label)
    {
        if (id == INVALID_ENTITYID)
            return;
        for (const RuntimeEntityRef& ref : refs)
        {
            if (ref.id == id)
                return;
        }
        refs.push_back(RuntimeEntityRef{id, puppet, label});
    };

    std::vector<EntityId> proxyIds;
    AddRemoteProxyEntityIds(proxyIds);
    for (EntityId proxyId : proxyIds)
        addRef(proxyId, false, "proxy");
    addRef(m_mimicEntityId, m_mimicIsPuppet, m_mimicIsPuppet ? "mimic_puppet" : "mimic_authority");
    std::vector<EntityId> runtimeEnemyIds;
    AddRuntimeEnemyEntityIds(runtimeEnemyIds);
    for (EntityId enemyId : runtimeEnemyIds)
        addRef(enemyId, true, "enemy_puppet");

    uint32_t existing = 0;
    uint32_t missingNoSave = 0;
    uint32_t localPlayer = 0;
    uint32_t unremovable = 0;
    uint32_t clientState = 0;
    uint32_t garbage = 0;
    uint32_t guardSkips = 0;
    std::string details;
    std::string guardReason;

    for (const RuntimeEntityRef& ref : refs)
    {
        IEntity* entity = nullptr;
        if (gEnv && gEnv->pEntitySystem)
            entity = gEnv->pEntitySystem->GetEntity(ref.id);

        if (!entity)
        {
            if (details.size() < 512)
            {
                if (!details.empty())
                    details += ",";
                details += std::string(ref.label) + ":" + std::to_string(ref.id) + ":missing";
            }
            continue;
        }

        ++existing;
        uint32_t flags = 0;
        bool isGarbage = false;
        const char* rawName = nullptr;
        uint64_t archetypeId = 0;
        IEntityArchetype* archetype = nullptr;

        if (!TryGuardedCall("runtime flag snapshot GetFlags", [entity]() { return entity->GetFlags(); }, flags, &guardReason))
        {
            ++guardSkips;
            continue;
        }

        TryGuardedCall("runtime flag snapshot IsGarbage", [entity]() { return entity->IsGarbage(); }, isGarbage, &guardReason);
        TryGuardedCall("runtime flag snapshot GetName", [entity]() { return entity->GetName(); }, rawName, &guardReason);
        if (TryGuardedCall("runtime flag snapshot GetArchetype", [entity]() { return entity->GetArchetype(); }, archetype, &guardReason) &&
            archetype)
        {
            TryGuardedCall("runtime flag snapshot archetype id", [archetype]() { return archetype->GetId(); }, archetypeId, &guardReason);
        }

        const bool hasNoSave = (flags & static_cast<uint32_t>(ENTITY_FLAG_NO_SAVE)) != 0;
        const bool hasLocalPlayer = (flags & static_cast<uint32_t>(ENTITY_FLAG_LOCAL_PLAYER)) != 0;
        const bool hasUnremovable = (flags & static_cast<uint32_t>(ENTITY_FLAG_UNREMOVABLE)) != 0;
        const bool hasClientState = (flags & static_cast<uint32_t>(ENTITY_FLAG_CLIENTSIDE_STATE)) != 0;

        missingNoSave += hasNoSave ? 0u : 1u;
        localPlayer += hasLocalPlayer ? 1u : 0u;
        unremovable += hasUnremovable ? 1u : 0u;
        clientState += hasClientState ? 1u : 0u;
        garbage += isGarbage ? 1u : 0u;

        if (details.size() < 512)
        {
            if (!details.empty())
                details += ",";
            details += std::string(ref.label) +
                ":" + std::to_string(ref.id) +
                ":f=" + Hex32(flags) +
                ":ns=" + std::to_string(hasNoSave ? 1 : 0) +
                ":lp=" + std::to_string(hasLocalPlayer ? 1 : 0) +
                ":ur=" + std::to_string(hasUnremovable ? 1 : 0) +
                ":cs=" + std::to_string(hasClientState ? 1 : 0) +
                ":g=" + std::to_string(isGarbage ? 1 : 0) +
                ":arch=" + std::to_string(archetypeId) +
                ":name=" + StatusToken(ReadRuntimeCString(rawName, 48));
        }
    }

    std::ostringstream out;
    out
        << "runtime entity flags reason=" << (reason ? reason : "unknown")
        << " tracked=" << refs.size()
        << " existing=" << existing
        << " missingNoSave=" << missingNoSave
        << " localPlayer=" << localPlayer
        << " unremovable=" << unremovable
        << " clientState=" << clientState
        << " garbage=" << garbage
        << " guardSkips=" << guardSkips
        << " details=" << (details.empty() ? "-" : details);
    if (!guardReason.empty())
        out << " lastGuard=" << guardReason;
    return out.str();
}

void ModMain::BeginCoopLoadGuard(const char* reason)
{
    ++m_loadGuardBeginCount;
    const bool wasActive = m_saveLoadGuardActive;
    if (!wasActive)
    {
        SendHostLoadStartingNotice(reason);
        ResetWorldPresentationForLoad(reason, true);
    }
    SetTransitionPhase("load_guard_begin_enter", reason);
    m_saveLoadGuardActive = true;
    m_waitingForPostLoadContinue = false;
    m_pendingPostLoadResync = true;
    m_postLoadInteractiveSeconds = 0.0f;
    m_postLoadWaitReason = "native loading";
    m_lastSaveLoadEvent = std::string("load guard begin: ") + (reason ? reason : "unknown");
    if (m_networkMode != CoopNetworkMode::Off && m_arkLevelTransitionLoadActive)
    {
        m_lastRuntimePerceptionEvent = BuildRuntimePerceptionSnapshot("load guard begin before coop pause");
        LogCoop(m_lastRuntimePerceptionEvent);
        PrepareCoopRuntimeEntitiesForLevelTransition(reason);
        if (ShouldRunNativePerceptionLoadStartDuringTransition(reason))
        {
            PrepareNativePerceptionManagersForLevelTransition(reason);
        }
        else
        {
            m_lastNativePerceptionEvent =
                "pre-native perception OnLevelLoadStart deferred reason=" +
                std::string(reason ? reason : "unknown");
            LogCoop(m_lastNativePerceptionEvent);
        }
        m_lastRuntimePerceptionEvent = BuildRuntimePerceptionSnapshot("load guard begin after coop pause");
        LogCoop(m_lastRuntimePerceptionEvent);
    }
    if (!wasActive)
        ResetRuntimeWorldRefsForLoad(reason);
    m_networkStatus = "load guard active";
    LogCoop(m_lastSaveLoadEvent);
    SetTransitionPhase("load_guard_begin_active", reason);
}

void ModMain::MarkCoopLoadNativeComplete(const char* reason)
{
    ++m_postLoadNativeCompleteCount;
    SetTransitionPhase("native_load_complete_enter", reason);
    m_saveLoadGuardActive = true;
    m_waitingForPostLoadContinue = true;
    m_pendingPostLoadResync = true;
    m_postLoadInteractiveSeconds = 0.0f;
    m_postLoadWaitReason = "waiting for continue";
    m_autoReengageAfterLoadingAccumulator = kAutoReengageAfterLoadingSeconds;
    m_autoReengageAfterLoadingAttempts = 0;
    m_lastSaveLoadEvent = std::string("native load complete, waiting for player: ") + (reason ? reason : "unknown");
    m_networkStatus = "waiting for press-any-key continue";
    LogCoop(m_lastSaveLoadEvent);
    SetTransitionPhase("native_load_complete_wait_continue", reason);
    ClearJoinOverlayState("native load complete");
    if (m_autoSkipAfterLoadingScreenRequested)
    {
        QueueAutoReengageAfterLoadingScreen("native load complete", true);
    }
}

bool ModMain::IsPostLoadGameplayInteractive(std::string& reason) const
{
    if (!gEnv)
    {
        reason = "no env";
        return false;
    }

    if (!gEnv->pEntitySystem)
    {
        reason = "no entity system";
        return false;
    }

    if (gEnv->pSystem && gEnv->pSystem->IsPaused())
    {
        reason = "system paused";
        return false;
    }

    if (gEnv->pTimer && gEnv->pTimer->IsTimerPaused(ITimer::ETIMER_GAME))
    {
        reason = "game timer paused";
        return false;
    }

    if (!ArkPlayer::GetInstancePtr())
    {
        reason = "no ArkPlayer";
        return false;
    }

    const ArkPlayer& player = ArkPlayer::GetInstance();
    if (!player.GetEntity())
    {
        reason = "no player entity";
        return false;
    }

    if (!player.m_input.m_modeStack.empty())
    {
        const ArkPlayerInput::Mode mode = player.m_input.m_modeStack.back().m_mode;
        if (mode != ArkPlayerInput::Mode::player)
        {
            reason = "input mode " + std::to_string(static_cast<int>(mode));
            return false;
        }
    }

    reason = "interactive";
    return true;
}

void ModMain::TickCoopLoadGuard(float frameTime, bool allowNativeStateMutation)
{
    if (!m_saveLoadGuardActive || !m_waitingForPostLoadContinue)
        return;

    if (allowNativeStateMutation)
        TryDrainAutoReengageAfterLoadingScreen("load guard tick");

    if (m_autoSkipAfterLoadingScreenRequested && m_autoReengageAfterLoadingAttempts < kAutoReengageAfterLoadingMaxAttempts)
    {
        m_autoReengageAfterLoadingAccumulator += std::max(0.0f, frameTime);
        if (m_autoReengageAfterLoadingAccumulator >= kAutoReengageAfterLoadingSeconds)
        {
            m_autoReengageAfterLoadingAccumulator = 0.0f;
            QueueAutoReengageAfterLoadingScreen(
                allowNativeStateMutation ? "load guard tick" : "flash loadtime tick",
                true);
            if (allowNativeStateMutation)
                TryDrainAutoReengageAfterLoadingScreen("load guard tick");
        }
    }

    if (!allowNativeStateMutation)
        return;

    std::string reason;
    if (!IsPostLoadGameplayInteractive(reason))
    {
        const bool forceAfterAutoskip =
            m_autoSkipAfterLoadingScreenRequested &&
            m_autoReengageAfterLoadingAttempts >= kAutoReengageAfterLoadingMaxAttempts &&
            !EnvFlagEnabled("COOP_STRICT_POSTLOAD_INTERACTIVE") &&
            (reason == "system paused" || reason == "game timer paused");
        if (forceAfterAutoskip)
        {
            ++m_postLoadInteractiveReadyCount;
            m_postLoadWaitReason = reason;
            SetTransitionPhase("post_load_interactive_forced", reason.c_str());
            EndCoopLoadGuard("post-load gameplay interactive forced after autoskip retries");
            LogCoop("load guard tick returned after forced EndCoopLoadGuard");
            return;
        }

        ++m_postLoadInteractiveWaitCount;
        m_postLoadInteractiveSeconds = 0.0f;
        m_postLoadWaitReason = reason;
        if ((m_postLoadInteractiveWaitCount % 60) == 0)
        {
            SetTransitionPhase("post_load_wait_interactive", reason.c_str());
            LogCoop("post-load interactive wait: " + reason);
        }
        return;
    }

    m_postLoadWaitReason = reason;
    m_postLoadInteractiveSeconds += std::max(0.0f, frameTime);
    const float postLoadInteractiveHoldSeconds = ResolveEnvSeconds(
        "COOP_POSTLOAD_INTERACTIVE_HOLD_SECONDS",
        kPostLoadInteractiveHoldSeconds,
        0.0f,
        30.0f);
    if (m_postLoadInteractiveSeconds < postLoadInteractiveHoldSeconds)
        return;

    ++m_postLoadInteractiveReadyCount;
    SetTransitionPhase("post_load_interactive_ready", reason.c_str());
    EndCoopLoadGuard("post-load gameplay interactive");
    LogCoop("load guard tick returned after EndCoopLoadGuard");
}

void ModMain::EndCoopLoadGuard(const char* reason)
{
    if (!m_saveLoadGuardActive && !m_pendingPostLoadResync)
        return;

    SetTransitionPhase("load_guard_end_enter", reason);
    const std::string_view endReason = reason ? std::string_view(reason) : std::string_view();
    const bool loadFailed =
        endReason.find("failed") != std::string_view::npos ||
        endReason.find("ERROR") != std::string_view::npos ||
        endReason.find("error") != std::string_view::npos;
    const bool hostWorldLoadComplete =
        !loadFailed &&
        m_networkMode == CoopNetworkMode::Client &&
        m_pendingHostWorldEpoch != 0;
    const bool arkLevelTransitionComplete =
        !loadFailed &&
        m_arkLevelTransitionLoadActive;

    ++m_loadGuardEndCount;
    m_saveLoadGuardActive = false;
    m_waitingForPostLoadContinue = false;
    m_pendingPostLoadResync = false;
    m_postLoadInteractiveSeconds = 0.0f;
    m_postLoadWaitReason = "-";
    if (!loadFailed)
    {
        if (hostWorldLoadComplete)
            m_localWorldEpoch = m_pendingHostWorldEpoch;
        else if (arkLevelTransitionComplete)
            ++m_levelTransitionEpochKeeps;
        else
            ++m_localWorldEpoch;
        if (m_localWorldEpoch == 0)
            m_localWorldEpoch = 1;
    }
    m_hasRemoteSession = false;
    m_remoteLevelName.clear();
    m_remoteLevelId = 0;
    m_remoteWorldEpoch = 0;
    m_remoteLevelEpoch = 0;
    m_remotePlayerLocation = Vec3(ZERO);
    m_remoteSessionFlags = 0;
    // The peer registry survives a world load, but the flattened active-peer
    // fields above do not. Force the next SessionHello to repopulate them even
    // when it comes from the same peer that was active before the load.
    m_activeRemotePeerToken = 0;
    ResetReplicationSequenceGuardsForWorldChange("local load complete");
    if (!m_reliableSendQueue.empty())
    {
        // Native loading can stop this process from receiving an ACK while
        // another peer is already interactive. Preserve the ordered stream,
        // but do not count that engine stall against its delivery deadline.
        const float reliableResumeTime = GetNowSeconds();
        for (PendingReliablePacket& pending : m_reliableSendQueue)
        {
            pending.enqueuedTime = reliableResumeTime;
            pending.lastSendTime = -1.0f;
            pending.sendAttempts = 0;
        }
        m_reliableBacklogDisconnectPending = false;
        m_networkTelemetry.UpdateReliableQueue(m_reliableSendQueue.size(), 0.0f);
        m_lastReliableEvent =
            "resumed reliable backlog after load packets " +
            std::to_string(m_reliableSendQueue.size());
    }
    const std::string nextLevelName = GetCurrentLevelName();
    if (!m_localLevelName.empty() && m_localLevelName != "unknown" &&
        !nextLevelName.empty() && nextLevelName != "unknown" &&
        !IsKnownSameLevel(m_localLevelName, nextLevelName))
    {
        ++m_localLevelEpoch;
        if (m_localLevelEpoch == 0)
            m_localLevelEpoch = 1;
    }
    m_localLevelName = nextLevelName;
    m_localLevelId = HashLevelName(m_localLevelName);
    if (m_networkMode == CoopNetworkMode::Client)
    {
        if (arkLevelTransitionComplete)
            m_clientLocalAreaEnteredByTransitionLevel = m_localLevelName;
        else if (hostWorldLoadComplete || loadFailed)
            m_clientLocalAreaEnteredByTransitionLevel.clear();
    }
    m_sessionGameplayReady = false;
    m_sessionTickAccumulator = kSessionTickSeconds;
    m_enemyRegistryScanAccumulator = 0.0f;
    m_clientEnemyCullAccumulator = 0.0f;
    m_enemyRegistryNeedsScan = true;
    m_clientEnemyCullNeedsScan = true;
    m_lastRuntimeCleanupLevelName.clear();
    m_lastSaveLoadEvent = std::string("load guard end: ") + (reason ? reason : "unknown");
    if (arkLevelTransitionComplete)
    {
        m_lastSaveLoadEvent += " area-transition-kept-world-epoch";
        m_lastLevelTransitionEvent =
            "area transition complete kept world epoch dest=" +
            std::to_string(m_pendingArkTransitionLocationId) +
            " " + GetLocationDebugName(m_pendingArkTransitionLocationId);
    }
    m_networkStatus = "post-load coop resync pending";
    LogCoop(m_lastSaveLoadEvent);
    SetTransitionPhase("load_guard_end_state_reset", reason);

    if ((arkLevelTransitionComplete || loadFailed) &&
        m_networkMode == CoopNetworkMode::Client &&
        m_clientCoopArkTempBridgeNeedsCleanup)
    {
        SetTransitionPhase("client_bridge_cleanup", arkLevelTransitionComplete ? "area transition complete" : "load failed");
        CleanupClientCoopLevelStateBridge(arkLevelTransitionComplete ? "post-load area transition complete" : "post-load failed");
    }

    if (hostWorldLoadComplete)
    {
        SetTransitionPhase("host_world_load_finalize", reason);
        m_pendingHostWorldRequest = false;
        m_hasPendingHostWorldOffer = false;
        m_lastWorldSyncEvent = "host world load complete";
        m_pendingHostWorldLoadAfterPlayerState = false;
        if (m_pendingReceivedPlayerStateApply)
        {
            m_clientAwaitingHostPlayerState = true;
            if (!TryApplyReceivedPlayerStateTransfer("post-load host player state"))
                m_lastWorldSyncEvent = "host world load complete; waiting for player state apply";
        }
        else
        {
            m_clientAwaitingHostPlayerState = false;
            SetTransitionPhase("send_world_ready_after_host_world", reason);
            const float readyDelay = ResolveEnvSeconds(
                "COOP_CLIENT_WORLD_READY_DELAY_SECONDS",
                0.0f,
                0.0f,
                30.0f);
            if (readyDelay > 0.0f)
            {
                m_deferredClientWorldReadySeconds = std::max(m_deferredClientWorldReadySeconds, readyDelay);
                m_lastWorldSyncEvent =
                    "queued delayed client world ready seconds=" + std::to_string(readyDelay);
                LogCoop(m_lastWorldSyncEvent);
            }
            else
            {
                SendClientWorldReady();
            }
        }
        m_pendingHostWorldEpoch = 0;
        m_pendingHostWorldLevel.clear();
        m_pendingHostWorldSavePath.clear();
    }
    else if (!loadFailed &&
        m_networkMode == CoopNetworkMode::Host &&
        m_pendingHostSaveLoadBroadcastAfterLoad)
    {
        SetTransitionPhase("host_save_load_broadcast", reason);
        if (m_hasRemoteEndpoint)
        {
            m_hasPendingHostWorldOffer = true;
            m_worldSyncRequestAccumulator = kWorldSyncRequestSeconds;
            m_hostPlayerStatePreloadSent = false;
            m_hostPlayerStateSentWorldEpoch = 0;
            m_pendingHostPlayerStateSaveKey = m_currentHostSaveStateKey;
            m_lastWorldSyncEvent = "queued host load command after native load";
            LogCoop(m_lastWorldSyncEvent);
        }
    }
    else if (loadFailed && m_pendingHostWorldEpoch != 0)
    {
        SetTransitionPhase("host_world_load_failed_finalize", reason);
        m_lastWorldSyncEvent = "host world load failed";
        m_pendingHostWorldLoadAfterPlayerState = false;
        m_pendingNativePlayerStateOverrideValid = false;
        m_pendingNativePlayerStateOverride = PlayerSidecarState();
        m_receivedPlayerStateInventoryPreparedForNativeLoad = false;
        m_receivedPlayerStateAbilitiesPreparedForNativeLoad = false;
        m_skipNextHostAuthoritativeInventoryApply = false;
        m_receivedPlayerStateMergedDuringNativeLoad = false;
        m_pendingPlayerSidecarInventoryRestore = false;
        m_pendingPlayerSidecarInventoryRestoreNeedsClear = false;
        m_pendingPlayerSidecarInventoryItems.clear();
        m_pendingPlayerSidecarEquippedWeaponArchetypeId = 0;
        m_pendingPlayerSidecarQuickSelect.clear();
        m_pendingPlayerSidecarHasQuickSelect = false;
        m_pendingPlayerSidecarChipsetRestore = false;
        m_pendingPlayerSidecarChipsets.clear();
        m_playerSidecarInventoryPending = 0;
        m_playerSidecarChipsetsPending = 0;
        m_pendingHostWorldEpoch = 0;
        m_pendingHostWorldLevel.clear();
        m_pendingHostWorldSavePath.clear();
    }
    else if (loadFailed)
    {
        m_pendingHostSaveLoadBroadcastAfterLoad = false;
    }

    m_arkLevelTransitionLoadActive = false;
    m_pendingArkTransitionLocationId = 0;
    m_runtimeTransitionCleanupPrepared = false;
    if (!loadFailed)
    {
        m_transitionRuntimeProxyEntityIds.clear();
        m_transitionRuntimeEntityIds.clear();
    }
    if (!loadFailed && m_networkMode != CoopNetworkMode::Off)
    {
        m_postLoadVisualPerceptionSuppressFrames = GetEnvUIntClamped(
            "COOP_POSTLOAD_VISUAL_SUPPRESS_FRAMES",
            90,
            0,
            600);
        if (m_postLoadVisualPerceptionSuppressFrames > 0)
        {
            LogCoop("post-load visual perception quarantine frames=" +
                std::to_string(m_postLoadVisualPerceptionSuppressFrames));
        }
        m_debugPostProxySpawnTraceFrames = std::max<int>(
            m_debugPostProxySpawnTraceFrames,
            static_cast<int>(GetEnvUIntClamped("COOP_POSTLOAD_MAIN_TRACE_FRAMES", 0, 0, 60)));
        if (m_debugPostProxySpawnTraceFrames > 0)
            LogCoop("post-load main update trace frames=" + std::to_string(m_debugPostProxySpawnTraceFrames));
    }

    if (!loadFailed && !m_pendingAutoStartMode.empty() && m_networkMode == CoopNetworkMode::Off)
    {
        const std::string mode = m_pendingAutoStartMode;
        m_pendingAutoStartMode.clear();
        if (mode == "host")
        {
            LogCoop("deferred autostart host requested after load");
            StartHost();
        }
        else if (mode == "client")
        {
            LogCoop("deferred autostart client requested after load");
            StartClient();
        }
    }

    if (!loadFailed)
    {
        if (EnvFlagEnabled("COOP_DISABLE_AREA_JOURNAL_TRANSFER") ||
            EnvFlagEnabled("COOP_DISABLE_POST_LOAD_AREA_TRANSFER"))
        {
            SetTransitionPhase("post_load_deferred_area_transfer_skipped", reason);
            m_lastAreaJournalTransferEvent = "post-load deferred area journal skipped by env";
            LogCoop(m_lastAreaJournalTransferEvent);
        }
        else
        {
            SetTransitionPhase("post_load_deferred_area_transfer", reason);
            TryStartDeferredAreaJournalTransfer("post-load deferred area journal");
        }
    }

    SetTransitionPhase("load_guard_end_exit", reason);
    LogCoop("load guard end returned");
}

void ModMain::OnCryActionSaveGameRequested(
    const char* path,
    bool quick,
    bool forceImmediate,
    int reason,
    bool ignoreDelay,
    const char* checkpointName)
{
    (void)quick;
    (void)forceImmediate;
    (void)ignoreDelay;

    ++m_saveGameHookCalls;
    const bool internalHostSnapshot =
        m_networkMode == CoopNetworkMode::Host &&
        m_hostInternalSnapshotSaveActive;
    const bool internalClientPlayerSnapshot =
        m_networkMode == CoopNetworkMode::Client &&
        m_clientInternalPlayerSnapshotSaveActive;
    const bool internalCoopSnapshot = internalHostSnapshot || internalClientPlayerSnapshot;
    if (!internalCoopSnapshot)
        m_lastSaveLoadPath = path && path[0] ? path : "-";
    if (m_networkMode == CoopNetworkMode::Host && !internalHostSnapshot)
    {
        SetCurrentHostSaveStateKey(BuildHostSaveStateKey(m_lastSaveLoadPath), true);
        BroadcastHostSaveIdentity("native host save hook");
    }
    m_lastSaveLoadEvent =
        std::string(internalCoopSnapshot ? "SaveGame internal snapshot reason=" : "SaveGame reason=") +
        std::to_string(reason);
    if (checkpointName && checkpointName[0])
        m_lastSaveLoadEvent += " checkpoint=" + std::string(checkpointName);

    if (NativeSaveInstrumentationEnabled())
    {
        BeginNativeSideBlobCapture(
            internalHostSnapshot ? "internal host snapshot save hook" :
            internalClientPlayerSnapshot ? "internal client player snapshot save hook" :
            "native save hook");
    }

    if (internalClientPlayerSnapshot)
    {
        m_lastPlayerStateTransferEvent = "capturing native client player snapshot";
        LogCoop(m_lastPlayerStateTransferEvent);
        return;
    }

    QueuePlayerSidecarSave("native save hook");
    if (m_networkMode == CoopNetworkMode::Host)
    {
        if (internalHostSnapshot)
        {
            m_lastPlayerStateTransferEvent = "skipped player-state upload for internal host snapshot";
            LogCoop(m_lastPlayerStateTransferEvent);
        }
        else
        {
            SnapshotLatestHostPlayerStatesForSave(m_currentHostSaveStateKey, "native host save hook");
            RequestRemotePlayerStateUpload("native host save hook");
        }
    }
    else
    {
        QueueClientPlayerStateUpload("native client save hook");
    }
    PurgeCoopRuntimeEntitiesForSave("CCryAction::SaveGame");
}

void ModMain::OnCryActionSaveGameReturned(
    const char* path,
    bool quick,
    bool forceImmediate,
    int reason,
    bool ignoreDelay,
    const char* checkpointName,
    bool result)
{
    const bool internalHostSnapshot =
        m_networkMode == CoopNetworkMode::Host &&
        m_hostInternalSnapshotSaveActive;
    const bool internalClientPlayerSnapshot =
        m_networkMode == CoopNetworkMode::Client &&
        m_clientInternalPlayerSnapshotSaveActive;
    const bool internalCoopSnapshot = internalHostSnapshot || internalClientPlayerSnapshot;

    m_lastSaveLoadEvent =
        std::string("SaveGame returned ") + (result ? "1" : "0") +
        (internalHostSnapshot ? " internalHostSnapshot=1" : "") +
        (internalClientPlayerSnapshot ? " internalClientPlayerSnapshot=1" : "") +
        (internalCoopSnapshot ? "" : " userSave=1") +
        " reason=" + std::to_string(reason) +
        " quick=" + std::to_string(quick ? 1 : 0) +
        " force=" + std::to_string(forceImmediate ? 1 : 0) +
        " ignoreDelay=" + std::to_string(ignoreDelay ? 1 : 0) +
        " path=" + StatusToken(path && path[0] ? std::string(path) : std::string("-"));
    if (checkpointName && checkpointName[0])
        m_lastSaveLoadEvent += " checkpoint=" + StatusToken(checkpointName);
    LogCoop(m_lastSaveLoadEvent);
}

void ModMain::OnCryActionNotifySaveGame(ISaveGame* saveGame)
{
    const uint64_t atlasSeq = BeginSaveStateTracePhase(
        CoopSaveStateBridge::TracePhase::ActiveSaveNotify,
        CoopSaveStateBridge::SchemaSemantic::Section,
        "CCryAction::NotifySaveGame",
        saveGame,
        nullptr,
        "pre-vanilla");
    EndSaveStateTracePhase(
        atlasSeq,
        CoopSaveStateBridge::TracePhase::ActiveSaveNotify,
        CoopSaveStateBridge::SchemaSemantic::Section,
        "CCryAction::NotifySaveGame",
        saveGame,
        nullptr,
        "pre-vanilla");

    ++m_nativeSideBlobSaveNotifyCalls;
    if (!m_nativeSideBlobProbeEnabled)
    {
        m_lastNativeSideBlobEvent = "save notify skipped: probe disabled";
        return;
    }

    if (!saveGame)
    {
        ++m_nativeSideBlobFailures;
        m_lastNativeSideBlobEvent = "save notify failed: null ISaveGame";
        return;
    }

    if (!IsLikelyRuntimeCppObject(saveGame))
    {
        ++m_nativeSideBlobFailures;
        m_lastNativeSideBlobEvent = "save notify failed: unreadable ISaveGame";
        return;
    }

    std::string guardReason;
    bool wrote = false;
    if (!TryGuardedCall(
            "coop native sideblob AddSection/write probe",
            [&]() -> bool
            {
                alignas(TSerialize) std::byte serializerStorage[sizeof(TSerialize)];
                TSerialize* serializer = reinterpret_cast<TSerialize*>(serializerStorage);
                TSerialize* returned = saveGame->AddSection(serializer, kNativeSideBlobProbeSection);
                if (!returned)
                    return false;
                int version = 1;
                int marker = 0x23402340;
                string username = GetLocalUsername().c_str();
                string levelName = GetCurrentLevelName().c_str();
                int worldEpoch = static_cast<int>(m_localWorldEpoch);
                int inventoryRows = static_cast<int>(m_playerSidecarInventorySaved);

                returned->Value("version", version);
                returned->Value("marker", marker);
                returned->Value("username", username);
                returned->Value("level", levelName);
                returned->Value("worldEpoch", worldEpoch);
                returned->Value("inventoryRows", inventoryRows);
                return returned->Ok();
            },
            wrote,
            &guardReason) ||
        !wrote)
    {
        ++m_nativeSideBlobFailures;
        m_lastNativeSideBlobEvent = "save section write failed: " + (guardReason.empty() ? std::string("serializer not ok") : guardReason);
        LogCoop(m_lastNativeSideBlobEvent);
        return;
    }

    std::string capturedSummary;
    if (m_nativeSideBlobCapture.active || m_nativeSideBlobCapture.sawPlayerWrite || m_nativeSideBlobCapture.sawInventoryWrite)
    {
        if (!WriteCapturedNativeSideBlob(saveGame, capturedSummary))
        {
            ++m_nativeSideBlobFailures;
            ++m_nativeSideBlobCapturedFailures;
            LogCoop("native captured sideblob write failed: " + capturedSummary);
        }
    }
    else
    {
        capturedSummary = " capturedSkipped=no_capture";
    }

    std::string mirrorSummary;
    if (m_nativeSideBlobActiveMirrorEnabled)
    {
        uint32_t mirrorSections = 0;
        uint32_t mirrorItemSections = 0;
        std::string mirrorReason;
        if (TryWriteNativePlayerMirrorSideBlob(saveGame, mirrorSections, mirrorItemSections, mirrorReason))
        {
            m_nativeSideBlobMirrorWriteSections += mirrorSections;
            m_nativeSideBlobMirrorItemWriteSections += mirrorItemSections;
            mirrorSummary =
                " mirrorSections=" + std::to_string(mirrorSections) +
                " mirrorItems=" + std::to_string(mirrorItemSections);
        }
        else
        {
            ++m_nativeSideBlobFailures;
            ++m_nativeSideBlobMirrorFailures;
            mirrorSummary = " mirrorWriteFailed=" + (mirrorReason.empty() ? std::string("unknown") : mirrorReason);
            LogCoop("native sideblob mirror write failed: " + (mirrorReason.empty() ? std::string("unknown") : mirrorReason));
        }
    }
    else
    {
        mirrorSummary = " mirrorSkipped=active_disabled";
    }

    ++m_nativeSideBlobWriteSuccesses;
    m_lastNativeSideBlobEvent =
        std::string("save section wrote ") + kNativeSideBlobProbeSection +
        " user=" + GetLocalUsername() +
        " level=" + GetCurrentLevelName() +
        capturedSummary +
        mirrorSummary;
    LogCoop(m_lastNativeSideBlobEvent);
}

void ModMain::OnCryActionNotifySaveGamePostVanilla(ISaveGame* saveGame)
{
    const uint64_t atlasSeq = BeginSaveStateTracePhase(
        CoopSaveStateBridge::TracePhase::ActiveSaveNotify,
        CoopSaveStateBridge::SchemaSemantic::Section,
        "CCryAction::NotifySaveGamePostVanilla",
        saveGame,
        nullptr,
        "post-vanilla");
    EndSaveStateTracePhase(
        atlasSeq,
        CoopSaveStateBridge::TracePhase::ActiveSaveNotify,
        CoopSaveStateBridge::SchemaSemantic::Section,
        "CCryAction::NotifySaveGamePostVanilla",
        saveGame,
        nullptr,
        "post-vanilla");

    const bool shouldDump =
        EnvFlagEnabled("COOP_DUMP_SAVE_XML") ||
        (NativeSaveInstrumentationEnabled() &&
            (m_clientInternalPlayerSnapshotSaveActive ||
                m_hostInternalSnapshotSaveActive));
    if (!shouldDump)
        return;

    if (!saveGame || !IsLikelyRuntimeCppObject(saveGame, sizeof(void*) * 2))
    {
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent = "save xml diag skipped: unreadable ISaveGame";
        return;
    }

    if (!EnvFlagEnabled("COOP_TRY_ACTIVE_SAVE_ROOT"))
    {
        // ISaveGame here may be an active interface wrapper. Do not assume the
        // concrete ::Save layout or m_root offset from this callback.
        m_lastNativePlayerXmlPatchEvent =
            "active save notify observed; root probe skipped pending concrete Save hook snapshot=" +
            BuildSaveLoadObjectSnapshot(saveGame, "active_save_notify");
        LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);
        return;
    }

    XmlNodeRef root;
    std::string guardReason;
    if (!TryReadConcreteSaveLoadRoot(saveGame, "coop native save root xml", root, &guardReason))
    {
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent =
            "save xml diag failed: root unavailable" +
            (guardReason.empty() ? std::string() : " guard=" + guardReason) +
            " snapshot=" + BuildSaveLoadObjectSnapshot(saveGame, "save");
        LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);
        return;
    }

    WriteNativeSaveLoadXmlDiagnostics(
        "save_postvanilla",
        m_clientInternalPlayerSnapshotSaveActive ? "client player snapshot save" :
        m_hostInternalSnapshotSaveActive ? "host internal snapshot save" :
        "post vanilla save notify",
        root,
        EnvFlagEnabled("COOP_DUMP_SAVE_XML_FULL"));
}

void ModMain::OnConcreteSaveComplete(void* saveGame, bool successfulSoFar)
{
    const bool shouldDump =
        EnvFlagEnabled("COOP_DUMP_SAVE_XML") ||
        (NativeSaveInstrumentationEnabled() &&
            (m_clientInternalPlayerSnapshotSaveActive ||
                m_hostInternalSnapshotSaveActive));
    if (!shouldDump)
        return;

    if (!saveGame || !IsLikelyRuntimeCppObject(saveGame, sizeof(::Save)))
    {
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent = "concrete save complete diag skipped: unreadable Save";
        return;
    }

    ::Save* concreteSave = static_cast<::Save*>(saveGame);
    XmlNodeRef root;
    std::string guardReason;
    if (!TryGuardedVoidCall(
            "coop native concrete Save::Complete root read",
            [&]()
            {
                root = concreteSave->m_root;
            },
            &guardReason))
    {
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent =
            "concrete save complete root guard " + guardReason +
            " snapshot=" + BuildSaveLoadObjectSnapshot(saveGame, "concrete_save_complete");
        LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);
        return;
    }

    WriteNativeSaveLoadXmlDiagnostics(
        "save_complete_prevanilla",
        m_clientInternalPlayerSnapshotSaveActive ? "client player snapshot save complete" :
        m_hostInternalSnapshotSaveActive ? "host internal snapshot save complete" :
        (successfulSoFar ? "save complete pre vanilla" : "save complete pre vanilla unsuccessful"),
        root,
        EnvFlagEnabled("COOP_DUMP_SAVE_XML_FULL"));
}

void ModMain::OnActiveSaveWriteComplete(void* activeSave, const char* saveName, void* fileHandleRef, bool result)
{
    const std::string safeSaveName = ReadRuntimeCString(saveName, 260);
    const std::string completeReason = "ActiveSave::WriteComplete " + StatusToken(safeSaveName);
    if (m_networkMode == CoopNetworkMode::Host &&
        m_saveTransferSnapshotPending &&
        m_saveTransferSourcePath == "CoopHostSnapshot" &&
        safeSaveName.find("CoopHostSnapshot") != std::string::npos)
    {
        m_hostInternalSnapshotWriteCompleteReceived = true;
        m_hostInternalSnapshotWriteCompleteObserved = result;
        LogCoop(
            std::string("host snapshot write-complete observed result=") +
            (result ? "1" : "0") +
            " save=" + StatusToken(safeSaveName));
    }

    const bool hasNativeCapture =
        m_nativeSideBlobCapture.active ||
        m_nativeSideBlobCapture.sawPlayerWrite ||
        m_nativeSideBlobCapture.sawInventoryWrite ||
        m_nativeSideBlobCapture.sawItemWrite ||
        m_nativeSideBlobCapture.hasNativeFragmentPayload;
    const bool needsFinalStoreForNativeCapture = result && hasNativeCapture;
    const bool traceFinalStore =
        EnvFlagEnabled("COOP_TRACE_ACTIVE_SAVE_COMPLETE") ||
        EnvFlagEnabled("COOP_SAVE_ATLAS") ||
        EnvFlagEnabled("COOP_NATIVE_FRAGMENT_CAPTURE_FINAL_STORE") ||
        EnvFlagEnabled("COOP_NATIVE_SAVE_STORE_WRITE_TRAMPOLINE_PROBE") ||
        EnvFlagEnabled("COOP_NATIVE_SAVE_STORE_ALLOCATOR_PROBE");

    FlushNativeFinalStreamCapture(completeReason.c_str(), result);

    if (result && EnvFlagEnabled("COOP_NATIVE_SCRATCH_LOADSTORE_PROBE"))
    {
        std::string scratchProbeSave = safeSaveName;
        if (scratchProbeSave.find("CoopClientPlayerSnapshot") != std::string::npos)
            scratchProbeSave = "CoopClientPlayerSnapshot";
        ProbeScratchNativeLoadStoreFromSave(scratchProbeSave, completeReason.c_str());
    }

    if (!result)
    {
        FinalizeNativeSideBlobCaptureFromSaveComplete(
            completeReason.c_str(),
            result);
        if (!traceFinalStore)
            return;
    }

    if (!traceFinalStore && !needsFinalStoreForNativeCapture)
    {
        return;
    }

    ++m_activeSaveWriteCompleteTraceCalls;
    if (!activeSave)
    {
        ++m_activeSaveWriteCompleteTraceFailures;
        m_lastActiveSaveWriteCompleteTraceEvent =
            "active_save_write_complete null activeSave result=" + std::to_string(result ? 1 : 0) +
            " save=" + StatusToken(safeSaveName);
        LogCoop(m_lastActiveSaveWriteCompleteTraceEvent);
        FinalizeNativeSideBlobCaptureFromSaveComplete(
            completeReason.c_str(),
            result);
        return;
    }

    const auto* activeSaveBytes = reinterpret_cast<const uint8_t*>(activeSave);
    void* const storeOwner = const_cast<uint8_t*>(activeSaveBytes + 0x50);
    std::string guardReason;
    if (!PreflightRuntimePointer("active save write complete object", activeSave, 0x80, RuntimeAccess::Read, &guardReason))
    {
        ++m_activeSaveWriteCompleteTraceFailures;
        m_lastActiveSaveWriteCompleteTraceEvent =
            "active_save_write_complete activeSave unreadable guard=" + guardReason +
            " result=" + std::to_string(result ? 1 : 0) +
            " save=" + StatusToken(safeSaveName);
        LogCoop(m_lastActiveSaveWriteCompleteTraceEvent);
        FinalizeNativeSideBlobCaptureFromSaveComplete(
            completeReason.c_str(),
            result);
        return;
    }

    std::array<std::uintptr_t, 3> stackEntry = {};
    const bool copied = TryGuardedVoidCall(
        "active save write complete copy stack entry",
        [&]()
        {
            s_funcSaveStoreCopyCurrentStackEntry(storeOwner, stackEntry.data());
        },
        &guardReason);
    if (!copied)
    {
        ++m_activeSaveWriteCompleteTraceFailures;
        m_lastActiveSaveWriteCompleteTraceEvent =
            "active_save_write_complete copy failed guard=" + guardReason +
            " activeSave=" + PointerHex(activeSave) +
            " storeOwner=" + PointerHex(storeOwner) +
            " result=" + std::to_string(result ? 1 : 0) +
            " save=" + StatusToken(safeSaveName);
        LogCoop(m_lastActiveSaveWriteCompleteTraceEvent);
        FinalizeNativeSideBlobCaptureFromSaveComplete(
            completeReason.c_str(),
            result);
        return;
    }

    void* resolvedNode = nullptr;
    const bool resolved = TryGuardedCall(
        "active save write complete resolve node",
        [&]() -> void*
        {
            return s_funcSaveStoreResolveWriteStackEntryNode(stackEntry.data());
        },
        resolvedNode,
        &guardReason);
    if (!resolved)
    {
        ++m_activeSaveWriteCompleteTraceFailures;
        m_lastActiveSaveWriteCompleteTraceEvent =
            "active_save_write_complete resolve failed guard=" + guardReason +
            " activeSave=" + PointerHex(activeSave) +
            " storeOwner=" + PointerHex(storeOwner) +
            " stack=" + Hex64(stackEntry[0]) + "," + Hex64(stackEntry[1]) + "," + Hex64(stackEntry[2]) +
            " result=" + std::to_string(result ? 1 : 0) +
            " save=" + StatusToken(safeSaveName);
        LogCoop(m_lastActiveSaveWriteCompleteTraceEvent);
        FinalizeNativeSideBlobCaptureFromSaveComplete(
            completeReason.c_str(),
            result);
        return;
    }

    CoopSaveStoreDecoder::DecodeOptions options = CoopSaveStoreDecoder::OptionsFromEnvironment();
    options.fullStoreMap = options.fullStoreMap || EnvFlagEnabled("COOP_TRACE_ACTIVE_SAVE_COMPLETE_FULL_STORE");
    CoopSaveStoreDecoder::DecodeResult decoded =
        CoopSaveStoreDecoder::DecodeWriteStackEntry(stackEntry.data(), resolvedNode, options);

    if (EnvFlagEnabled("COOP_NATIVE_SAVE_STORE_WRITE_TRAMPOLINE_PROBE"))
    {
        ++m_nativeWriteStoreProbeCalls;
        const CoopNativeSaveStoreApi::WriteStoreProbeResult probe =
            CoopNativeSaveStoreApi::ProbeWriteStoreTrampolines(storeOwner, stackEntry);
        if (probe.ok)
            ++m_nativeWriteStoreProbeSuccesses;
        else
            m_nativeWriteStoreProbeGuards += probe.guards != 0 ? probe.guards : 1u;

        m_lastNativeWriteStoreProbeEvent =
            CoopNativeSaveStoreApi::BuildWriteStoreProbeStatus(probe);
        if (m_nativeWriteStoreProbeCalls <= 16 || !probe.ok)
            LogCoop("native_write_store_probe " + m_lastNativeWriteStoreProbeEvent);
    }

    if (EnvFlagEnabled("COOP_NATIVE_SAVE_STORE_ALLOCATOR_PROBE"))
    {
        ++m_nativeWriteAllocatorProbeCalls;
        const uint32_t requestedNodes = GetEnvUIntClamped(
            "COOP_NATIVE_SAVE_STORE_ALLOCATOR_PROBE_NODES",
            6,
            0,
            4096);
        const uint32_t requestedBacking = GetEnvUIntClamped(
            "COOP_NATIVE_SAVE_STORE_ALLOCATOR_PROBE_BACKING",
            4,
            0,
            4096);
        const uint32_t requestedEntities = GetEnvUIntClamped(
            "COOP_NATIVE_SAVE_STORE_ALLOCATOR_PROBE_ENTITIES",
            1,
            0,
            4096);
        const CoopNativeSaveStoreApi::WriteAllocatorProbeResult allocatorProbe =
            CoopNativeSaveStoreApi::ProbeWriteAllocatorReadiness(
                storeOwner,
                stackEntry,
                requestedNodes,
                requestedBacking,
                requestedEntities);
        if (allocatorProbe.ok)
            ++m_nativeWriteAllocatorProbeSuccesses;
        else
            m_nativeWriteAllocatorProbeGuards += allocatorProbe.guards != 0 ? allocatorProbe.guards : 1u;

        m_lastNativeWriteAllocatorProbeEvent =
            CoopNativeSaveStoreApi::BuildWriteAllocatorProbeStatus(allocatorProbe);
        if (m_nativeWriteAllocatorProbeCalls <= 16 || !allocatorProbe.ok)
            LogCoop("native_write_allocator_probe " + m_lastNativeWriteAllocatorProbeEvent);
    }

    if (decoded.storeMap.ok)
    {
        ++m_activeSaveWriteCompleteTraceSuccesses;
        m_lastSaveStoreMapEvent = CoopSaveStoreDecoder::BuildStoreMapStatus(decoded.storeMap);
    }
    else
    {
        ++m_activeSaveWriteCompleteTraceFailures;
    }

    m_lastActiveSaveWriteCompleteTraceEvent =
        "active_save_write_complete result=" + std::to_string(result ? 1 : 0) +
        " save=" + StatusToken(safeSaveName) +
        " activeSave=" + PointerHex(activeSave) +
        " storeOwner=" + PointerHex(storeOwner) +
        " fileRef=" + PointerHex(fileHandleRef) +
        " node=" + PointerHex(resolvedNode) +
        " stack=" + Hex64(stackEntry[0]) + "," + Hex64(stackEntry[1]) + "," + Hex64(stackEntry[2]) +
        " slots=" + std::to_string(decoded.slots) +
        " candidates=" + std::to_string(decoded.candidates) +
        " guards=" + std::to_string(decoded.guards) +
        " detail=" + StatusToken(decoded.detail);
    LogCoop(m_lastActiveSaveWriteCompleteTraceEvent);

    m_saveStateBridge.RecordSerializerStoreProbe(
        "ActiveISaveGame::WriteComplete",
        result ? "post-write-complete" : "post-write-complete-failed",
        safeSaveName.c_str(),
        stackEntry.data(),
        decoded.detail.c_str());

    FinalizeNativeSideBlobCaptureFromSaveComplete(
        completeReason.c_str(),
        result);
}

void ModMain::BeginNativeFinalStreamCapture(const char* saveName)
{
    const std::string safeSaveName = ReadRuntimeCString(saveName, 260);
    m_activeNativeFinalStreamSaveName = safeSaveName.empty() ? std::string("unknown_save") : safeSaveName;
    m_nativeFinalStreamCapturedChunks = 0;
    m_nativeFinalStreamCapturedBytes = 0;
    m_nativeFinalStreamBufferedBytes = 0;
    m_nativeFinalStreamDroppedBytes = 0;
    m_nativeFinalStreamGuards = 0;
    m_nativeFinalStreamChecksum = kFnv1aOffsetBasis;
    m_nativeFinalStreamBuffer.clear();
    m_lastNativeFinalStreamDumpPath = "-";
    m_lastNativeFinalStoreObjectEvent = "-";
    m_nativeFinalStoreObjectSnapshot = {};

    if (NativeFinalStreamByteCaptureEnabled())
    {
        const uint32_t maxCaptureBytes = GetEnvUIntClamped(
            "COOP_NATIVE_FINAL_STREAM_CAPTURE_MAX_BYTES",
            8u * 1024u * 1024u,
            0x1000u,
            128u * 1024u * 1024u);
        if (m_nativeFinalStreamBuffer.capacity() < maxCaptureBytes)
            m_nativeFinalStreamBuffer.reserve(maxCaptureBytes);
    }

    m_lastNativeFinalStreamEvent =
        "final_stream begin save=" + StatusToken(m_activeNativeFinalStreamSaveName) +
        " byteCapture=" + std::to_string(NativeFinalStreamByteCaptureEnabled() ? 1 : 0);
}

void ModMain::FlushNativeFinalStreamCapture(const char* phase, bool result)
{
    if (!EnvFlagEnabled("COOP_NATIVE_FINAL_STREAM_DUMP"))
        return;

    if (m_nativeFinalStreamBuffer.empty())
    {
        m_lastNativeFinalStreamEvent =
            "final_stream dump_empty phase=" + StatusToken(phase ? std::string(phase) : std::string("-")) +
            " result=" + std::to_string(result ? 1 : 0) +
            " chunks=" + std::to_string(m_nativeFinalStreamCapturedChunks) +
            " total=" + std::to_string(m_nativeFinalStreamCapturedBytes);
        return;
    }

    const std::filesystem::path root = GetCoopNativeFinalStreamRoot();
    if (root.empty())
    {
        ++m_nativeFinalStreamGuards;
        m_lastNativeFinalStreamEvent = "final_stream dump_failed profile_root_unavailable";
        return;
    }

    std::error_code error;
    std::filesystem::create_directories(root, error);
    if (error)
    {
        ++m_nativeFinalStreamGuards;
        m_lastNativeFinalStreamEvent =
            "final_stream dump_failed mkdir " + StatusToken(error.message());
        return;
    }

    const uint32_t nextDump = m_nativeFinalStreamDumpWrites + 1;
    const std::string safeSave = SanitizePathComponent(m_activeNativeFinalStreamSaveName.empty() ? std::string("unknown_save") : m_activeNativeFinalStreamSaveName);
    const std::string partial = m_nativeFinalStreamDroppedBytes != 0 ? "_partial" : "";
    const std::string fileName =
        "final_stream_" + std::to_string(nextDump) +
        "_" + safeSave +
        "_" + Hex32(m_nativeFinalStreamChecksum) +
        "_" + std::to_string(m_nativeFinalStreamBufferedBytes) +
        partial +
        ".bin";
    const std::filesystem::path path = root / fileName;
    std::filesystem::path tempPath = path;
    tempPath += ".tmp";

    {
        std::ofstream output(tempPath, std::ios::binary | std::ios::trunc);
        if (!output)
        {
            ++m_nativeFinalStreamGuards;
            m_lastNativeFinalStreamEvent = "final_stream dump_failed open path=" + StatusToken(CoopFilesystem::ToUtf8(path));
            return;
        }

        output.write(
            reinterpret_cast<const char*>(m_nativeFinalStreamBuffer.data()),
            static_cast<std::streamsize>(m_nativeFinalStreamBuffer.size()));
        if (!output)
        {
            ++m_nativeFinalStreamGuards;
            m_lastNativeFinalStreamEvent = "final_stream dump_failed write path=" + StatusToken(CoopFilesystem::ToUtf8(path));
            return;
        }
    }

    std::filesystem::rename(tempPath, path, error);
    if (error)
    {
        error.clear();
        std::filesystem::copy_file(tempPath, path, std::filesystem::copy_options::overwrite_existing, error);
        std::error_code removeError;
        std::filesystem::remove(tempPath, removeError);
        if (error)
        {
            ++m_nativeFinalStreamGuards;
            m_lastNativeFinalStreamEvent =
                "final_stream dump_failed commit " + StatusToken(error.message()) +
                " path=" + StatusToken(CoopFilesystem::ToUtf8(path));
            return;
        }
    }

    std::filesystem::path metaPath = path;
    metaPath += ".txt";
    std::ofstream meta(metaPath, std::ios::binary | std::ios::trunc);
    if (meta)
    {
        meta << "phase=" << (phase ? phase : "-") << "\n";
        meta << "result=" << (result ? 1 : 0) << "\n";
        meta << "save=" << m_activeNativeFinalStreamSaveName << "\n";
        meta << "chunks=" << m_nativeFinalStreamCapturedChunks << "\n";
        meta << "capturedBytes=" << m_nativeFinalStreamCapturedBytes << "\n";
        meta << "bufferedBytes=" << m_nativeFinalStreamBufferedBytes << "\n";
        meta << "droppedBytes=" << m_nativeFinalStreamDroppedBytes << "\n";
        meta << "checksum=" << Hex32(m_nativeFinalStreamChecksum) << "\n";
        meta << "finalObjectValid=" << (m_nativeFinalStoreObjectSnapshot.valid ? 1 : 0) << "\n";
        meta << "finalObject.table14Begin=" << m_nativeFinalStoreObjectSnapshot.table14Begin << "\n";
        meta << "finalObject.table14End=" << m_nativeFinalStoreObjectSnapshot.table14End << "\n";
        meta << "finalObject.table1cBegin=" << m_nativeFinalStoreObjectSnapshot.table1cBegin << "\n";
        meta << "finalObject.table1cEnd=" << m_nativeFinalStoreObjectSnapshot.table1cEnd << "\n";
        meta << "finalObject.table24Begin=" << m_nativeFinalStoreObjectSnapshot.table24Begin << "\n";
        meta << "finalObject.table24End=" << m_nativeFinalStoreObjectSnapshot.table24End << "\n";
        meta << "finalObject.childEntries=" << m_nativeFinalStoreObjectSnapshot.childEntries << "\n";
        meta << "finalObject.attrTokens=" << m_nativeFinalStoreObjectSnapshot.attrTokens << "\n";
        meta << "finalObject.finalBytes=" << m_nativeFinalStoreObjectSnapshot.finalBytes << "\n";
        meta << "finalObject.rootNodeIndex=" << m_nativeFinalStoreObjectSnapshot.rootNodeIndex << "\n";
        meta << "finalObject.flags=" << static_cast<uint32_t>(m_nativeFinalStoreObjectSnapshot.flags) << "\n";
        meta << "finalObject.streamOwner=" << Hex64(static_cast<uint64_t>(m_nativeFinalStoreObjectSnapshot.streamOwner)) << "\n";
        meta << "finalObject.currentChunk=" << Hex64(static_cast<uint64_t>(m_nativeFinalStoreObjectSnapshot.currentChunk)) << "\n";
    }

    ++m_nativeFinalStreamDumpWrites;
    m_lastNativeFinalStreamDumpPath = CoopFilesystem::ToUtf8(path);
    m_lastNativeFinalStreamEvent =
        "final_stream dump_ok path=" + StatusToken(CoopFilesystem::ToUtf8(path)) +
        " bytes=" + std::to_string(m_nativeFinalStreamBufferedBytes) +
        " dropped=" + std::to_string(m_nativeFinalStreamDroppedBytes) +
        " checksum=" + Hex32(m_nativeFinalStreamChecksum);
    LogCoop(m_lastNativeFinalStreamEvent);
}

void ModMain::OnSaveStoreFinalizeToReadStreamObject(void* writeStore, void* finalObject)
{
    ++m_nativeFinalStoreObjectCalls;

    const bool hasObservedCapture =
        m_nativeSideBlobCapture.active ||
        m_nativeSideBlobCapture.sawPlayerWrite ||
        m_nativeSideBlobCapture.sawInventoryWrite ||
        m_nativeSideBlobCapture.sawItemWrite;
    const bool captureInteresting =
        hasObservedCapture ||
        EnvFlagEnabled("COOP_TRACE_NATIVE_FINAL_STREAM") ||
        EnvFlagEnabled("COOP_TRACE_NATIVE_FINAL_STORE_OBJECT") ||
        NativeFinalStreamByteCaptureEnabled();
    if (!captureInteresting)
        return;

    if (!finalObject)
    {
        ++m_nativeFinalStoreObjectGuards;
        m_lastNativeFinalStoreObjectEvent =
            "final_store_object null writeStore=" + PointerHex(writeStore);
        return;
    }

    std::string reason;
    if (!PreflightRuntimePointer(
            "native final store object",
            finalObject,
            0x50,
            RuntimeAccess::Read,
            &reason))
    {
        ++m_nativeFinalStoreObjectGuards;
        m_lastNativeFinalStoreObjectEvent =
            "final_store_object preflight_failed writeStore=" + PointerHex(writeStore) +
            " object=" + PointerHex(finalObject) +
            " guard=" + StatusToken(reason);
        return;
    }

    NativeFinalStoreObjectSnapshot snapshot;

    struct ReadContext
    {
        const uint8_t* object = nullptr;
        NativeFinalStoreObjectSnapshot* snapshot = nullptr;
    } context { reinterpret_cast<const uint8_t*>(finalObject), &snapshot };

    const bool readOk = CoopRuntimeGuards::TryRunGuardedCallback(
        "native final store object read",
        [](void* rawContext) -> bool
        {
            auto* ctx = static_cast<ReadContext*>(rawContext);
            auto readU32 = [&](size_t offset) -> uint32_t
            {
                uint32_t value = 0;
                std::memcpy(&value, ctx->object + offset, sizeof(value));
                return value;
            };
            auto readPtr = [&](size_t offset) -> std::uintptr_t
            {
                std::uintptr_t value = 0;
                std::memcpy(&value, ctx->object + offset, sizeof(value));
                return value;
            };

            ctx->snapshot->table14Begin = readU32(0x14);
            ctx->snapshot->table14End = readU32(0x18);
            ctx->snapshot->table1cBegin = readU32(0x1c);
            ctx->snapshot->table1cEnd = readU32(0x20);
            ctx->snapshot->table24Begin = readU32(0x24);
            ctx->snapshot->table24End = readU32(0x28);
            ctx->snapshot->childEntries = readU32(0x2c);
            ctx->snapshot->attrTokens = readU32(0x30);
            ctx->snapshot->finalBytes = readU32(0x34);
            ctx->snapshot->rootNodeIndex = readU32(0x38);
            ctx->snapshot->flags = *(ctx->object + 0x3c);
            ctx->snapshot->streamOwner = readPtr(0x40);
            ctx->snapshot->currentChunk = readPtr(0x48);
            ctx->snapshot->valid = true;
            return true;
        },
        &context,
        &reason);
    if (!readOk)
    {
        ++m_nativeFinalStoreObjectGuards;
        m_lastNativeFinalStoreObjectEvent =
            "final_store_object read_failed writeStore=" + PointerHex(writeStore) +
            " object=" + PointerHex(finalObject) +
            " guard=" + StatusToken(reason);
        return;
    }

    ++m_nativeFinalStoreObjectTraces;
    m_nativeFinalStoreObjectSnapshot = snapshot;
    m_lastNativeFinalStoreObjectEvent =
        "final_store_object writeStore=" + PointerHex(writeStore) +
        " object=" + PointerHex(finalObject) +
        " table14=" + std::to_string(snapshot.table14Begin) + "," + std::to_string(snapshot.table14End) +
        " table1c=" + std::to_string(snapshot.table1cBegin) + "," + std::to_string(snapshot.table1cEnd) +
        " table24=" + std::to_string(snapshot.table24Begin) + "," + std::to_string(snapshot.table24End) +
        " childEntries=" + std::to_string(snapshot.childEntries) +
        " attrTokens=" + std::to_string(snapshot.attrTokens) +
        " finalBytes=" + std::to_string(snapshot.finalBytes) +
        " rootNode=" + std::to_string(snapshot.rootNodeIndex) +
        " flags=" + std::to_string(static_cast<uint32_t>(snapshot.flags)) +
        " streamOwner=" + Hex64(static_cast<uint64_t>(snapshot.streamOwner)) +
        " currentChunk=" + Hex64(static_cast<uint64_t>(snapshot.currentChunk));

    if (hasObservedCapture)
    {
        const bool shouldAttachNativePayload =
            NativeFragmentProgressiveCaptureEnabled() ||
            EnvFlagEnabled("COOP_NATIVE_FRAGMENT_CAPTURE_BYTES") ||
            EnvFlagEnabled("COOP_NATIVE_PLAYER_STATE_REQUIRE_NATIVE_FRAGMENT") ||
            CoopRuntimeConfig::UnsafeFlag("COOP_ENABLE_NATIVE_COOP_SAVE_MERGE_MUTATION") ||
            EnvFlagEnabled("COOP_NATIVE_FRAGMENT_APPLY_FULL_TRANSPLANT") ||
            EnvFlagEnabled("COOP_NATIVE_FRAGMENT_APPLY_SAME_SHAPE_REBASE");
        if (shouldAttachNativePayload)
            TryAttachNativeFragmentPayload(m_nativeSideBlobCapture, "SaveStore::FinalizeToReadStreamObject");

        FinalizeNativeSideBlobCaptureFromSaveComplete(
            "SaveStore::FinalizeToReadStreamObject",
            true);
    }
}

void ModMain::OnSaveStoreFinalChunkWriteSink(void* sink, const void* bytes, uint32_t byteCount)
{
    ++m_nativeFinalStreamSinkCalls;

    const bool captureInteresting =
        m_nativeSideBlobCapture.active ||
        m_nativeSideBlobCapture.sawPlayerWrite ||
        m_nativeSideBlobCapture.sawInventoryWrite ||
        m_nativeSideBlobCapture.sawItemWrite ||
        EnvFlagEnabled("COOP_TRACE_NATIVE_FINAL_STREAM") ||
        NativeFinalStreamByteCaptureEnabled();
    if (!captureInteresting)
        return;

    if (!bytes || byteCount == 0)
    {
        m_lastNativeFinalStreamEvent =
            "final_stream empty sink=" + PointerHex(sink) +
            " bytes=" + PointerHex(bytes) +
            " count=" + std::to_string(byteCount);
        return;
    }

    const uint32_t maxChunkBytes = GetEnvUIntClamped(
        "COOP_NATIVE_FINAL_STREAM_MAX_CHUNK_BYTES",
        0x200000u,
        0x10u,
        0x4000000u);
    if (byteCount > maxChunkBytes)
    {
        ++m_nativeFinalStreamGuards;
        m_lastNativeFinalStreamEvent =
            "final_stream chunk_too_large sink=" + PointerHex(sink) +
            " bytes=" + PointerHex(bytes) +
            " count=" + std::to_string(byteCount) +
            " max=" + std::to_string(maxChunkBytes);
        return;
    }

    std::string reason;
    if (!PreflightRuntimePointer(
            "native final stream chunk",
            bytes,
            byteCount,
            RuntimeAccess::Read,
            &reason))
    {
        ++m_nativeFinalStreamGuards;
        m_lastNativeFinalStreamEvent =
            "final_stream preflight_failed sink=" + PointerHex(sink) +
            " bytes=" + PointerHex(bytes) +
            " count=" + std::to_string(byteCount) +
            " guard=" + StatusToken(reason);
        return;
    }

    struct ChecksumContext
    {
        uint32_t checksum = kFnv1aOffsetBasis;
        const uint8_t* bytes = nullptr;
        uint32_t byteCount = 0;
    } context { m_nativeFinalStreamChecksum, reinterpret_cast<const uint8_t*>(bytes), byteCount };

    const bool hashed = CoopRuntimeGuards::TryRunGuardedCallback(
        "native final stream checksum",
        [](void* rawContext) -> bool
        {
            auto* ctx = static_cast<ChecksumContext*>(rawContext);
            ctx->checksum = UpdateFnv1a(ctx->checksum, ctx->bytes, ctx->byteCount);
            return true;
        },
        &context,
        &reason);
    if (!hashed)
    {
        ++m_nativeFinalStreamGuards;
        m_lastNativeFinalStreamEvent =
            "final_stream checksum_failed sink=" + PointerHex(sink) +
            " bytes=" + PointerHex(bytes) +
            " count=" + std::to_string(byteCount) +
            " guard=" + StatusToken(reason);
        return;
    }

    m_nativeFinalStreamChecksum = context.checksum;
    ++m_nativeFinalStreamCapturedChunks;
    if (UINT32_MAX - m_nativeFinalStreamCapturedBytes < byteCount)
        m_nativeFinalStreamCapturedBytes = UINT32_MAX;
    else
        m_nativeFinalStreamCapturedBytes += byteCount;

    if (NativeFinalStreamByteCaptureEnabled())
    {
        const uint32_t maxCaptureBytes = GetEnvUIntClamped(
            "COOP_NATIVE_FINAL_STREAM_CAPTURE_MAX_BYTES",
            8u * 1024u * 1024u,
            0x1000u,
            128u * 1024u * 1024u);
        const size_t currentSize = m_nativeFinalStreamBuffer.size();
        const size_t remaining = currentSize < maxCaptureBytes ? static_cast<size_t>(maxCaptureBytes) - currentSize : 0;
        const size_t copyBytes = std::min<size_t>(remaining, byteCount);
        if (copyBytes != 0)
        {
            const auto* chunkBytes = reinterpret_cast<const uint8_t*>(bytes);
            m_nativeFinalStreamBuffer.insert(m_nativeFinalStreamBuffer.end(), chunkBytes, chunkBytes + copyBytes);
            m_nativeFinalStreamBufferedBytes = static_cast<uint32_t>(m_nativeFinalStreamBuffer.size());
        }

        if (copyBytes < byteCount)
        {
            const uint32_t dropped = static_cast<uint32_t>(byteCount - copyBytes);
            if (UINT32_MAX - m_nativeFinalStreamDroppedBytes < dropped)
                m_nativeFinalStreamDroppedBytes = UINT32_MAX;
            else
                m_nativeFinalStreamDroppedBytes += dropped;
        }
    }

    m_lastNativeFinalStreamEvent =
        "final_stream chunk sink=" + PointerHex(sink) +
        " bytes=" + PointerHex(bytes) +
        " count=" + std::to_string(byteCount) +
        " chunks=" + std::to_string(m_nativeFinalStreamCapturedChunks) +
        " total=" + std::to_string(m_nativeFinalStreamCapturedBytes) +
        " buffered=" + std::to_string(m_nativeFinalStreamBufferedBytes) +
        " dropped=" + std::to_string(m_nativeFinalStreamDroppedBytes) +
        " checksum=" + Hex32(m_nativeFinalStreamChecksum);
}

void ModMain::OnSaveStoreFinalizeDetachedWriteNode(void* writeNode, bool beforeOriginal)
{
    ++m_nativeWriteNodeOracleCalls;

    const bool trace =
        m_nativeSideBlobCapture.active ||
        m_nativeSideBlobCapture.sawPlayerWrite ||
        m_nativeSideBlobCapture.sawInventoryWrite ||
        m_nativeSideBlobCapture.sawItemWrite ||
        EnvFlagEnabled("COOP_TRACE_NATIVE_WRITE_NODE_ORACLE") ||
        EnvFlagEnabled("COOP_TRACE_NATIVE_FINAL_STREAM") ||
        EnvFlagEnabled("COOP_NATIVE_FRAGMENT_APPLY_FULL_TRANSPLANT");
    if (!trace)
        return;

    if (!writeNode)
    {
        ++m_nativeWriteNodeOracleGuards;
        m_lastNativeWriteNodeOracleEvent =
            std::string("write_node_oracle ") + (beforeOriginal ? "before" : "after") + " null";
        return;
    }

    std::string reason;
    if (!PreflightRuntimePointer(
            "native write node oracle node",
            writeNode,
            0x80,
            RuntimeAccess::Read,
            &reason))
    {
        ++m_nativeWriteNodeOracleGuards;
        m_lastNativeWriteNodeOracleEvent =
            std::string("write_node_oracle ") + (beforeOriginal ? "before" : "after") +
            " preflight_failed node=" + PointerHex(writeNode) +
            " guard=" + StatusToken(reason);
        return;
    }

    struct WriteNodeView
    {
        std::uintptr_t store = 0;
        uint32_t nodeIndex = 0;
        int32_t finalizeState = 0;
        uint32_t nameToken = 0;
        uint32_t childCount = 0;
        std::uintptr_t attrBegin = 0;
        std::uintptr_t attrEnd = 0;
        std::uintptr_t childBegin = 0;
        std::uintptr_t childEnd = 0;
        uint8_t valid = 0;
        uint32_t storeFinalizeCursor = 0;
    } view;

    struct ReadContext
    {
        const uint8_t* node = nullptr;
        WriteNodeView* view = nullptr;
    } context { reinterpret_cast<const uint8_t*>(writeNode), &view };

    const bool readOk = CoopRuntimeGuards::TryRunGuardedCallback(
        "native write node oracle read",
        [](void* rawContext) -> bool
        {
            auto* ctx = static_cast<ReadContext*>(rawContext);
            auto readU32 = [&](size_t offset) -> uint32_t
            {
                uint32_t value = 0;
                std::memcpy(&value, ctx->node + offset, sizeof(value));
                return value;
            };
            auto readI32 = [&](size_t offset) -> int32_t
            {
                int32_t value = 0;
                std::memcpy(&value, ctx->node + offset, sizeof(value));
                return value;
            };
            auto readPtr = [&](size_t offset) -> std::uintptr_t
            {
                std::uintptr_t value = 0;
                std::memcpy(&value, ctx->node + offset, sizeof(value));
                return value;
            };

            ctx->view->store = readPtr(0x10);
            ctx->view->nodeIndex = readU32(0x18);
            ctx->view->finalizeState = readI32(0x1c);
            ctx->view->nameToken = readU32(0x20);
            ctx->view->valid = *(ctx->node + 0x41);
            ctx->view->childCount = readU32(0x44);
            ctx->view->attrBegin = readPtr(0x50);
            ctx->view->attrEnd = readPtr(0x58);
            ctx->view->childBegin = readPtr(0x68);
            ctx->view->childEnd = readPtr(0x70);
            if (ctx->view->store != 0)
                std::memcpy(&ctx->view->storeFinalizeCursor, reinterpret_cast<const void*>(ctx->view->store + 0x400), sizeof(ctx->view->storeFinalizeCursor));
            return true;
        },
        &context,
        &reason);
    if (!readOk)
    {
        ++m_nativeWriteNodeOracleGuards;
        m_lastNativeWriteNodeOracleEvent =
            std::string("write_node_oracle ") + (beforeOriginal ? "before" : "after") +
            " read_failed node=" + PointerHex(writeNode) +
            " guard=" + StatusToken(reason);
        return;
    }

    const uint32_t attrRecords =
        view.attrEnd >= view.attrBegin && view.attrBegin != 0 && ((view.attrEnd - view.attrBegin) % 0x28u) == 0
            ? static_cast<uint32_t>((view.attrEnd - view.attrBegin) / 0x28u)
            : 0;
    const uint32_t childRecords =
        view.childEnd >= view.childBegin && view.childBegin != 0 && ((view.childEnd - view.childBegin) % sizeof(uint32_t)) == 0
            ? static_cast<uint32_t>((view.childEnd - view.childBegin) / sizeof(uint32_t))
            : 0;
    const int32_t finalReadNodeIndex =
        beforeOriginal && view.storeFinalizeCursor != 0
            ? static_cast<int32_t>(view.storeFinalizeCursor) - 1
            : static_cast<int32_t>(view.storeFinalizeCursor) - 2;

    ++m_nativeWriteNodeOracleTraces;
    m_nativeWriteNodeOracleAttrRecords += attrRecords;
    m_nativeWriteNodeOracleChildRecords += childRecords;

    if (!beforeOriginal &&
        view.store != 0 &&
        view.nodeIndex != UINT32_MAX &&
        finalReadNodeIndex >= 0 &&
        (m_nativeSideBlobCapture.active ||
            m_nativeSideBlobCapture.sawPlayerWrite ||
            m_nativeSideBlobCapture.sawInventoryWrite ||
            m_nativeSideBlobCapture.sawItemWrite))
    {
        const uint32_t maxOracleRecords = GetEnvUIntClamped(
            "COOP_NATIVE_WRITE_NODE_ORACLE_MAX_RECORDS",
            500000u,
            1024u,
            2000000u);
        if (m_nativeWriteNodeOracleRecords.size() < maxOracleRecords)
        {
            CoopNativeFragmentPayload::PayloadWriteNodeOracleInputRecord record;
            record.store = view.store;
            record.writeIndex = view.nodeIndex;
            record.finalIndex = static_cast<uint32_t>(finalReadNodeIndex);
            record.nameToken = view.nameToken;
            record.attrRecords = attrRecords;
            record.childRecords = childRecords;
            record.childCount = view.childCount;
            record.flags =
                (view.valid ? 0x1u : 0u) |
                (view.finalizeState != 0 ? 0x2u : 0u);
            m_nativeWriteNodeOracleRecords.push_back(record);
            m_nativeWriteNodeOracleStored = static_cast<uint32_t>(m_nativeWriteNodeOracleRecords.size());
        }
        else if (m_nativeWriteNodeOracleDropped != UINT32_MAX)
        {
            ++m_nativeWriteNodeOracleDropped;
        }
    }

    m_lastNativeWriteNodeOracleEvent =
        std::string("write_node_oracle ") + (beforeOriginal ? "before" : "after") +
        " node=" + PointerHex(writeNode) +
        " store=" + Hex64(static_cast<uint64_t>(view.store)) +
        " writeIndex=" + std::to_string(view.nodeIndex) +
        " finalIndex=" + std::to_string(finalReadNodeIndex) +
        " nameToken=" + std::to_string(view.nameToken) +
        " attrs=" + std::to_string(attrRecords) +
        " children=" + std::to_string(childRecords) +
        " childCount=" + std::to_string(view.childCount) +
        " state=" + std::to_string(view.finalizeState) +
        " valid=" + std::to_string(view.valid ? 1 : 0) +
        " capture=" +
            std::to_string((m_nativeSideBlobCapture.active || m_nativeSideBlobCapture.sawInventoryWrite || m_nativeSideBlobCapture.sawItemWrite) ? 1 : 0) +
        " stored=" + std::to_string(m_nativeWriteNodeOracleStored) +
        " dropped=" + std::to_string(m_nativeWriteNodeOracleDropped);

    if (EnvFlagEnabled("COOP_TRACE_NATIVE_WRITE_NODE_ORACLE") &&
        (m_nativeWriteNodeOracleTraces <= 64 || (m_nativeWriteNodeOracleTraces % 256) == 0))
    {
        LogCoop(m_lastNativeWriteNodeOracleEvent);
    }
}

void ModMain::OnSaveStoreLoadStoreInitFromFile(void* loadStore, const char* fileName, bool result)
{
    ++m_nativeLoadStoreInitCalls;

    const std::string safeFile = ReadRuntimeCString(fileName, 260);
    const bool trace =
        EnvFlagEnabled("COOP_TRACE_NATIVE_LOAD_STORE") ||
        EnvFlagEnabled("COOP_TRACE_NATIVE_LOAD_STORE_FULL_STORE") ||
        EnvFlagEnabled("COOP_TRACE_NATIVE_FINAL_STORE_OBJECT") ||
        EnvFlagEnabled("COOP_SAVE_ATLAS");

    if (!trace)
    {
        m_lastNativeLoadStoreInitEvent =
            "load_store_init observed result=" + std::to_string(result ? 1 : 0) +
            " file=" + StatusToken(safeFile);
        return;
    }

    if (!loadStore)
    {
        ++m_nativeLoadStoreInitGuards;
        m_lastNativeLoadStoreInitEvent =
            "load_store_init null result=" + std::to_string(result ? 1 : 0) +
            " file=" + StatusToken(safeFile);
        LogCoop(m_lastNativeLoadStoreInitEvent);
        return;
    }

    std::string guardReason;
    if (!PreflightRuntimePointer(
            "native load store init object",
            loadStore,
            0x180,
            RuntimeAccess::Read,
            &guardReason))
    {
        ++m_nativeLoadStoreInitGuards;
        m_lastNativeLoadStoreInitEvent =
            "load_store_init object unreadable guard=" + StatusToken(guardReason) +
            " result=" + std::to_string(result ? 1 : 0) +
            " store=" + PointerHex(loadStore) +
            " file=" + StatusToken(safeFile);
        LogCoop(m_lastNativeLoadStoreInitEvent);
        return;
    }

    std::array<std::uintptr_t, 3> rootEntry = {};
    const bool copied = TryGuardedVoidCall(
        "native load store init copy root",
        [&]()
        {
            s_funcSaveStoreCopyRootReadStackEntry(loadStore, rootEntry.data());
        },
        &guardReason);
    if (!copied)
    {
        ++m_nativeLoadStoreInitGuards;
        m_lastNativeLoadStoreInitEvent =
            "load_store_init copy_root_failed guard=" + StatusToken(guardReason) +
            " result=" + std::to_string(result ? 1 : 0) +
            " store=" + PointerHex(loadStore) +
            " file=" + StatusToken(safeFile);
        LogCoop(m_lastNativeLoadStoreInitEvent);
        return;
    }

    void* resolvedNode = nullptr;
    const bool resolved = TryGuardedCall(
        "native load store init root node",
        [&]() -> void*
        {
            return s_funcSaveStoreCurrentStackEntryToNode(rootEntry.data());
        },
        resolvedNode,
        &guardReason);

    CoopSaveStoreDecoder::DecodeOptions options = CoopSaveStoreDecoder::OptionsFromEnvironment();
    options.fullStoreMap = options.fullStoreMap || EnvFlagEnabled("COOP_TRACE_NATIVE_LOAD_STORE_FULL_STORE");
    CoopSaveStoreDecoder::DecodeResult decoded;
    if (resolved)
        decoded = CoopSaveStoreDecoder::DecodeReadStackEntry(rootEntry.data(), resolvedNode, options);
    else
        ++m_nativeLoadStoreInitGuards;

    uint32_t releaseGuards = 0;
    std::string releaseReason;
    const bool released = TryGuardedVoidCall(
        "native load store init release root",
        [&]()
        {
            s_funcSaveStoreReleaseStackEntry(rootEntry.data());
        },
        &releaseReason);
    if (!released)
    {
        ++releaseGuards;
        ++m_nativeLoadStoreInitGuards;
    }

    if (resolved && decoded.storeMap.ok)
    {
        ++m_nativeLoadStoreInitTraces;
        m_lastSaveStoreMapEvent = CoopSaveStoreDecoder::BuildStoreMapStatus(decoded.storeMap);
        if (decoded.storeMap.readStore)
        {
            const CoopNativeSaveStoreApi::CheckResult apiCheck =
                CoopNativeSaveStoreApi::CheckReadNodeByIndex(decoded.storeMap);
            ++m_nativeSaveStoreApiChecks;
            if (apiCheck.ok)
                ++m_nativeSaveStoreApiCheckSuccesses;
            else
                ++m_nativeSaveStoreApiCheckFailures;
            m_lastNativeSaveStoreApiEvent = CoopNativeSaveStoreApi::BuildCheckStatus(apiCheck);

            if (EnvFlagEnabled("COOP_NATIVE_READ_STORE_GRAPH_PROBE"))
            {
                ProbeNativeReadStoreGraphSource(
                    decoded.storeMap,
                    safeFile.c_str(),
                    "load_store_init");
            }
        }
    }
    else if (resolved)
    {
        ++m_nativeLoadStoreInitGuards;
    }

    m_lastNativeLoadStoreInitEvent =
        "load_store_init result=" + std::to_string(result ? 1 : 0) +
        " file=" + StatusToken(safeFile) +
        " store=" + PointerHex(loadStore) +
        " resolved=" + std::to_string(resolved ? 1 : 0) +
        " node=" + PointerHex(resolvedNode) +
        " decoded=" + std::to_string(decoded.storeMap.ok ? 1 : 0) +
        " read=" + std::to_string(decoded.storeMap.readStore ? 1 : 0) +
        " nodes=" + std::to_string(decoded.storeMap.nodeCount) +
        " rootIdx=" + std::to_string(decoded.nodeIndex) +
        " rootId=" + std::to_string(decoded.nodeId) +
        " guards=" + std::to_string(decoded.guards + releaseGuards) +
        " detail=" + StatusToken(
            resolved
                ? decoded.detail
                : std::string("resolve_failed_") + guardReason);
    if (!releaseReason.empty())
        m_lastNativeLoadStoreInitEvent += "_release=" + StatusToken(releaseReason);
    LogCoop(m_lastNativeLoadStoreInitEvent);
}

bool ModMain::ProbeScratchNativeLoadStoreFromSave(const std::string& savePathOrName, const char* reason)
{
    ++m_nativeScratchLoadStoreProbes;

    std::string resolvedPath;
    if (!ResolveReadableSaveFile(savePathOrName, resolvedPath))
    {
        ++m_nativeScratchLoadStoreGuards;
        m_lastNativeScratchLoadStoreEvent =
            "scratch_load_store failed resolve save=" + StatusToken(savePathOrName) +
            " reason=" + StatusToken(reason ? std::string(reason) : std::string("-"));
        LogCoop(m_lastNativeScratchLoadStoreEvent);
        return false;
    }

    // Probe-only. This intentionally avoids the active LoadGame object and lets
    // Vanilla convert a save file into a read-store graph in isolated storage.
    //
    // The read-store is not a zero-initializable POD. The native ActiveILoadGame
    // constructor builds an owner object at +0x30, constructs the LoadStore at
    // +0x38 with that owner, then initializes the root stack entry at +0x178.
    // Reuse that exact low-level sequence instead of calling LoadStoreInit on
    // blank memory.
    alignas(16) std::array<uint8_t, 0x190> scratchActiveLoad = {};
    void* const scratchBase = scratchActiveLoad.data();
    void* const scratchOwnerSlot = scratchActiveLoad.data() + 0x30;
    void* const scratchLoadStore = scratchActiveLoad.data() + 0x38;
    void* const scratchRootEntry = scratchActiveLoad.data() + 0x178;

    std::string guardReason;
    bool constructed = false;
    bool baseConstructed = false;
    bool ownerConstructed = false;
    bool loadStoreConstructed = false;
    bool rootEntryConstructed = false;

    const auto cleanupScratch = [&]()
    {
        std::string cleanupReason;
        if (loadStoreConstructed)
        {
            TryGuardedVoidCall(
                "scratch native load store destroy",
                [&]()
                {
                    s_funcSaveStoreLoadStoreDestroy(scratchLoadStore);
                },
                &cleanupReason);
        }

        void* owner = nullptr;
        std::memcpy(&owner, scratchOwnerSlot, sizeof(owner));
        if (owner)
        {
            TryGuardedVoidCall(
                "scratch native load store owner release",
                [owner]()
                {
                    void* vtable = nullptr;
                    std::memcpy(&vtable, owner, sizeof(vtable));
                    if (!vtable)
                        return;
                    void* releaseFunc = nullptr;
                    std::memcpy(&releaseFunc, static_cast<uint8_t*>(vtable) + 0x10, sizeof(releaseFunc));
                    if (!releaseFunc)
                        return;
                    using ReleaseFunc = void (*)(void*);
                    reinterpret_cast<ReleaseFunc>(releaseFunc)(owner);
                },
                &cleanupReason);
        }

        if (baseConstructed)
        {
            TryGuardedVoidCall(
                "scratch native active load base destroy",
                [&]()
                {
                    s_funcActiveLoadBaseDestroy(scratchBase);
                },
                &cleanupReason);
        }
    };

    const bool constructedOk = TryGuardedVoidCall(
        "scratch native load store construct",
        [&]()
        {
            s_funcActiveLoadBaseConstruct(scratchBase);
            baseConstructed = true;
            s_funcSaveStoreOwnerConstruct(scratchOwnerSlot);
            ownerConstructed = true;

            void* owner = nullptr;
            std::memcpy(&owner, scratchOwnerSlot, sizeof(owner));
            s_funcSaveStoreLoadStoreConstruct(scratchLoadStore, owner);
            loadStoreConstructed = true;
            s_funcSaveStoreInitRootReadStackEntry(scratchLoadStore, scratchRootEntry);
            rootEntryConstructed = true;
            constructed = true;
        },
        &guardReason);
    if (!constructedOk || !constructed)
    {
        ++m_nativeScratchLoadStoreGuards;
        cleanupScratch();
        m_lastNativeScratchLoadStoreEvent =
            "scratch_load_store failed construct save=" + StatusToken(resolvedPath) +
            " constructed=" + std::to_string(constructed ? 1 : 0) +
            " base=" + std::to_string(baseConstructed ? 1 : 0) +
            " owner=" + std::to_string(ownerConstructed ? 1 : 0) +
            " loadStore=" + std::to_string(loadStoreConstructed ? 1 : 0) +
            " rootEntry=" + std::to_string(rootEntryConstructed ? 1 : 0) +
            " guard=" + StatusToken(guardReason);
        LogCoop(m_lastNativeScratchLoadStoreEvent);
        return false;
    }

    bool loadOk = false;
    const bool callOk = TryGuardedCall(
        "scratch native load store init",
        [&]() -> bool
        {
            return s_hookSaveStoreLoadStoreInitFromFile.InvokeOrig(
                scratchLoadStore,
                resolvedPath.c_str());
        },
        loadOk,
        &guardReason);
    if (!callOk || !loadOk)
    {
        ++m_nativeScratchLoadStoreGuards;
        cleanupScratch();
        m_lastNativeScratchLoadStoreEvent =
            "scratch_load_store failed init save=" + StatusToken(resolvedPath) +
            " call=" + std::to_string(callOk ? 1 : 0) +
            " result=" + std::to_string(loadOk ? 1 : 0) +
            " constructed=1" +
            " guard=" + StatusToken(guardReason);
        LogCoop(m_lastNativeScratchLoadStoreEvent);
        return false;
    }

    std::array<std::uintptr_t, 3> rootEntry = {};
    const bool copied = TryGuardedVoidCall(
        "scratch native load store copy root",
        [&]()
        {
            s_funcSaveStoreCopyRootReadStackEntry(scratchLoadStore, rootEntry.data());
        },
        &guardReason);
    if (!copied)
    {
        ++m_nativeScratchLoadStoreGuards;
        cleanupScratch();
        m_lastNativeScratchLoadStoreEvent =
            "scratch_load_store failed copy_root save=" + StatusToken(resolvedPath) +
            " guard=" + StatusToken(guardReason);
        LogCoop(m_lastNativeScratchLoadStoreEvent);
        return false;
    }

    void* rootNode = nullptr;
    const bool resolved = TryGuardedCall(
        "scratch native load store root node",
        [&]() -> void*
        {
            return s_funcSaveStoreCurrentStackEntryToNode(rootEntry.data());
        },
        rootNode,
        &guardReason);

    CoopSaveStoreDecoder::DecodeOptions options = CoopSaveStoreDecoder::OptionsFromEnvironment();
    options.fullStoreMap = options.fullStoreMap || EnvFlagEnabled("COOP_TRACE_NATIVE_LOAD_STORE_FULL_STORE");
    CoopSaveStoreDecoder::DecodeResult decoded;
    if (resolved)
        decoded = CoopSaveStoreDecoder::DecodeReadStackEntry(rootEntry.data(), rootNode, options);

    std::string releaseReason;
    const bool released = TryGuardedVoidCall(
        "scratch native load store release root",
        [&]()
        {
            s_funcSaveStoreReleaseStackEntry(rootEntry.data());
        },
        &releaseReason);

    if (!resolved || !decoded.storeMap.ok)
    {
        ++m_nativeScratchLoadStoreGuards;
        cleanupScratch();
        m_lastNativeScratchLoadStoreEvent =
            "scratch_load_store failed decode save=" + StatusToken(resolvedPath) +
            " resolved=" + std::to_string(resolved ? 1 : 0) +
            " released=" + std::to_string(released ? 1 : 0) +
            " guard=" + StatusToken(guardReason) +
            " detail=" + StatusToken(decoded.detail);
        LogCoop(m_lastNativeScratchLoadStoreEvent);
        return false;
    }

    CoopNativeSaveStoreApi::CheckResult apiCheck;
    if (decoded.storeMap.readStore)
    {
        apiCheck = CoopNativeSaveStoreApi::CheckReadNodeByIndex(decoded.storeMap);
        ++m_nativeSaveStoreApiChecks;
        if (apiCheck.ok)
            ++m_nativeSaveStoreApiCheckSuccesses;
        else
            ++m_nativeSaveStoreApiCheckFailures;
        m_lastNativeSaveStoreApiEvent = CoopNativeSaveStoreApi::BuildCheckStatus(apiCheck);

        if (EnvFlagEnabled("COOP_NATIVE_SCRATCH_READ_STORE_GRAPH_PROBE"))
        {
            ProbeNativeReadStoreGraphSource(
                decoded.storeMap,
                resolvedPath.c_str(),
                "scratch_load_store",
                EnvFlagEnabled("COOP_NATIVE_SCRATCH_READ_STORE_GRAPH_DEEP_MATERIALIZE"),
                EnvFlagEnabled("COOP_NATIVE_SCRATCH_READ_STORE_GRAPH_START_GAMESTATE"));
        }

        if (EnvFlagEnabled("COOP_NATIVE_SCRATCH_CAPTURE_READ_FRAGMENT") ||
            EnvFlagEnabled("COOP_NATIVE_PRELOAD_CAPTURE_TARGET") ||
            EnvFlagEnabled("COOP_NATIVE_PRELOAD_VERIFY_MERGED_PACKAGE"))
        {
            CaptureNativeReadStoreFragmentFromStoreMap(
                decoded.storeMap,
                resolvedPath.c_str(),
                "scratch_load_store");
        }
    }

    ++m_nativeScratchLoadStoreSuccesses;
    cleanupScratch();
    m_lastSaveStoreMapEvent = CoopSaveStoreDecoder::BuildStoreMapStatus(decoded.storeMap);
    m_lastNativeScratchLoadStoreEvent =
        "scratch_load_store ok save=" + StatusToken(resolvedPath) +
        " reason=" + StatusToken(reason ? std::string(reason) : std::string("-")) +
        " constructed=1" +
        " read=" + std::to_string(decoded.storeMap.readStore ? 1 : 0) +
        " nodes=" + std::to_string(decoded.storeMap.nodeCount) +
        " rootIdx=" + std::to_string(decoded.nodeIndex) +
        " rootId=" + std::to_string(decoded.nodeId) +
        " gameState=" + std::to_string(apiCheck.gameStateSectionFound ? 1 : 0) +
        " gameStateIdx=" + std::to_string(apiCheck.gameStateSectionNodeIndex) +
        " guards=" + std::to_string(decoded.guards + (released ? 0u : 1u)) +
        (releaseReason.empty() ? std::string() : " release=" + StatusToken(releaseReason));
    LogCoop(m_lastNativeScratchLoadStoreEvent);
    return true;
}

bool ModMain::CaptureNativeReadStoreFragmentFromStoreMap(
    const CoopSaveStoreDecoder::StoreMap& storeMap,
    const char* fileName,
    const char* reason)
{
    ++m_nativeReadStoreFragmentProbes;

    const CoopNativeSaveStoreApi::StoreHandle store =
        CoopNativeSaveStoreApi::MakeReadStoreHandle(storeMap);
    if (!store.valid)
    {
        ++m_nativeReadStoreFragmentFailures;
        m_lastNativeReadStoreFragmentEvent =
            "read_fragment failed invalid_store file=" +
            StatusToken(fileName ? std::string(fileName) : std::string("-"));
        LogCoop("native read fragment " + m_lastNativeReadStoreFragmentEvent);
        return false;
    }

    std::vector<unsigned> sourceIdOrder;
    sourceIdOrder.reserve(m_gameStateLocalPlayerInventoryItemIndexById.size());
    auto appendUniqueSourceId = [&sourceIdOrder](unsigned entityId)
    {
        if (entityId == 0)
            return;

        if (std::find(sourceIdOrder.begin(), sourceIdOrder.end(), entityId) == sourceIdOrder.end())
            sourceIdOrder.push_back(entityId);
    };

    if (m_nativeTargetFragmentCapture.IsActive() &&
        EnvFlagEnabled("COOP_NATIVE_TARGET_READ_FRAGMENT_AUGMENT"))
    {
        const CoopNativeGameStateFragmentLocator::NativeInventoryFragmentBundle targetBundle =
            m_nativeTargetFragmentCapture.BuildBundle();
        for (unsigned entityId : targetBundle.inventoryEntityIds)
            appendUniqueSourceId(entityId);
    }

    uint32_t payloadSourceIds = 0;
    if (m_pendingNativePlayerStateOverrideValid &&
        m_pendingNativePlayerStateOverride.hasNativeCapture &&
        m_pendingNativePlayerStateOverride.nativeCapture.hasNativeFragmentPayload)
    {
        payloadSourceIds += AppendNativeFragmentPayloadItemIds(
            m_pendingNativePlayerStateOverride.nativeCapture.nativeFragmentPayload,
            sourceIdOrder);
    }
    payloadSourceIds += AppendNativeFragmentPayloadItemIds(
        m_lastNativeFragmentImportPayload,
        sourceIdOrder);

    if (!m_gameStateLocalPlayerInventoryItemIndexById.empty())
    {
        std::vector<std::pair<unsigned, size_t>> orderedIds;
        orderedIds.reserve(m_gameStateLocalPlayerInventoryItemIndexById.size());
        for (const auto& entry : m_gameStateLocalPlayerInventoryItemIndexById)
            orderedIds.emplace_back(entry.first, entry.second);
        std::sort(
            orderedIds.begin(),
            orderedIds.end(),
            [](const auto& lhs, const auto& rhs)
            {
                if (lhs.second != rhs.second)
                    return lhs.second < rhs.second;
                return lhs.first < rhs.first;
            });
        for (const auto& entry : orderedIds)
            appendUniqueSourceId(entry.first);
    }
    if (sourceIdOrder.empty())
    {
        for (const NativeCapturedItemState& item : m_nativeSideBlobCapture.items)
        {
            if (item.itemId != 0)
                appendUniqueSourceId(item.itemId);
        }
    }

    std::unordered_set<unsigned> sourceIds;
    sourceIds.reserve(sourceIdOrder.size());
    for (unsigned entityId : sourceIdOrder)
        sourceIds.insert(entityId);

    if (sourceIds.empty())
    {
        ++m_nativeReadStoreFragmentFailures;
        m_lastNativeReadStoreFragmentEvent =
            "read_fragment failed no_local_item_ids file=" +
            StatusToken(fileName ? std::string(fileName) : std::string("-")) +
            " reason=" + StatusToken(reason ? std::string(reason) : std::string("-"));
        LogCoop("native read fragment " + m_lastNativeReadStoreFragmentEvent);
        return false;
    }

    std::string guardReason;
    CoopNativeSaveStoreApi::NodeView rootNode;
    CoopNativeSaveStoreApi::NodeView nativeRootNode;
    nativeRootNode.nodePtr = storeMap.currentNode.nodePtr;
    nativeRootNode.nodeIndex = storeMap.currentNode.nodeIndex;
    nativeRootNode.nodeId = storeMap.currentNode.nodeId;
    nativeRootNode.childCursor = storeMap.currentNode.childCursor;
    nativeRootNode.childCount = storeMap.currentNode.childCount;
    nativeRootNode.attrCursor = storeMap.currentNode.attrCursor;
    nativeRootNode.attrCount = storeMap.currentNode.attrCount;
    nativeRootNode.childIndexBlockBegin = storeMap.currentNode.childIndexBlockBegin;
    nativeRootNode.childIndexBlockEnd = storeMap.currentNode.childIndexBlockEnd;
    nativeRootNode.valid = storeMap.currentNode.valid;

    bool startAtGameState = false;
    std::string startReason;
    if (CoopNativeSaveStoreApi::TryFindReadSection(store, "GameState", rootNode, &guardReason) &&
        rootNode.valid &&
        rootNode.nodePtr != 0)
    {
        startAtGameState = true;
        startReason = "find_section_ok";
    }
    else
    {
        startReason = guardReason.empty() ? "find_section_failed" : guardReason;
    }

    if (!startAtGameState)
    {
        std::vector<uint32_t> rootEntries;
        std::string scanReason;
        if (nativeRootNode.valid &&
            nativeRootNode.nodePtr != 0 &&
            CoopNativeSaveStoreApi::TryEnumerateChildEntryIndices(
                nativeRootNode,
                rootEntries,
                GetEnvUIntClamped("COOP_NATIVE_READ_FRAGMENT_ROOT_CHILDREN", 2048, 1, 16384),
                &scanReason))
        {
            for (uint32_t entryIndex : rootEntries)
            {
                CoopNativeSaveStoreApi::NodeView childNode;
                if (!CoopNativeSaveStoreApi::TryReadChildEntryByIndex(store, entryIndex, childNode, &scanReason) ||
                    !childNode.valid ||
                    childNode.nodePtr == 0)
                {
                    continue;
                }

                const char* childName = nullptr;
                if (!CoopNativeSaveStoreApi::TryResolveReadNodeName(childNode, childName, &scanReason) ||
                    !childName ||
                    !childName[0])
                {
                    continue;
                }

                const std::string childNameText = ReadRuntimeCString(childName, 160);
                if (childNameText != "GameState")
                    continue;

                rootNode = childNode;
                startAtGameState = true;
                startReason = "root_child_scan_ok_entry_" + std::to_string(entryIndex);
                break;
            }

            if (!startAtGameState)
                startReason += "_root_child_scan_missed";
        }
        else
        {
            startReason += "_root_child_scan_failed_" + (scanReason.empty() ? std::string("unknown") : scanReason);
        }
    }

    if (!startAtGameState &&
        nativeRootNode.valid &&
        nativeRootNode.nodePtr != 0 &&
        (EnvFlagEnabled("COOP_NATIVE_READ_FRAGMENT_ALLOW_CURRENT_ROOT") ||
            (m_nativeTargetFragmentCapture.IsActive() &&
                EnvFlagEnabled("COOP_NATIVE_TARGET_READ_FRAGMENT_AUGMENT"))))
    {
        rootNode = nativeRootNode;
        startAtGameState = true;
        startReason += "_current_read_store_root_fallback";
    }

    if (!startAtGameState)
    {
        ++m_nativeReadStoreFragmentFailures;
        m_lastNativeReadStoreFragmentEvent =
            "read_fragment failed missing_game_state file=" +
            StatusToken(fileName ? std::string(fileName) : std::string("-")) +
            " start=" + StatusToken(startReason);
        LogCoop("native read fragment " + m_lastNativeReadStoreFragmentEvent);
        return false;
    }

    auto makeNodeInfo = [&](const CoopNativeSaveStoreApi::NodeView& node, const std::string& path, bool inventoryNode, bool itemNode)
    {
        NativeDecodedStoreNodeInfo info;
        info.nodeIndex = node.nodeIndex;
        info.nodeId = node.nodeId;
        info.attrCursor = node.attrCursor;
        info.attrCount = node.attrCount;
        info.childCursor = node.childCursor;
        info.childCount = node.childCount;
        info.storePtr = storeMap.store;
        info.nodePtr = node.nodePtr;
        info.nodeBlockBegin = storeMap.nodeBlockBegin;
        info.nodeBlockEnd = storeMap.nodeBlockEnd;
        info.nodeCount = storeMap.nodeCount;
        info.childIndexBlockBegin = node.childIndexBlockBegin;
        info.childIndexBlockEnd = node.childIndexBlockEnd;
        info.attrStringBase = storeMap.attrStringBase;
        info.attrNameOffsetTable = storeMap.attrNameOffsetTable;
        info.attrTokenContext = storeMap.attrTokenContext;
        info.attrTokenIndexBase = storeMap.attrTokenIndexBase;
        info.attrTokenBase = storeMap.attrTokenBase;
        info.childNameDataBase = storeMap.childNameDataBase;
        info.childNameResolverContext = storeMap.childNameResolverContext;
        info.childNameOffsetTable = storeMap.childNameOffsetTable;
        info.readStore = true;
        info.nodeReadable = node.nodePtr != 0;
        info.nodeValid = node.valid;
        info.inventoryNode = inventoryNode;
        info.itemNode = itemNode;
        info.source = itemNode
            ? "CArkItem::FullSerialize(player-inventory-item/read-store)"
            : "ArkInventory::FullSerialize(local-player/read-store)";
        info.op = "read-store-fragment";
        info.path = path;
        return info;
    };

    auto readU32Attr = [&](const CoopNativeSaveStoreApi::NodeView& node, const char* name, uint32_t& outValue) -> bool
    {
        CoopNativeSaveStoreApi::ReadAttributeView attr;
        return CoopNativeSaveStoreApi::TryFindReadAttribute(store, node, name, attr, nullptr) &&
            CoopNativeSaveStoreApi::TryReadU32Attribute(attr, outValue, nullptr);
    };

    auto findReadAttrRecord = [&](
        const CoopNativeSaveStoreApi::NodeView& node,
        const char* name,
        CoopNativeSaveStoreApi::ReadAttributeRecord& outRecord) -> bool
    {
        if (!name || !name[0] || node.attrCount == 0)
            return false;

        std::vector<CoopNativeSaveStoreApi::ReadAttributeRecord> attributes;
        if (!CoopNativeSaveStoreApi::TryEnumerateReadAttributes(
                store,
                node,
                attributes,
                std::max<uint32_t>(node.attrCount, 1u),
                nullptr))
        {
            return false;
        }

        for (const CoopNativeSaveStoreApi::ReadAttributeRecord& attribute : attributes)
        {
            if (attribute.nameResolved && attribute.name == name)
            {
                outRecord = attribute;
                return true;
            }
        }

        return false;
    };

    auto readU32AttrLoose = [&](
        const CoopNativeSaveStoreApi::NodeView& node,
        const char* name,
        uint32_t& outValue) -> bool
    {
        outValue = 0;
        if (readU32Attr(node, name, outValue))
            return true;

        CoopNativeSaveStoreApi::ReadAttributeRecord record;
        if (!findReadAttrRecord(node, name, record))
            return false;

        if (record.nativeU32Readable)
        {
            outValue = record.nativeU32;
            return true;
        }

        if (!record.valueReadable || record.valueByteCount == 0 || record.valueByteCount > sizeof(uint32_t))
            return false;

        outValue = static_cast<uint32_t>(record.valueBits & 0xFFFFFFFFu);
        return true;
    };

    auto hasAttr = [&](const CoopNativeSaveStoreApi::NodeView& node, const char* name) -> bool
    {
        CoopNativeSaveStoreApi::ReadAttributeView attr;
        if (CoopNativeSaveStoreApi::TryFindReadAttribute(store, node, name, attr, nullptr))
            return true;

        CoopNativeSaveStoreApi::ReadAttributeRecord record;
        return findReadAttrRecord(node, name, record);
    };

    struct QueueItem
    {
        CoopNativeSaveStoreApi::NodeView node;
        std::string path;
        uint32_t depth = 0;
        unsigned ancestorEntityId = 0;
        unsigned activeItemEntityId = 0;
        uint32_t childEntryIndex = 0;
        bool materializeFromChildEntry = false;
    };

    struct ItemCandidate
    {
        CoopNativeSaveStoreApi::NodeView node;
        std::string path;
        unsigned entityId = 0;
    };

    CoopNativeGameStateFragmentLocator locator;
    locator.BeginRun(m_nextNativeFragmentRunId++, "read-store materialized source");
    locator.OnGameStateSerializer(nullptr, "GameState", true, eST_SaveGame);

    std::deque<QueueItem> queue;
    std::unordered_set<std::string> visited;
    queue.push_back({ rootNode, "GameState", 0, 0, 0 });
    visited.insert("GameState@" + std::to_string(rootNode.nodeIndex));

    const uint32_t maxNodes = GetEnvUIntClamped(
        "COOP_NATIVE_READ_FRAGMENT_MAX_NODES",
        8192,
        32,
        100000);
    const uint32_t maxDepth = GetEnvUIntClamped(
        "COOP_NATIVE_READ_FRAGMENT_MAX_DEPTH",
        18,
        1,
        96);
    const uint32_t maxChildrenPerNode = GetEnvUIntClamped(
        "COOP_NATIVE_READ_FRAGMENT_MAX_CHILDREN",
        2048,
        1,
        16384);

    uint32_t scanned = 0;
    uint32_t materialized = 0;
    uint32_t childEntries = 0;
    uint32_t guards = 0;
    uint32_t inventoryCells = 0;
    uint32_t inventoryCellsSkipped = 0;
    uint32_t itemCandidates = 0;
    uint32_t itemCandidatesMapped = 0;
    uint32_t itemCandidatesSkipped = 0;
    uint32_t flatScanned = 0;
    uint32_t flatCells = 0;
    uint32_t flatCellSkipped = 0;
    uint32_t flatItemCandidates = 0;
    uint32_t flatItemCandidatesMapped = 0;
    uint32_t flatItemCandidatesSkipped = 0;
    uint32_t flatItemObserved = 0;
    uint32_t flatGuards = 0;
    std::vector<ItemCandidate> unmappedCandidates;

    while (!queue.empty() && scanned < maxNodes)
    {
        QueueItem item = std::move(queue.front());
        queue.pop_front();

        if (item.materializeFromChildEntry)
        {
            if (!CoopNativeSaveStoreApi::TryReadChildEntryByIndex(store, item.childEntryIndex, item.node, &guardReason))
            {
                ++guards;
                continue;
            }
            ++materialized;
            if (!item.node.valid || item.node.nodePtr == 0)
                continue;
        }

        ++scanned;

        uint32_t nodeEntityId = 0;
        const bool hasEntityId = readU32AttrLoose(item.node, "entityId", nodeEntityId) && nodeEntityId != 0;
        const unsigned effectiveEntityId = hasEntityId
            ? static_cast<unsigned>(nodeEntityId)
            : item.ancestorEntityId;

        const bool storedItemsValuePath =
            item.path.find("Inventory/storedItems/i/v") != std::string::npos &&
            item.node.attrCount == 5;
        if (storedItemsValuePath)
        {
            uint32_t cellEntityId = 0;
            if (readU32AttrLoose(item.node, "entityId", cellEntityId) &&
                cellEntityId != 0 &&
                sourceIds.find(static_cast<unsigned>(cellEntityId)) != sourceIds.end())
            {
                locator.OnDecodedStoreNode(makeNodeInfo(item.node, "Inventory/storedItems/i/v", true, false));
                locator.OnInventoryCellEntityId(
                    static_cast<unsigned>(cellEntityId),
                    "ArkInventory::FullSerialize(local-player/read-store)",
                    "Inventory/storedItems/i/v/entityId");
                ++inventoryCells;
            }
            else
            {
                ++inventoryCellsSkipped;
            }
        }

        const bool itemCandidate =
            item.path.find("Inventory/storedItems") == std::string::npos &&
            hasAttr(item.node, "m_count") &&
            hasAttr(item.node, "selectedArchetype") &&
            hasAttr(item.node, "ownerId");
        unsigned nextActiveItemEntityId = item.activeItemEntityId;
        if (itemCandidate)
        {
            ++itemCandidates;
            if (effectiveEntityId != 0 && sourceIds.find(effectiveEntityId) != sourceIds.end())
            {
                locator.OnReadStoreItemNodeForEntity(
                    effectiveEntityId,
                    makeNodeInfo(item.node, item.path, false, true));
                nextActiveItemEntityId = effectiveEntityId;
                ++itemCandidatesMapped;
            }
            else
            {
                ++itemCandidatesSkipped;
                if (unmappedCandidates.size() < sourceIdOrder.size() + 16)
                    unmappedCandidates.push_back({ item.node, item.path, effectiveEntityId });
            }
        }
        else if (item.activeItemEntityId != 0)
        {
            locator.OnReadStoreItemObservedNodeForEntity(
                item.activeItemEntityId,
                makeNodeInfo(item.node, item.path, false, true));
        }

        if (item.depth >= maxDepth || item.node.childCount == 0)
            continue;

        std::vector<uint32_t> entries;
        if (!CoopNativeSaveStoreApi::TryEnumerateChildEntryIndices(
                item.node,
                entries,
                maxChildrenPerNode,
                &guardReason))
        {
            ++guards;
            continue;
        }
        childEntries += static_cast<uint32_t>(entries.size());

        for (uint32_t entryIndex : entries)
        {
            if (queue.size() + scanned >= maxNodes)
                break;

            CoopNativeSaveStoreApi::NodeView childNode;
            if (!CoopNativeSaveStoreApi::TryReadChildEntryByIndex(store, entryIndex, childNode, &guardReason))
            {
                ++guards;
                continue;
            }
            ++materialized;

            if (!childNode.valid || childNode.nodePtr == 0)
                continue;

            const char* childName = nullptr;
            std::string childNameText;
            if (CoopNativeSaveStoreApi::TryResolveReadNodeName(childNode, childName, nullptr) && childName && childName[0])
                childNameText = ReadRuntimeCString(childName, 160);
            if (childNameText.empty())
                childNameText = "#" + std::to_string(entryIndex);

            const std::string childPath = item.path + "/" + childNameText;
            const std::string visitKey = childPath + "#entry_" + std::to_string(entryIndex);
            if (visited.find(visitKey) != visited.end())
                continue;
            visited.insert(visitKey);

            queue.push_back({
                {},
                childPath,
                item.depth + 1,
                effectiveEntityId,
                nextActiveItemEntityId,
                entryIndex,
                true,
            });
        }
    }

    const bool flatScanEnabled = !EnvFlagEnabled("COOP_NATIVE_READ_FRAGMENT_DISABLE_FLAT_SCAN");
    if (flatScanEnabled)
    {
        const uint32_t flatMaxNodes = std::min<uint32_t>(
            store.nodeCount,
            GetEnvUIntClamped("COOP_NATIVE_READ_FRAGMENT_FLAT_MAX_NODES", 65536, 64, 250000));
        const uint32_t flatMaxItemDepth = GetEnvUIntClamped(
            "COOP_NATIVE_READ_FRAGMENT_FLAT_ITEM_DEPTH",
            10,
            1,
            32);
        const uint32_t flatMaxChildren = GetEnvUIntClamped(
            "COOP_NATIVE_READ_FRAGMENT_FLAT_MAX_CHILDREN",
            2048,
            1,
            16384);

        auto observeFlatItemSubtree = [&](
            unsigned entityId,
            const CoopNativeSaveStoreApi::NodeView& root,
            const std::string& rootPath)
        {
            struct FlatItemQueueItem
            {
                CoopNativeSaveStoreApi::NodeView node;
                std::string path;
                uint32_t depth = 0;
                uint32_t childEntryIndex = 0;
                bool materializeFromChildEntry = false;
            };

            std::deque<FlatItemQueueItem> itemQueue;
            std::unordered_set<std::string> itemVisited;
            itemQueue.push_back({ root, rootPath, 0 });
            itemVisited.insert("root_" + std::to_string(root.nodeIndex));

            while (!itemQueue.empty())
            {
                FlatItemQueueItem current = std::move(itemQueue.front());
                itemQueue.pop_front();

                if (current.materializeFromChildEntry)
                {
                    std::string itemGuardReason;
                    if (!CoopNativeSaveStoreApi::TryReadChildEntryByIndex(store, current.childEntryIndex, current.node, &itemGuardReason))
                    {
                        ++flatGuards;
                        continue;
                    }
                    if (!current.node.valid || current.node.nodePtr == 0)
                        continue;
                }

                if (current.depth != 0)
                {
                    locator.OnReadStoreItemObservedNodeForEntity(
                        entityId,
                        makeNodeInfo(current.node, current.path, false, true));
                    ++flatItemObserved;
                }

                if (current.depth >= flatMaxItemDepth || current.node.childCount == 0)
                    continue;

                std::vector<uint32_t> entries;
                std::string itemGuardReason;
                if (!CoopNativeSaveStoreApi::TryEnumerateChildEntryIndices(
                        current.node,
                        entries,
                        flatMaxChildren,
                        &itemGuardReason))
                {
                    ++flatGuards;
                    continue;
                }

                for (uint32_t entryIndex : entries)
                {
                    CoopNativeSaveStoreApi::NodeView childNode;
                    if (!CoopNativeSaveStoreApi::TryReadChildEntryByIndex(store, entryIndex, childNode, &itemGuardReason))
                    {
                        ++flatGuards;
                        continue;
                    }
                    if (!childNode.valid || childNode.nodePtr == 0)
                        continue;
                    const std::string visitKey =
                        current.path + "/" + std::to_string(entryIndex);
                    if (itemVisited.find(visitKey) != itemVisited.end())
                        continue;
                    itemVisited.insert(visitKey);

                    const char* childName = nullptr;
                    std::string childNameText;
                    if (CoopNativeSaveStoreApi::TryResolveReadNodeName(childNode, childName, nullptr) && childName && childName[0])
                        childNameText = ReadRuntimeCString(childName, 160);
                    if (childNameText.empty())
                        childNameText = "#" + std::to_string(entryIndex);

                    itemQueue.push_back({
                        {},
                        current.path + "/" + childNameText,
                        current.depth + 1,
                        entryIndex,
                        true,
                    });
                }
            }
        };

        for (uint32_t nodeIndex = 0; nodeIndex < flatMaxNodes; ++nodeIndex)
        {
            CoopNativeSaveStoreApi::NodeView flatNode;
            std::string flatReason;
            if (!CoopNativeSaveStoreApi::TryReadNodeByIndex(store, nodeIndex, flatNode, &flatReason) ||
                !flatNode.valid ||
                flatNode.nodePtr == 0)
            {
                ++flatGuards;
                continue;
            }

            ++flatScanned;

            uint32_t cellEntityId = 0;
            const bool cellShape =
                readU32AttrLoose(flatNode, "entityId", cellEntityId) &&
                cellEntityId != 0 &&
                hasAttr(flatNode, "x") &&
                hasAttr(flatNode, "y") &&
                hasAttr(flatNode, "width") &&
                hasAttr(flatNode, "height");
            if (cellShape)
            {
                if (sourceIds.find(static_cast<unsigned>(cellEntityId)) != sourceIds.end())
                {
                    locator.OnDecodedStoreNode(makeNodeInfo(flatNode, "Inventory/storedItems/i/v", true, false));
                    locator.OnInventoryCellEntityId(
                        static_cast<unsigned>(cellEntityId),
                        "ArkInventory::FullSerialize(local-player/read-store-flat)",
                        "Inventory/storedItems/i/v/entityId");
                    ++flatCells;
                }
                else
                {
                    ++flatCellSkipped;
                }
            }

            const bool itemShape =
                hasAttr(flatNode, "m_count") &&
                hasAttr(flatNode, "selectedArchetype") &&
                hasAttr(flatNode, "ownerId");
            if (!itemShape)
                continue;

            ++flatItemCandidates;
            uint32_t itemEntityId = 0;
            const bool hasItemEntityId =
                readU32AttrLoose(flatNode, "entityId", itemEntityId) ||
                readU32AttrLoose(flatNode, "id", itemEntityId);
            if (hasItemEntityId &&
                itemEntityId != 0 &&
                sourceIds.find(static_cast<unsigned>(itemEntityId)) != sourceIds.end())
            {
                locator.OnReadStoreItemNodeForEntity(
                    static_cast<unsigned>(itemEntityId),
                    makeNodeInfo(flatNode, "CArkItem::FullSerialize/player-inventory-item", false, true));
                observeFlatItemSubtree(
                    static_cast<unsigned>(itemEntityId),
                    flatNode,
                    "CArkItem::FullSerialize/player-inventory-item");
                ++flatItemCandidatesMapped;
            }
            else
            {
                ++flatItemCandidatesSkipped;
                if (unmappedCandidates.size() < sourceIdOrder.size() + 32)
                    unmappedCandidates.push_back({ flatNode, "CArkItem::FullSerialize/player-inventory-item", hasItemEntityId ? static_cast<unsigned>(itemEntityId) : 0u });
            }
        }
    }

    uint32_t ordinalMapped = 0;
    if (EnvFlagEnabled("COOP_NATIVE_READ_FRAGMENT_ORDINAL_FALLBACK"))
    {
        std::unordered_set<unsigned> alreadyMapped;
        const CoopNativeGameStateFragmentLocator::NativeInventoryFragmentBundle beforeFallback =
            locator.BuildFragmentBundle();
        for (unsigned entityId : beforeFallback.resolvedItemEntityIds)
            alreadyMapped.insert(entityId);

        size_t candidateIndex = 0;
        for (unsigned entityId : sourceIdOrder)
        {
            if (alreadyMapped.find(entityId) != alreadyMapped.end())
                continue;

            while (candidateIndex < unmappedCandidates.size() &&
                unmappedCandidates[candidateIndex].entityId != 0 &&
                sourceIds.find(unmappedCandidates[candidateIndex].entityId) != sourceIds.end())
            {
                ++candidateIndex;
            }
            if (candidateIndex >= unmappedCandidates.size())
                break;

            locator.OnReadStoreItemNodeForEntity(
                entityId,
                makeNodeInfo(unmappedCandidates[candidateIndex].node, unmappedCandidates[candidateIndex].path, false, true));
            alreadyMapped.insert(entityId);
            ++ordinalMapped;
            ++candidateIndex;
        }
    }

    locator.FinalizeRun("read-store fragment capture");
    if (m_nativeTargetFragmentCapture.IsActive() &&
        EnvFlagEnabled("COOP_NATIVE_TARGET_READ_FRAGMENT_AUGMENT"))
    {
        const CoopNativeGameStateFragmentLocator::NativeInventoryFragmentBundle readStoreBundle =
            locator.BuildFragmentBundle();
        m_nativeTargetFragmentCapture.MergeReadStoreBundle(
            readStoreBundle,
            "read-store fragment augment");
    }

    const uint32_t maxBytes = GetEnvUIntClamped(
        "COOP_NATIVE_FRAGMENT_CAPTURE_MAX_BYTES",
        4u * 1024u * 1024u,
        0x100u,
        64u * 1024u * 1024u);
    const CoopNativeGameStateFragmentLocator::NativeInventoryFragmentByteCapture capture =
        locator.CaptureFragmentBytes(maxBytes);
    if (!capture.ok)
    {
        ++m_nativeReadStoreFragmentFailures;
        m_lastNativeReadStoreFragmentEvent =
            "read_fragment failed capture=" + StatusToken(capture.reason) +
            " file=" + StatusToken(fileName ? std::string(fileName) : std::string("-")) +
            " reason=" + StatusToken(reason ? std::string(reason) : std::string("-")) +
            " sourceIds=" + std::to_string(sourceIds.size()) +
            "/payload_" + std::to_string(payloadSourceIds) +
            " cells=" + std::to_string(inventoryCells) +
            "/" + std::to_string(inventoryCellsSkipped) +
            " itemCandidates=" + std::to_string(itemCandidates) +
            "/" + std::to_string(itemCandidatesMapped) +
            "/" + std::to_string(itemCandidatesSkipped) +
            " flat=" + std::to_string(flatScanEnabled ? 1 : 0) +
            "/" + std::to_string(flatScanned) +
            "/cells_" + std::to_string(flatCells) +
            "/" + std::to_string(flatCellSkipped) +
            "/items_" + std::to_string(flatItemCandidates) +
            "/" + std::to_string(flatItemCandidatesMapped) +
            "/" + std::to_string(flatItemCandidatesSkipped) +
            "/obs_" + std::to_string(flatItemObserved) +
            "/guards_" + std::to_string(flatGuards) +
            " ordinal=" + std::to_string(ordinalMapped) +
            " nodes=" + std::to_string(scanned) +
            " materialized=" + std::to_string(materialized) +
            " children=" + std::to_string(childEntries) +
            " guards=" + std::to_string(guards) +
            " bundle=" + StatusToken(locator.BuildFragmentBundleStatus());
        LogCoop("native read fragment " + m_lastNativeReadStoreFragmentEvent);
        return false;
    }

    const CoopNativeFragmentPayload::BuildResult payload =
        CoopNativeFragmentPayload::BuildInventoryPayload(capture);
    if (!payload.ok)
    {
        ++m_nativeReadStoreFragmentFailures;
        m_lastNativeReadStoreFragmentEvent =
            "read_fragment failed payload=" + StatusToken(CoopNativeFragmentPayload::BuildStatus(payload)) +
            " file=" + StatusToken(fileName ? std::string(fileName) : std::string("-"));
        LogCoop("native read fragment " + m_lastNativeReadStoreFragmentEvent);
        return false;
    }

    const CoopNativeFragmentPayload::ParsedPayload parsed =
        CoopNativeFragmentPayload::ParseInventoryPayload(payload.bytes);
    if (!parsed.ok)
    {
        ++m_nativeReadStoreFragmentFailures;
        m_lastNativeReadStoreFragmentEvent =
            "read_fragment failed validate=" + StatusToken(CoopNativeFragmentPayload::BuildStatus(parsed)) +
            " file=" + StatusToken(fileName ? std::string(fileName) : std::string("-"));
        LogCoop("native read fragment " + m_lastNativeReadStoreFragmentEvent);
        return false;
    }

    const bool preferPayload = EnvFlagEnabled("COOP_NATIVE_READ_FRAGMENT_PREFER_PAYLOAD");
    if (preferPayload)
    {
        m_lastNativeFragmentImportPayload = payload.bytes;
        m_lastNativeFragmentPayloadEvent =
            "read-store payload candidate preferred " + CoopNativeFragmentPayload::BuildStatus(parsed);
    }

    if (EnvFlagEnabled("COOP_NATIVE_READ_FRAGMENT_REPLACE_CAPTURE_PAYLOAD") &&
        (m_nativeSideBlobCapture.active ||
            m_nativeSideBlobCapture.sawPlayerWrite ||
            m_nativeSideBlobCapture.sawInventoryWrite ||
            m_nativeSideBlobCapture.sawItemWrite))
    {
        CopyNativeFragmentPayloadToCapture(m_nativeSideBlobCapture, parsed, payload.bytes);
        m_lastNativeFragmentImportPayload = m_nativeSideBlobCapture.nativeFragmentPayload;
        m_lastNativeFragmentPayloadEvent =
            "read-store payload replaced active capture " + CoopNativeFragmentPayload::BuildStatus(parsed);
    }

    ++m_nativeReadStoreFragmentSuccesses;
    m_nativeReadStoreFragmentBytes = static_cast<uint32_t>(payload.bytes.size());
    m_lastNativeReadStoreFragmentEvent =
        "read_fragment ok " + CoopNativeFragmentPayload::BuildStatus(parsed) +
        " file=" + StatusToken(fileName ? std::string(fileName) : std::string("-")) +
        " reason=" + StatusToken(reason ? std::string(reason) : std::string("-")) +
        " sourceIds=" + std::to_string(sourceIds.size()) +
        "/payload_" + std::to_string(payloadSourceIds) +
        " cells=" + std::to_string(inventoryCells) +
        "/" + std::to_string(inventoryCellsSkipped) +
        " itemCandidates=" + std::to_string(itemCandidates) +
        "/" + std::to_string(itemCandidatesMapped) +
        "/" + std::to_string(itemCandidatesSkipped) +
        " flat=" + std::to_string(flatScanEnabled ? 1 : 0) +
        "/" + std::to_string(flatScanned) +
        "/cells_" + std::to_string(flatCells) +
        "/" + std::to_string(flatCellSkipped) +
        "/items_" + std::to_string(flatItemCandidates) +
        "/" + std::to_string(flatItemCandidatesMapped) +
        "/" + std::to_string(flatItemCandidatesSkipped) +
        "/obs_" + std::to_string(flatItemObserved) +
        "/guards_" + std::to_string(flatGuards) +
        " ordinal=" + std::to_string(ordinalMapped) +
        " nodes=" + std::to_string(scanned) +
        " materialized=" + std::to_string(materialized) +
        " children=" + std::to_string(childEntries) +
        " guards=" + std::to_string(guards) +
        " prefer=" + std::to_string(preferPayload ? 1 : 0) +
        " bundle=" + StatusToken(locator.BuildFragmentBundleStatus());
    LogCoop("native read fragment " + m_lastNativeReadStoreFragmentEvent);
    return true;
}

void ModMain::ProbeNativeReadStoreGraphSource(
    const CoopSaveStoreDecoder::StoreMap& storeMap,
    const char* fileName,
    const char* reason,
    bool forceDeepMaterialize,
    bool forceStartAtGameState)
{
    ++m_nativeReadStoreGraphProbes;

    const uint32_t maxNodes = GetEnvUIntClamped(
        "COOP_NATIVE_READ_STORE_GRAPH_MAX_NODES",
        96,
        4,
        2048);
    const uint32_t requestedMaxDepth = GetEnvUIntClamped(
        "COOP_NATIVE_READ_STORE_GRAPH_MAX_DEPTH",
        1,
        1,
        64);
    const uint32_t maxChildrenPerNode = GetEnvUIntClamped(
        "COOP_NATIVE_READ_STORE_GRAPH_MAX_CHILDREN",
        128,
        1,
        1024);
    const bool deepMaterialize =
        forceDeepMaterialize ||
        EnvFlagEnabled("COOP_NATIVE_READ_STORE_GRAPH_DEEP_MATERIALIZE");
    const uint32_t maxDepth = deepMaterialize
        ? requestedMaxDepth
        : 1u;

    const CoopNativeSaveStoreApi::StoreHandle store =
        CoopNativeSaveStoreApi::MakeReadStoreHandle(storeMap);
    if (!store.valid)
    {
        ++m_nativeReadStoreGraphGuards;
        m_lastNativeReadStoreGraphEvent =
            "graph_probe failed invalid_store file=" + StatusToken(fileName ? std::string(fileName) : std::string("-"));
        LogCoop("native read graph " + m_lastNativeReadStoreGraphEvent);
        return;
    }

    CoopNativeSaveStoreApi::NodeView rootNode;
    rootNode.nodePtr = storeMap.currentNode.nodePtr;
    rootNode.nodeIndex = storeMap.currentNode.nodeIndex;
    rootNode.nodeId = storeMap.currentNode.nodeId;
    rootNode.childCursor = storeMap.currentNode.childCursor;
    rootNode.childCount = storeMap.currentNode.childCount;
    rootNode.attrCursor = storeMap.currentNode.attrCursor;
    rootNode.attrCount = storeMap.currentNode.attrCount;
    rootNode.childIndexBlockBegin = storeMap.currentNode.childIndexBlockBegin;
    rootNode.childIndexBlockEnd = storeMap.currentNode.childIndexBlockEnd;
    rootNode.valid = storeMap.currentNode.valid;
    if (!rootNode.valid || rootNode.nodePtr == 0)
    {
        ++m_nativeReadStoreGraphGuards;
        m_lastNativeReadStoreGraphEvent =
            "graph_probe failed invalid_root file=" + StatusToken(fileName ? std::string(fileName) : std::string("-"));
        LogCoop("native read graph " + m_lastNativeReadStoreGraphEvent);
        return;
    }

    std::string guardReason;
    const bool wantStartAtGameState =
        forceStartAtGameState ||
        EnvFlagEnabled("COOP_NATIVE_READ_STORE_GRAPH_START_GAMESTATE");
    std::string startGameStateReason = wantStartAtGameState ? "requested" : "disabled";
    std::string rootPath = "Root";
    bool startAtGameState = false;
    if (wantStartAtGameState)
    {
        CoopNativeSaveStoreApi::NodeView gameStateNode;
        if (CoopNativeSaveStoreApi::TryFindReadSection(store, "GameState", gameStateNode, &guardReason) &&
            gameStateNode.valid &&
            gameStateNode.nodePtr != 0)
        {
            rootNode = gameStateNode;
            rootPath = "GameState";
            startAtGameState = true;
            startGameStateReason = "find_section_ok";
        }
        else
        {
            ++m_nativeReadStoreGraphGuards;
            startGameStateReason = guardReason.empty() ? "find_section_failed" : guardReason;

            std::vector<uint32_t> rootEntries;
            std::string scanReason;
            if (CoopNativeSaveStoreApi::TryEnumerateChildEntryIndices(
                    rootNode,
                    rootEntries,
                    GetEnvUIntClamped("COOP_NATIVE_READ_STORE_GRAPH_ROOT_START_MAX_CHILDREN", 1024, 1, 4096),
                    &scanReason))
            {
                for (uint32_t entryIndex : rootEntries)
                {
                    CoopNativeSaveStoreApi::NodeView childNode;
                    if (!CoopNativeSaveStoreApi::TryReadChildEntryByIndex(store, entryIndex, childNode, &scanReason) ||
                        !childNode.valid ||
                        childNode.nodePtr == 0)
                    {
                        continue;
                    }

                    const char* childName = nullptr;
                    if (!CoopNativeSaveStoreApi::TryResolveReadNodeName(childNode, childName, &scanReason) ||
                        !childName ||
                        !childName[0])
                    {
                        continue;
                    }

                    const std::string childNameText = ReadRuntimeCString(childName, 160);
                    if (childNameText != "GameState")
                        continue;

                    rootNode = childNode;
                    rootPath = "GameState";
                    startAtGameState = true;
                    startGameStateReason = "root_child_scan_ok_entry_" + std::to_string(entryIndex);
                    break;
                }

                if (!startAtGameState && startGameStateReason != "find_section_failed")
                    startGameStateReason += "_root_child_scan_missed";
                else if (!startAtGameState)
                    startGameStateReason = "root_child_scan_missed";
            }
            else
            {
                startGameStateReason += "_root_child_scan_failed_" + (scanReason.empty() ? std::string("unknown") : scanReason);
            }
        }
    }

    struct GraphQueueItem
    {
        CoopNativeSaveStoreApi::NodeView node;
        std::string path;
        uint32_t depth = 0;
    };

    std::deque<GraphQueueItem> queue;
    std::unordered_set<std::string> visitedPaths;
    queue.push_back({ rootNode, rootPath, 0 });
    visitedPaths.insert(rootPath + "@" + std::to_string(rootNode.nodeIndex));

    uint32_t scanned = 0;
    uint32_t materialized = 0;
    uint32_t named = 0;
    uint32_t childEntries = 0;
    uint32_t gameStateHits = startAtGameState ? 1u : 0u;
    uint32_t inventoryHits = 0;
    uint32_t storedItemValueHits = 0;
    uint32_t entityIdHits = 0;
    uint32_t mCountHits = 0;
    uint32_t attrRecords = 0;
    uint32_t attrNamed = 0;
    uint32_t attrReadable = 0;
    uint32_t attrU32Values = 0;
    uint32_t attrMatchHits = 0;
    uint32_t guards = 0;
    std::vector<std::string> samples;
    std::vector<unsigned> entityIds;
    std::vector<uint32_t> attrMatchValues;

    if (const char* rawMatchValues = std::getenv("COOP_NATIVE_READ_STORE_GRAPH_MATCH_U32_VALUES"))
    {
        const char* cursor = rawMatchValues;
        while (cursor && cursor[0])
        {
            char* end = nullptr;
            const unsigned long parsed = std::strtoul(cursor, &end, 0);
            if (end != cursor)
                attrMatchValues.push_back(static_cast<uint32_t>(parsed));
            cursor = end;
            while (cursor && (cursor[0] == ',' || cursor[0] == ';' || cursor[0] == ' ' || cursor[0] == '\t'))
                ++cursor;
            if (end == cursor && cursor && cursor[0])
                ++cursor;
        }
    }

    const size_t maxSamples = static_cast<size_t>(GetEnvUIntClamped(
        "COOP_NATIVE_READ_STORE_GRAPH_MAX_SAMPLES",
        10,
        1,
        128));
    const bool attrProbe = EnvFlagEnabled("COOP_NATIVE_READ_STORE_GRAPH_ATTR_PROBE");
    const bool sampleAllAttrs = EnvFlagEnabled("COOP_NATIVE_READ_STORE_GRAPH_SAMPLE_ALL_ATTRS");
    const uint32_t maxAttrsPerNode = GetEnvUIntClamped(
        "COOP_NATIVE_READ_STORE_GRAPH_MAX_ATTRS_PER_NODE",
        64,
        1,
        512);
    auto appendSample = [&](const std::string& sample)
    {
        if (samples.size() < maxSamples)
            samples.push_back(StatusToken(sample));
    };

    while (!queue.empty() && scanned < maxNodes)
    {
        GraphQueueItem item = std::move(queue.front());
        queue.pop_front();
        ++scanned;

        const bool inventoryPath = item.path.find("Inventory") != std::string::npos;
        const bool storedItemsPath = item.path.find("Inventory/storedItems") != std::string::npos;
        const bool storedItemValuePath = item.path.find("Inventory/storedItems/i/v") != std::string::npos;
        if (inventoryPath)
            ++inventoryHits;
        if (storedItemValuePath)
            ++storedItemValueHits;

        bool nodeHasEntityId = false;
        bool nodeHasMCount = false;
        CoopNativeSaveStoreApi::ReadAttributeView entityAttr;
        if (CoopNativeSaveStoreApi::TryFindReadAttribute(store, item.node, "entityId", entityAttr, nullptr))
        {
            uint32_t entityId = 0;
            if (CoopNativeSaveStoreApi::TryReadU32Attribute(entityAttr, entityId, nullptr) && entityId != 0)
            {
                nodeHasEntityId = true;
                ++entityIdHits;
                if (entityIds.size() < 12)
                    entityIds.push_back(entityId);
            }
        }

        CoopNativeSaveStoreApi::ReadAttributeView countAttr;
        if (CoopNativeSaveStoreApi::TryFindReadAttribute(store, item.node, "m_count", countAttr, nullptr))
        {
            nodeHasMCount = true;
            ++mCountHits;
        }

        if (attrProbe && item.node.attrCount > 0)
        {
            std::vector<CoopNativeSaveStoreApi::ReadAttributeRecord> attributes;
            std::string attrReason;
            if (CoopNativeSaveStoreApi::TryEnumerateReadAttributes(
                    store,
                    item.node,
                    attributes,
                    maxAttrsPerNode,
                    &attrReason))
            {
                attrRecords += static_cast<uint32_t>(attributes.size());
                for (const CoopNativeSaveStoreApi::ReadAttributeRecord& attribute : attributes)
                {
                    if (attribute.nameResolved)
                        ++attrNamed;
                    if (attribute.valueReadable)
                        ++attrReadable;

                    const uint32_t low32 = static_cast<uint32_t>(attribute.valueBits & 0xFFFFFFFFu);
                    const bool hasU32 = attribute.nativeU32Readable || attribute.valueByteCount >= sizeof(uint32_t);
                    const uint32_t displayU32 = attribute.nativeU32Readable ? attribute.nativeU32 : low32;
                    if (hasU32)
                        ++attrU32Values;

                    bool matchedValue = false;
                    if (hasU32 && !attrMatchValues.empty())
                    {
                        matchedValue =
                            std::find(attrMatchValues.begin(), attrMatchValues.end(), displayU32) != attrMatchValues.end();
                        if (matchedValue)
                            ++attrMatchHits;
                    }

                    const bool interestingAttrName =
                        attribute.name == "entityId" ||
                        attribute.name == "m_count" ||
                        attribute.name.find("Inventory") != std::string::npos ||
                        attribute.name.find("Item") != std::string::npos ||
                        attribute.name.find("item") != std::string::npos;

                    if (sampleAllAttrs || matchedValue || interestingAttrName)
                    {
                        appendSample(
                            item.path +
                            ":idx=" + std::to_string(item.node.nodeIndex) +
                            ":attr#" + std::to_string(attribute.ordinal) +
                            ":name=" + (attribute.nameResolved ? attribute.name : std::string("#") + std::to_string(attribute.view.nameIndex)) +
                            ":type=" + std::to_string(attribute.view.type) +
                            ":cursor=" + std::to_string(attribute.valueCursor) +
                            ":bytes=" + std::to_string(attribute.valueByteCount) +
                            ":u32=" + (hasU32 ? std::to_string(displayU32) : std::string("-")) +
                            ":native=" + std::to_string(attribute.nativeU32Readable ? 1 : 0));
                    }
                }
            }
            else
            {
                ++guards;
                if (sampleAllAttrs)
                    appendSample(item.path + ":attr_enum_failed:" + (attrReason.empty() ? std::string("unknown") : attrReason));
            }
        }

        if (inventoryPath || storedItemsPath || nodeHasEntityId || nodeHasMCount)
        {
            appendSample(
                item.path +
                ":idx=" + std::to_string(item.node.nodeIndex) +
                ":attrs=" + std::to_string(item.node.attrCount) +
                ":children=" + std::to_string(item.node.childCount));
        }

        if (item.depth >= maxDepth || item.node.childCount == 0)
            continue;

        std::vector<uint32_t> entries;
        if (!CoopNativeSaveStoreApi::TryEnumerateChildEntryIndices(
                item.node,
                entries,
                maxChildrenPerNode,
                &guardReason))
        {
            ++guards;
            continue;
        }
        childEntries += static_cast<uint32_t>(entries.size());

        for (uint32_t entryIndex : entries)
        {
            if (queue.size() + scanned >= maxNodes)
                break;

            CoopNativeSaveStoreApi::NodeView childNode;
            if (!CoopNativeSaveStoreApi::TryReadChildEntryByIndex(store, entryIndex, childNode, &guardReason))
            {
                ++guards;
                continue;
            }
            ++materialized;

            if (!childNode.valid || childNode.nodePtr == 0)
                continue;
            const char* childName = nullptr;
            std::string childNameText;
            if (CoopNativeSaveStoreApi::TryResolveReadNodeName(childNode, childName, nullptr) && childName && childName[0])
            {
                childNameText = ReadRuntimeCString(childName, 160);
                ++named;
            }
            if (childNameText.empty())
                childNameText = "#" + std::to_string(entryIndex);

            if (childNameText == "GameState")
                ++gameStateHits;

            const std::string childPath =
                item.path == "Root"
                    ? childNameText
                    : item.path + "/" + childNameText;
            const std::string childVisitKey = childPath + "@" + std::to_string(childNode.nodeIndex);
            if (visitedPaths.find(childVisitKey) != visitedPaths.end())
                continue;
            visitedPaths.insert(childVisitKey);

            queue.push_back({
                childNode,
                childPath,
                item.depth + 1,
            });
        }
    }

    ++m_nativeReadStoreGraphSuccesses;
    m_nativeReadStoreGraphGuards += guards;

    std::ostringstream sampleText;
    for (size_t i = 0; i < samples.size(); ++i)
    {
        if (i > 0)
            sampleText << ",";
        sampleText << samples[i];
    }
    std::ostringstream entityText;
    for (size_t i = 0; i < entityIds.size(); ++i)
    {
        if (i > 0)
            entityText << ",";
        entityText << entityIds[i];
    }

    m_lastNativeReadStoreGraphEvent =
        "graph_probe ok"
        " file=" + StatusToken(fileName ? std::string(fileName) : std::string("-")) +
        " reason=" + StatusToken(reason ? std::string(reason) : std::string("-")) +
        " nodes=" + std::to_string(scanned) +
        " materialized=" + std::to_string(materialized) +
        " named=" + std::to_string(named) +
        " childEntries=" + std::to_string(childEntries) +
        " gameStateHits=" + std::to_string(gameStateHits) +
        " wantStartGameState=" + std::to_string(wantStartAtGameState ? 1 : 0) +
        " startGameState=" + std::to_string(startAtGameState ? 1 : 0) +
        " startReason=" + StatusToken(startGameStateReason) +
        " deep=" + std::to_string(deepMaterialize ? 1 : 0) +
        " invHits=" + std::to_string(inventoryHits) +
        " storedValueHits=" + std::to_string(storedItemValueHits) +
        " entityHits=" + std::to_string(entityIdHits) +
        " mCountHits=" + std::to_string(mCountHits) +
        " attrProbe=" + std::to_string(attrProbe ? 1 : 0) +
        " attrRecords=" + std::to_string(attrRecords) +
        " attrNamed=" + std::to_string(attrNamed) +
        " attrReadable=" + std::to_string(attrReadable) +
        " attrU32=" + std::to_string(attrU32Values) +
        " attrMatches=" + std::to_string(attrMatchHits) +
        " guards=" + std::to_string(guards) +
        " entities=" + StatusToken(entityText.str().empty() ? std::string("-") : entityText.str()) +
        " samples=" + StatusToken(sampleText.str().empty() ? std::string("-") : sampleText.str());
    LogCoop("native read graph " + m_lastNativeReadStoreGraphEvent);
}

bool ModMain::WriteNativeSaveLoadXmlDiagnostics(const char* phase, const char* reason, const XmlNodeRef& root, bool fullXml)
{
    if (!static_cast<IXmlNode*>(root))
    {
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent = "xml diag failed: null root";
        return false;
    }

    const std::filesystem::path profileRoot = GetPreyProfileRoot();
    if (profileRoot.empty())
    {
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent = "xml diag failed: profile root unavailable";
        return false;
    }

    const std::filesystem::path diagnosticsRoot = profileRoot / "CoopPrototype" / "Diagnostics" / "NativeSaveXml";
    std::error_code error;
    std::filesystem::create_directories(diagnosticsRoot, error);
    if (error)
    {
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent = "xml diag failed: create diagnostics dir " + error.message();
        return false;
    }

    const uint32_t serial = m_nativePlayerXmlDiagnosticsWrites + 1;
    const std::string safePhase = SanitizePathComponent(phase && phase[0] ? std::string(phase) : std::string("xml"));
    char serialText[32] = {};
    std::snprintf(serialText, sizeof(serialText), "%04u", serial);
    const std::filesystem::path skeletonPath =
        diagnosticsRoot / (std::string(serialText) + "_" + safePhase + "_skeleton.txt");
    const std::filesystem::path indexPath =
        diagnosticsRoot / (std::string(serialText) + "_" + safePhase + "_index.jsonl");

    const uint32_t maxNodes = GetEnvUIntClamped("COOP_XML_DIAG_MAX_NODES", 2048, 16, 20000);
    const uint32_t maxDepth = GetEnvUIntClamped("COOP_XML_DIAG_MAX_DEPTH", 12, 1, 64);

    std::ostringstream skeleton;
    skeleton << "phase=" << (phase && phase[0] ? phase : "-") << "\n"
        << "reason=" << (reason && reason[0] ? reason : "-") << "\n"
        << "mode=" << GetNetworkModeName() << "\n"
        << "level=" << GetCurrentLevelName() << "\n"
        << "pendingReceivedPlayerState=" << (m_pendingReceivedPlayerStateApply ? 1 : 0) << "\n"
        << "pendingNativeOverride=" << (m_pendingNativePlayerStateOverrideValid ? 1 : 0) << "\n"
        << "clientAwaitHostPlayerState=" << (m_clientAwaitingHostPlayerState ? 1 : 0) << "\n"
        << "saveLoadGuard=" << (m_saveLoadGuardActive ? 1 : 0) << "\n"
        << "maxNodes=" << maxNodes << "\n"
        << "maxDepth=" << maxDepth << "\n\n";

    uint32_t visited = 0;
    std::string guardReason;
    bool skeletonOk = TryGuardedVoidCall(
        "coop native xml skeleton dump",
        [&]()
        {
            AppendXmlNodeSkeletonUnsafe(
                root,
                0,
                static_cast<int>(maxDepth),
                maxNodes,
                visited,
                skeleton);
        },
        &guardReason);
    if (!skeletonOk)
    {
        skeleton << "\n[guarded traversal failed] " << guardReason << "\n";
        ++m_nativePlayerXmlPatchFailures;
    }

    std::ofstream output(skeletonPath, std::ios::binary | std::ios::trunc);
    if (!output)
    {
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent = "xml diag failed: cannot open " + CoopFilesystem::ToUtf8(skeletonPath);
        return false;
    }
    output << skeleton.str();
    output.close();

    const CoopNativeSaveXmlPatch::PathIndexResult indexResult =
        CoopNativeSaveXmlPatch::WritePathIndex(root, indexPath, maxNodes, maxDepth);
    if (!indexResult.ok)
        ++m_nativePlayerXmlPatchFailures;

    bool fullXmlWritten = false;
    if (fullXml)
    {
        IXmlStringData* xmlData = nullptr;
        std::string xmlGuardReason;
        if (TryGuardedCall(
                "coop native xml get full data",
                [&root]() -> IXmlStringData*
                {
                    return root->getXMLData(0);
                },
                xmlData,
                &xmlGuardReason) &&
            xmlData)
        {
            std::string xmlPayload;
            bool copied = TryGuardedCall(
                "coop native xml copy full data",
                [xmlData]() -> std::string
                {
                    const char* text = xmlData->GetString();
                    const size_t length = xmlData->GetStringLength();
                    return text && length > 0 ? std::string(text, length) : std::string();
                },
                xmlPayload,
                &xmlGuardReason);

            std::string releaseReason;
            TryGuardedVoidCall(
                "coop native xml release full data",
                [xmlData]()
                {
                    xmlData->Release();
                },
                &releaseReason);

            if (copied)
            {
                const std::filesystem::path fullPath =
                    diagnosticsRoot / (std::string(serialText) + "_" + safePhase + "_full.xml");
                std::ofstream fullOutput(fullPath, std::ios::binary | std::ios::trunc);
                if (fullOutput)
                {
                    fullOutput.write(xmlPayload.data(), static_cast<std::streamsize>(xmlPayload.size()));
                    fullXmlWritten = true;
                }
            }
        }
        else
        {
            LogCoop("native player xml full dump skipped: " + (xmlGuardReason.empty() ? std::string("getXMLData failed") : xmlGuardReason));
        }
    }

    ++m_nativePlayerXmlDiagnosticsWrites;
    m_lastNativePlayerXmlPatchEvent =
        "xml diag wrote " + CoopFilesystem::ToUtf8(skeletonPath) +
        " nodes=" + std::to_string(visited) +
        " index=" + std::to_string(indexResult.written ? 1 : 0) +
        " indexNodes=" + std::to_string(indexResult.nodes) +
        " indexHits=" + std::to_string(indexResult.hits) +
        " full=" + std::to_string(fullXmlWritten ? 1 : 0) +
        (skeletonOk ? std::string() : " traversalGuard=" + guardReason) +
        (indexResult.ok ? std::string() : " indexGuard=" + indexResult.guardReason);
    LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);
    return skeletonOk;
}

bool ModMain::TryPrepareNativePlayerStateXmlPatchFromRoot(const XmlNodeRef& root, const char* reason)
{
    const bool forcedDump = EnvFlagEnabled("COOP_DUMP_LOAD_XML");
    const bool nativePlayerMergeEnabled = ShouldUseNativePlayerStatePreloadMerge() || NativeSaveInstrumentationEnabled();
    const bool shouldPatch =
        nativePlayerMergeEnabled &&
        m_networkMode == CoopNetworkMode::Client &&
        (m_pendingReceivedPlayerStateApply ||
            m_pendingNativePlayerStateOverrideValid ||
            m_clientAwaitingHostPlayerState);
    if (!forcedDump && !shouldPatch)
        return false;

    ++m_nativePlayerXmlPatchAttempts;
    if (!static_cast<IXmlNode*>(root))
    {
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent =
            "load xml root not ready reason=" +
            (reason && reason[0] ? std::string(reason) : std::string("unknown"));
        LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);
        return false;
    }

    std::string rootGuardReason;
    if (!PreflightRuntimePointer(
            "coop native xml root preflight",
            static_cast<IXmlNode*>(root),
            sizeof(void*),
            RuntimeAccess::Read,
            &rootGuardReason))
    {
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent =
            "load xml root unreadable ptr=" +
            PointerHex(static_cast<IXmlNode*>(root)) +
            " guard=" + rootGuardReason +
            " reason=" +
            (reason && reason[0] ? std::string(reason) : std::string("unknown"));
        LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);
        return false;
    }

    bool smokeOk = false;
    if (!TryGuardedCall(
            "coop native xml root smoke",
            [&]() -> bool
            {
                const char* tag = root->getTag();
                const int children = root->getChildCount();
                (void)tag;
                (void)children;
                return true;
            },
            smokeOk,
            &rootGuardReason) ||
        !smokeOk)
    {
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent =
            "load xml root smoke failed ptr=" +
            PointerHex(static_cast<IXmlNode*>(root)) +
            " guard=" + rootGuardReason +
            " reason=" +
            (reason && reason[0] ? std::string(reason) : std::string("unknown"));
        LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);
        return false;
    }

    m_lastNativePlayerXmlPatchEvent =
        "load xml root ready reason=" +
        (reason && reason[0] ? std::string(reason) : std::string("native load"));
    LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);

    WriteNativeSaveLoadXmlDiagnostics(
        "load_concrete_init",
        reason && reason[0] ? reason : "native concrete load root",
        root,
        EnvFlagEnabled("COOP_DUMP_LOAD_XML_FULL"));

    if (!shouldPatch)
    {
        m_lastNativePlayerXmlPatchEvent = "load xml diag only: no pending client player override";
        return false;
    }

    // Intentional stop line: production join/load must not fall back to
    // RemoveAllItems/Give or post-load CArkItem field mutation. The next step is
    // to replace the player/inventory subtrees in this root before vanilla reads
    // them, using the dumped layout as source of truth.
    ++m_nativePlayerXmlPatchFailures;
    m_lastNativePlayerXmlPatchEvent =
        "native XML patch pending at concrete load root; legacy inventory replay disabled reason=" +
        (reason && reason[0] ? std::string(reason) : std::string("native concrete load root"));
    LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);
    return false;
}

bool ModMain::TryPrepareNativePlayerStateXmlPatch(ILoadGame* loadGame, const char* reason)
{
    const bool forcedDump = EnvFlagEnabled("COOP_DUMP_LOAD_XML");
    const bool nativePlayerMergeEnabled = ShouldUseNativePlayerStatePreloadMerge() || NativeSaveInstrumentationEnabled();
    const bool shouldPatch =
        nativePlayerMergeEnabled &&
        m_networkMode == CoopNetworkMode::Client &&
        (m_pendingReceivedPlayerStateApply ||
            m_pendingNativePlayerStateOverrideValid ||
            m_clientAwaitingHostPlayerState);
    if (!forcedDump && !shouldPatch)
        return false;

    if (!loadGame || !IsLikelyRuntimeCppObject(loadGame, sizeof(void*) * 2))
    {
        ++m_nativePlayerXmlPatchAttempts;
        ++m_nativePlayerXmlPatchFailures;
        m_lastNativePlayerXmlPatchEvent = "load xml patch failed: unreadable ILoadGame";
        LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);
        return false;
    }

    XmlNodeRef root;
    std::string guardReason;
    if (!TryReadConcreteSaveLoadRoot(loadGame, "coop native load root xml", root, &guardReason))
    {
        ++m_nativePlayerXmlPatchAttempts;
        m_lastNativePlayerXmlPatchEvent =
            "load xml root not ready" +
            (guardReason.empty() ? std::string() : " guard=" + guardReason) +
            " snapshot=" + BuildSaveLoadObjectSnapshot(loadGame, "load");
        LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);
        return false;
    }

    return TryPrepareNativePlayerStateXmlPatchFromRoot(
        root,
        reason && reason[0] ? reason : "pre vanilla load notify");
}

void ModMain::OnCryActionNotifyLoadGame(ILoadGame* loadGame)
{
    const uint64_t atlasSeq = BeginSaveStateTracePhase(
        CoopSaveStateBridge::TracePhase::ActiveLoadNotify,
        CoopSaveStateBridge::SchemaSemantic::Section,
        "CCryAction::NotifyLoadGame",
        loadGame,
        nullptr,
        "pre-vanilla");
    EndSaveStateTracePhase(
        atlasSeq,
        CoopSaveStateBridge::TracePhase::ActiveLoadNotify,
        CoopSaveStateBridge::SchemaSemantic::Section,
        "CCryAction::NotifyLoadGame",
        loadGame,
        nullptr,
        "pre-vanilla");

    ++m_nativeSideBlobLoadNotifyCalls;

    const bool shouldInspectLoadXml =
        EnvFlagEnabled("COOP_DUMP_LOAD_XML") ||
        ((ShouldUseNativePlayerStatePreloadMerge() || NativeSaveInstrumentationEnabled()) &&
            m_networkMode == CoopNetworkMode::Client &&
            (m_pendingReceivedPlayerStateApply ||
                m_pendingNativePlayerStateOverrideValid ||
                m_clientAwaitingHostPlayerState));
    if (EnvFlagEnabled("COOP_TRY_ACTIVE_LOAD_ROOT"))
    {
        TryPrepareNativePlayerStateXmlPatch(loadGame, "pre vanilla active load notify");
    }
    else if (shouldInspectLoadXml)
    {
        // ILoadGame here may be an active interface wrapper, not the concrete
        // ::Load object whose header exposes m_root. Treat it as a chain marker
        // only; concrete root probing happens in Load::Init.
        m_lastNativePlayerXmlPatchEvent =
            "active load notify observed; root probe skipped pending concrete Load::Init snapshot=" +
            BuildSaveLoadObjectSnapshot(loadGame, "active_load_notify");
        LogCoop("native player xml " + m_lastNativePlayerXmlPatchEvent);
    }

    if (EnvFlagEnabled("COOP_NATIVE_LOAD_FRAGMENT_SECTION"))
        TryReadNativeWriteCompleteFragmentPayloadSection(loadGame, "CCryAction::NotifyLoadGame");

    if (!m_nativeSideBlobProbeEnabled)
    {
        m_lastNativeSideBlobEvent = "load notify skipped: probe disabled";
        return;
    }

    if (!loadGame)
    {
        ++m_nativeSideBlobFailures;
        m_lastNativeSideBlobEvent = "load notify failed: null ILoadGame";
        return;
    }

    if (!IsLikelyRuntimeCppObject(loadGame))
    {
        ++m_nativeSideBlobFailures;
        m_lastNativeSideBlobEvent = "load notify failed: unreadable ILoadGame";
        return;
    }

    std::string guardReason;
    bool haveSection = false;
    if (!TryGuardedCall(
            "coop native sideblob HaveSection",
            [&]() -> bool
            {
                return loadGame->HaveSection(kNativeSideBlobProbeSection);
            },
            haveSection,
            &guardReason))
    {
        ++m_nativeSideBlobFailures;
        m_lastNativeSideBlobEvent = "load section probe failed: " + guardReason;
        LogCoop(m_lastNativeSideBlobEvent);
        return;
    }

    if (!haveSection)
    {
        m_lastNativeSideBlobEvent = std::string("load section missing ") + kNativeSideBlobProbeSection;
        return;
    }

    std::unique_ptr<TSerialize> section;
    if (!TryGuardedCall(
            "coop native sideblob GetSection",
            [&]() -> std::unique_ptr<TSerialize>
            {
                std::unique_ptr<TSerialize> result;
                loadGame->GetSection(&result, kNativeSideBlobProbeSection);
                return result;
            },
            section,
            &guardReason) ||
        !section)
    {
        ++m_nativeSideBlobFailures;
        m_lastNativeSideBlobEvent = "load section get failed: " + (guardReason.empty() ? std::string("null section") : guardReason);
        LogCoop(m_lastNativeSideBlobEvent);
        return;
    }

    int version = 0;
    int marker = 0;
    string username;
    string levelName;
    int worldEpoch = 0;
    int inventoryRows = 0;
    bool readOk = false;
    if (!TryGuardedCall(
            "coop native sideblob read probe",
            [&]() -> bool
            {
                section->Value("version", version);
                section->Value("marker", marker);
                section->Value("username", username);
                section->Value("level", levelName);
                section->Value("worldEpoch", worldEpoch);
                section->Value("inventoryRows", inventoryRows);
                return section->Ok();
            },
            readOk,
            &guardReason) ||
        !readOk)
    {
        ++m_nativeSideBlobFailures;
        m_lastNativeSideBlobEvent = "load section read failed: " + (guardReason.empty() ? std::string("serializer not ok") : guardReason);
        LogCoop(m_lastNativeSideBlobEvent);
        return;
    }

    std::string capturedSummary;
    if (!ReadCapturedNativeSideBlob(loadGame, capturedSummary))
    {
        ++m_nativeSideBlobFailures;
        ++m_nativeSideBlobCapturedFailures;
        LogCoop("native captured sideblob read failed: " + capturedSummary);
    }

    std::string mirrorSummary;
    if (m_nativeSideBlobActiveMirrorEnabled)
    {
        uint32_t mirrorSections = 0;
        uint32_t mirrorItemSections = 0;
        std::string mirrorReason;
        if (TryReadNativePlayerMirrorSideBlob(loadGame, mirrorSections, mirrorItemSections, mirrorReason))
        {
            m_nativeSideBlobMirrorReadSections += mirrorSections;
            m_nativeSideBlobMirrorItemReadSections += mirrorItemSections;
            mirrorSummary =
                " mirrorSections=" + std::to_string(mirrorSections) +
                " mirrorItems=" + std::to_string(mirrorItemSections);
        }
        else if (!mirrorReason.empty())
        {
            ++m_nativeSideBlobFailures;
            ++m_nativeSideBlobMirrorFailures;
            mirrorSummary = " mirrorReadFailed=" + mirrorReason;
            LogCoop("native sideblob mirror read failed: " + mirrorReason);
        }
    }
    else
    {
        mirrorSummary = " mirrorSkipped=active_disabled";
    }

    ++m_nativeSideBlobReadSuccesses;
    m_lastNativeSideBlobEvent =
        "load section read version=" + std::to_string(version) +
        " marker=" + std::to_string(marker) +
        " user=" + std::string(username.c_str()) +
        " level=" + std::string(levelName.c_str()) +
        " epoch=" + std::to_string(worldEpoch) +
        " invRows=" + std::to_string(inventoryRows) +
        capturedSummary +
        mirrorSummary;
    LogCoop(m_lastNativeSideBlobEvent);
}

void ModMain::OnCryActionLoadGameRequested(const char* path, bool quick, bool ignoreDelay)
{
    (void)quick;
    (void)ignoreDelay;

    ++m_loadGameHookCalls;
    m_lastSaveLoadPath = path && path[0] ? path : "-";
    if (m_networkMode == CoopNetworkMode::Host || m_pendingAutoStartMode == "host")
    {
        SetCurrentHostSaveStateKey(BuildHostSaveStateKey(m_lastSaveLoadPath), false);
        const std::string lowerPath = ToLowerAscii(m_lastSaveLoadPath);
        const bool looksLikeSaveFile =
            lowerPath.find("savegames") != std::string::npos ||
            lowerPath.find(".csf") != std::string::npos ||
            lowerPath.find("autosave") != std::string::npos ||
            lowerPath.find("quicksave") != std::string::npos ||
            lowerPath.find("manual") != std::string::npos;
        m_pendingHostSaveLoadBroadcastAfterLoad =
            m_networkMode == CoopNetworkMode::Host &&
            m_hasRemoteEndpoint &&
            !m_arkLevelTransitionLoadActive &&
            looksLikeSaveFile;
    }
    SaveLocalPlayerSidecar("before native load");
    m_playerSidecarInventoryNativeRestoreReady = false;
    m_playerSidecarInventoryNativeRestoreActive = false;
    m_lastNativeInventoryLocalSerializeWasRead = false;
    BeginCoopLoadGuard("CCryAction::LoadGame");
}

void ModMain::OnCryActionLoadGameFinished(const char* path, int result)
{
    if (path && path[0])
        m_lastSaveLoadPath = path;

    m_lastSaveLoadEvent = "LoadGame returned " + std::to_string(result);
    if (result != eLGR_Ok && result != eLGR_Streaming)
        EndCoopLoadGuard("LoadGame failed");
}

void ModMain::ActivateClientCoopSaveSlot(const std::string& savePath, uint32_t transferId, const char* reason)
{
    if (m_networkMode != CoopNetworkMode::Client || savePath.empty())
        return;

    const std::filesystem::path saveFile = CoopFilesystem::FromUtf8(savePath);
    const std::filesystem::path slotDirectory = saveFile.parent_path();
    const std::filesystem::path tempDirectory = BuildCoopClientSessionTempDirectory();
    if (slotDirectory.empty() || tempDirectory.empty())
    {
        ++m_clientLevelStateBridgeFailures;
        m_lastClientLevelStateBridgeEvent = "activate failed: missing coop save slot path";
        LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
        return;
    }

    m_activeClientCoopSaveSlotDirectory = CoopFilesystem::ToUtf8(slotDirectory);
    m_activeClientCoopLevelStateDirectory = CoopFilesystem::ToUtf8(tempDirectory);
    m_activeClientCoopSaveTransferId = transferId;
    m_clientCoopArkTempBridgeActive = false;
    m_clientCoopArkTempBridgeNeedsCleanup = false;
    m_clientCoopArkTempBridgePath.clear();

    m_lastClientLevelStateBridgeEvent =
        "activated coop save slot transfer=" + std::to_string(transferId) +
        " reason=" + (reason && reason[0] ? std::string(reason) : std::string("unknown"));
    LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
    SeedClientCoopLevelStateFromSaveSlot(reason && reason[0] ? reason : "activate");
}

bool ModMain::SeedClientCoopLevelStateFromSaveSlot(const char* reason)
{
    if (m_networkMode != CoopNetworkMode::Client ||
        m_activeClientCoopSaveSlotDirectory.empty() ||
        m_activeClientCoopLevelStateDirectory.empty())
    {
        return false;
    }

    CoopDirectoryCopySummary summary;
    if (!CopyRegularFilesFlat(
            CoopFilesystem::FromUtf8(m_activeClientCoopSaveSlotDirectory),
            CoopFilesystem::FromUtf8(m_activeClientCoopLevelStateDirectory),
            true,
            false,
            summary))
    {
        ++m_clientLevelStateBridgeFailures;
        m_lastClientLevelStateBridgeEvent =
            "seed failed reason=" + (reason && reason[0] ? std::string(reason) : std::string("unknown")) +
            " " + summary.detail;
        LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
        return false;
    }

    ++m_clientLevelStateBridgeSeeds;
    m_lastClientLevelStateBridgeEvent =
        "seeded coop levelstate reason=" + (reason && reason[0] ? std::string(reason) : std::string("unknown")) +
        " " + summary.detail;
    LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
    return true;
}

int ModMain::GetArkSaveLoadCampaignSlotSafe(ArkSaveLoadSystem* saveLoadSystem, const char* reason)
{
    int campaignSlot = 0;
    std::string guardReason;
    if (saveLoadSystem &&
        IsLikelyRuntimeCppObject(saveLoadSystem, sizeof(ArkSaveLoadSystem)) &&
        TryGuardedCall(
            reason && reason[0] ? reason : "ArkSaveLoadSystem::GetCampaignSlot coop bridge",
            [saveLoadSystem]() { return saveLoadSystem->GetCampaignSlot(); },
            campaignSlot,
            &guardReason))
    {
        return std::clamp(campaignSlot, 0, 2);
    }

    return 0;
}

bool ModMain::PrepareClientCoopLevelStateBridge(ArkSaveLoadSystem* saveLoadSystem, const char* reason)
{
    if (m_networkMode != CoopNetworkMode::Client || m_activeClientCoopLevelStateDirectory.empty())
        return false;

    const std::filesystem::path coopTempDirectory = CoopFilesystem::FromUtf8(m_activeClientCoopLevelStateDirectory);
    if (!DirectoryHasRegularFiles(coopTempDirectory) && !SeedClientCoopLevelStateFromSaveSlot(reason))
        return false;

    const int campaignSlot = GetArkSaveLoadCampaignSlotSafe(saveLoadSystem, "ArkSaveLoadSystem::GetCampaignSlot levelstate bridge");
    const std::filesystem::path arkTempDirectory = BuildPreyCampaignTempDirectory(campaignSlot);
    if (arkTempDirectory.empty())
    {
        ++m_clientLevelStateBridgeFailures;
        m_lastClientLevelStateBridgeEvent = "prepare failed: ark temp unavailable";
        LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
        return false;
    }

    if (m_clientCoopArkTempBridgeActive &&
        !m_clientCoopArkTempBridgePath.empty() &&
        CoopFilesystem::FromUtf8(m_clientCoopArkTempBridgePath) == arkTempDirectory &&
        HasCoopClientLevelStateBridgeMarker(arkTempDirectory))
    {
        m_lastClientLevelStateBridgeEvent =
            "prepare skipped active reason=" +
            (reason && reason[0] ? std::string(reason) : std::string("unknown"));
        LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
        return true;
    }

    CoopDirectoryCopySummary summary;
    if (!CopyRegularFilesFlat(coopTempDirectory, arkTempDirectory, true, true, summary))
    {
        ++m_clientLevelStateBridgeFailures;
        m_lastClientLevelStateBridgeEvent =
            "prepare failed reason=" + (reason && reason[0] ? std::string(reason) : std::string("unknown")) +
            " " + summary.detail;
        LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
        return false;
    }

    std::string markerDetail;
    if (!WriteCoopClientLevelStateBridgeMarker(arkTempDirectory, markerDetail))
    {
        ++m_clientLevelStateBridgeFailures;
        m_lastClientLevelStateBridgeEvent = "prepare marker failed: " + markerDetail;
        LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
        return false;
    }

    ++m_clientLevelStateBridgeSyncs;
    m_clientCoopArkTempBridgePath = CoopFilesystem::ToUtf8(arkTempDirectory);
    m_clientCoopArkTempBridgeActive = true;
    m_clientCoopArkTempBridgeNeedsCleanup = true;
    m_lastClientLevelStateBridgeEvent =
        "prepared ark temp slot=" + std::to_string(campaignSlot) +
        " reason=" + (reason && reason[0] ? std::string(reason) : std::string("unknown")) +
        " " + summary.detail;
    LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
    return true;
}

bool ModMain::SyncClientCoopLevelStateBridgeFromArkTemp(const char* reason)
{
    if (m_networkMode != CoopNetworkMode::Client ||
        m_clientCoopArkTempBridgePath.empty() ||
        m_activeClientCoopLevelStateDirectory.empty())
    {
        return false;
    }

    const std::filesystem::path arkTempDirectory = CoopFilesystem::FromUtf8(m_clientCoopArkTempBridgePath);
    if (!HasCoopClientLevelStateBridgeMarker(arkTempDirectory))
    {
        m_lastClientLevelStateBridgeEvent =
            "sync skipped: bridge marker missing reason=" +
            (reason && reason[0] ? std::string(reason) : std::string("unknown"));
        return false;
    }

    CoopDirectoryCopySummary summary;
    if (!CopyRegularFilesFlat(
            arkTempDirectory,
            CoopFilesystem::FromUtf8(m_activeClientCoopLevelStateDirectory),
            true,
            true,
            summary))
    {
        ++m_clientLevelStateBridgeFailures;
        m_lastClientLevelStateBridgeEvent =
            "sync failed reason=" + (reason && reason[0] ? std::string(reason) : std::string("unknown")) +
            " " + summary.detail;
        LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
        return false;
    }

    ++m_clientLevelStateBridgeSyncs;
    m_lastClientLevelStateBridgeEvent =
        "synced ark temp to coop reason=" + (reason && reason[0] ? std::string(reason) : std::string("unknown")) +
        " " + summary.detail;
    LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
    return true;
}

void ModMain::CleanupClientCoopLevelStateBridge(const char* reason)
{
    if (m_clientCoopArkTempBridgePath.empty())
        return;

    const std::filesystem::path arkTempDirectory = CoopFilesystem::FromUtf8(m_clientCoopArkTempBridgePath);
    const bool marked = HasCoopClientLevelStateBridgeMarker(arkTempDirectory);
    if (marked && !SyncClientCoopLevelStateBridgeFromArkTemp(reason))
    {
        ++m_clientLevelStateBridgeFailures;
        m_lastClientLevelStateBridgeEvent =
            "cleanup deferred after sync failure reason=" +
            (reason && reason[0] ? std::string(reason) : std::string("unknown"));
        LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
        return;
    }

    if (marked)
    {
        std::error_code error;
        std::filesystem::remove_all(arkTempDirectory, error);
        if (error)
        {
            ++m_clientLevelStateBridgeFailures;
            m_lastClientLevelStateBridgeEvent =
                "cleanup remove failed reason=" +
                (reason && reason[0] ? std::string(reason) : std::string("unknown"));
            LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
            return;
        }
        ++m_clientLevelStateBridgeCleanups;
        m_lastClientLevelStateBridgeEvent =
            "cleaned ark temp bridge reason=" +
            (reason && reason[0] ? std::string(reason) : std::string("unknown"));
    }
    else
    {
        m_lastClientLevelStateBridgeEvent =
            "cleanup skipped: marker missing reason=" +
            (reason && reason[0] ? std::string(reason) : std::string("unknown"));
    }

    m_clientCoopArkTempBridgeActive = false;
    m_clientCoopArkTempBridgeNeedsCleanup = false;
    m_clientCoopArkTempBridgePath.clear();
    LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
}

void ModMain::OnArkPlayerSerializeHook(
    ArkPlayer* player,
    const char* functionName,
    bool reading,
    int target,
    bool ok)
{
    ++m_nativePlayerSerializeCalls;
    if (reading)
        ++m_nativePlayerSerializeReadCalls;

    const bool localPlayer = player && ArkPlayer::GetInstancePtr() == player;
    m_lastNativePlayerEvent = std::string(functionName ? functionName : "ArkPlayer::Serialize") +
        (reading ? " read " : " write ") +
        SerializationTargetName(target) +
        (ok ? " ok" : " not-ok") +
        " local=" + BoolText(localPlayer) +
        " pendingApply=" + std::to_string(m_pendingReceivedPlayerStateApply ? 1 : 0) +
        " pendingInv=" + std::to_string(m_playerSidecarInventoryPending) +
        " clear=" + std::to_string(m_pendingPlayerSidecarInventoryRestoreNeedsClear ? 1 : 0);

    if (localPlayer && (reading || m_saveLoadGuardActive || m_pendingReceivedPlayerStateApply || ShouldTraceNativeInventoryDetails()))
        LogCoop("native player " + m_lastNativePlayerEvent);

    if (localPlayer &&
        reading &&
        ok &&
        target == eST_SaveGame &&
        m_pendingReceivedPlayerStateApply)
    {
        TryMergeReceivedPlayerStateDuringNativeLoad(
            functionName && functionName[0] ?
                functionName :
                "ArkPlayer::FullSerialize");
    }

    CaptureNativePlayerSideBlobSnapshot(player, functionName, reading, target, ok);
}

void ModMain::OnArkPlayerPostSerializeHook(ArkPlayer* player, const char* functionName)
{
    ++m_nativePlayerPostSerializeCalls;

    const bool localPlayer = player && ArkPlayer::GetInstancePtr() == player;
    m_lastNativePlayerEvent = std::string(functionName ? functionName : "ArkPlayer::PostSerialize") +
        " local=" + BoolText(localPlayer) +
        " pendingApply=" + std::to_string(m_pendingReceivedPlayerStateApply ? 1 : 0) +
        " pendingInv=" + std::to_string(m_playerSidecarInventoryPending) +
        " clear=" + std::to_string(m_pendingPlayerSidecarInventoryRestoreNeedsClear ? 1 : 0);

    if (localPlayer && (m_saveLoadGuardActive || m_pendingReceivedPlayerStateApply || ShouldTraceNativeInventoryDetails()))
        LogCoop("native player " + m_lastNativePlayerEvent);

    if (localPlayer && m_pendingReceivedPlayerStateApply)
        TryMergeReceivedPlayerStateDuringNativeLoad(functionName ? functionName : "ArkPlayer::PostSerialize");
}

void ModMain::OnArkPlayerComponentPostSerializeHook(ArkPlayerComponent* component, const char* functionName)
{
    ++m_nativePlayerComponentPostSerializeCalls;

    ArkPlayer* player = ArkPlayer::GetInstancePtr();
    const bool localPlayerComponent = player && component && component == &player->m_playerComponent;
    m_lastNativePlayerEvent = std::string(functionName ? functionName : "ArkPlayerComponent::PostSerialize") +
        " local=" + BoolText(localPlayerComponent) +
        " pendingApply=" + std::to_string(m_pendingReceivedPlayerStateApply ? 1 : 0) +
        " pendingInv=" + std::to_string(m_playerSidecarInventoryPending) +
        " clear=" + std::to_string(m_pendingPlayerSidecarInventoryRestoreNeedsClear ? 1 : 0);

    if (localPlayerComponent && (m_saveLoadGuardActive || m_pendingReceivedPlayerStateApply || ShouldTraceNativeInventoryDetails()))
        LogCoop("native player " + m_lastNativePlayerEvent);

    if (localPlayerComponent && m_pendingReceivedPlayerStateApply)
        TryMergeReceivedPlayerStateDuringNativeLoad(functionName ? functionName : "ArkPlayerComponent::PostSerialize");
}

std::string ModMain::GetSaveGamePathOverrideForHook(const char* path, bool quick, int reason, const char* checkpointName)
{
    (void)quick;

    if (m_networkMode != CoopNetworkMode::Client)
        return {};

    const bool internalClientPlayerSnapshot = m_clientInternalPlayerSnapshotSaveActive;

    const char* quarantine = std::getenv("COOP_CLIENT_SAVE_QUARANTINE");
    if (!internalClientPlayerSnapshot && quarantine && quarantine[0] && std::atoi(quarantine) == 0)
    {
        ++m_clientSaveRedirectBypassCount;
        m_lastClientSaveRedirectEvent = "client save quarantine disabled";
        return {};
    }

    const std::string originalPath = path && path[0] ? path : "-";
    if (internalClientPlayerSnapshot)
    {
        ++m_clientSaveRedirectBypassCount;
        m_lastClientSaveRedirectEvent =
            "client internal player snapshot uses native slot " + originalPath;
        LogCoop(m_lastClientSaveRedirectEvent);
        return {};
    }

    const std::string saveKey =
        !m_currentHostSaveStateKey.empty() ? m_currentHostSaveStateKey :
        (!m_playerStateTransferSaveKey.empty() ? m_playerStateTransferSaveKey :
            (!m_pendingHostWorldLevel.empty() ? std::string("host_") + m_pendingHostWorldLevel : std::string("coop_client")));
    const std::string redirectedPath = BuildCoopClientTempSavePath(saveKey, originalPath, reason, checkpointName);
    if (redirectedPath.empty())
    {
        ++m_clientSaveRedirectBypassCount;
        m_lastClientSaveRedirectEvent = "client save quarantine failed to build path";
        return {};
    }

    ++m_clientSaveRedirectCount;
    m_lastClientSaveRedirectEvent =
        std::string(internalClientPlayerSnapshot ? "redirected internal client player snapshot " : "redirected client save ") +
        originalPath + " -> " + redirectedPath;
    LogCoop(m_lastClientSaveRedirectEvent);
    return redirectedPath;
}

void ModMain::OnFlashUILoadingProgress(int progressAmount)
{
    ++m_flashLoadingProgressCalls;
    if (progressAmount == m_lastFlashLoadingProgress && (m_flashLoadingProgressCalls % 25) != 0)
        return;

    m_lastFlashLoadingProgress = progressAmount;
    m_lastFlashLoadingEvent = "progress " + std::to_string(progressAmount);
    if (EnvFlagEnabled("COOP_TRACE_FLASH_LOADING"))
        CoopRuntimeLog::WriteRateLimited("flash_loading_progress", "flash loading " + m_lastFlashLoadingEvent, 1.0, 1);
}

void ModMain::OnFlashUILoadingComplete()
{
    ++m_flashLoadingCompleteCalls;
    m_lastFlashLoadingEvent = "complete";
    LogCoop("flash loading complete");
}

void ModMain::OnFlashUILoadingError(const char* error)
{
    ++m_flashLoadingErrorCalls;
    m_lastFlashLoadingEvent = std::string("error ") + (error && error[0] ? error : "-");
    LogCoop("flash loading " + m_lastFlashLoadingEvent);
}

void ModMain::OnFlashUIShowLoadingScreen()
{
    ++m_flashShowLoadingScreenCalls;
    m_lastFlashLoadingEvent = "show";
    LogCoop("flash loading screen show");
}

void ModMain::OnFlashUIHideLoadingScreen()
{
    ++m_flashHideLoadingScreenCalls;
    m_lastFlashLoadingEvent = "hide";
    LogCoop("flash loading screen hide");
}

void ModMain::OnFlashUILoadtimeUpdate(float frameTime)
{
    ++m_flashLoadtimeUpdateCalls;
    if (m_saveLoadGuardActive)
    {
        const float loadGuardFrameTime = std::max(frameTime, 0.1f);
        TickCoopLoadGuard(loadGuardFrameTime, false);
        m_runtimeExtractor.TickControlOnly(loadGuardFrameTime);
    }

    m_flashLoadtimeUpdateSeconds += std::max(frameTime, 0.1f);
    if (m_flashLoadtimeUpdateSeconds >= 2.0f)
    {
        m_flashLoadtimeUpdateSeconds = 0.0f;
        m_lastFlashLoadingEvent =
            "loadtime update progress=" + std::to_string(m_lastFlashLoadingProgress) +
            " waitContinue=" + std::to_string(m_waitingForPostLoadContinue ? 1 : 0) +
            " loadGuard=" + std::to_string(m_saveLoadGuardActive ? 1 : 0);
        if (EnvFlagEnabled("COOP_TRACE_FLASH_LOADING"))
            CoopRuntimeLog::WriteRateLimited("flash_loadtime_update", "flash loading " + m_lastFlashLoadingEvent, 2.0, 1);
    }
}

void ModMain::OnFlashUILoadtimeRender()
{
    ++m_flashLoadtimeRenderCalls;

    if (m_saveLoadGuardActive || m_waitingForPostLoadContinue)
    {
        constexpr float kLoadingRenderPumpFrameTime = 0.1f;
        TickCoopLoadGuard(kLoadingRenderPumpFrameTime, false);
        m_runtimeExtractor.TickControlOnly(kLoadingRenderPumpFrameTime);
    }
}

void ModMain::OnCoopSystemEvent(int event, std::uintptr_t wparam, std::uintptr_t lparam)
{
    (void)wparam;
    (void)lparam;

    const ESystemEvent systemEvent = static_cast<ESystemEvent>(event);
    switch (systemEvent)
    {
    case ESYSTEM_EVENT_LEVEL_LOAD_RESUME_GAME:
    case ESYSTEM_EVENT_LEVEL_LOAD_PREPARE:
    case ESYSTEM_EVENT_LEVEL_LOAD_START_LOADINGSCREEN:
    case ESYSTEM_EVENT_LEVEL_LOAD_START:
    case ESYSTEM_EVENT_LEVEL_UNLOAD:
    case ESYSTEM_EVENT_LOAD_SAVE_STARTED:
        if (m_saveLoadGuardActive || systemEvent != ESYSTEM_EVENT_LOAD_SAVE_STARTED)
        {
            ++m_systemLoadEventCount;
            SetTransitionPhase("system_load_event_begin", GetSystemEventName(event));
            BeginCoopLoadGuard(GetSystemEventName(event));
        }
        break;
    case ESYSTEM_EVENT_LEVEL_LOAD_ERROR:
        ++m_systemLoadEventCount;
        SetTransitionPhase("system_load_event_error", GetSystemEventName(event));
        EndCoopLoadGuard("LEVEL_LOAD_ERROR");
        break;
    case ESYSTEM_EVENT_LEVEL_LOAD_END:
    case ESYSTEM_EVENT_TRANSITION_GAME_STATE_LOADED:
        if (m_saveLoadGuardActive)
        {
            ++m_systemLoadEventCount;
            m_lastSaveLoadEvent = std::string("load event: ") + GetSystemEventName(event);
            SetTransitionPhase("system_load_event_mid", GetSystemEventName(event));
        }
        break;
    case ESYSTEM_EVENT_LEVEL_GAMEPLAY_START:
    case ESYSTEM_EVENT_QUICKLOAD_SAVE_FINISHED:
        ++m_systemLoadEventCount;
        SetTransitionPhase("system_load_event_native_done", GetSystemEventName(event));
        MarkCoopLoadNativeComplete(GetSystemEventName(event));
        break;
    default:
        break;
    }
}

