        " loadGuard=" + std::to_string(m_saveLoadGuardActive ? 1 : 0) +
        " cleanup=" + std::to_string(m_runtimeTransitionCleanupPrepared ? 1 : 0);

    if (m_visualPerceptionAcquireEntries <= 8 || (m_visualPerceptionAcquireEntries % 64) == 0)
        LogCoop(m_lastVisualPerceptionEvent);
