void ModMain::AppendSpatialEntityTraceDetails(std::ostringstream& out, const char* logLine) const
{
    GetEntitiesInBoxWarning warning;
    if (!TryParseGetEntitiesInBoxWarning(logLine, warning))
    {
        out << "spatial_query=parse_failed\n";
        return;
    }

    out << "spatial_query cells=" << warning.requestedCells
        << " bounds=" << FormatAabbTrace(warning.queryBounds) << "\n";

    if (!gEnv || !gEnv->pEntitySystem)
    {
        out << "spatial_suspects=entity_system_missing\n";
        return;
    }

    IEntityIt* rawIterator = nullptr;
    std::string guardReason;
    if (!TryGuardedCall("spatial sniper entity iterator", []() { return gEnv->pEntitySystem->GetEntityIterator(); }, rawIterator, &guardReason) ||
        !rawIterator)
    {
        out << "spatial_suspects=iterator_missing";
        if (!guardReason.empty())
            out << " guard=" << StatusToken(guardReason);
        out << "\n";
        return;
    }

    IEntityItPtr iterator = rawIterator;
    if (!TryGuardedVoidCall("spatial sniper iterator MoveFirst", [&iterator]() { iterator->MoveFirst(); }, &guardReason))
    {
        out << "spatial_suspects=iterator_move_failed guard=" << StatusToken(guardReason) << "\n";
        return;
    }

    size_t seen = 0;
    size_t suspects = 0;
    while (true)
    {
        bool isEnd = true;
        if (!TryGuardedCall("spatial sniper iterator IsEnd", [&iterator]() { return iterator->IsEnd(); }, isEnd, &guardReason) || isEnd)
            break;

        IEntity* entity = nullptr;
        if (!TryGuardedCall("spatial sniper iterator Next", [&iterator]() { return iterator->Next(); }, entity, &guardReason) ||
            !entity ||
            !IsLikelyRuntimeCppObject(entity))
        {
            continue;
        }
        ++seen;

        IPhysicalEntity* physics = nullptr;
        if (!TryGuardedCall("spatial sniper IEntity::GetPhysics", [entity]() { return entity->GetPhysics(); }, physics, &guardReason) ||
            !physics)
        {
            continue;
        }

        pe_status_pos physicsStatus;
        int statusResult = 0;
        if (!TryGuardedCall(
                "spatial sniper physics GetStatus pos",
                [physics, &physicsStatus]() { return physics->GetStatus(&physicsStatus); },
                statusResult,
                &guardReason) ||
            statusResult <= 0)
        {
            continue;
        }

        Vec3 pos(ZERO);
        if (!TryGuardedCall("spatial sniper IEntity::GetWorldPos", [entity]() { return entity->GetWorldPos(); }, pos, &guardReason) ||
            !IsFiniteVec3Trace(pos))
        {
            continue;
        }

        AABB physicsWorldBounds;
        physicsWorldBounds.min = pos + physicsStatus.BBox[0];
        physicsWorldBounds.max = pos + physicsStatus.BBox[1];
        const bool hugeBounds = IsHugePhysicsBounds(physicsStatus.BBox[0], physicsStatus.BBox[1]);
        const bool matchesQuery = AabbCloseEnough(physicsWorldBounds, warning.queryBounds, 2.0f);
        if (!hugeBounds && !matchesQuery)
            continue;

        ++suspects;
        if (suspects > 8)
            continue;

        EntityId entityId = INVALID_ENTITYID;
        uint64_t guid = 0;
        uint32_t flags = 0;
        bool hidden = false;
        bool garbage = false;
        const char* rawName = nullptr;
        const char* rawClassName = nullptr;
        TryGuardedCall("spatial sniper IEntity::GetId", [entity]() { return entity->GetId(); }, entityId, &guardReason);
        TryGuardedCall("spatial sniper IEntity::GetGuid", [entity]() { return entity->GetGuid(); }, guid, &guardReason);
        TryGuardedCall("spatial sniper IEntity::GetFlags", [entity]() { return entity->GetFlags(); }, flags, &guardReason);
        TryGuardedCall("spatial sniper IEntity::IsHidden", [entity]() { return entity->IsHidden(); }, hidden, &guardReason);
        TryGuardedCall("spatial sniper IEntity::IsGarbage", [entity]() { return entity->IsGarbage(); }, garbage, &guardReason);
        TryGuardedCall("spatial sniper IEntity::GetName", [entity]() { return entity->GetName(); }, rawName, &guardReason);

        IEntityClass* entityClass = nullptr;
        if (TryGuardedCall("spatial sniper IEntity::GetClass", [entity]() { return entity->GetClass(); }, entityClass, &guardReason) &&
            entityClass &&
            IsLikelyRuntimeCppObject(entityClass))
        {
            TryGuardedCall("spatial sniper IEntityClass::GetName", [entityClass]() { return entityClass->GetName(); }, rawClassName, &guardReason);
        }

        out << "spatial_suspect"
            << " id=" << entityId
            << " guid=" << guid
            << " class=" << StatusToken(ReadRuntimeCString(rawClassName, 96))
            << " name=" << StatusToken(ReadRuntimeCString(rawName, 128))
            << " pos=" << FormatVec3Trace(pos)
            << " physBBox=" << FormatAabbTrace(AABB(physicsStatus.BBox[0], physicsStatus.BBox[1]))
            << " worldFromPhys=" << FormatAabbTrace(physicsWorldBounds)
            << " huge=" << (hugeBounds ? 1 : 0)
            << " queryMatch=" << (matchesQuery ? 1 : 0)
            << " flags=" << Hex32(flags)
            << " hidden=" << (hidden ? 1 : 0)
            << " garbage=" << (garbage ? 1 : 0);

        if (IsRemoteProxyEntity(entityId))
            out << " role=remote_proxy";
        else if (guid != 0 && m_liveProps.find(guid) != m_liveProps.end())
            out << " role=live_prop";
        else if (IsEnemyPuppetEntity(entityId))
            out << " role=enemy_puppet";
        else
            out << " role=none";

        out << "\n";
    }

    out << "spatial_suspects seen=" << seen
        << " matched=" << suspects;
    if (!guardReason.empty())
        out << " lastGuard=" << StatusToken(guardReason);
    out << "\n";

    if (suspects == 0)
    {
        out << "spatial_query_note=no entity physics bounds matched; caller may be using a transient/raw physics bbox\n";
    }
}

void ModMain::OnAnimationQueueLogLine(const char* text, bool newLine)
{
    (void)newLine;
    if (!text || !text[0])
        return;

    const bool animationQueue =
        std::strstr(text, "Animation-queue filled up") != nullptr ||
        std::strstr(text, "Animation-queue overflow") != nullptr;
    const bool hugeEntityBox =
        std::strstr(text, "GetEntitiesInBox: too many cells requested") != nullptr;
    if (!animationQueue && !hugeEntityBox)
        return;

    ++m_animationQueueLogHits;
    m_lastAnimationQueueTraceEvent = text;

    const float now = gEnv && gEnv->pTimer ? gEnv->pTimer->GetAsyncCurTime() : 0.0f;
    if (hugeEntityBox &&
        !HugePhysicsBoundsRepairDisabled() &&
        EnvFlagDefaultEnabled("COOP_REPAIR_HUGE_PHYSICS_BOUNDS_ON_SPATIAL_WARNING") &&
        now - m_lastHugePhysicsBoundsEventRepairTime >= 0.35f)
    {
        m_lastHugePhysicsBoundsEventRepairTime = now;
        QueueHugePhysicsBoundsRepairFromSpatialWarning(text);
    }

    // Spatial warning traces enumerate the whole level, capture a stack and
    // synchronously write a file. That instrumentation is useful on demand,
    // but running it for every frame of a large authored mover stalls the game
    // thread and even makes Flash and mouse input appear frozen.
    const bool traceEvery = EnvFlagEnabled("COOP_TRACE_EVERY_ANIMATION_QUEUE_LOG");
    if (hugeEntityBox &&
        !traceEvery &&
        !EnvFlagEnabled("COOP_TRACE_HUGE_PHYSICS_WARNING"))
    {
        ++m_animationQueueTraceSkips;
        return;
    }
    if (!traceEvery &&
        m_animationQueueTraceWrites > 0 &&
        now - m_lastAnimationQueueTraceTime < 0.35f)
    {
        ++m_animationQueueTraceSkips;
        return;
    }

    if (!traceEvery && m_animationQueueTraceWrites >= 24)
    {
        ++m_animationQueueTraceSkips;
        return;
    }

    m_lastAnimationQueueTraceTime = now;
    ++m_animationQueueTraceWrites;
    const std::string path = BuildAnimationQueueTracePath(m_animationQueueTraceWrites);
    m_lastAnimationQueueTracePath = path;

    std::ostringstream out;
    out << "CoopPrototype animation/spatial log sniper\n"
        << "kind=" << (animationQueue ? "animation_queue" : "huge_entity_box") << "\n"
        << "pid=" << GetCurrentProcessId() << " tid=" << GetCurrentThreadId() << "\n"
        << "line=" << text << "\n\n";
    if (hugeEntityBox)
        AppendSpatialEntityTraceDetails(out, text);
    AppendCurrentStack(out);
    out << "\n";
    out << BuildCrashBreadcrumbs();
    WriteCrashTraceFile(path, out.str());
}

void ModMain::OnPhysicalWorldGetEntitiesInBoxHook(const Vec3& ptmin, const Vec3& ptmax, int objtypes, int szListPrealloc)
{
    ++m_physicalWorldBoxHookCalls;

    if (!EnvFlagDefaultEnabled("COOP_QUEUE_HUGE_PHYSICS_BOUNDS_FROM_PHYSICALWORLD_HOOK") ||
        HugePhysicsBoundsRepairDisabled() ||
        !IsFiniteVec3Trace(ptmin) ||
        !IsFiniteVec3Trace(ptmax))
    {
        return;
    }

    const Vec3 extents(std::fabs(ptmax.x - ptmin.x), std::fabs(ptmax.y - ptmin.y), std::fabs(ptmax.z - ptmin.z));
    const uint32_t largeAxes =
        (extents.x > 80.0f ? 1u : 0u) +
        (extents.y > 80.0f ? 1u : 0u) +
        (extents.z > 80.0f ? 1u : 0u);
    const bool hugeQuery =
        extents.x > 250.0f ||
        extents.y > 250.0f ||
        extents.z > 250.0f ||
        largeAxes >= 2;
    if (!hugeQuery)
        return;

    ++m_physicalWorldBoxHookHugeQueries;

    const float now = gEnv && gEnv->pTimer ? gEnv->pTimer->GetAsyncCurTime() : 0.0f;
    if (now - m_lastHugePhysicsBoundsEventRepairTime < 0.35f)
        return;

    m_lastHugePhysicsBoundsEventRepairTime = now;
    if (QueueHugePhysicsBoundsRepairFromBounds(0, ptmin, ptmax, "physicalworld_hook"))
    {
        ++m_physicalWorldBoxHookQueuedRepairs;
        m_lastPhysicalWorldBoxHookEvent =
            "physicalworld_get_entities_in_box_huge"
            "_objtypes_" + std::to_string(objtypes) +
            "_prealloc_" + std::to_string(szListPrealloc) +
            "_bounds_" + StatusToken(FormatAabbTrace(AABB(ptmin, ptmax))) +
            "_extents_" + StatusToken(FormatVec3Trace(extents));
    }
}

void ModMain::RegisterAnimationQueueLogSniper()
{
    if (m_animationQueueLogCallbackRegistered || !gEnv || !gEnv->pLog)
        return;

    if (!m_animationQueueLogCallback)
        m_animationQueueLogCallback = std::make_unique<CoopAnimationQueueLogCallback>();

    gEnv->pLog->AddCallback(m_animationQueueLogCallback.get());
    m_animationQueueLogCallbackRegistered = true;
    m_lastAnimationQueueTraceEvent = "animation queue log sniper registered";
}

void ModMain::UnregisterAnimationQueueLogSniper()
{
    if (!m_animationQueueLogCallbackRegistered)
        return;

    if (gEnv && gEnv->pLog && m_animationQueueLogCallback)
        gEnv->pLog->RemoveCallback(m_animationQueueLogCallback.get());

    m_animationQueueLogCallbackRegistered = false;
}

void ModMain::RegisterPhysicalWorldBoxQueryHook()
{
    if (s_hookedPhysicalWorld ||
        !EnvFlagEnabled("COOP_ENABLE_PHYSICALWORLD_GET_ENTITIES_IN_BOX_HOOK") ||
        !gEnv ||
        !gEnv->pPhysicalWorld)
    {
        return;
    }

    if (!s_physicalWorldVTableHook.HookObject(gEnv->pPhysicalWorld))
    {
        m_lastPhysicalWorldBoxHookEvent =
            "physicalworld_get_entities_in_box_hook_failed_clone";
        LogCoop(m_lastPhysicalWorldBoxHookEvent);
        return;
    }

    s_originalPhysicalWorldGetEntitiesInBox =
        s_physicalWorldVTableHook.HookMethod(
            kIPhysicalWorldGetEntitiesInBoxVtableIndex,
            &PhysicalWorld_GetEntitiesInBox_Hook);
    if (!s_originalPhysicalWorldGetEntitiesInBox)
    {
        const bool restored = s_physicalWorldVTableHook.UnhookObject();
        m_lastPhysicalWorldBoxHookEvent =
            restored
                ? "physicalworld_get_entities_in_box_hook_failed_method"
                : "physicalworld_get_entities_in_box_hook_failed_method_restore";
        LogCoop(m_lastPhysicalWorldBoxHookEvent);
        return;
    }

    s_hookedPhysicalWorld = gEnv->pPhysicalWorld;
    m_lastPhysicalWorldBoxHookEvent =
        "physicalworld_get_entities_in_box_hook_installed"
        "_index_" + std::to_string(kIPhysicalWorldGetEntitiesInBoxVtableIndex);
    LogCoop(m_lastPhysicalWorldBoxHookEvent);
}

void ModMain::UnregisterPhysicalWorldBoxQueryHook()
{
    if (!s_hookedPhysicalWorld)
        return;

    if (!s_physicalWorldVTableHook.UnhookObject())
    {
        m_lastPhysicalWorldBoxHookEvent =
            "physicalworld_get_entities_in_box_hook_remove_deferred_vtable_changed";
        LogCoop(m_lastPhysicalWorldBoxHookEvent);
        return;
    }

    s_hookedPhysicalWorld = nullptr;
    s_originalPhysicalWorldGetEntitiesInBox = nullptr;
    m_lastPhysicalWorldBoxHookEvent = "physicalworld_get_entities_in_box_hook_removed";
    LogCoop(m_lastPhysicalWorldBoxHookEvent);
}

void ModMain::InstallCrashExceptionHandler()
{
    const std::filesystem::path profileRoot = GetPreyProfileRoot();
    if (g_crashTraceDirectory.empty() && !profileRoot.empty())
    {
        const std::filesystem::path crashDir = profileRoot / "CoopPrototype" / "CrashTraces";
        std::error_code error;
        std::filesystem::create_directories(crashDir, error);
        if (!error)
            g_crashTraceDirectory = CoopFilesystem::ToUtf8(crashDir);
    }

    if (!g_purecallTraceHandlerInstalled)
    {
        g_previousPurecallHandler = _set_purecall_handler(&CoopPurecallTraceHandler);
        g_purecallTraceHandlerInstalled = true;
        LogCoop("purecall trace handler installed dir=" + (g_crashTraceDirectory.empty() ? std::string(".") : g_crashTraceDirectory));
    }

    if (!g_invalidParameterTraceHandlerInstalled)
    {
        g_previousInvalidParameterHandler = _set_invalid_parameter_handler(&CoopInvalidParameterTraceHandler);
        g_invalidParameterTraceHandlerInstalled = true;
        LogCoop("invalid parameter trace handler installed dir=" + (g_crashTraceDirectory.empty() ? std::string(".") : g_crashTraceDirectory));
    }

    if (!g_crashVectoredHandler)
    {
        g_crashVectoredHandler = AddVectoredExceptionHandler(1, &CoopCrashVectoredExceptionHandler);
        if (g_crashVectoredHandler)
            LogCoop("crash trace handler installed dir=" + (g_crashTraceDirectory.empty() ? std::string(".") : g_crashTraceDirectory));
    }

    RegisterAnimationQueueLogSniper();
    RegisterPhysicalWorldBoxQueryHook();
}

void ModMain::RemoveCrashExceptionHandler()
{
    UnregisterPhysicalWorldBoxQueryHook();
    UnregisterAnimationQueueLogSniper();

    if (g_purecallTraceHandlerInstalled)
    {
        _set_purecall_handler(g_previousPurecallHandler);
        g_previousPurecallHandler = nullptr;
        g_purecallTraceHandlerInstalled = false;
    }

    if (g_invalidParameterTraceHandlerInstalled)
    {
        _set_invalid_parameter_handler(g_previousInvalidParameterHandler);
        g_previousInvalidParameterHandler = nullptr;
        g_invalidParameterTraceHandlerInstalled = false;
    }

    if (!g_crashVectoredHandler)
        return;

    RemoveVectoredExceptionHandler(g_crashVectoredHandler);
    g_crashVectoredHandler = nullptr;
}

