ArkLevelTransitionDoor* ModMain::QueryLevelTransitionDoor(IEntity& entity) const
{
    if (!IsLikelyRuntimeCppObject(&entity))
        return nullptr;

    std::string guardReason;
    IEntityClass* entityClass = nullptr;
    if (!TryGuardedCall("IEntity::GetClass transition", [&entity]() { return entity.GetClass(); }, entityClass, &guardReason))
        return nullptr;
    if (!IsLikelyRuntimeCppObject(entityClass))
        return nullptr;

    const char* className = nullptr;
    if (!TryGuardedCall("IEntityClass::GetName transition", [entityClass]() { return entityClass->GetName(); }, className, &guardReason))
        return nullptr;
    if (!RuntimeCStringEquals(className, "ArkLevelTransitionDoor", 64))
        return nullptr;

    IGameFramework* framework = nullptr;
    if (!gEnv || !gEnv->pGame ||
        !TryGuardedCall("IGame::GetIGameFramework transition", []() { return gEnv->pGame->GetIGameFramework(); }, framework, &guardReason))
    {
        return nullptr;
    }

    if (!IsLikelyRuntimeCppObject(framework))
        return nullptr;

    EntityId entityId = INVALID_ENTITYID;
    if (!TryGuardedCall("IEntity::GetId transition", [&entity]() { return entity.GetId(); }, entityId, &guardReason))
        return nullptr;

    IGameObjectExtension* extension = nullptr;
    if (!TryGuardedCall(
        "IGameFramework::QueryGameObjectExtension transition",
        [framework, entityId]() { return framework->QueryGameObjectExtension(entityId, "ArkLevelTransitionDoor"); },
        extension,
        &guardReason))
    {
        return nullptr;
    }
    if (!IsLikelyRuntimeCppObject(extension, sizeof(ArkLevelTransitionDoor)))
        return nullptr;

    return static_cast<ArkLevelTransitionDoor*>(extension);
}

std::string ModMain::GetLocationDebugName(uint64_t locationId) const
{
    struct KnownLocation
    {
        uint64_t id;
        const char* name;
    };

    static constexpr KnownLocation kKnownLocations[] = {
        { 1713490239386284818ULL, "Arboretum" },
        { 1713490239377285936ULL, "Lobby" },
        { 1713490239386284337ULL, "Exterior" },
        { 4349723564895209499ULL, "Life Support" },
        { 6732635291182790112ULL, "Power Plant" },
        { 844024417275035158ULL, "Bridge" },
        { 844024417275035159ULL, "LevelTravelA" },
        { 844024417275035160ULL, "LevelTravelB" },
        { 844024417275036975ULL, "TranStar Testing Facility" },
        { 844024417289722427ULL, "Off Station" },
        { 15659330456296333985ULL, "Cargo Bay" },
        { 12889009724983807463ULL, "Neuromod Division" },
        { 11824555372632688907ULL, "Psychotronics" },
        { 844024417263019221ULL, "Hardware Labs" },
        { 1713490239377738413ULL, "Deep Storage" },
        { 844024417252490146ULL, "Crew Quarters" },
        { 1713490239386284988ULL, "Shuttle Bay" },
        { 4349723564886052417ULL, "G.U.T.S." },
    };

    for (const KnownLocation& location : kKnownLocations)
    {
        if (location.id == locationId)
            return location.name;
    }

    return "unknown";
}

void ModMain::RefreshLevelTransitionDebug()
{
    ++m_levelTransitionDoorScanCount;
    m_levelTransitionDebugRows.clear();

    if (!gEnv || !gEnv->pEntitySystem)
    {
        m_lastLevelTransitionEvent = "scan failed: no entity system";
        return;
    }

    std::string guardReason;
    IEntityIt* rawIterator = nullptr;
    if (!TryGuardedCall("IEntitySystem::GetEntityIterator transition scan", []() { return gEnv->pEntitySystem->GetEntityIterator(); }, rawIterator, &guardReason))
    {
        ++m_levelTransitionGuardSkips;
        m_lastLevelTransitionEvent = "scan failed: guarded entity iterator call failed";
        return;
    }

    IEntityItPtr iterator = rawIterator;
    if (!iterator)
    {
        m_lastLevelTransitionEvent = "scan failed: no entity iterator";
        return;
    }

    if (!TryGuardedVoidCall("IEntityIt::MoveFirst transition scan", [&iterator]() { iterator->MoveFirst(); }, &guardReason))
    {
        ++m_levelTransitionGuardSkips;
        m_lastLevelTransitionEvent = "scan failed: guarded MoveFirst failed";
        return;
    }

    while (true)
    {
        bool isEnd = true;
        if (!TryGuardedCall("IEntityIt::IsEnd transition scan", [&iterator]() { return iterator->IsEnd(); }, isEnd, &guardReason))
        {
            ++m_levelTransitionGuardSkips;
            break;
        }
        if (isEnd)
            break;

        IEntity* entity = nullptr;
        if (!TryGuardedCall("IEntityIt::Next transition scan", [&iterator]() { return iterator->Next(); }, entity, &guardReason))
        {
            ++m_levelTransitionGuardSkips;
            break;
        }
        if (!entity || !IsLikelyRuntimeCppObject(entity))
        {
            ++m_levelTransitionGuardSkips;
            continue;
        }

        IEntityClass* entityClass = nullptr;
        if (!TryGuardedCall("IEntity::GetClass transition scan", [entity]() { return entity->GetClass(); }, entityClass, &guardReason))
        {
            ++m_levelTransitionGuardSkips;
            continue;
        }
        if (!IsLikelyRuntimeCppObject(entityClass))
        {
            ++m_levelTransitionGuardSkips;
            continue;
        }

        const char* className = nullptr;
        if (!TryGuardedCall("IEntityClass::GetName transition scan", [entityClass]() { return entityClass->GetName(); }, className, &guardReason))
        {
            ++m_levelTransitionGuardSkips;
            continue;
        }
        if (!RuntimeCStringEquals(className, "ArkLevelTransitionDoor", 64))
            continue;

        LevelTransitionDoorDebugRow row;
        const char* entityName = nullptr;
        if (!TryGuardedCall("IEntity::GetId transition scan", [entity]() { return entity->GetId(); }, row.entityId, &guardReason) ||
            !TryGuardedCall("IEntity::GetGuid transition scan", [entity]() { return entity->GetGuid(); }, row.entityGuid, &guardReason) ||
            !TryGuardedCall("IEntity::GetWorldPos transition scan", [entity]() { return entity->GetWorldPos(); }, row.position, &guardReason))
        {
            ++m_levelTransitionGuardSkips;
            continue;
        }
        if (TryGuardedCall("IEntity::GetName transition scan", [entity]() { return entity->GetName(); }, entityName, &guardReason))
            row.name = ReadRuntimeCString(entityName, 128);
        if (row.name.empty())
            row.name = "-";

        if (ArkLevelTransitionDoor* door = QueryLevelTransitionDoor(*entity))
        {
            uint64_t destinationId = 0;
            bool locked = false;
            bool inaccessible = false;
            bool trialGated = false;
            bool transitionGo = false;

            const bool readCore =
                TryReadRuntimeValue(&door->m_locationId, destinationId) &&
                TryReadRuntimeValue(&door->m_bLocked, locked) &&
                TryReadRuntimeValue(&door->m_bInaccessible, inaccessible) &&
                TryReadRuntimeValue(&door->m_bIsTrialGated, trialGated) &&
                TryReadRuntimeValue(&door->m_bLevelTransitionGo, transitionGo);

            if (!readCore)
            {
                ++m_levelTransitionGuardSkips;
                row.destinationName = "guarded read failed";
                m_levelTransitionDebugRows.push_back(std::move(row));
                continue;
            }

            row.extensionAvailable = true;
            row.destinationId = destinationId;
            row.destinationName = GetLocationDebugName(destinationId);
            row.arkLocationName = "native getter disabled";
            row.locked = locked;
            row.inaccessible = inaccessible;
            row.trialGated = trialGated;
            row.transitionGo = transitionGo;
        }
        else
        {
            row.destinationName = "extension unavailable";
        }

        m_levelTransitionDebugRows.push_back(std::move(row));
    }

    if (m_selectedLevelTransitionDoor >= static_cast<int>(m_levelTransitionDebugRows.size()))
        m_selectedLevelTransitionDoor = static_cast<int>(m_levelTransitionDebugRows.empty() ? 0 : m_levelTransitionDebugRows.size() - 1);
    if (m_selectedLevelTransitionDoor < 0)
        m_selectedLevelTransitionDoor = 0;

    m_lastLevelTransitionEvent =
        "scan found " + std::to_string(m_levelTransitionDebugRows.size()) +
        " ArkLevelTransitionDoor entities guardSkips=" + std::to_string(m_levelTransitionGuardSkips);
}

void ModMain::TickLevelTransitionPresentationRecovery(float frameTime)
{
    if (m_networkMode == CoopNetworkMode::Off ||
        m_saveLoadGuardActive ||
        !IsGameReady() ||
        !gEnv ||
        !gEnv->pEntitySystem)
    {
        m_levelTransitionPresentationAccumulator = 0.0f;
        return;
    }

    m_levelTransitionPresentationAccumulator += std::max(0.0f, frameTime);
    if (m_levelTransitionPresentationAccumulator < 0.5f)
        return;
    m_levelTransitionPresentationAccumulator = 0.0f;

    const std::string currentLevel = GetCurrentLevelName();
    if (currentLevel == "unknown")
        return;

    if (m_levelTransitionPresentationLevel != currentLevel ||
        m_levelTransitionPresentationNativeCompleteSeen != m_postLoadNativeCompleteCount ||
        m_levelTransitionDebugRows.empty())
    {
        RefreshLevelTransitionDebug();
        m_levelTransitionPresentationLevel = currentLevel;
        m_levelTransitionPresentationNativeCompleteSeen = m_postLoadNativeCompleteCount;
    }

    std::string guardReason;
    for (const LevelTransitionDoorDebugRow& row : m_levelTransitionDebugRows)
    {
        IEntity* entity = nullptr;
        if (!TryGuardedCall(
                "transition presentation cached GetEntity",
                [&row]() { return gEnv->pEntitySystem->GetEntity(row.entityId); },
                entity,
                &guardReason) ||
            !entity ||
            !IsLikelyRuntimeCppObject(entity))
        {
            continue;
        }

        if (ArkLevelTransitionDoor* door = QueryLevelTransitionDoor(*entity))
            OnArkLevelTransitionDoorUpdated(door);
    }
}

bool ModMain::SelectLevelTransitionDoorByDestination(const std::string& destination)
{
    RefreshLevelTransitionDebug();

    const std::string rawToken = ToLowerAscii(destination);
    const std::string normalizedToken = ToLowerAscii(NormalizeLevelName(destination));
    std::string shortToken = normalizedToken;
    const size_t lastSlash = shortToken.find_last_of('/');
    if (lastSlash != std::string::npos && lastSlash + 1 < shortToken.size())
        shortToken = shortToken.substr(lastSlash + 1);

    uint64_t destinationId = 0;
    const bool hasDestinationId = TryParseUint64(destination, destinationId);

    auto matchesToken = [&](const LevelTransitionDoorDebugRow& row)
    {
        if (hasDestinationId && row.destinationId == destinationId)
            return true;

        const std::string destinationName = ToLowerAscii(row.destinationName);
        const std::string entityName = ToLowerAscii(row.name);
        if (!destinationName.empty() &&
            (destinationName.find(rawToken) != std::string::npos ||
                destinationName.find(shortToken) != std::string::npos ||
                rawToken.find(destinationName) != std::string::npos ||
                normalizedToken.find(destinationName) != std::string::npos))
        {
            return true;
        }

        return !entityName.empty() &&
            (entityName.find(rawToken) != std::string::npos ||
                entityName.find(shortToken) != std::string::npos);
    };

    for (size_t i = 0; i < m_levelTransitionDebugRows.size(); ++i)
    {
        const LevelTransitionDoorDebugRow& row = m_levelTransitionDebugRows[i];
        if (!row.extensionAvailable || !matchesToken(row))
            continue;

        m_selectedLevelTransitionDoor = static_cast<int>(i);
        m_lastLevelTransitionEvent =
            "selected transition door=" + std::to_string(row.entityId) +
            " dest=" + std::to_string(row.destinationId) +
            " " + row.destinationName +
            " token=" + destination;
        return true;
    }

    m_lastLevelTransitionEvent =
        "select transition failed: no destination match token=" + destination +
        " doors=" + std::to_string(m_levelTransitionDebugRows.size());
    return false;
}

bool ModMain::InvokeSelectedLevelTransitionDoor()
{
    ++m_levelTransitionInvokeAttempts;

    if (!m_allowExperimentalNativeTransitionInvoke)
    {
        m_lastLevelTransitionEvent = "native transition invoke blocked by safety toggle";
        return false;
    }

    if (m_selectedLevelTransitionDoor < 0 ||
        m_selectedLevelTransitionDoor >= static_cast<int>(m_levelTransitionDebugRows.size()))
    {
        m_lastLevelTransitionEvent = "native transition invoke failed: no selected door";
        return false;
    }

    const LevelTransitionDoorDebugRow& row = m_levelTransitionDebugRows[m_selectedLevelTransitionDoor];
    std::string guardReason;
    IEntity* entity = nullptr;
    if (gEnv && gEnv->pEntitySystem)
    {
        if (!TryGuardedCall("IEntitySystem::GetEntity transition invoke", [&row]() { return gEnv->pEntitySystem->GetEntity(row.entityId); }, entity, &guardReason))
        {
            ++m_levelTransitionGuardSkips;
            m_lastLevelTransitionEvent = "native transition invoke failed: guarded GetEntity failed";
            return false;
        }
    }
    if (!entity)
    {
        m_lastLevelTransitionEvent = "native transition invoke failed: selected entity missing";
        return false;
    }

    ArkLevelTransitionDoor* door = QueryLevelTransitionDoor(*entity);
    if (!door)
    {
        m_lastLevelTransitionEvent = "native transition invoke failed: extension unavailable";
        return false;
    }

    uint64_t destinationId = 0;
    bool locked = false;
    bool inaccessible = false;
    bool trialGated = false;
    if (!TryReadRuntimeValue(&door->m_locationId, destinationId) ||
        !TryReadRuntimeValue(&door->m_bLocked, locked) ||
        !TryReadRuntimeValue(&door->m_bInaccessible, inaccessible) ||
        !TryReadRuntimeValue(&door->m_bIsTrialGated, trialGated))
    {
        ++m_levelTransitionGuardSkips;
        m_lastLevelTransitionEvent = "native transition invoke failed: guarded door-state read failed";
        return false;
    }

    // The extractor's explicit experimental toggle may drive a locked door:
    // the campaign harness advances objective lifecycles through native
    // ArkObjectiveComponent APIs, which do not run every nearby FlowGraph
    // unlock output. An inaccessible airlock is different: invoking it can
    // enter Ark's level-state loader without a valid destination state and
    // crash inside the original game code. m_bIsTrialGated is likewise
    // authored metadata ("hide this destination in the trial edition"), not
    // the current retail door state; Lobby -> Hardware Labs legitimately has
    // it set in the full game.
    if (inaccessible)
    {
        m_lastLevelTransitionEvent =
            "native transition invoke blocked by vanilla door state door=" +
            std::to_string(row.entityId) +
            " dest=" + std::to_string(destinationId) +
            " locked=" + std::to_string(locked ? 1 : 0) +
            " inaccessible=" + std::to_string(inaccessible ? 1 : 0) +
            " trialGated=" + std::to_string(trialGated ? 1 : 0);
        LogCoop(m_lastLevelTransitionEvent);
        return false;
    }

    SaveLocalPlayerSidecar("before Ark native transition");
    m_lastLevelTransitionEvent =
        "invoking Ark native transition door=" + std::to_string(row.entityId) +
        " dest=" + std::to_string(destinationId) +
        " " + GetLocationDebugName(destinationId);
    LogCoop(m_lastLevelTransitionEvent);

    ++m_levelTransitionInvokeSuccesses;
    if (!TryGuardedVoidCall("ArkLevelTransitionDoor::OnTransitionConfirmed invoke", [door]() { door->OnTransitionConfirmed(); }, &guardReason))
    {
        ++m_levelTransitionGuardSkips;
        m_lastLevelTransitionEvent = "native transition invoke failed: guarded OnTransitionConfirmed failed";
        return false;
    }
    return true;
}

void ModMain::DrawLevelTransitionDebug()
{
    ImGui::Separator();
    if (!ImGui::CollapsingHeader("Ark Level Transitions"))
        return;

    IArkSaveLoadSystem* saveLoadSystem = nullptr;
    bool inTransition = false;
    bool restoring = false;
    std::string guardReason;
    IGameFramework* framework = nullptr;
    if (gEnv && gEnv->pGame &&
        TryGuardedCall("IGame::GetIGameFramework transition debug", []() { return gEnv->pGame->GetIGameFramework(); }, framework, &guardReason) &&
        IsLikelyRuntimeCppObject(framework))
    {
        TryGuardedCall("IGameFramework::GetArkSaveLoadSystem transition debug", [framework]() { return &framework->GetArkSaveLoadSystem(); }, saveLoadSystem, &guardReason);
        if (!IsLikelyRuntimeCppObject(saveLoadSystem))
            saveLoadSystem = nullptr;
    }
    if (saveLoadSystem)
    {
        if (!TryGuardedCall("IArkSaveLoadSystem::InLevelTransition", [saveLoadSystem]() { return saveLoadSystem->InLevelTransition(); }, inTransition, &guardReason))
            ++m_levelTransitionGuardSkips;
        if (!TryGuardedCall("IArkSaveLoadSystem::IsRestoringLevelState", [saveLoadSystem]() { return saveLoadSystem->IsRestoringLevelState(); }, restoring, &guardReason))
            ++m_levelTransitionGuardSkips;
    }

    ImGui::Text("Ark save-load: inTransition=%d restoring=%d",
        inTransition ? 1 : 0,
        restoring ? 1 : 0);
    ImGui::Text("Door scan=%u hook=%u invoke=%u/%u guardSkips=%u epochKeeps=%u presentation=%u/%u/%u screenLoc=%u last=%s",
        m_levelTransitionDoorScanCount,
        m_levelTransitionConfirmedHookCalls,
        m_levelTransitionInvokeSuccesses,
        m_levelTransitionInvokeAttempts,
        m_levelTransitionGuardSkips,
        m_levelTransitionEpochKeeps,
        m_levelTransitionPresentationRepairs,
        m_levelTransitionPresentationCancelCalls,
        m_levelTransitionPresentationFailures,
        m_levelTransitionScreenLocationCorrections,
        m_lastLevelTransitionEvent.c_str());
    ImGui::TextWrapped("Transition presentation last: %s",
        m_lastLevelTransitionPresentationEvent.c_str());
    ImGui::TextWrapped("Transition screen location last: %s",
        m_lastLevelTransitionScreenLocationEvent.c_str());

    if (ImGui::Button("Scan transition doors"))
        RefreshLevelTransitionDebug();

    ImGui::SameLine();
    ImGui::Checkbox("Allow experimental native transition invoke", &m_allowExperimentalNativeTransitionInvoke);

    if (ImGui::Button("Invoke selected Ark transition"))
        InvokeSelectedLevelTransitionDoor();

    if (m_levelTransitionDebugRows.empty())
    {
        ImGui::TextWrapped("No transition doors scanned yet. Use Scan transition doors while a level is loaded.");
        return;
    }

    ImGui::BeginChild("CoopTransitionDoorList", ImVec2(0.0f, 150.0f), true);
    for (int i = 0; i < static_cast<int>(m_levelTransitionDebugRows.size()); ++i)
    {
        const LevelTransitionDoorDebugRow& row = m_levelTransitionDebugRows[i];
        char label[384] = {};
        std::snprintf(label, sizeof(label),
            "#%d id=%u %s -> %llu %s%s%s%s%s",
            i,
            row.entityId,
            row.name.c_str(),
            static_cast<unsigned long long>(row.destinationId),
            row.destinationName.c_str(),
            row.extensionAvailable ? "" : " no-ext",
            row.locked ? " locked" : "",
            row.inaccessible ? " inaccessible" : "",
            row.trialGated ? " trial" : "");

        if (ImGui::Selectable(label, m_selectedLevelTransitionDoor == i))
            m_selectedLevelTransitionDoor = i;
    }
    ImGui::EndChild();

    if (m_selectedLevelTransitionDoor >= 0 &&
        m_selectedLevelTransitionDoor < static_cast<int>(m_levelTransitionDebugRows.size()))
    {
        const LevelTransitionDoorDebugRow& row = m_levelTransitionDebugRows[m_selectedLevelTransitionDoor];
        ImGui::Text("Selected: id=%u guid=%llu pos=(%.2f %.2f %.2f)",
            row.entityId,
            static_cast<unsigned long long>(row.entityGuid),
            row.position.x,
            row.position.y,
            row.position.z);
        ImGui::Text("Destination: %llu %s ArkName=%s transitionGo=%d",
            static_cast<unsigned long long>(row.destinationId),
            row.destinationName.c_str(),
            row.arkLocationName.empty() ? "-" : row.arkLocationName.c_str(),
            row.transitionGo ? 1 : 0);
    }
}

void ModMain::OnArkLevelTransitionConfirmed(ArkLevelTransitionDoor* door)
{
    ++m_levelTransitionConfirmedHookCalls;

    if (!door)
    {
        m_lastLevelTransitionEvent = "OnTransitionConfirmed hook: null door";
        LogCoop(m_lastLevelTransitionEvent);
        return;
    }

    if (!IsLikelyRuntimeCppObject(door, sizeof(ArkLevelTransitionDoor)))
    {
        ++m_levelTransitionGuardSkips;
        m_lastLevelTransitionEvent = "OnTransitionConfirmed hook: guarded invalid door pointer";
        LogCoop(m_lastLevelTransitionEvent);
        return;
    }

    m_arkLevelTransitionLoadActive = true;
    m_runtimeTransitionCleanupPrepared = false;
    m_transitionRuntimeProxyEntityIds.clear();
    m_transitionRuntimeEntityIds.clear();
    m_sessionGameplayReady = false;
    m_sessionStatus = "native transition";
    m_networkStatus = "native transition session paused";

    std::string guardReason;
    EntityId entityId = INVALID_ENTITYID;
    IEntity* entity = nullptr;
    if (!TryGuardedCall("ArkLevelTransitionDoor::GetEntityId hook", [door]() { return door->GetEntityId(); }, entityId, &guardReason) ||
        !TryGuardedCall("ArkLevelTransitionDoor::GetEntity hook", [door]() { return door->GetEntity(); }, entity, &guardReason))
    {
        ++m_levelTransitionGuardSkips;
        m_lastLevelTransitionEvent = "OnTransitionConfirmed hook: guarded entity read failed";
        LogCoop(m_lastLevelTransitionEvent);
        return;
    }

    std::string entityName = "-";
    if (IsLikelyRuntimeCppObject(entity))
    {
        const char* entityNameRaw = nullptr;
        if (TryGuardedCall("IEntity::GetName transition hook", [entity]() { return entity->GetName(); }, entityNameRaw, &guardReason))
            entityName = ReadRuntimeCString(entityNameRaw, 128);
        if (entityName.empty())
            entityName = "-";
    }

    uint64_t destinationId = 0;
    bool locked = false;
    bool inaccessible = false;
    if (!TryReadRuntimeValue(&door->m_locationId, destinationId) ||
        !TryReadRuntimeValue(&door->m_bLocked, locked) ||
        !TryReadRuntimeValue(&door->m_bInaccessible, inaccessible))
    {
        ++m_levelTransitionGuardSkips;
        m_lastLevelTransitionEvent = "OnTransitionConfirmed hook: guarded field read failed";
        LogCoop(m_lastLevelTransitionEvent);
        return;
    }

    const std::string destinationName = GetLocationDebugName(destinationId);
    m_pendingArkTransitionLocationId = destinationId;

    m_lastLevelTransitionEvent =
        "OnTransitionConfirmed door=" + std::to_string(entityId) +
        " name=" + entityName +
        " dest=" + std::to_string(destinationId) +
        " " + destinationName +
        " locked=" + std::to_string(locked ? 1 : 0) +
        " inaccessible=" + std::to_string(inaccessible ? 1 : 0);
    LogCoop(m_lastLevelTransitionEvent);

    if (m_networkMode != CoopNetworkMode::Off)
    {
        SetTransitionPhase("native_transition_confirmed", destinationName.c_str());
        RefreshCoopRuntimeEntitySaveFlags("native transition confirmed");
        m_lastRuntimeEntityFlagsEvent = BuildRuntimeEntityFlagSnapshot("native transition confirmed");
        LogCoop(m_lastRuntimeEntityFlagsEvent);
        m_lastRuntimePerceptionEvent = BuildRuntimePerceptionSnapshot("before native transition original no-pre-purge");
        LogCoop(m_lastRuntimePerceptionEvent);
        RemoveRuntimeEntitiesBeforeNativeTransition("native transition confirmed");
        ResetReplicationSequenceGuardsForWorldChange("native transition begin");
        if (m_networkMode == CoopNetworkMode::Client && m_areaLeaseActive && m_areaLeaseLocalReady)
            SendClientAreaLeaseCommand(CoopProtocol::AreaLeaseCommand::Freeze, "native transition confirmed");
        m_sessionGameplayReady = false;
        m_sessionStatus = "native transition";
        m_networkStatus = "native transition session paused";
    }
}

void ModMain::OnArkLevelTransitionDoorUpdated(ArkLevelTransitionDoor* door)
{
    if (m_networkMode == CoopNetworkMode::Off ||
        m_saveLoadGuardActive ||
        m_arkLevelTransitionLoadActive ||
        !IsGameReady() ||
        !door ||
        !IsLikelyRuntimeCppObject(door, sizeof(ArkLevelTransitionDoor)) ||
        !gEnv ||
        !gEnv->pEntitySystem)
    {
        return;
    }

    IEntity* doorEntity = nullptr;
    EntityId doorEntityId = INVALID_ENTITYID;
    EntityId screenEntityId = INVALID_ENTITYID;
    bool transitionGo = false;
    std::string guardReason;
    if (!TryGuardedCall(
            "transition presentation door GetEntity",
            [door]() { return door->GetEntity(); },
            doorEntity,
            &guardReason) ||
        !doorEntity ||
        !TryGuardedCall(
            "transition presentation door GetEntityId",
            [door]() { return door->GetEntityId(); },
            doorEntityId,
            &guardReason) ||
        !TryReadRuntimeValue(&door->m_worldUIOwner.m_worldUI, screenEntityId) ||
        !TryReadRuntimeValue(&door->m_bLevelTransitionGo, transitionGo) ||
        screenEntityId == INVALID_ENTITYID)
    {
        return;
    }

    IEntity* screenEntity = nullptr;
    if (!TryGuardedCall(
            "transition presentation GetEntity screen",
            [screenEntityId]() { return gEnv->pEntitySystem->GetEntity(screenEntityId); },
            screenEntity,
            &guardReason) ||
        !screenEntity ||
        !IsLikelyRuntimeCppObject(screenEntity))
    {
        return;
    }

    Vec3 screenWorldPosition(ZERO);
    Quat screenWorldRotation(IDENTITY);
    if (TryGuardedCall(
            "transition screen location world position",
            [screenEntity]() { return screenEntity->GetWorldPos(); },
            screenWorldPosition,
            &guardReason) &&
        TryGuardedCall(
            "transition screen location world rotation",
            [screenEntity]() { return screenEntity->GetWorldRotation(); },
            screenWorldRotation,
            &guardReason))
    {
        QuatT correctedLocal(screenWorldRotation, screenWorldPosition);
        if (TryCorrectTransitionWorldUIScreenLocation(
                &door->m_worldUIOwner,
                correctedLocal))
        {
            const Vec3 screenScale = screenEntity->GetScale();
            const bool transformOk = TryGuardedVoidCall(
                "transition screen location SetPosRotScale local",
                [screenEntity, correctedLocal, screenScale]()
                {
                    screenEntity->SetPosRotScale(
                        correctedLocal.t,
                        correctedLocal.q,
                        screenScale,
                        ENTITY_XFORM_USER);
                },
                &guardReason);
            if (transformOk)
            {
                Vec3 repairedWorldPosition(ZERO);
                TryGuardedCall(
                    "transition screen location repaired world position",
                    [screenEntity]() { return screenEntity->GetWorldPos(); },
                    repairedWorldPosition,
                    &guardReason);
                if (m_lastLevelTransitionScreenLocationOwnerId != doorEntityId)
                {
                    m_lastLevelTransitionScreenLocationOwnerId = doorEntityId;
                    ++m_levelTransitionScreenLocationCorrections;
                    m_lastLevelTransitionScreenLocationEvent =
                        "corrected transition screen local transform owner=" +
                        std::to_string(doorEntityId) +
                        " screen=" + std::to_string(screenEntityId) +
                        " rawWorld=" + FormatVec3Trace(screenWorldPosition) +
                        " local=" + FormatVec3Trace(correctedLocal.t) +
                        " repairedWorld=" + FormatVec3Trace(repairedWorldPosition);
                    LogCoop(m_lastLevelTransitionScreenLocationEvent);
                }
            }
            else
            {
                ++m_levelTransitionPresentationFailures;
                m_lastLevelTransitionScreenLocationEvent =
                    "failed transition screen local transform owner=" +
                    std::to_string(doorEntityId) +
                    " screen=" + std::to_string(screenEntityId) +
                    " reason=" + (guardReason.empty() ? std::string("-") : guardReason);
                LogCoop(m_lastLevelTransitionScreenLocationEvent);
            }
        }
    }

    uint32_t doorFlags = 0;
    uint32_t screenFlags = 0;
    if (!TryGuardedCall(
            "transition presentation door GetFlags",
            [doorEntity]() { return doorEntity->GetFlags(); },
            doorFlags,
            &guardReason) ||
        !TryGuardedCall(
            "transition presentation screen GetFlags",
            [screenEntity]() { return screenEntity->GetFlags(); },
            screenFlags,
            &guardReason))
    {
        return;
    }

    const uint32_t renderEventFlag = static_cast<uint32_t>(ENTITY_FLAG_SEND_RENDER_EVENT);
    const bool missingDoorRenderEvent = (doorFlags & renderEventFlag) == 0;
    const bool missingScreenRenderEvent = (screenFlags & renderEventFlag) == 0;
    if (!missingDoorRenderEvent && !missingScreenRenderEvent)
    {
        m_levelTransitionPresentationAttemptEpochs.erase(doorEntityId);
        return;
    }

    const uint64_t repairEpoch =
        (static_cast<uint64_t>(m_postLoadNativeCompleteCount) << 32u) |
        static_cast<uint64_t>(m_transitionPhaseSerial);
    const auto attemptIt = m_levelTransitionPresentationAttemptEpochs.find(doorEntityId);
    if (attemptIt != m_levelTransitionPresentationAttemptEpochs.end() &&
        attemptIt->second == repairEpoch)
    {
        return;
    }
    m_levelTransitionPresentationAttemptEpochs[doorEntityId] = repairEpoch;

    // A confirmed exterior transition can be interrupted by the other peer's
    // world handoff. Vanilla can then leave the owner and its generated green
    // ArkWorldUI surface with render events disabled. The location repair
    // above independently handles the rarer double-owner-transform failure.
    // Here, use native cancellation cleanup for a stale transition, restore
    // only the exact flag present on healthy sibling doors, and refresh the UI.
    bool cancelOk = true;
    if (transitionGo)
    {
        cancelOk = TryGuardedVoidCall(
            "transition presentation OnTransitionCancelled",
            [door]() { door->OnTransitionCancelled(); },
            &guardReason);
        if (cancelOk)
            ++m_levelTransitionPresentationCancelCalls;
    }

    const bool doorFlagsOk = !missingDoorRenderEvent ||
        TryGuardedVoidCall(
            "transition presentation door SetFlags",
            [doorEntity, doorFlags, renderEventFlag]()
            {
                doorEntity->SetFlags(doorFlags | renderEventFlag);
            },
            &guardReason);
    const bool screenFlagsOk = !missingScreenRenderEvent ||
        TryGuardedVoidCall(
            "transition presentation screen SetFlags",
            [screenEntity, screenFlags, renderEventFlag]()
            {
                screenEntity->SetFlags(screenFlags | renderEventFlag);
            },
            &guardReason);
    const bool refreshOk = TryGuardedVoidCall(
        "transition presentation RefreshUI",
        [door]() { door->RefreshUI(); },
        &guardReason);

    if (cancelOk && doorFlagsOk && screenFlagsOk && refreshOk)
    {
        ++m_levelTransitionPresentationRepairs;
        m_lastLevelTransitionPresentationEvent =
            "repaired transition presentation door=" + std::to_string(doorEntityId) +
            " screen=" + std::to_string(screenEntityId) +
            " transitionGo=" + std::to_string(transitionGo ? 1 : 0) +
            " doorFlags=" + Hex32(doorFlags) +
            " screenFlags=" + Hex32(screenFlags);
        LogCoop(m_lastLevelTransitionPresentationEvent);
    }
    else
    {
        ++m_levelTransitionPresentationFailures;
        m_lastLevelTransitionPresentationEvent =
            "failed transition presentation repair door=" + std::to_string(doorEntityId) +
            " screen=" + std::to_string(screenEntityId) +
            " reason=" + (guardReason.empty() ? std::string("-") : guardReason);
        LogCoop(m_lastLevelTransitionPresentationEvent);
    }
}

bool ModMain::TryCorrectTransitionWorldUIScreenLocation(
    const ArkWorldUIOwner* owner,
    QuatT& location)
{
    if (m_networkMode == CoopNetworkMode::Off ||
        !owner ||
        !IsLikelyRuntimeCppObject(owner, sizeof(ArkWorldUIOwner)) ||
        !location.IsValid())
    {
        return false;
    }

    ArkInteractiveScreen* interactiveScreen = nullptr;
    IEntity* ownerEntity = nullptr;
    IEntityClass* ownerClass = nullptr;
    const char* rawClassName = nullptr;
    EntityId ownerEntityId = INVALID_ENTITYID;
    EntityId screenEntityId = INVALID_ENTITYID;
    Vec3 ownerPosition(ZERO);
    Quat ownerRotation(IDENTITY);
    std::string guardReason;
    if (!TryGuardedCall(
            "transition screen location interactive screen",
            [owner]() { return &owner->m_interactiveScreen; },
            interactiveScreen,
            &guardReason) ||
        !IsLikelyRuntimeCppObject(interactiveScreen) ||
        !TryGuardedCall(
            "transition screen location owner entity",
            [interactiveScreen]() { return interactiveScreen->GetEntity(); },
            ownerEntity,
            &guardReason) ||
        !ownerEntity ||
        !IsLikelyRuntimeCppObject(ownerEntity) ||
        !TryGuardedCall(
            "transition screen location owner class",
            [ownerEntity]() { return ownerEntity->GetClass(); },
            ownerClass,
            &guardReason) ||
        !IsLikelyRuntimeCppObject(ownerClass) ||
        !TryGuardedCall(
            "transition screen location owner class name",
            [ownerClass]() { return ownerClass->GetName(); },
            rawClassName,
            &guardReason) ||
        !RuntimeCStringEquals(rawClassName, "ArkLevelTransitionDoor", 64) ||
        !TryGuardedCall(
            "transition screen location owner id",
            [ownerEntity]() { return ownerEntity->GetId(); },
            ownerEntityId,
            &guardReason) ||
        !TryReadRuntimeValue(&owner->m_worldUI, screenEntityId) ||
        screenEntityId == INVALID_ENTITYID ||
        !TryGuardedCall(
            "transition screen location owner position",
            [ownerEntity]() { return ownerEntity->GetWorldPos(); },
            ownerPosition,
            &guardReason) ||
        !TryGuardedCall(
            "transition screen location owner rotation",
            [ownerEntity]() { return ownerEntity->GetWorldRotation(); },
            ownerRotation,
            &guardReason) ||
        !IsFiniteVec3Trace(ownerPosition) ||
        !ownerRotation.IsValid())
    {
        return false;
    }

    IEntity* screenEntity = nullptr;
    IEntity* parentEntity = nullptr;
    if (!gEnv ||
        !gEnv->pEntitySystem ||
        !TryGuardedCall(
            "transition screen location screen entity",
            [screenEntityId]() { return gEnv->pEntitySystem->GetEntity(screenEntityId); },
            screenEntity,
            &guardReason) ||
        !screenEntity ||
        !TryGuardedCall(
            "transition screen location parent entity",
            [screenEntity]() { return screenEntity->GetParent(); },
            parentEntity,
            &guardReason) ||
        parentEntity != ownerEntity)
    {
        return false;
    }

    // A healthy transition screen is about 1.3 m from its door. In the
    // observed corrupted save, that authored world-space transform was stored
    // on the generated ArkWorldUI entity as its owner-local transform:
    //
    //     badScreenWorld = doorWorld * correctScreenWorld
    //
    // Undo the repeated owner transform once to recover the intended world
    // mount, validate that it is close to this exact parent door, then convert
    // it to the local transform consumed by SetPosRotScale.
    constexpr float kMinimumBrokenDistanceSq = 64.0f;
    constexpr float kMaximumRecoveredDistanceSq = 16.0f;
    if ((location.t - ownerPosition).GetLengthSquared() <= kMinimumBrokenDistanceSq)
        return false;

    ownerRotation.Normalize();
    const QuatT ownerWorld(ownerRotation, ownerPosition);
    const QuatT recoveredWorld = ownerWorld.GetInverted() * location;
    if (!recoveredWorld.IsValid() ||
        (recoveredWorld.t - ownerPosition).GetLengthSquared() > kMaximumRecoveredDistanceSq)
    {
        return false;
    }

    QuatT correctedLocal = ownerWorld.GetInverted() * recoveredWorld;
    if (!correctedLocal.IsValid())
        return false;
    correctedLocal.q.Normalize();
    location = correctedLocal;
    return true;
}

void ModMain::OnArkSaveLoadSaveCurrentLevelState(ArkSaveLoadSystem* saveLoadSystem, bool beforeOriginal)
{
    if (beforeOriginal)
        ++m_levelStateSaveCalls;

    bool inTransition = false;
    bool restoring = false;
    bool guarded = false;
    std::string guardReason;

    if (IsLikelyRuntimeCppObject(saveLoadSystem, sizeof(ArkSaveLoadSystem)))
    {
        if (!TryGuardedCall("ArkSaveLoadSystem::InLevelTransition save-state hook",
                [saveLoadSystem]() { return saveLoadSystem->InLevelTransition(); }, inTransition, &guardReason))
        {
            guarded = true;
        }

        if (!TryGuardedCall("ArkSaveLoadSystem::IsRestoringLevelState save-state hook",
                [saveLoadSystem]() { return saveLoadSystem->IsRestoringLevelState(); }, restoring, &guardReason))
        {
            guarded = true;
        }
    }
    else
    {
        guarded = true;
        guardReason = "invalid ArkSaveLoadSystem pointer";
    }

    const std::string levelName = NormalizeLevelName(GetCurrentLevelName());
    m_areaStateJournal.NoteLevelStateSave(
        levelName,
        beforeOriginal ? CoopAreaStateJournal::LevelStatePhase::BeforeOriginal : CoopAreaStateJournal::LevelStatePhase::AfterOriginal);

    m_lastLevelStateEvent =
        std::string(beforeOriginal ? "before" : "after") +
        " SaveCurrentLevelState level=" + levelName +
        " inTransition=" + std::to_string(inTransition ? 1 : 0) +
        " restoring=" + std::to_string(restoring ? 1 : 0) +
        " guarded=" + std::to_string(guarded ? 1 : 0);

    if (guarded && !guardReason.empty())
        m_lastLevelStateEvent += " reason=" + guardReason;

    LogCoop(m_lastLevelStateEvent);
    LogCoop("area journal " + m_areaStateJournal.GetLastEvent());

    const bool transitionActive =
        m_saveLoadGuardActive ||
        m_pendingPostLoadResync ||
        m_arkLevelTransitionLoadActive ||
        inTransition;

    if (m_networkMode != CoopNetworkMode::Off && transitionActive)
    {
        SetTransitionPhase(beforeOriginal ? "save_current_levelstate_before" : "save_current_levelstate_after", levelName.c_str());
        if (beforeOriginal)
            RefreshCoopRuntimeEntitySaveFlags("before SaveCurrentLevelState");
        m_lastRuntimeEntityFlagsEvent = BuildRuntimeEntityFlagSnapshot(beforeOriginal ? "before SaveCurrentLevelState" : "after SaveCurrentLevelState");
        LogCoop(m_lastRuntimeEntityFlagsEvent);
    }

    if (m_networkMode == CoopNetworkMode::Client && transitionActive)
    {
        const bool nativeDoorTravelSave =
            beforeOriginal &&
            m_arkLevelTransitionLoadActive &&
            !m_saveLoadGuardActive &&
            !m_pendingPostLoadResync;

        if (nativeDoorTravelSave)
        {
            m_lastClientLevelStateBridgeEvent =
                "prepare skipped before SaveCurrentLevelState during native door travel";
            LogCoop("client levelstate bridge " + m_lastClientLevelStateBridgeEvent);
        }
        else if (beforeOriginal)
        {
            PrepareClientCoopLevelStateBridge(saveLoadSystem, "before SaveCurrentLevelState");
        }
    }

    if (!beforeOriginal && m_networkMode != CoopNetworkMode::Off && transitionActive)
        PrepareCoopRuntimeEntitiesForLevelTransition("after SaveCurrentLevelState");

    if (!beforeOriginal &&
        m_networkMode != CoopNetworkMode::Off &&
        !m_areaJournalTransferSending &&
        !m_areaJournalTransferReceiving)
    {
        const bool hostOwnsSavedLevel =
            m_networkMode == CoopNetworkMode::Host ||
            (m_networkMode == CoopNetworkMode::Client &&
                !m_remoteLevelName.empty() &&
                IsKnownSameLevel(levelName, m_remoteLevelName));
        const bool remoteOwnsSavedLevel =
            transitionActive &&
            ShouldSuppressHostAreaJournalForRemoteOwnedLevel(levelName);

        if (transitionActive)
        {
            if (hostOwnsSavedLevel)
            {
                m_lastAreaJournalTransferEvent =
                    "area journal transfer skipped during transition: host owns level=" + levelName;
                LogCoop(m_lastAreaJournalTransferEvent);
            }
            else if (remoteOwnsSavedLevel)
            {
                m_lastAreaJournalTransferEvent =
                    "area journal transfer skipped during transition: remote owns level=" + levelName;
                LogCoop(m_lastAreaJournalTransferEvent);
            }
            else
            {
                QueueDeferredAreaJournalTransfer("native area save during transition", levelName);
            }
        }
        else
        {
            BeginAreaJournalTransfer("native area save", levelName);
        }
    }
}

void ModMain::OnArkSaveLoadLoadCurrentLevelState(ArkSaveLoadSystem* saveLoadSystem, bool beforeOriginal)
{
    if (beforeOriginal)
        ++m_levelStateLoadCalls;

    bool inTransition = false;
    bool restoring = false;
    bool guarded = false;
    std::string guardReason;

    if (IsLikelyRuntimeCppObject(saveLoadSystem, sizeof(ArkSaveLoadSystem)))
    {
        if (!TryGuardedCall("ArkSaveLoadSystem::InLevelTransition load-state hook",
                [saveLoadSystem]() { return saveLoadSystem->InLevelTransition(); }, inTransition, &guardReason))
        {
            guarded = true;
        }

        if (!TryGuardedCall("ArkSaveLoadSystem::IsRestoringLevelState load-state hook",
                [saveLoadSystem]() { return saveLoadSystem->IsRestoringLevelState(); }, restoring, &guardReason))
        {
            guarded = true;
        }
    }
    else
    {
        guarded = true;
        guardReason = "invalid ArkSaveLoadSystem pointer";
    }

    const std::string levelName = NormalizeLevelName(GetCurrentLevelName());
    m_areaStateJournal.NoteLevelStateLoad(
        levelName,
        beforeOriginal ? CoopAreaStateJournal::LevelStatePhase::BeforeOriginal : CoopAreaStateJournal::LevelStatePhase::AfterOriginal);

    m_lastLevelStateEvent =
        std::string(beforeOriginal ? "before" : "after") +
        " LoadCurrentLevelState level=" + levelName +
        " inTransition=" + std::to_string(inTransition ? 1 : 0) +
        " restoring=" + std::to_string(restoring ? 1 : 0) +
        " guarded=" + std::to_string(guarded ? 1 : 0);

    if (guarded && !guardReason.empty())
        m_lastLevelStateEvent += " reason=" + guardReason;

    LogCoop(m_lastLevelStateEvent);
    LogCoop("area journal " + m_areaStateJournal.GetLastEvent());

    const bool transitionActive =
        m_saveLoadGuardActive ||
        m_pendingPostLoadResync ||
        m_arkLevelTransitionLoadActive ||
        inTransition ||
        restoring;

    if (m_networkMode != CoopNetworkMode::Off && transitionActive)
    {
        SetTransitionPhase(beforeOriginal ? "load_current_levelstate_before" : "load_current_levelstate_after", levelName.c_str());
        m_lastRuntimeEntityFlagsEvent = BuildRuntimeEntityFlagSnapshot(beforeOriginal ? "before LoadCurrentLevelState" : "after LoadCurrentLevelState");
        LogCoop(m_lastRuntimeEntityFlagsEvent);
    }

    if (m_networkMode == CoopNetworkMode::Client && transitionActive)
    {
        if (beforeOriginal)
            PrepareClientCoopLevelStateBridge(saveLoadSystem, "before LoadCurrentLevelState");
    }

    if (!beforeOriginal)
    {
        bool hostEnteringRemoteOwnedArea = false;
        if (m_networkMode == CoopNetworkMode::Host && m_hasRemoteSession)
        {
            for (const auto& entry : m_remotePeers)
            {
                if (entry.second.areaLeaseActive &&
                    IsKnownSameLevel(levelName, entry.second.areaLeaseLevelName))
                {
                    hostEnteringRemoteOwnedArea = true;
                    break;
                }
            }
        }

        if (hostEnteringRemoteOwnedArea)
        {
            const uint64_t restorePeerToken = m_activeRemotePeerToken;
            StoreActiveRemotePeerContext();
            uint64_t handoffPeerToken = 0;
            for (const auto& entry : m_remotePeers)
            {
                if (entry.second.areaLeaseActive &&
                    IsKnownSameLevel(levelName, entry.second.areaLeaseLevelName))
                {
                    handoffPeerToken = entry.first;
                    break;
                }
            }

            if (handoffPeerToken != 0)
                ActivateRemotePeerContext(handoffPeerToken);
            m_pendingRemoteAreaHandoffRequestLevel = levelName;
            if (m_areaLeaseActive && IsKnownSameLevel(levelName, m_areaLeaseLevelName))
            {
                // Keep the authority token valid until the final snapshot
                // arrives; releasing it here invalidates the requested handoff.
                m_areaLeaseAwaitingHandoffSnapshot = true;
                m_areaLeaseHandoffWaitSeconds = 120.0f;
            }
            StoreActiveRemotePeerContext();
            if (restorePeerToken != 0 && restorePeerToken != m_activeRemotePeerToken)
                ActivateRemotePeerContext(restorePeerToken);

            m_lastAreaOverlayEvent =
                "server area overlay skipped: pending remote handoff level=" + levelName;
            LogCoop(m_lastAreaOverlayEvent);
        }
        else
        {
            QueueServerAreaStateOverlayForLevel(levelName, "native area load");
        }
    }
}

bool ModMain::OnCEntitySerializeHook(IEntity* entity, bool reading, int target, int flags)
{
    if (m_networkMode == CoopNetworkMode::Off ||
        (!m_saveLoadGuardActive && !m_pendingPostLoadResync && !m_arkLevelTransitionLoadActive))
    {
        return false;
    }

    if (!IsLikelyRuntimeCppObject(entity))
        return false;

    std::string guardReason;
    EntityId entityId = INVALID_ENTITYID;
    if (!TryGuardedCall("CEntity::Serialize coop runtime GetId", [entity]() { return entity->GetId(); }, entityId, &guardReason))
        return false;

    bool tracked =
        IsRemoteProxyEntity(entityId) ||
        entityId == m_mimicEntityId ||
        IsEnemyPuppetEntity(entityId);

    const char* rawName = nullptr;
    if (!tracked &&
        TryGuardedCall("CEntity::Serialize coop runtime GetName", [entity]() { return entity->GetName(); }, rawName, &guardReason))
    {
        tracked = IsCoopRuntimeEntityName(rawName);
    }

    if (!tracked)
        return false;

    ++m_coopRuntimeEntitySerializeCalls;

    uint32_t entityFlags = 0;
    uint64_t archetypeId = 0;
    IEntityArchetype* archetype = nullptr;
    TryGuardedCall("CEntity::Serialize coop runtime GetFlags", [entity]() { return entity->GetFlags(); }, entityFlags, &guardReason);
    if (TryGuardedCall("CEntity::Serialize coop runtime GetArchetype", [entity]() { return entity->GetArchetype(); }, archetype, &guardReason) &&
        archetype)
    {
        TryGuardedCall("CEntity::Serialize coop runtime archetype id", [archetype]() { return archetype->GetId(); }, archetypeId, &guardReason);
    }
    if (!rawName)
        TryGuardedCall("CEntity::Serialize coop runtime GetName second", [entity]() { return entity->GetName(); }, rawName, &guardReason);

    m_lastRuntimeEntitySerializeEvent =
        "coop runtime entity CEntity::Serialize count=" +
        std::to_string(m_coopRuntimeEntitySerializeCalls) +
        " id=" + std::to_string(entityId) +
        " reading=" + std::to_string(reading ? 1 : 0) +
        " target=" + std::to_string(target) +
        " nFlags=" + Hex32(static_cast<uint32_t>(flags)) +
        " entityFlags=" + Hex32(entityFlags) +
        " noSave=" + std::to_string((entityFlags & static_cast<uint32_t>(ENTITY_FLAG_NO_SAVE)) ? 1 : 0) +
        " localPlayer=" + std::to_string((entityFlags & static_cast<uint32_t>(ENTITY_FLAG_LOCAL_PLAYER)) ? 1 : 0) +
        " unremovable=" + std::to_string((entityFlags & static_cast<uint32_t>(ENTITY_FLAG_UNREMOVABLE)) ? 1 : 0) +
        " archetype=" + std::to_string(archetypeId) +
        " name=" + StatusToken(ReadRuntimeCString(rawName, 64));

    const bool skipOriginal =
        !reading &&
        target == static_cast<int>(eST_SaveGame);
    if (skipOriginal)
    {
        ++m_coopRuntimeEntitySerializeSkips;
        m_lastRuntimeEntitySerializeEvent += " action=skip_original";
    }
    else
    {
        m_lastRuntimeEntitySerializeEvent += " action=allow_original";
    }

    if (m_coopRuntimeEntitySerializeLogs < 16 || (m_coopRuntimeEntitySerializeCalls % 64) == 0)
    {
        ++m_coopRuntimeEntitySerializeLogs;
        LogCoop(m_lastRuntimeEntitySerializeEvent);
    }

    return skipOriginal;
}

void ModMain::OnArkGameSerializeForLevelStateHook(
    ArkGame* game,
    const char* phase,
    bool reading,
    int target,
    bool ok,
    const char* serializerFingerprint,
    std::uintptr_t serializerImpl,
    std::uintptr_t serializerVtable)
{
    (void)serializerImpl;
    if (phase && std::strcmp(phase, "before") == 0)
    {
        ++m_levelStateArkGameSerializeCalls;
        if (reading)
            ++m_levelStateArkGameSerializeReadCalls;
    }

    if (serializerVtable != 0 && m_levelStateSerializerVtableLabels.find(serializerVtable) == m_levelStateSerializerVtableLabels.end())
    {
        const std::string label = std::string("ArkGameLevelState_") + (reading ? "read" : "write");
        m_levelStateSerializerVtableLabels.emplace(serializerVtable, label);
        if (EnvFlagEnabled("COOP_TRACE_SERIALIZER_VTABLES"))
        {
            ++m_levelStateSerializerVtableDumps;
            m_lastLevelStateSerializerVtableEvent = DumpSerializerVtable(serializerVtable, label, 12);
            LogCoop(DumpSerializerVtable(serializerVtable, label, 32));
        }
    }

    std::string guardReason;
    uint64_t locationId = 0;
    bool inLevelTransition = false;
    bool guarded = false;
    if (game && IsLikelyRuntimeCppObject(game))
    {
        if (!TryGuardedCall("ArkGame::GetCurrentLocationId level-state serialize hook",
                [game]() { return game->GetCurrentLocationId(); }, locationId, &guardReason))
        {
            guarded = true;
        }
        if (!TryGuardedCall("ArkGame::InLevelToLevelTransition level-state serialize hook",
                [game]() { return game->InLevelToLevelTransition(); }, inLevelTransition, &guardReason))
        {
            guarded = true;
        }
    }
    else
    {
        guarded = true;
        guardReason = "invalid ArkGame pointer";
    }

    m_lastLevelStateSerializeEvent =
        std::string("ArkGame::SerializeForLevelState ") + (phase ? phase : "?") +
        " level=" + NormalizeLevelName(GetCurrentLevelName()) +
        " reading=" + std::to_string(reading ? 1 : 0) +
        " target=" + std::to_string(target) +
        " ok=" + std::to_string(ok ? 1 : 0) +
        " " + (serializerFingerprint && serializerFingerprint[0] ? serializerFingerprint : "ser=-") +
        " location=" + std::to_string(locationId) +
        " ltl=" + std::to_string(inLevelTransition ? 1 : 0) +
        " guarded=" + std::to_string(guarded ? 1 : 0);
    if (guarded && !guardReason.empty())
        m_lastLevelStateSerializeEvent += " reason=" + guardReason;

    LogCoop(m_lastLevelStateSerializeEvent);
}

bool ModMain::ShouldTraceLevelStateSerializer() const
{
    return m_levelStateSerializerTraceEnabled;
}

bool ModMain::ShouldTraceLevelStateSerializerSource(const char* source) const
{
    if (!m_levelStateSerializerTraceEnabled)
        return false;

    const bool clientHostPlayerLoad =
        m_networkMode == CoopNetworkMode::Client &&
        (m_pendingReceivedPlayerStateApply ||
            m_pendingNativePlayerStateOverrideValid ||
            m_clientAwaitingHostPlayerState);
    if (!clientHostPlayerLoad)
        return true;

    const std::string_view safeSource = source && source[0] ? std::string_view(source) : std::string_view();
    if (safeSource.rfind("ArkInventory::FullSerialize", 0) == 0)
        return true;
    if (safeSource.rfind("CArkItem::FullSerialize(player-inventory-item)", 0) == 0)
        return true;

    // During client host-save import ArkPlayer/ArkGame traces can consume the
    // entire trace budget before the inventory serializer runs. Keep the trace
    // focused on the sources that are currently overwriting per-client inventory.
    return false;
}

uint32_t ModMain::GetLevelStateSerializerTraceLimit() const
{
    return std::max<uint32_t>(1, m_levelStateSerializerTraceLimit);
}

void ModMain::RecordLevelStateSerializerTraceOp(
    const char* source,
    const char* op,
    const char* name,
    const char* typeName,
    bool reading,
    int depth,
    const char* detail)
{
    if (!m_levelStateSerializerTraceEnabled)
        return;

    if (!ShouldTraceLevelStateSerializerSource(source))
        return;

    if (op && std::strcmp(op, "call-begin") == 0)
        ++m_levelStateSerializerTraceCalls;

    const std::string safeSource = source && source[0] ? std::string(source) : std::string("-");
    const std::string safeOp = op && op[0] ? std::string(op) : std::string("-");
    const std::string safeName = name && name[0] ? std::string(name) : std::string("-");
    const std::string safeType = typeName && typeName[0] ? std::string(typeName) : std::string("-");
    const CoopSaveStateBridge::SchemaSemantic semantic =
        CoopSaveStateBridge::ClassifySerializerPath(safeSource, safeName, safeType, safeOp);
    const size_t semanticIndex = static_cast<size_t>(semantic);
    if (semanticIndex < m_saveSchemaTraceBuckets.size())
        ++m_saveSchemaTraceBuckets[semanticIndex];
    ++m_saveSchemaTraceClassifiedOps;
    if (semantic == CoopSaveStateBridge::SchemaSemantic::Unknown)
        ++m_saveSchemaTraceUnknownOps;
    m_lastSaveSchemaTraceEvent =
        "save_schema_trace"
        " semantic=" + std::string(CoopSaveStateBridge::SemanticName(semantic)) +
        " source=" + safeSource +
        " op=" + safeOp +
        " path=" + StatusToken(safeName) +
        " type=" + StatusToken(safeType) +
        " reading=" + std::to_string(reading ? 1 : 0) +
        " depth=" + std::to_string(std::max(0, depth));

    m_saveStateBridge.RecordSerializerOp(
        safeSource.c_str(),
        safeOp.c_str(),
        safeName.c_str(),
        safeType.c_str(),
        semantic,
        reading,
        depth,
        detail);

    if (m_levelStateSerializerTraceUniqueOnly)
    {
        const std::string key =
            safeSource + "|" +
            safeOp + "|" +
            safeName + "|" +
            safeType + "|" +
            std::to_string(reading ? 1 : 0) + "|" +
            std::to_string(std::max(0, depth));
        auto [it, inserted] = m_levelStateSerializerTraceUniqueKeys.emplace(key, 1);
        if (!inserted)
        {
            ++it->second;
            ++m_levelStateSerializerTraceRepeatedOps;
            return;
        }
    }

    const uint32_t limit = GetLevelStateSerializerTraceLimit();
    if (m_levelStateSerializerTraceOps >= limit)
    {
        ++m_levelStateSerializerTraceDroppedOps;
        if (m_levelStateSerializerTraceDroppedOps == 1)
        {
            m_lastLevelStateSerializerTraceEvent =
                "serializer_trace_dropped limit=" + std::to_string(limit);
            LogCoop(m_lastLevelStateSerializerTraceEvent);
        }
        return;
    }

    ++m_levelStateSerializerTraceOps;
    m_lastLevelStateSerializerTraceEvent =
        "serializer_trace"
        " index=" + std::to_string(m_levelStateSerializerTraceOps) +
        " source=" + safeSource +
        " op=" + safeOp +
        " semantic=" + std::string(CoopSaveStateBridge::SemanticName(semantic)) +
        " name=" + StatusToken(safeName) +
        " type=" + StatusToken(safeType) +
        " reading=" + std::to_string(reading ? 1 : 0) +
        " depth=" + std::to_string(std::max(0, depth));
    if (detail && detail[0])
        m_lastLevelStateSerializerTraceEvent += " detail=" + StatusToken(detail);

    LogCoop(m_lastLevelStateSerializerTraceEvent);
}

void ModMain::RecordNativeGameStateInventoryCellEntityId(
    const char* source,
    const char* path,
    unsigned entityId,
    bool reading,
    int target)
{
    if (entityId == 0)
        return;

    const std::string safeSource = source && source[0] ? std::string(source) : std::string("-");
    const std::string safePath = path && path[0] ? std::string(path) : std::string("-");
    if (safeSource.find("ArkInventory::FullSerialize(local-player)") == std::string::npos)
        return;
    if (safePath != "Inventory/storedItems/i/v/entityId")
        return;

    m_gameStateLocalPlayerInventoryItemIds.insert(entityId);
    if (!reading || m_nativeSideBlobCapture.active)
    {
        if (m_nativeSideBlobCapture.active &&
            !reading &&
            !IsActiveNativeSideBlobCaptureItem(entityId))
        {
            m_lastNativeFragmentPayloadEvent =
                "source inventory cell skipped non-captured entity=" + std::to_string(entityId);
            return;
        }

        m_nativeFragmentLocator.OnInventoryCellEntityId(entityId, safeSource, safePath);
        if (NativeFragmentProgressiveExportEnabled() || NativeFragmentProgressiveCaptureEnabled())
            TryExportNativeFragmentPayload("inventory cell entity id");
    }
    if (reading &&
        m_nativeTargetFragmentCapture.IsActive() &&
        ShouldCaptureNativeFragmentTarget(reading, target, GetNativeInventorySerializeScopeSection()))
    {
        m_nativeTargetFragmentCapture.RecordInventoryCellEntityId(entityId, safeSource, safePath);
    }
}

bool ModMain::TryAttachNativeFragmentPayload(NativeSideBlobCaptureState& target, const char* reason)
{
    const uint32_t maxBytes = GetEnvUIntClamped(
        "COOP_NATIVE_FRAGMENT_CAPTURE_MAX_BYTES",
        4u * 1024u * 1024u,
        0x100u,
        64u * 1024u * 1024u);
    const CoopNativeGameStateFragmentLocator::NativeInventoryFragmentByteCapture capture =
        m_nativeFragmentLocator.CaptureFragmentBytes(maxBytes);
    if (!capture.ok)
    {
        m_lastNativeFragmentPayloadEvent =
            "payload waiting capture=" + capture.reason +
            (reason && reason[0] ? " reason=" + std::string(reason) : "");
        return false;
    }

    const CoopNativeFragmentPayload::BuildResult payload =
        CoopNativeFragmentPayload::BuildInventoryPayload(capture, m_nativeWriteNodeOracleRecords);
    if (!payload.ok)
    {
        m_lastNativeFragmentPayloadEvent =
            "payload build failed " + CoopNativeFragmentPayload::BuildStatus(payload) +
            (reason && reason[0] ? " reason=" + std::string(reason) : "");
        LogCoop(m_lastNativeFragmentPayloadEvent);
        return false;
    }

    const CoopNativeFragmentPayload::ParsedPayload parsed =
        CoopNativeFragmentPayload::ParseInventoryPayload(payload.bytes);
    if (!parsed.ok)
    {
        m_lastNativeFragmentPayloadEvent =
            "payload validate failed " + CoopNativeFragmentPayload::BuildStatus(parsed) +
            (reason && reason[0] ? " reason=" + std::string(reason) : "");
        LogCoop(m_lastNativeFragmentPayloadEvent);
        return false;
    }

    const bool upgraded = CopyNativeFragmentPayloadToCapture(target, parsed, payload.bytes);
    if (upgraded)
        m_lastNativeFragmentImportPayload = target.nativeFragmentPayload;
    else if (target.hasNativeFragmentPayload && !target.nativeFragmentPayload.empty())
        m_lastNativeFragmentImportPayload = target.nativeFragmentPayload;

    m_lastNativeFragmentPayloadEvent =
        std::string(upgraded ? "payload attached " : "payload retained existing ") +
        CoopNativeFragmentPayload::BuildStatus(parsed) +
        (target.hasNativeFragmentPayload
            ? " activeBytes=" + std::to_string(target.nativeFragmentPayloadBytes)
            : " activeBytes=0") +
        (reason && reason[0] ? " reason=" + std::string(reason) : "");
    return target.hasNativeFragmentPayload;
}

bool ModMain::AttachNativeSnapshotSaveToCapture(
    NativeSideBlobCaptureState& capture,
    const std::string& savePathOrName,
    const char* reason)
{
    std::string savePath;
    if (!ResolveReadableSaveFile(savePathOrName, savePath))
    {
        LogCoop(
            "native player snapshot attach failed: save not readable " +
            StatusToken(savePathOrName) +
            (reason && reason[0] ? " reason=" + std::string(reason) : ""));
        return false;
    }

    std::vector<uint8_t> bytes;
    uint32_t checksum = 0;
    if (!ReadBinaryFileLimited(savePath, kMaxNativePlayerSnapshotSaveBytes, bytes, &checksum))
    {
        LogCoop(
            "native player snapshot attach failed: read failed path=" +
            StatusToken(savePath) +
            (reason && reason[0] ? " reason=" + std::string(reason) : ""));
        return false;
    }

    capture.hasNativeSnapshotSave = true;
    capture.nativeSnapshotSaveBytes = static_cast<uint32_t>(bytes.size());
    capture.nativeSnapshotSaveChecksum = checksum;
    capture.nativeSnapshotSave = std::move(bytes);
    LogCoop(
        "native player snapshot attached bytes=" +
        std::to_string(capture.nativeSnapshotSaveBytes) +
        " checksum=" + Hex32(capture.nativeSnapshotSaveChecksum) +
        " path=" + StatusToken(savePath) +
        (reason && reason[0] ? " reason=" + std::string(reason) : ""));
    return true;
}

bool ModMain::TryExportNativeFragmentPayload(const char* reason)
{
    const bool exportFile = NativeFragmentProgressiveExportEnabled();
    const bool progressiveCapture = NativeFragmentProgressiveCaptureEnabled();
    if (!exportFile && !progressiveCapture)
        return false;

    const bool activeCapture =
        progressiveCapture &&
        (m_nativeSideBlobCapture.active ||
            m_nativeSideBlobCapture.sawPlayerWrite ||
            m_nativeSideBlobCapture.sawInventoryWrite ||
            m_nativeSideBlobCapture.sawItemWrite);

    const uint32_t maxBytes = GetEnvUIntClamped(
        "COOP_NATIVE_FRAGMENT_CAPTURE_MAX_BYTES",
        4u * 1024u * 1024u,
        0x100u,
        64u * 1024u * 1024u);
    const CoopNativeGameStateFragmentLocator::NativeInventoryFragmentByteCapture capture =
        m_nativeFragmentLocator.CaptureFragmentBytes(maxBytes);
    if (!capture.ok)
    {
        m_lastNativeFragmentPayloadEvent =
            "payload waiting capture=" + capture.reason +
            (reason && reason[0] ? " reason=" + std::string(reason) : "");
        return false;
    }

    const CoopNativeFragmentPayload::BuildResult payload =
        CoopNativeFragmentPayload::BuildInventoryPayload(capture, m_nativeWriteNodeOracleRecords);
    if (!payload.ok)
    {
        ++m_nativeFragmentPayloadExportFailures;
        m_lastNativeFragmentPayloadEvent =
            "payload build failed " + CoopNativeFragmentPayload::BuildStatus(payload) +
            (reason && reason[0] ? " reason=" + std::string(reason) : "");
        LogCoop(m_lastNativeFragmentPayloadEvent);
        return false;
    }

    const CoopNativeFragmentPayload::ParsedPayload parsed =
        CoopNativeFragmentPayload::ParseInventoryPayload(payload.bytes);
    if (!parsed.ok)
    {
        ++m_nativeFragmentPayloadExportFailures;
        m_lastNativeFragmentPayloadEvent =
            "payload validate failed " + CoopNativeFragmentPayload::BuildStatus(parsed) +
            (reason && reason[0] ? " reason=" + std::string(reason) : "");
        LogCoop(m_lastNativeFragmentPayloadEvent);
        return false;
    }

    if (ShouldPreferNativeFragmentPayload(m_lastNativeFragmentImportPayload, parsed))
    {
        m_lastNativeFragmentImportPayload = payload.bytes;
    }

    bool activeCaptureUpgraded = false;
    if (activeCapture)
    {
        activeCaptureUpgraded =
            CopyNativeFragmentPayloadToCapture(m_nativeSideBlobCapture, parsed, payload.bytes);
        if (activeCaptureUpgraded)
        {
            m_lastNativeFragmentImportPayload = m_nativeSideBlobCapture.nativeFragmentPayload;
        }
    }

    if (!exportFile)
    {
        m_lastNativeFragmentPayloadEvent =
            std::string(activeCaptureUpgraded ? "payload active-capture upgraded " : "payload candidate observed ") +
            CoopNativeFragmentPayload::BuildStatus(parsed) +
            (activeCapture
                ? " activeBytes=" + std::to_string(m_nativeSideBlobCapture.nativeFragmentPayloadBytes)
                : " activeBytes=0") +
            (reason && reason[0] ? " reason=" + std::string(reason) : "");
        return activeCaptureUpgraded;
    }

    if (m_lastNativeFragmentPayloadSchemaHash == payload.schemaHash &&
        m_lastNativeFragmentPayloadContentHash == payload.contentHash &&
        !m_lastNativeFragmentPayloadPath.empty() &&
        m_lastNativeFragmentPayloadPath != "-")
    {
        return true;
    }

    const std::filesystem::path root = GetCoopNativeFragmentPayloadRoot();
    if (root.empty())
    {
        ++m_nativeFragmentPayloadExportFailures;
        m_lastNativeFragmentPayloadEvent = "payload export failed: no profile root";
        return false;
    }

    char fileName[192] = {};
    std::snprintf(
        fileName,
        sizeof(fileName),
        "native_inventory_run_%016llX_schema_%016llX_content_%016llX.cnfp",
        static_cast<unsigned long long>(payload.runId),
        static_cast<unsigned long long>(payload.schemaHash),
        static_cast<unsigned long long>(payload.contentHash));
    const std::filesystem::path path = root / fileName;

    ++m_nativeFragmentPayloadExportAttempts;
    std::string writeReason;
    if (!CoopNativeFragmentPayload::WritePayloadFile(path, payload, &writeReason))
    {
        ++m_nativeFragmentPayloadExportFailures;
        m_lastNativeFragmentPayloadEvent =
            "payload export failed: " + writeReason +
            " " + CoopNativeFragmentPayload::BuildStatus(payload);
        LogCoop(m_lastNativeFragmentPayloadEvent);
        return false;
    }

    ++m_nativeFragmentPayloadExportSuccesses;
    m_nativeFragmentPayloadExportBytes = static_cast<uint32_t>(payload.bytes.size());
    m_lastNativeFragmentPayloadSchemaHash = payload.schemaHash;
    m_lastNativeFragmentPayloadContentHash = payload.contentHash;
    m_lastNativeFragmentPayloadPath = CoopFilesystem::ToUtf8(path);
    m_lastNativeFragmentPayloadEvent =
        "payload exported " + CoopNativeFragmentPayload::BuildStatus(payload) +
        " path=" + CoopFilesystem::ToUtf8(path) +
        (reason && reason[0] ? " reason=" + std::string(reason) : "");
    LogCoop(m_lastNativeFragmentPayloadEvent);
    return true;
}

void ModMain::FinalizeNativeSideBlobCaptureFromSaveComplete(const char* reason, bool saveSucceeded)
{
    const bool hasObservedCapture =
        m_nativeSideBlobCapture.active ||
        m_nativeSideBlobCapture.sawPlayerWrite ||
        m_nativeSideBlobCapture.sawInventoryWrite ||
        m_nativeSideBlobCapture.sawItemWrite;
    if (!hasObservedCapture && !m_nativeSideBlobCapture.hasNativeFragmentPayload)
        return;

    const char* effectiveReason = reason && reason[0] ? reason : "native save complete";
    if (!saveSucceeded)
    {
        ++m_nativeSideBlobCapturedFailures;
        m_lastNativeSideBlobCapturedEvent =
            std::string("native capture discarded: save failed") +
            " reason=" + effectiveReason;
        m_nativeSideBlobCapture = NativeSideBlobCaptureState();
        m_activeNativeFragmentCaptureRunId = 0;
        LogCoop(m_lastNativeSideBlobCapturedEvent);
        return;
    }

    if (hasObservedCapture)
    {
        TryAttachNativeFragmentPayload(m_nativeSideBlobCapture, effectiveReason);
    }

    FinalizeNativeSideBlobCaptureForPlayerState(effectiveReason);
}

void ModMain::TryApplyNativeFragmentTargetNoopPatch(
    const CoopNativeGameStateFragmentLocator::NativeInventoryFragmentBundle& targetBundle,
    const char* reason)
{
    CoopNativeFragmentPayload::ParsedPayload payload;
    payload.reason = "missing_payload";
    if (m_pendingNativePlayerStateOverrideValid &&
        m_pendingNativePlayerStateOverride.hasNativeCapture &&
        m_pendingNativePlayerStateOverride.nativeCapture.hasNativeFragmentPayload)
    {
        payload = CoopNativeFragmentPayload::ParseInventoryPayload(
            m_pendingNativePlayerStateOverride.nativeCapture.nativeFragmentPayload);
        if (!payload.ok && payload.reason.empty())
            payload.reason = "pending_payload_parse_failed";
    }
    else if (!m_lastNativeFragmentImportPayload.empty())
    {
        payload = CoopNativeFragmentPayload::ParseInventoryPayload(m_lastNativeFragmentImportPayload);
        if (!payload.ok && payload.reason.empty())
            payload.reason = "last_payload_parse_failed";
    }

    CoopNativeFragmentResolver::NativeResolverReadiness resolverReadiness;
    resolverReadiness.nativeEntityAllocatorReady =
        CoopNativeEntityIdAllocator::IsNativeEntityAllocatorAvailable();
    const CoopNativeFragmentResolver::InventoryFragmentResolution resolution =
        CoopNativeFragmentResolver::ResolveInventoryFragment(payload, targetBundle, resolverReadiness);

    CoopNativeFragmentApply::ApplyResult apply =
        CoopNativeFragmentApply::TryApplyFullTransplantPlan(
            payload,
            targetBundle,
            resolution.materializerPlan);
    if (!apply.enabled)
    {
        apply = CoopNativeFragmentApply::TryApplySameShapeNumericAttributes(
            payload,
            targetBundle,
            resolution.materializerPlan);
    }
    if (!apply.enabled)
    {
        apply = CoopNativeFragmentApply::TryApplySameShapeNoop(
            payload,
            targetBundle,
            resolution.materializerPlan);
    }

    ++m_nativeFragmentApplyAttempts;
    if (apply.ok)
        ++m_nativeFragmentApplySuccesses;
    else if (apply.enabled)
        ++m_nativeFragmentApplyFailures;

    m_lastNativeFragmentApplyEvent =
        CoopNativeFragmentApply::BuildApplyStatus(apply) +
        "/trigger=" + StatusToken(reason && reason[0] ? std::string(reason) : std::string("-"));
    LogCoop("native fragment apply " + m_lastNativeFragmentApplyEvent);
}

bool ModMain::ShouldProbeSerializerNodeContext(const char* source) const
{
    const bool forcedForNativeCapture = m_nativeSideBlobCapture.active;
    const bool forcedForTargetReadCapture =
        m_nativeTargetFragmentCapture.IsActive() ||
        EnvFlagEnabled("COOP_NATIVE_FRAGMENT_CAPTURE_TARGET_READ");
    const bool forcedForNativeTarget =
        forcedForTargetReadCapture ||
        m_pendingNativePlayerStateOverrideValid &&
        m_pendingNativePlayerStateOverride.hasNativeCapture &&
        m_pendingNativePlayerStateOverride.nativeCapture.hasNativeFragmentPayload;
    if (!forcedForNativeCapture && !forcedForNativeTarget && !EnvFlagEnabled("COOP_SERIALIZER_NODE_PROBE"))
        return false;

    const std::string_view safeSource = source && source[0] ? std::string_view(source) : std::string_view();
    if (!forcedForNativeCapture &&
        !forcedForNativeTarget &&
        !MatchesOptionalEnvSubstring("COOP_SERIALIZER_NODE_PROBE_SOURCE_FILTER", safeSource))
    return false;

    if (!forcedForNativeCapture &&
        !forcedForNativeTarget &&
        EnvFlagEnabled("COOP_SERIALIZER_NODE_PROBE_ALL"))
        return true;

    return
        safeSource.rfind("ArkPlayer::FullSerialize", 0) == 0 ||
        safeSource.rfind("ArkInventory::FullSerialize(local-player)", 0) == 0 ||
        safeSource.rfind("CArkItem::FullSerialize(player-inventory-item)", 0) == 0;
}

bool ModMain::ShouldCaptureNativeFragmentTarget(
    bool reading,
    int target,
    const std::string& sectionName) const
{
    const bool explicitReadCapture = EnvFlagEnabled("COOP_NATIVE_FRAGMENT_CAPTURE_TARGET_READ");
    const bool hasPendingPayload =
        m_pendingNativePlayerStateOverrideValid &&
        m_pendingNativePlayerStateOverride.hasNativeCapture &&
        m_pendingNativePlayerStateOverride.nativeCapture.hasNativeFragmentPayload &&
        !m_pendingNativePlayerStateOverride.nativeCapture.nativeFragmentPayload.empty();
    const bool keepLastReadTarget =
        EnvFlagEnabled("COOP_NATIVE_FRAGMENT_KEEP_LAST_READ_TARGET") ||
        m_networkMode != CoopNetworkMode::Off;

    return
        reading &&
        target == eST_SaveGame &&
        CoopSaveStateBridge::IsGameStateSection(sectionName) &&
        (explicitReadCapture || hasPendingPayload || keepLastReadTarget);
}

void ModMain::RecordSerializerNodeContextProbe(
    const char* source,
    const char* op,
    const char* path,
    ISerialize* serializerImpl)
{
    if (!ShouldProbeSerializerNodeContext(source) || !serializerImpl)
        return;

    const std::string_view safePathView = path && path[0] ? std::string_view(path) : std::string_view();
    const bool targetCaptureCandidate = m_nativeTargetFragmentCapture.IsActive();
    if (!m_nativeSideBlobCapture.active &&
        !targetCaptureCandidate &&
        !MatchesOptionalEnvSubstring("COOP_SERIALIZER_NODE_PROBE_PATH_FILTER", safePathView))
        return;

    const std::string safeSource = source && source[0] ? std::string(source) : std::string("-");
    const std::string safeOp = op && op[0] ? std::string(op) : std::string("-");
    const std::string safePath = path && path[0] ? std::string(path) : std::string("-");
    const bool priorityNativeFragmentProbe =
        (safeSource.find("ArkInventory::FullSerialize(local-player)") != std::string::npos &&
            (safePath == "Inventory/storedItems/i/v" ||
                safePath.rfind("Inventory/storedItems/i/v/", 0) == 0)) ||
        safeSource.find("CArkItem::FullSerialize(player-inventory-item)") != std::string::npos;

    ++m_serializerNodeProbeAttempts;
    const uint32_t logLimit = GetEnvUIntClamped("COOP_SERIALIZER_NODE_PROBE_LIMIT", 80, 1, 5000);
    if (!priorityNativeFragmentProbe && m_serializerNodeProbeAttempts > logLimit)
    {
        if (m_serializerNodeProbeAttempts == logLimit + 1)
        {
            m_lastSerializerNodeProbeEvent =
                "serializer_node_probe_dropped limit=" + std::to_string(logLimit);
            LogCoop(m_lastSerializerNodeProbeEvent);
        }
        return;
    }

    const bool forceDecodeStore = m_nativeSideBlobCapture.active || targetCaptureCandidate;
    SerializerNodeProbeScan scan = ProbeSerializerNodeContext(serializerImpl, forceDecodeStore);
    m_serializerNodeProbeSlots += scan.slots;
    m_serializerNodeProbeCandidates += scan.candidates;
    m_serializerNodeProbeGuards += scan.guards;

    m_lastSerializerNodeProbeEvent =
        "serializer_node_probe"
        " source=" + safeSource +
        " op=" + safeOp +
        " path=" + StatusToken(safePath) +
        " impl=" + PointerHex(serializerImpl) +
        " " + RuntimeRvaText(serializerImpl) +
        " slots=" + std::to_string(scan.slots) +
        " helperStack=" + std::to_string(scan.helperStackSeen ? 1 : 0) +
        " priority=" + std::to_string(priorityNativeFragmentProbe ? 1 : 0) +
        " candidates=" + std::to_string(scan.candidates) +
        " guards=" + std::to_string(scan.guards);
    if (!scan.detail.empty())
        m_lastSerializerNodeProbeEvent += " nodes=" + StatusToken(scan.detail);
    if (scan.storeMap.ok)
    {
        m_lastSaveStoreMapEvent = CoopSaveStoreDecoder::BuildStoreMapStatus(scan.storeMap);
        if (scan.storeMap.readStore)
        {
            const CoopNativeSaveStoreApi::CheckResult apiCheck =
                CoopNativeSaveStoreApi::CheckReadNodeByIndex(scan.storeMap);
            ++m_nativeSaveStoreApiChecks;
            if (apiCheck.ok)
                ++m_nativeSaveStoreApiCheckSuccesses;
            else
                ++m_nativeSaveStoreApiCheckFailures;
            m_lastNativeSaveStoreApiEvent = CoopNativeSaveStoreApi::BuildCheckStatus(apiCheck);

            if (targetCaptureCandidate &&
                CoopNativeSaveBridge::IsTargetReadStoreAugmentPoint(safeSource) &&
                EnvFlagEnabled("COOP_NATIVE_TARGET_READ_FRAGMENT_AUGMENT") &&
                !m_nativeTargetFragmentCapture.HasAttemptedAugment())
            {
                const CoopNativeGameStateFragmentLocator::NativeInventoryFragmentBundle targetBundle =
                    m_nativeTargetFragmentCapture.BuildBundle();
                const bool hasFragmentIds = !targetBundle.inventoryEntityIds.empty();
                if (hasFragmentIds)
                {
                    m_nativeTargetFragmentCapture.MarkAugmentAttempted();
                    const bool augmentOk = CaptureNativeReadStoreFragmentFromStoreMap(
                        scan.storeMap,
                        safeSource.c_str(),
                        "target_read_fragment_augment");
                    const CoopNativeGameStateFragmentLocator::NativeInventoryFragmentBundle augmentedBundle =
                        m_nativeTargetFragmentCapture.BuildBundle();
                    if (augmentedBundle.ok)
                    {
                        TryApplyNativeFragmentTargetNoopPatch(
                            augmentedBundle,
                            "target read-store augment complete");
                        m_nativeTargetFragmentCapture.Complete("target read-store augment complete");
                        m_nativeTargetFragmentCapture.SetLastEvent(
                            "target read-store augment complete " +
                            m_nativeTargetFragmentCapture.BuildBundleStatus());
                    }
                    else if (!augmentOk)
                    {
                        m_nativeTargetFragmentCapture.SetLastEvent(
                            "target read-store augment failed " +
                            m_nativeTargetFragmentCapture.BuildBundleStatus());
                    }
                }
            }
        }
        else if (m_lastNativeSaveStoreApiEvent == "-")
        {
            m_lastNativeSaveStoreApiEvent = "skipped_write_store";
        }
    }

    m_saveStateBridge.RecordSerializerOp(
        safeSource.c_str(),
        "node-probe",
        safePath.c_str(),
        "serializer-node-context",
        CoopSaveStateBridge::SchemaSemantic::Unknown,
        true,
        0,
        m_lastSerializerNodeProbeEvent.c_str());
    if (scan.helperStackSeen)
    {
        m_saveStateBridge.RecordSerializerStoreProbe(
            safeSource.c_str(),
            safeOp.c_str(),
            safePath.c_str(),
            serializerImpl,
            scan.detail.c_str());

        const bool inventoryNode =
            safeSource.find("ArkInventory::FullSerialize(local-player)") != std::string::npos ||
            safePath.find("Inventory/storedItems") != std::string::npos;
        const bool itemNode =
            safeSource.find("CArkItem::FullSerialize(player-inventory-item)") != std::string::npos;

        auto forwardNodeInfo = [&](const NativeDecodedStoreNodeInfo& nodeInfo)
        {
            const bool targetNode =
                nodeInfo.readStore &&
                m_nativeTargetFragmentCapture.IsActive() &&
                targetCaptureCandidate &&
                (nodeInfo.inventoryNode || nodeInfo.itemNode);
            const bool sourceNode =
                !nodeInfo.readStore ||
                m_nativeSideBlobCapture.active;
            if (sourceNode)
            {
                m_nativeFragmentLocator.OnDecodedStoreNode(nodeInfo);
                if (NativeFragmentProgressiveExportEnabled() || NativeFragmentProgressiveCaptureEnabled())
                    TryExportNativeFragmentPayload("serializer node probe");
            }
            if (targetNode)
            {
                m_nativeTargetFragmentCapture.RecordDecodedStoreNode(nodeInfo);
            }
        };

        const bool sampledCaptureEnabled =
            scan.storeMap.ok &&
            !EnvFlagEnabled("COOP_NATIVE_FRAGMENT_DISABLE_SAMPLED_NODE_CAPTURE") &&
            (m_nativeSideBlobCapture.active || targetCaptureCandidate);
        const bool sampleInventoryContextNodes =
            EnvFlagEnabled("COOP_NATIVE_FRAGMENT_SAMPLE_INVENTORY_CONTEXT");
        uint32_t sampledForwarded = 0;
        if (sampledCaptureEnabled)
        {
            for (const CoopSaveStoreDecoder::StoreNodeRecord& record : scan.storeMap.sampledNodes)
            {
                if (inventoryNode && !itemNode && !sampleInventoryContextNodes)
                    continue;
                if (!ShouldForwardSampledSerializerNode(record, scan.nodeIndex))
                    continue;

                NativeDecodedStoreNodeInfo sampledNodeInfo = BuildNativeDecodedStoreNodeInfo(
                    scan.storeMap,
                    record,
                    scan.nodeBlockBegin,
                    safeSource,
                    safeOp,
                    safePath,
                    inventoryNode,
                    itemNode);
                forwardNodeInfo(sampledNodeInfo);
                ++sampledForwarded;
            }
        }

        NativeDecodedStoreNodeInfo nodeInfo;
        nodeInfo.nodeIndex = scan.nodeIndex >= 0 ? static_cast<uint32_t>(scan.nodeIndex) : 0;
        nodeInfo.nodeId = scan.nodeId;
        nodeInfo.attrCursor = scan.attrCursor;
        nodeInfo.attrCount = scan.attrCount;
        nodeInfo.childCursor = scan.childCursor;
        nodeInfo.childCount = scan.childCount;
        nodeInfo.storePtr = scan.store;
        nodeInfo.nodePtr = scan.node;
        nodeInfo.nodeBlockBegin = scan.nodeBlockBegin;
        nodeInfo.nodeBlockEnd = scan.storeMap.nodeBlockEnd;
        if (nodeInfo.nodeBlockEnd <= nodeInfo.nodeBlockBegin && nodeInfo.nodeBlockBegin != 0)
        {
            const uint32_t nodeCount = std::max<uint32_t>(scan.storeMap.nodeCount, nodeInfo.nodeIndex + 1u);
            nodeInfo.nodeBlockEnd =
                nodeInfo.nodeBlockBegin + static_cast<std::uintptr_t>(nodeCount) * 0x50u;
        }
        nodeInfo.nodeCount = scan.storeMap.nodeCount;
        nodeInfo.childIndexBlockBegin = scan.storeMap.currentNode.childIndexBlockBegin;
        nodeInfo.childIndexBlockEnd = scan.storeMap.currentNode.childIndexBlockEnd;
        nodeInfo.attrStringBase = scan.storeMap.attrStringBase;
        nodeInfo.attrNameOffsetTable = scan.storeMap.attrNameOffsetTable;
        nodeInfo.attrTokenContext = scan.storeMap.attrTokenContext;
        nodeInfo.attrTokenIndexBase = scan.storeMap.attrTokenIndexBase;
        nodeInfo.attrTokenBase = scan.storeMap.attrTokenBase;
        nodeInfo.childNameDataBase = scan.storeMap.childNameDataBase;
        nodeInfo.childNameResolverContext = scan.storeMap.childNameResolverContext;
        nodeInfo.childNameOffsetTable = scan.storeMap.childNameOffsetTable;
        nodeInfo.attrVectorBegin = scan.attrVectorBegin;
        nodeInfo.attrVectorEnd = scan.attrVectorEnd;
        nodeInfo.childVectorBegin = scan.childVectorBegin;
        nodeInfo.childVectorEnd = scan.childVectorEnd;
        nodeInfo.readStore = scan.storeMap.readStore;
        nodeInfo.nodeReadable = scan.nodeReadable;
        nodeInfo.nodeValid = scan.nodeValid;
        nodeInfo.inventoryNode = inventoryNode;
        nodeInfo.itemNode = itemNode;
        nodeInfo.source = safeSource;
        nodeInfo.op = safeOp;
        nodeInfo.path = safePath;
        forwardNodeInfo(nodeInfo);

        if (sampledForwarded > 0)
            m_lastSerializerNodeProbeEvent += " sampledCapture=" + std::to_string(sampledForwarded);
    }

    const bool explicitProbeLogging =
        EnvFlagEnabled("COOP_SERIALIZER_NODE_PROBE") ||
        EnvFlagEnabled("COOP_NATIVE_FRAGMENT_LOG_FORCED_NODE_PROBE");
    const bool shouldLog =
        explicitProbeLogging &&
        (priorityNativeFragmentProbe ||
            scan.candidates > 0 ||
            m_serializerNodeProbeLogs < 12 ||
            EnvFlagEnabled("COOP_SERIALIZER_NODE_PROBE_LOG_EMPTY"));
    if (shouldLog)
    {
        ++m_serializerNodeProbeLogs;
        LogCoop(m_lastSerializerNodeProbeEvent);
    }
}

void ModMain::RecordNativeGameStateFragmentCandidate(
    const char* source,
    const char* kind,
    const void* objectPtr,
    const void* serializerPtr,
    bool reading,
    int target,
    const std::string& sectionName)
{
    const std::string safeSource = source && source[0] ? std::string(source) : std::string("-");
    const std::string safeKind = kind && kind[0] ? std::string(kind) : std::string("fragment");
    const bool inventoryFragment = safeKind.find("inventory") != std::string::npos;
    const bool itemFragment = safeKind.find("item") != std::string::npos;
    const CoopSaveStateBridge::SchemaSemantic semantic = inventoryFragment
        ? CoopSaveStateBridge::SchemaSemantic::PlayerInventory
        : itemFragment
            ? CoopSaveStateBridge::SchemaSemantic::Item
            : CoopSaveStateBridge::SchemaSemantic::PlayerCore;

    if (inventoryFragment)
        ++m_nativeGameStateInventoryFragmentCandidates;
    else if (itemFragment)
        ++m_nativeGameStateItemFragmentCandidates;
    else
        ++m_nativeGameStatePlayerFragmentCandidates;

    if (reading)
        ++m_nativeGameStateFragmentReadCandidates;
    else
        ++m_nativeGameStateFragmentWriteCandidates;

    const std::string detail =
        "kind=" + safeKind +
        " section=" + StatusToken(sectionName.empty() ? std::string("-") : sectionName) +
        " object=" + PointerHex(objectPtr) +
        " serializer=" + PointerHex(serializerPtr) +
        " target=" + std::to_string(target);

    m_lastNativeGameStateFragmentEvent =
        "game_state_player_fragment " +
        detail +
        " reading=" + std::to_string(reading ? 1 : 0);

    m_saveStateBridge.RecordSerializerOp(
        safeSource.c_str(),
        "fragment-candidate",
        inventoryFragment
            ? "GameState/local-player/Inventory"
            : itemFragment
                ? "GameState/local-player/Item"
                : "GameState/local-player/Player",
        "-",
        semantic,
        reading,
        0,
        detail.c_str());
}

