CoopSaveStateBridge::CoopSaveMergeResult ModMain::MergeCoopSaveForLoadedSection(
    const CoopSaveStateBridge::SectionEvent& event,
    std::unique_ptr<TSerialize>* serializerOwner,
    const char* reason)
{
    CoopSaveStateBridge::NativeSaveSectionState vanillaSave;
    vanillaSave.sectionName = event.sectionName;
    vanillaSave.serializerOwner = serializerOwner;
    vanillaSave.serializer = serializerOwner ? serializerOwner->get() : nullptr;
    vanillaSave.fingerprint = event.fingerprint;
    vanillaSave.reading = event.reading;
    vanillaSave.target = event.target;
    vanillaSave.ok = event.ok;
    vanillaSave.gameState = event.gameState;
    vanillaSave.persistentState = event.persistentState;
    vanillaSave.allowMutation = CoopRuntimeConfig::UnsafeFlag("COOP_ENABLE_NATIVE_COOP_SAVE_MERGE_MUTATION");
    vanillaSave.reason = reason && reason[0] ? reason : "active load section";

    CoopSaveStateBridge::CoopPlayerSaveSection coopSection;
    if (m_pendingNativePlayerStateOverrideValid)
    {
        coopSection.username = m_pendingNativePlayerStateOverride.username;
        coopSection.levelName = m_pendingNativePlayerStateOverride.levelName;
        coopSection.saveKey = m_playerStateTransferSaveKey;
        coopSection.hasNativeCapture = m_pendingNativePlayerStateOverride.hasNativeCapture;
        if (m_pendingNativePlayerStateOverride.hasNativeCapture)
        {
            coopSection.nativeCapture = &m_pendingNativePlayerStateOverride.nativeCapture;
            if (m_pendingNativePlayerStateOverride.nativeCapture.hasNativeFragmentPayload &&
                !m_pendingNativePlayerStateOverride.nativeCapture.nativeFragmentPayload.empty())
            {
                m_lastNativeFragmentImportPayload =
                    m_pendingNativePlayerStateOverride.nativeCapture.nativeFragmentPayload;
            }
        }
    }

    CoopSaveStateBridge::CoopSaveMergeResult result =
        m_saveStateBridge.MergeCoopSave(vanillaSave, coopSection);

    if (result.attempted)
        ++m_coopSaveMergeAttempts;
    if (result.candidate)
        ++m_coopSaveMergeCandidates;
    if (result.patched)
        ++m_coopSaveMergePatched;
    if (result.passthrough)
        ++m_coopSaveMergePassthrough;
    if (result.deferred)
        ++m_coopSaveMergeDeferred;
    if (result.failed)
        ++m_coopSaveMergeFailures;

    m_lastCoopSaveMergeEvent = CoopSaveStateBridge::BuildCompactStatus(result);
    return result;
}

