void ModMain::OnSaveStateBridgeSectionEvent(const CoopSaveStateBridge::SectionEvent& event)
{
    ++m_saveStateBridgeEvents;
    if (event.nativePatchCandidate)
        ++m_saveStateBridgePatchCandidates;

    m_lastSaveStateBridgeEvent = CoopSaveStateBridge::BuildCompactStatus(event);
    m_saveStateBridge.RecordSectionEvent(event);

    RecordSaveLoadSectionTrace(
        event.source.c_str(),
        event.sectionName.c_str(),
        event.reading,
        event.target,
        event.ok,
        event.serializerText.c_str());
}

