    float localPlayerMaxHealth = -1.0f;
    int localPlayerArmor = -1;
    int localPlayerInputMode = -1;
    size_t localPlayerInputDepth = 0;
    std::string localInteractiveReason;
    const bool localInteractive = IsPostLoadGameplayInteractive(localInteractiveReason);
    ArkPlayer* statusPlayer = ArkPlayer::GetInstancePtr();
    if (statusPlayer && statusPlayer->GetEntity())
    {
        localPlayerLocation = statusPlayer->GetEntity()->GetWorldPos();
        localPlayerInputDepth = statusPlayer->m_input.m_modeStack.size();
        if (!statusPlayer->m_input.m_modeStack.empty())
        {
            localPlayerInputMode = static_cast<int>(
                statusPlayer->m_input.m_modeStack.back().m_mode);
        }
        TryGuardedCall(
            "status local player health",
            [statusPlayer]() { return statusPlayer->GetHealth(); },
            localPlayerHealth,
            nullptr);
        TryGuardedCall(
            "status local player max health",
            [statusPlayer]() { return statusPlayer->GetMaxHealth(); },
            localPlayerMaxHealth,
            nullptr);
        TryGuardedCall(
            "status local player armor",
            [statusPlayer]() { return statusPlayer->GetArmor(); },
            localPlayerArmor,
            nullptr);
    }

