        const SharedDropRecord& record = entry.second;
        liveSharedDropCount += record.live ? 1u : 0u;
        pendingSharedDropCount += record.pickupPending ? 1u : 0u;
        grantedSharedDropCount += record.localPickupGranted ? 1u : 0u;
        boundSharedDropTombstoneCount +=
            !record.live && record.localEntityId != INVALID_ENTITYID ? 1u : 0u;
