                TryGuardedCall("runtime area door IsPlayingAnimation", [door]() { return door->IsPlayingAnimation(); }, playingAnimation, &reason);
                TryGuardedCall("runtime area door area entity count", [door]() { return door->m_entitiesInArea.size(); }, areaEntities, &reason);
                TryGuardedCall("runtime area door timer remaining", [door]() { return door->m_openTimer.GetTimeRemaining(); }, closeTimerSeconds, &reason);
                TryGuardedCall("runtime area door timer duration", [door]() { return door->m_openTimer.GetDuration(); }, closeTimerDuration, &reason);
