uint64_t ModMain::HashStoryString(const std::string& text) const
{
    uint64_t hash = 14695981039346656037ull;
    for (unsigned char ch : text)
    {
        hash ^= static_cast<uint64_t>(ch);
        hash *= 1099511628211ull;
    }
    return hash == 0 ? 1 : hash;
}

uint64_t ModMain::CurrentHostSaveKeyHash() const
{
    if (!m_currentHostSaveStateKey.empty())
        return HashStoryString(m_currentHostSaveStateKey);
    if (!m_playerStateTransferSaveKey.empty())
        return HashStoryString(m_playerStateTransferSaveKey);
    if (!m_lastSaveLoadPath.empty() && m_lastSaveLoadPath != "-")
        return HashStoryString(BuildHostSaveStateKey(m_lastSaveLoadPath));
    return 0;
}

bool ModMain::IsCurrentOrRecentHostSaveKeyHash(uint64_t hash) const
{
    if (hash == 0)
        return false;
    if (hash == CurrentHostSaveKeyHash())
        return true;

    const float now = GetNowSeconds();
    return std::any_of(
        m_recentHostSaveKeyHashes.begin(),
        m_recentHostSaveKeyHashes.end(),
        [hash, now](const RecentHostSaveKeyHash& recent)
        {
            return recent.hash == hash && recent.expiresAt >= now;
        });
}

void ModMain::SetCurrentHostSaveStateKey(const std::string& saveKey, bool retainPrevious)
{
    if (saveKey == m_currentHostSaveStateKey)
        return;

    const float now = GetNowSeconds();
    while (!m_recentHostSaveKeyHashes.empty() &&
        m_recentHostSaveKeyHashes.front().expiresAt < now)
    {
        m_recentHostSaveKeyHashes.pop_front();
    }

    const uint64_t previousHash = CurrentHostSaveKeyHash();
    if (!retainPrevious)
    {
        m_recentHostSaveKeyHashes.clear();
    }
    else if (previousHash != 0)
    {
        const auto duplicate = std::find_if(
            m_recentHostSaveKeyHashes.begin(),
            m_recentHostSaveKeyHashes.end(),
            [previousHash](const RecentHostSaveKeyHash& recent)
            {
                return recent.hash == previousHash;
            });
        if (duplicate != m_recentHostSaveKeyHashes.end())
        {
            duplicate->expiresAt = now + kHostSaveKeyHandoverSeconds;
        }
        else
        {
            m_recentHostSaveKeyHashes.push_back(
                {previousHash, now + kHostSaveKeyHandoverSeconds});
            while (m_recentHostSaveKeyHashes.size() > kMaxRecentHostSaveKeyHashes)
                m_recentHostSaveKeyHashes.pop_front();
        }
    }

    m_currentHostSaveStateKey = saveKey;
    ReconcileLocalInventoryDirtyForSaveKey(saveKey);
}

uint64_t ModMain::BuildStoryEventId(uint16_t eventKind, uint64_t targetId, int32_t count, uint16_t flags, uint32_t sequence) const
{
    uint64_t hash = 14695981039346656037ull;
    auto mix64 = [&hash](uint64_t value)
    {
        for (int i = 0; i < 8; ++i)
        {
            hash ^= (value >> (i * 8)) & 0xffu;
            hash *= 1099511628211ull;
        }
    };

    mix64(GetLocalAccountToken());
    mix64(CurrentHostSaveKeyHash());
    mix64(m_localLevelId);
    mix64(m_localWorldEpoch);
    mix64(sequence);
    mix64(eventKind);
    mix64(targetId);
    mix64(static_cast<uint32_t>(count));
    mix64(flags);
    return hash == 0 ? 1 : hash;
}

uint64_t ModMain::BuildAreaObjectEventId(
    uint16_t eventKind,
    uint64_t targetGuid,
    uint16_t value,
    int32_t count,
    uint32_t flags,
    uint32_t sequence,
    const char* textValue) const
{
    uint64_t hash = 14695981039346656037ull;
    auto mix64 = [&hash](uint64_t mixedValue)
    {
        for (int i = 0; i < 8; ++i)
        {
            hash ^= (mixedValue >> (i * 8)) & 0xffu;
            hash *= 1099511628211ull;
        }
    };

    const bool decentralizedMainLiftOutage =
        eventKind == CoopProtocol::kAreaObjectEventMainLiftOutage;
    if (!decentralizedMainLiftOutage)
        mix64(GetLocalAccountToken());
    mix64(CurrentHostSaveKeyHash());
    mix64(m_localLevelId);
    mix64(m_localWorldEpoch);
    if (!decentralizedMainLiftOutage)
        mix64(sequence);
    else
        mix64(0x4c4946544f555431ULL); // "LIFTOUT1", authored one-shot generation.
    mix64(eventKind);
    mix64(targetGuid);
    mix64(value);
    mix64(static_cast<uint32_t>(count));
    mix64(flags);
    if (textValue)
    {
        for (size_t i = 0; textValue[i] != '\0' && i < CoopProtocol::kAreaObjectWireTextValueCapacity; ++i)
            mix64(static_cast<unsigned char>(textValue[i]));
    }
    return hash == 0 ? 1 : hash;
}

bool ModMain::BuildStoryEventPacket(
    CoopProtocol::StoryEventPacket& packet,
    uint16_t eventKind,
    uint64_t targetId,
    int32_t count,
    uint16_t flags,
    const char* reason,
    const char* textValue)
{
    if (eventKind == 0 || targetId == 0)
        return false;

    packet.magic = CoopProtocol::kPacketMagic;
    packet.version = CoopProtocol::kProtocolVersion;
    packet.type = static_cast<uint16_t>(CoopProtocol::PacketType::StoryEvent);
    packet.sequence = CoopSerialSequence::Advance(m_storyEventSequence);
    packet.eventKind = eventKind;
    packet.targetId = targetId;
    packet.count = count;
    packet.flags = flags;
    packet.worldEpoch = m_localWorldEpoch;
    packet.levelId = m_localLevelId;
    packet.hostSaveKeyHash = CurrentHostSaveKeyHash();
    packet.sourcePeerHash = GetLocalAccountToken();
    packet.preVersion = m_storyRevision;
    packet.postVersion = m_storyRevision + 1;
    packet.storyRevision = packet.postVersion;
    if (textValue && textValue[0])
        CopyFixedString(packet.textValue, sizeof(packet.textValue), textValue);
    packet.eventId = BuildStoryEventId(eventKind, targetId, count, flags, packet.sequence);
    (void)reason;
    return packet.eventId != 0;
}

bool ModMain::BuildAreaObjectEventPacket(
    CoopProtocol::AreaObjectEventPacket& packet,
    uint16_t eventKind,
    uint64_t targetGuid,
    uint16_t value,
    uint32_t flags,
    const char* reason,
    int32_t count,
    const char* textValue)
{
    if (eventKind == 0 || targetGuid == 0)
        return false;

    if (eventKind == CoopProtocol::kAreaObjectEventLevelGameTokenBool ||
        eventKind == CoopProtocol::kAreaObjectEventLevelGameTokenInt ||
        eventKind == CoopProtocol::kAreaObjectEventLevelGameTokenString)
    {
        int tokenId = 0;
        if (!DecodeAreaGameTokenId(targetGuid, tokenId) ||
            !IsWhitelistedAreaGameTokenId(eventKind, tokenId) ||
            (eventKind == CoopProtocol::kAreaObjectEventLevelGameTokenBool && value > 1) ||
            (eventKind == CoopProtocol::kAreaObjectEventLevelGameTokenString &&
                (!textValue || std::strlen(textValue) >= CoopProtocol::kAreaObjectTextValueCapacity)))
        {
            return false;
        }
    }
    if ((eventKind == CoopProtocol::kAreaObjectEventWorkstationView ||
            eventKind == CoopProtocol::kAreaObjectEventWorkstationUtilityPressed) &&
        (!textValue || !textValue[0] ||
            std::strlen(textValue) >= CoopProtocol::kAreaObjectTextValueCapacity ||
            (eventKind == CoopProtocol::kAreaObjectEventWorkstationUtilityPressed &&
                (value != 1 || count != 0))))
    {
        return false;
    }
    if (eventKind == CoopProtocol::kAreaObjectEventElevatorTransit &&
        (!textValue || !textValue[0] ||
            std::strlen(textValue) >= CoopProtocol::kAreaObjectTextValueCapacity ||
            value != 1))
    {
        return false;
    }
    if (eventKind == CoopProtocol::kAreaObjectEventMainLiftOutage &&
        (targetGuid != kCoopLobbyMainLiftGuid || value != 1 || flags != 0 ||
            count != 1 || !textValue || !textValue[0] ||
            std::strlen(textValue) >= CoopProtocol::kAreaObjectTextValueCapacity))
    {
        return false;
    }
    if (eventKind == CoopProtocol::kAreaObjectEventHelicopterPassengerStart &&
        (targetGuid != kCoopSimulationLabsHelicopterUsePromptGuid ||
            value != 1 || flags != 0 || count != 0 ||
            (textValue && textValue[0])))
    {
        return false;
    }
    if ((eventKind == CoopProtocol::kAreaObjectEventKioskButtonState ||
            eventKind == CoopProtocol::kAreaObjectEventKioskButtonPressed ||
            eventKind ==
                CoopProtocol::kAreaObjectEventGenericElevatorKioskButtonPressed) &&
        (flags != 0 || count < 0 || count >= 3 ||
            (eventKind == CoopProtocol::kAreaObjectEventKioskButtonState
                    ? value > static_cast<uint16_t>(EArkKioskButtonState::Error)
                    : value != 1)))
    {
        return false;
    }
    const bool kioskButtonText =
        eventKind == CoopProtocol::kAreaObjectEventKioskButtonHeader ||
        eventKind == CoopProtocol::kAreaObjectEventKioskButtonBody;
    const bool kioskRootText =
        eventKind == CoopProtocol::kAreaObjectEventKioskHeader ||
        eventKind == CoopProtocol::kAreaObjectEventKioskBody;
    if (((kioskButtonText || kioskRootText ||
                eventKind == CoopProtocol::kAreaObjectEventKioskButtonVisible) &&
            flags != 0) ||
        (kioskButtonText && (count < 0 || count >= 3)) ||
        (kioskRootText && count != 0) ||
        ((kioskButtonText || kioskRootText) &&
            (!textValue ||
                std::strlen(textValue) >= CoopProtocol::kAreaObjectWireTextValueCapacity)) ||
        (eventKind == CoopProtocol::kAreaObjectEventKioskButtonVisible &&
            (count < 0 || count >= 3 || value > 1)))
    {
        return false;
    }
    if (eventKind == CoopProtocol::kAreaObjectEventDoorOpen &&
        (value > 1 ||
            (flags & CoopProtocol::kAreaObjectDoorStateFlagSnapshot) == 0 ||
            (flags & ~CoopProtocol::kAreaObjectDoorStateFlagMask) != 0))
    {
        return false;
    }
    if (eventKind == CoopProtocol::kAreaObjectEventDoorLocked ||
        eventKind == CoopProtocol::kAreaObjectEventDoorPowered)
    {
        // Protocol 117 never emits split door properties. They are carried by
        // one DoorOpen snapshot so reliable supersession cannot reorder them.
        return false;
    }
    packet.magic = CoopProtocol::kPacketMagic;
    packet.version = CoopProtocol::kProtocolVersion;
    packet.type = static_cast<uint16_t>(CoopProtocol::PacketType::AreaObjectEvent);
    packet.sequence = CoopSerialSequence::Advance(m_areaObjectEventSequence);
    packet.eventKind = eventKind;
    packet.targetGuid = targetGuid;
    if (eventKind == CoopProtocol::kAreaObjectEventWorldItemRemoved)
        packet.targetClassHash = HashStoryString("CArkItem");
    else if (eventKind == CoopProtocol::kAreaObjectEventOperatorDispenserLocked ||
        eventKind == CoopProtocol::kAreaObjectEventOperatorDispenserState)
        packet.targetClassHash = HashStoryString("ArkOperatorDispenser");
    else if (eventKind == CoopProtocol::kAreaObjectEventFabricatorInteractionState)
        packet.targetClassHash = HashStoryString("ArkFabricator");
    else if (eventKind == CoopProtocol::kAreaObjectEventElevatorKioskState)
        packet.targetClassHash = HashStoryString("ArkGenericElevatorKiosk");
    else if (eventKind ==
        CoopProtocol::kAreaObjectEventGenericElevatorKioskButtonPressed)
        packet.targetClassHash = HashStoryString("ArkGenericElevatorKiosk");
    else if (eventKind == CoopProtocol::kAreaObjectEventKioskButtonState ||
        eventKind == CoopProtocol::kAreaObjectEventKioskButtonPressed ||
        eventKind == CoopProtocol::kAreaObjectEventKioskButtonHeader ||
        eventKind == CoopProtocol::kAreaObjectEventKioskButtonBody ||
        eventKind == CoopProtocol::kAreaObjectEventKioskButtonVisible ||
        eventKind == CoopProtocol::kAreaObjectEventKioskHeader ||
        eventKind == CoopProtocol::kAreaObjectEventKioskBody)
        packet.targetClassHash = HashStoryString("ArkKiosk");
    else if (eventKind == CoopProtocol::kAreaObjectEventElevatorTransit ||
        eventKind == CoopProtocol::kAreaObjectEventMainLiftOutage)
        packet.targetClassHash = HashStoryString("ArkElevator");
    else if (eventKind == CoopProtocol::kAreaObjectEventInteractiveMachinePowered)
        packet.targetClassHash = HashStoryString("ArkInteractiveMachine");
    else if (eventKind == CoopProtocol::kAreaObjectEventInteractiveScreenPowered)
        packet.targetClassHash = HashStoryString("ArkInteractiveScreen");
    else if (eventKind == CoopProtocol::kAreaObjectEventWorkstationLocked ||
        eventKind == CoopProtocol::kAreaObjectEventWorkstationView ||
        eventKind == CoopProtocol::kAreaObjectEventWorkstationUtilityPressed)
        packet.targetClassHash = HashStoryString("ArkWorkstationScreen");
    else if (eventKind == CoopProtocol::kAreaObjectEventKeypadLocked)
        packet.targetClassHash = HashStoryString("ArkKeypad");
    else if (eventKind == CoopProtocol::kAreaObjectEventKeycardReaderLocked)
        packet.targetClassHash = HashStoryString("ArkKeycardReader");
    else if (eventKind == CoopProtocol::kAreaObjectEventContainerOpen)
        packet.targetClassHash = HashStoryString("ArkInventory");
    else if (eventKind == CoopProtocol::kAreaObjectEventInteractiveObjectActive ||
        eventKind == CoopProtocol::kAreaObjectEventInteractiveObjectDisabled ||
        eventKind == CoopProtocol::kAreaObjectEventHelicopterPassengerStart)
        packet.targetClassHash = HashStoryString("ArkInteractiveObject");
    else if (eventKind == CoopProtocol::kAreaObjectEventSwitchOn)
        packet.targetClassHash = HashStoryString("ArkSwitch");
    else if (eventKind == CoopProtocol::kAreaObjectEventApexTentacleSpawnerEnabled)
        packet.targetClassHash = HashStoryString("ArkApexTentacleSpawner");
    else if (eventKind == CoopProtocol::kAreaObjectEventCargoContainerMotion ||
        eventKind == CoopProtocol::kAreaObjectEventCargoContainerDoorsOpen)
        packet.targetClassHash = HashStoryString("ArkCargoContainer");
    else if (eventKind == CoopProtocol::kAreaObjectEventRotatorActive)
        packet.targetClassHash = HashStoryString("ArkRotator");
    else if (eventKind == CoopProtocol::kAreaObjectEventBreakableHealth)
        packet.targetClassHash = HashStoryString("ArkBreakable");
    else if (eventKind == CoopProtocol::kAreaObjectEventBreakableGlassImpact)
        packet.targetClassHash = HashStoryString("BreakableGlass");
    else if (eventKind == CoopProtocol::kAreaObjectEventLevelGameTokenBool ||
        eventKind == CoopProtocol::kAreaObjectEventLevelGameTokenInt ||
        eventKind == CoopProtocol::kAreaObjectEventLevelGameTokenString)
    {
        packet.targetClassHash = HashStoryString("LevelGameToken");
    }
    else
        packet.targetClassHash = HashStoryString("ArkDoor");
    packet.value = value;
    packet.count = count;
    packet.flags = flags;
    packet.worldEpoch = m_localWorldEpoch;
    packet.levelId = m_localLevelId;
    packet.hostSaveKeyHash = CurrentHostSaveKeyHash();
    packet.sourcePeerHash = GetLocalAccountToken();
    packet.preVersion = m_areaObjectRevision;
    packet.postVersion = m_areaObjectRevision + 1;
    packet.areaRevision = packet.postVersion;
    if (textValue && textValue[0])
        CopyFixedString(packet.textValue, sizeof(packet.textValue), textValue);
    packet.eventId = BuildAreaObjectEventId(
        eventKind,
        targetGuid,
        value,
        count,
        flags,
        packet.sequence,
        packet.textValue);
    (void)reason;
    return packet.eventId != 0;
}

bool ModMain::SendPacketTo(const void* packet, int packetSize, uint32_t address, uint16_t port, const char* failurePrefix)
{
    uint16_t packetType = 0;
    if (packet && packetSize >= static_cast<int>(sizeof(CoopProtocol::PacketHeader)))
    {
        CoopProtocol::PacketHeader header = {};
        std::memcpy(&header, packet, sizeof(header));
        if (CoopProtocol::IsValidHeader(header))
            packetType = header.type;
    }
    const uint32_t attemptedBytes = packetSize > 0 ? static_cast<uint32_t>(packetSize) : 0;
    m_networkTelemetry.RecordWireSendAttempt(packetType, attemptedBytes);

    sockaddr_in targetAddress = {};
    targetAddress.sin_family = AF_INET;
    targetAddress.sin_addr.s_addr = address;
    targetAddress.sin_port = port;

    const int sentBytes = sendto(
        ToSocket(m_socket),
        reinterpret_cast<const char*>(packet),
        packetSize,
        0,
        reinterpret_cast<const sockaddr*>(&targetAddress),
        sizeof(targetAddress));

    if (sentBytes == SOCKET_ERROR)
    {
        m_networkTelemetry.RecordWireSendFailure(packetType, attemptedBytes);
        m_networkStatus = WinsockStatus(failurePrefix, WSAGetLastError());
        return false;
    }

    m_networkTelemetry.RecordWireSendSuccess(packetType, static_cast<uint32_t>(sentBytes));
    return true;
}

bool ModMain::SendPosePacketTo(const CoopProtocol::PlayerPosePacket& packet, uint32_t address, uint16_t port, const char* failurePrefix)
{
    if (packet.mimicModelPathLength >= CoopProtocol::kMimicModelPathSize)
    {
        m_networkStatus = "player pose mimic path exceeds wire limit";
        return false;
    }

    const size_t wireSize = CoopProtocol::PlayerPoseWireSize(packet.mimicModelPathLength);
    if (!SendPacketTo(&packet, wireSize, address, port, failurePrefix))
        return false;

    ++m_sentPosePackets;
    return true;
}

