bool ModMain::SendTestMimicStateTo(
    const CoopProtocol::TestMimicStatePacket& packet,
    uint32_t address,
    uint16_t port,
    const char* failurePrefix,
    uint64_t excludedAccountToken)
{
    CoopProtocol::EnemyStateWirePacket wirePacket = {};
    const void* wireData = &packet;
    int wireSize = sizeof(packet);
    if (packet.enemyNetId != kTestMimicNetId)
    {
        if (!CoopEnemyStateWire::Encode(packet, wirePacket))
            return false;
        wireData = &wirePacket;
        wireSize = sizeof(wirePacket);
    }

    bool sent = false;
    bool allSent = true;
    if (m_networkMode == CoopNetworkMode::Host && !m_remotePeers.empty())
    {
        for (const auto& entry : m_remotePeers)
        {
            if (excludedAccountToken != 0 && entry.first == excludedAccountToken)
                continue;

            const RemotePeerSession& peer = entry.second;
            if (peer.address == 0 || peer.port == 0 || !peer.sessionReady ||
                !IsKnownSameLevel(m_localLevelName, peer.levelName))
                continue;
            sent = true;
            allSent = SendPacketTo(wireData, wireSize, peer.address, peer.port, failurePrefix) && allSent;
        }
    }
    else
    {
        if (m_networkMode == CoopNetworkMode::Client)
        {
            // Enemy authority traffic always traverses the session Host. The
            // compatibility endpoint can temporarily name another Client
            // after a relayed packet, which must not create a peer-to-peer
            // authority path around the central router.
            ResolveSessionHostEndpoint(address, port);
        }
        sent = true;
        allSent = SendPacketTo(wireData, wireSize, address, port, failurePrefix);
    }
    if (!sent && m_networkMode == CoopNetworkMode::Host)
    {
        m_networkTelemetry.RecordProducerSuppressed(
            static_cast<uint16_t>(CoopProtocol::PacketType::TestMimicState),
            CoopNetworkTelemetry::ProducerSuppressionReason::Readiness);
        return true;
    }
    if (!sent || !allSent)
        return false;

    ++m_sentMimicStatePackets;
    return true;
}

bool ModMain::DecodeTestMimicStateDatagram(
    const void* data,
    size_t dataSize,
    CoopProtocol::TestMimicStatePacket& packet)
{
    if (!data)
        return false;
    if (dataSize == sizeof(CoopProtocol::TestMimicStatePacket))
    {
        std::memcpy(&packet, data, sizeof(packet));
        return true;
    }
    if (dataSize != sizeof(CoopProtocol::EnemyStateWirePacket))
        return false;

    CoopProtocol::EnemyStateWirePacket wirePacket = {};
    std::memcpy(&wirePacket, data, sizeof(wirePacket));
    uint64_t archetypeId = 0;
    uint64_t stableEnemyId = 0;

    const auto rosterIt = m_enemyRosterByNetId.find(wirePacket.enemyNetId);
    if (rosterIt != m_enemyRosterByNetId.end())
    {
        archetypeId = rosterIt->second.archetypeId;
        stableEnemyId = rosterIt->second.stableEnemyId;
    }
    const auto authorityIt = m_enemyAuthorities.find(wirePacket.enemyNetId);
    if (authorityIt != m_enemyAuthorities.end())
    {
        if (archetypeId == 0)
            archetypeId = authorityIt->second.archetypeId;
        if (stableEnemyId == 0)
            stableEnemyId = authorityIt->second.stableEnemyId;
    }

    return CoopEnemyStateWire::Decode(wirePacket, archetypeId, stableEnemyId, packet);
}

