IGameTokenSystem* ModMain::GetStoryGameTokenSystem() const
{
    if (!gEnv || !gEnv->pGame)
        return nullptr;

    IGameFramework* framework = nullptr;
    std::string reason;
    if (!TryGuardedCall(
            "story token GetIGameFramework",
            []() { return gEnv->pGame->GetIGameFramework(); },
            framework,
            &reason) ||
        !framework)
    {
        return nullptr;
    }

    IGameTokenSystem* system = nullptr;
    if (!TryGuardedCall(
            "story token GetIGameTokenSystem",
            [framework]() { return framework->GetIGameTokenSystem(); },
            system,
            &reason))
    {
        return nullptr;
    }
    return system;
}

