bool ModMain::IsLocalStoryReadableComponent(const void* component, uint16_t eventKind) const
{
    const ArkPlayer* player = ArkPlayer::GetInstancePtr();
    if (!player || !component)
        return false;

    switch (eventKind)
    {
    case CoopProtocol::kStoryEventCollectNote:
        return player->m_playerComponent.m_pNoteComponent.get() == component;
    case CoopProtocol::kStoryEventCollectAudioLog:
        return player->m_playerComponent.m_pAudioLogComponent.get() == component;
    case CoopProtocol::kStoryEventCollectEmail:
    case CoopProtocol::kStoryEventCollectEmailDownload:
        return player->m_playerComponent.m_pEmailComponent.get() == component;
    default:
        return false;
    }
}

