void ModMain::OnLocalStoryKeyCardCollected(ArkKeyCardComponent* component, uint64_t id, bool changed, const char* reason)
{
    if (!changed || !IsLocalStoryKeyCardComponent(component))
        return;

    QueueLocalStoryEventForHook(CoopProtocol::kStoryEventGrantKeycard, id, 1, 0, reason);
}

void ModMain::OnLocalStoryKeyCodeCollected(ArkKeyCodeComponent* component, uint64_t id, bool changed, const char* reason)
{
    if (!changed || !IsLocalStoryKeyCodeComponent(component))
        return;

    std::string code;
    ArkKeyCodeEntry* entry = nullptr;
    if (TryGuardedCall(
            "story keycode capture entry",
            [component, id]() -> ArkKeyCodeEntry* { return component->GetEntry(id); },
            entry,
            nullptr) &&
        entry)
    {
        TryGuardedCall(
            "story keycode capture value",
            [entry]() -> std::string { return entry->m_code.c_str(); },
            code,
            nullptr);
    }

    QueueLocalStoryEventForHook(
        CoopProtocol::kStoryEventGrantKeycode,
        id,
        1,
        0,
        reason,
        code.c_str());
}

void ModMain::OnLocalStoryFabricationPlanGranted(
    ArkFabricationPlanComponent* component,
    uint64_t id,
    int count,
    bool unlimited,
    bool changed,
    const char* reason)
{
    if (!changed || !IsLocalStoryFabricationPlanComponent(component))
        return;

    const uint16_t flags = unlimited ? CoopProtocol::kStoryEventFlagUnlimited : 0;
    QueueLocalStoryEventForHook(CoopProtocol::kStoryEventGrantFabricationPlan, id, std::max(1, count), flags, reason);
}

void ModMain::OnLocalStoryObjectiveStateChanged(
    ArkObjectiveComponent* component,
    uint64_t id,
    int state,
    bool showOnHud,
    bool changed,
    const char* reason)
{
    if (!changed || !IsLocalStoryObjectiveComponent(component))
        return;

    uint16_t eventKind = 0;
    switch (static_cast<EArkObjectiveState>(state))
    {
    case EArkObjectiveState::ASSIGNED:
        eventKind = CoopProtocol::kStoryEventObjectiveAssigned;
        break;
    case EArkObjectiveState::COMPLETED:
        eventKind = CoopProtocol::kStoryEventObjectiveCompleted;
        break;
    case EArkObjectiveState::FAILED:
        eventKind = CoopProtocol::kStoryEventObjectiveFailed;
        break;
    case EArkObjectiveState::UNASSIGNED:
    case EArkObjectiveState::CANCELLED:
        eventKind = CoopProtocol::kStoryEventObjectiveUnassigned;
        state = static_cast<int>(EArkObjectiveState::UNASSIGNED);
        break;
    default:
        m_lastStoryEvent =
            "story_event_skip_unknown_objective_state_" + std::to_string(state) +
            "_target_" + std::to_string(id);
        return;
    }

    const uint16_t flags = showOnHud ? CoopProtocol::kStoryEventFlagShowHud : 0;
    QueueLocalStoryEventForHook(eventKind, id, state, flags, reason);
}

void ModMain::OnLocalStoryTaskStateChanged(
    ArkObjectiveComponent* component,
    uint64_t id,
    int state,
    bool changed,
    const char* reason)
{
    if (!changed || !IsLocalStoryObjectiveComponent(component))
        return;

    uint16_t eventKind = 0;
    switch (static_cast<EArkObjectiveTaskState>(state))
    {
    case EArkObjectiveTaskState::ACTIVE:
        eventKind = CoopProtocol::kStoryEventTaskActivated;
        break;
    case EArkObjectiveTaskState::INACTIVE:
        eventKind = CoopProtocol::kStoryEventTaskDeactivated;
        break;
    case EArkObjectiveTaskState::COMPLETED:
        eventKind = CoopProtocol::kStoryEventTaskCompleted;
        break;
    case EArkObjectiveTaskState::FAILED:
        eventKind = CoopProtocol::kStoryEventTaskFailed;
        break;
    default:
        m_lastStoryEvent =
            "story_event_skip_unknown_task_state_" + std::to_string(state) +
            "_target_" + std::to_string(id);
        return;
    }

    QueueLocalStoryEventForHook(eventKind, id, state, 0, reason);
}

