void ModMain::OnLocalStoryRemoteEventTriggered(uint64_t id, const char* reason)
{
    if (m_applyingRemoteStoryEvent)
        return;

    if (!FindStoryRemoteEventById(id))
    {
        m_lastStoryEvent =
            "story_event_skip_unwhitelisted_remote_event_" + std::to_string(id);
        return;
    }

    const uint32_t count = ++m_storyRemoteEventCounts[id];
    QueueLocalStoryEventForHook(
        CoopProtocol::kStoryEventRemoteEvent,
        id,
        static_cast<int32_t>(std::min<uint32_t>(count, static_cast<uint32_t>(std::numeric_limits<int32_t>::max()))),
        0,
        reason);
}

bool ModMain::OnLocalMainLiftOutageRemoteEvent(uint64_t id, const char* name)
{
    (void)name;
    if (id != kCoopMainLiftOutageRemoteEventId ||
        m_networkMode == CoopNetworkMode::Off || !IsSessionGameplayReady() ||
        m_saveLoadGuardActive ||
        NormalizeLevelName(GetCurrentLevelName()) != "campaign/research/lobby")
    {
        return true;
    }

    if (!IsLocalPlayerInsideMainLiftShaft())
    {
        if (!m_mainLiftOutageSuppressedForLocalPlayer)
        {
            m_mainLiftOutageSuppressedForLocalPlayer = true;
            ++m_mainLiftOutageScopeSkips;
        }
        m_mainLiftOutsideOutageAwaitingNativeContinuation = true;
        m_lastMainLiftOutageEvent =
            "suppressed local main-lift outage outside shaft event=" +
            std::to_string(id);
        LogCoop(m_lastMainLiftOutageEvent);
        return false;
    }

    m_mainLiftOutageSuppressedForLocalPlayer = false;
    m_mainLiftOutageEnemyCaptureSeconds = 30.0f;
    m_mainLiftOutageAwaitingContinuation = true;
    if (!m_mainLiftOutagePresented)
    {
        m_mainLiftOutagePresented = true;
        ++m_mainLiftOutagePresentations;
    }
    else
    {
        ++m_mainLiftOutageDuplicateObservations;
    }

    // A routed replay is the peer-local presentation of an already announced
    // semantic event. Never echo it back through the session Host.
    if (m_replayingMainLiftOutageRemoteEvent)
    {
        m_lastMainLiftOutageEvent =
            "started routed main-lift outage FlowGraph event=" +
            std::to_string(id) + " name=" + StatusToken(name);
        return true;
    }

    if (m_mainLiftOutageAnnounced)
        return true;

    if (QueueLocalAreaObjectEventForHook(
            CoopProtocol::kAreaObjectEventMainLiftOutage,
            kCoopLobbyMainLiftGuid,
            1,
            0,
            "native Lobby elevator ambush RemoteEvent observed",
            1,
            kCoopMainLiftOutageRemoteEventWireValue))
    {
        m_mainLiftOutageAnnounced = true;
        ++m_mainLiftOutageAnnouncements;
        m_mainLiftOutageEventId = m_lastAreaObjectEventId;
        m_mainLiftOutageEnemyStableId =
            BuildMainLiftOutageEnemyStableId(m_mainLiftOutageEventId);
        m_lastMainLiftOutageEvent =
            "announced decentralized main-lift outage event=" +
            std::to_string(m_mainLiftOutageEventId) +
            " remoteEvent=" + std::to_string(id) +
            " enemyStable=" +
            std::to_string(m_mainLiftOutageEnemyStableId);
        LogCoop(m_lastMainLiftOutageEvent);
    }
    return true;
}

