bool ModMain::QueueLocalStoryEventForHook(
    uint16_t eventKind,
    uint64_t targetId,
    int32_t count,
    uint16_t flags,
    const char* reason,
    const char* textValue,
    uint64_t contextEntityGuid,
    uint64_t contextCharacterId,
    uint16_t contextFlags,
    int32_t contextChannel)
{
    if (IsReplayingRemoteDialogue())
        return false;

    const bool classifiedStoryKind =
        eventKind >= CoopProtocol::kStoryEventGrantKeycard &&
        eventKind <= CoopProtocol::kStoryEventGlobalString;
    const std::string coverageStoryDetail = reason && reason[0]
        ? std::string(reason)
        : "story_kind_" + std::to_string(eventKind);
    m_coverageDiscovery.RecordStoryCommit(classifiedStoryKind, coverageStoryDetail);

    if (m_applyingRemoteStoryEvent)
    {
        ++m_reentrantStoryEventSkips;
        m_lastStoryEvent =
            "story_event_skip_remote_echo_kind_" + std::to_string(eventKind) +
            "_target_" + std::to_string(targetId) +
            "_reason_" + StatusToken(reason && reason[0] ? std::string(reason) : std::string("-"));
        return false;
    }

    if (m_networkMode == CoopNetworkMode::Client &&
        !IsClientAreaAuthorityActive() &&
        m_remoteMainLiftPresentationActive)
    {
        // The observer is running the same native lift graph only so its
        // ScriptControlledPhysics mover, audio and screen presentation stay
        // vanilla. Area Authority already authored this ride. Do not let the
        // observer's delayed conversation/global-fact callbacks drive the
        // authority graph a second time (notably Lobby.LiftAtMid).
        ++m_reentrantStoryEventSkips;
        m_lastStoryEvent =
            "story_event_skip_remote_main_lift_presentation_kind_" +
            std::to_string(eventKind) + "_target_" +
            std::to_string(targetId);
        return false;
    }

    if (m_networkMode == CoopNetworkMode::Off ||
        m_socket == kInvalidNetworkSocket ||
        !m_hasRemoteEndpoint ||
        !IsSessionGameplayReady())
    {
        m_lastStoryEvent =
            "story_event_local_no_network_kind_" + std::to_string(eventKind) +
            "_target_" + std::to_string(targetId);
        return false;
    }

    CoopProtocol::StoryEventPacket packet = {};
    if (!BuildStoryEventPacket(packet, eventKind, targetId, count, flags, reason, textValue))
    {
        ++m_storyEventFailures;
        m_lastStoryEvent =
            "story_event_build_failed_kind_" + std::to_string(eventKind) +
            "_target_" + std::to_string(targetId);
        return false;
    }

    packet.contextEntityGuid = contextEntityGuid;
    packet.contextCharacterId = contextCharacterId;
    packet.contextFlags = contextFlags;
    packet.contextChannel = contextChannel;

    if (!SendStoryEventTo(packet, m_remoteAddress, m_remotePort, "story event send failed"))
    {
        ++m_storyEventFailures;
        m_lastStoryEvent =
            "story_event_send_failed_kind_" + std::to_string(eventKind) +
            "_target_" + std::to_string(targetId);
        return false;
    }

    m_storyRevision = std::max(m_storyRevision, packet.postVersion);
    m_appliedStoryEventIds.insert(packet.eventId);
    m_lastStoryEventId = packet.eventId;
    m_lastStoryEvent =
        "sent_story_event_kind_" + std::to_string(eventKind) +
        "_target_" + std::to_string(targetId) +
        "_event_" + std::to_string(packet.eventId) +
        "_rev_" + std::to_string(m_storyRevision) +
        "_save_" + std::to_string(packet.hostSaveKeyHash) +
        "_reason_" + StatusToken(reason && reason[0] ? std::string(reason) : std::string("-"));
    LogCoop(m_lastStoryEvent);
    return true;
}

void ModMain::SetRemoteDoorTraversalPhysics(ArkDoor* door, bool open, const char* reason)
{
    if (!door)
        return;

    IEntity* entity = nullptr;
    IPhysicalEntity* physics = nullptr;
    EntityId entityId = INVALID_ENTITYID;
    std::string guardReason;
    const bool resolved =
        TryGuardedCall("remote door traversal GetEntity", [door]() { return door->GetEntity(); }, entity, &guardReason) && entity &&
        TryGuardedCall("remote door traversal GetId", [entity]() { return entity->GetId(); }, entityId, &guardReason) &&
        TryGuardedCall("remote door traversal GetPhysics", [entity]() { return entity->GetPhysics(); }, physics, &guardReason) && physics;
    if (!resolved)
        return;

    uint32_t changedParts = 0;
    bool applied = true;
    if (open)
    {
        if (m_remoteOpenDoorPhysicsParts.find(entityId) != m_remoteOpenDoorPhysicsParts.end())
            return;

        pe_status_nparts partStatus;
        int partCount = 0;
        if (!TryGuardedCall(
                "remote door traversal part count",
                [physics, &partStatus]() { return physics->GetStatus(&partStatus); },
                partCount,
                &guardReason) || partCount <= 0 || partCount > 256)
        {
            return;
        }

        std::vector<RemoteDoorPhysicsPartState> snapshot(static_cast<size_t>(partCount));
        for (int partIndex = 0; partIndex < partCount; ++partIndex)
        {
            pe_params_part current;
            current.ipart = partIndex;
            int getResult = 0;
            if (!TryGuardedCall(
                    "remote door traversal read part",
                    [physics, &current]() { return physics->GetParams(&current); },
                    getResult,
                    &guardReason) || getResult == 0)
            {
                applied = false;
                continue;
            }

            snapshot[static_cast<size_t>(partIndex)] = {
                true,
                current.flagsOR,
                current.flagsColliderOR,
            };
            pe_params_part disabled;
            disabled.ipart = partIndex;
            // This only changes collision flags. Rebuilding the aggregate box
            // here mixes world-space child parts into compound movers such as
            // the main lift and corrupts their physics bounds.
            disabled.bRecalcBBox = 0;
            disabled.flagsAND = 0u;
            disabled.flagsOR = 0u;
            disabled.flagsColliderAND = 0u;
            disabled.flagsColliderOR = 0u;
            int setResult = 0;
            if (TryGuardedCall(
                    "remote door traversal disable part",
                    [physics, &disabled]() { return physics->SetParams(&disabled); },
                    setResult,
                    &guardReason) && setResult != 0)
            {
                ++changedParts;
            }
            else
            {
                applied = false;
            }
        }
        if (changedParts != 0)
            m_remoteOpenDoorPhysicsParts.emplace(entityId, std::move(snapshot));
        else
            applied = false;
    }
    else
    {
        const auto snapshotIt = m_remoteOpenDoorPhysicsParts.find(entityId);
        if (snapshotIt == m_remoteOpenDoorPhysicsParts.end())
            return;
        const auto& snapshot = snapshotIt->second;
        for (size_t partIndex = 0; partIndex < snapshot.size(); ++partIndex)
        {
            const RemoteDoorPhysicsPartState& original = snapshot[partIndex];
            if (!original.valid)
                continue;
            pe_params_part restored;
            restored.ipart = static_cast<int>(partIndex);
            // Preserve the mover's authored aggregate bounds for the same
            // reason as the disable path above.
            restored.bRecalcBBox = 0;
            restored.flagsAND = 0u;
            restored.flagsOR = original.flags;
            restored.flagsColliderAND = 0u;
            restored.flagsColliderOR = original.colliderFlags;
            int setResult = 0;
            if (TryGuardedCall(
                    "remote door traversal restore part",
                    [physics, &restored]() { return physics->SetParams(&restored); },
                    setResult,
                    &guardReason) && setResult != 0)
            {
                ++changedParts;
            }
            else
            {
                applied = false;
            }
        }
        if (applied)
            m_remoteOpenDoorPhysicsParts.erase(snapshotIt);
    }

    std::ostringstream detail;
    detail << "remote_door_traversal_" << (open ? "open" : "restore")
           << "_id_" << entityId
           << "_ok_" << (applied ? 1 : 0)
           << "_parts_" << changedParts
           << "_reason_" << StatusToken(reason && reason[0] ? std::string(reason) : guardReason);
    LogCoop(detail.str());
}

bool ModMain::ShouldCaptureRemoteAreaObjectConsequenceForHook(uint16_t eventKind) const
{
    const bool localAreaAuthority =
        m_networkMode == CoopNetworkMode::Host || IsClientAreaAuthorityActive();
    if (!localAreaAuthority ||
        m_remoteAreaObjectConsequenceCaptureSeconds <= 0.0f ||
        m_remoteAreaObjectConsequenceInputKind == 0 ||
        eventKind == 0 ||
        eventKind == m_remoteAreaObjectConsequenceInputKind)
    {
        return false;
    }

    // While another remote state packet is being replayed, its hooks are still
    // echoes. Only the routed interaction input that armed this window may
    // synchronously author new persistent consequences.
    return !m_applyingRemoteAreaObjectEvent ||
        m_applyingRemoteAreaObjectAuthorityInput;
}

void ModMain::OnLocalAreaObjectDoorStateChanged(ArkDoor* door, uint16_t eventKind, bool value, bool changed, const char* reason)
{
    if (!changed || !door)
        return;

    if ((m_applyingRemoteAreaObjectEvent ||
            m_remoteAreaObjectEchoSuppressSeconds > 0.0f) &&
        m_localAreaObjectCommandMutationDepth == 0 &&
        !ShouldCaptureRemoteAreaObjectConsequenceForHook(eventKind))
    {
        ++m_reentrantAreaObjectEventSkips;
        m_lastAreaObjectEvent =
            "area_object_skip_remote_echo_kind_" + std::to_string(eventKind) +
            "_window_" + std::to_string(m_remoteAreaObjectEchoSuppressSeconds) +
            "_reason_" + StatusToken(reason && reason[0] ? std::string(reason) : std::string("-"));
        return;
    }

    if (eventKind != CoopProtocol::kAreaObjectEventDoorOpen &&
        eventKind != CoopProtocol::kAreaObjectEventDoorLocked &&
        eventKind != CoopProtocol::kAreaObjectEventDoorPowered)
    {
        m_lastAreaObjectEvent =
            "area_object_skip_unknown_door_kind_" + std::to_string(eventKind);
        return;
    }

    IEntity* entity = nullptr;
    std::string guardReason;
    if (!TryGuardedCall("area object door GetEntity", [door]() { return door->GetEntity(); }, entity, &guardReason) ||
        !entity)
    {
        m_lastAreaObjectEvent =
            "area_object_door_missing_entity_kind_" + std::to_string(eventKind) +
            "_reason_" + StatusToken(guardReason.empty() ? std::string("-") : guardReason);
        return;
    }

    uint64_t guid = 0;
    if (!TryGuardedCall("area object door IEntity::GetGuid", [entity]() { return entity->GetGuid(); }, guid, &guardReason) ||
        guid == 0)
    {
        m_lastAreaObjectEvent =
            "area_object_door_missing_guid_kind_" + std::to_string(eventKind) +
            "_reason_" + StatusToken(guardReason.empty() ? std::string("-") : guardReason);
        return;
    }

    if (guid == kCoopLobbyMainLiftDoorGuid &&
        NormalizeLevelName(GetCurrentLevelName()) ==
            "campaign/research/lobby")
    {
        // The cabin door is part of the lift's native parented mover graph.
        // Replaying another peer's independently timed Open/Close snapshot
        // mutates those physical children while the local cabin is elsewhere,
        // inflating its aggregate bounds and stalling the whole Client. Each
        // peer already runs the same vanilla mover/door lifecycle locally.
        m_lastAreaObjectEvent =
            "kept main-lift cabin door peer-local guid=" +
            std::to_string(guid);
        return;
    }

    bool opened = false;
    bool locked = false;
    bool powered = false;
    const bool stateOk =
        TryReadArkDoorBool(
            door, &ArkDoor::m_bOpened, opened,
            "area object door snapshot opened", &guardReason) &&
        TryReadArkDoorBool(
            door, &ArkDoor::m_bLocked, locked,
            "area object door snapshot locked", &guardReason) &&
        TryReadArkDoorBool(
            door, &ArkDoor::m_bPowered, powered,
            "area object door snapshot powered", &guardReason);
    if (!stateOk)
    {
        m_lastAreaObjectEvent =
            "area_object_door_snapshot_unreadable_kind_" +
            std::to_string(eventKind) + "_reason_" +
            StatusToken(guardReason.empty() ? std::string("-") : guardReason);
        return;
    }

    // Door state is one roundhouse vanilla snapshot, not three independently
    // ordered fields. Any Open/Close/Lock/Power callback republishes the full
    // tuple; reliable supersession then keeps only the latest coherent state.
    const uint32_t stateFlags =
        CoopProtocol::kAreaObjectDoorStateFlagSnapshot |
        (powered ? CoopProtocol::kAreaObjectDoorStateFlagPowered : 0u) |
        (locked ? CoopProtocol::kAreaObjectDoorStateFlagLocked : 0u);
    ArkDoorScriptPresentationState scriptState;
    const bool scriptStateOk = TryReadArkDoorScriptPresentation(
        entity, scriptState, &guardReason, false);
    const uint32_t presentationFlags = scriptStateOk
        ? (CoopProtocol::kAreaObjectDoorStateFlagScriptState |
            (scriptState.powerSupplied
                ? CoopProtocol::kAreaObjectDoorStateFlagPowerSupplied
                : 0u) |
            (scriptState.disrupted
                ? CoopProtocol::kAreaObjectDoorStateFlagDisrupted
                : 0u))
        : 0u;
    if (!m_applyingRemoteAreaObjectEvent)
        m_pendingRemoteDoorPowerConvergence.erase(guid);

    (void)value;
    QueueLocalAreaObjectEventForHook(
        CoopProtocol::kAreaObjectEventDoorOpen,
        guid,
        opened ? 1u : 0u,
        stateFlags | presentationFlags,
        reason);
}

void ModMain::OnLocalAreaObjectInteractiveObjectStateChanged(
    IEntity* entity,
    uint16_t eventKind,
    bool value,
    bool changed,
    const char* reason)
{
    if (!changed || !entity)
        return;
    if ((m_applyingRemoteAreaObjectEvent || m_remoteAreaObjectEchoSuppressSeconds > 0.0f) &&
        m_localAreaObjectCommandMutationDepth == 0)
    {
        ++m_reentrantAreaObjectEventSkips;
        m_lastAreaObjectEvent =
            "area_object_skip_remote_echo_kind_" + std::to_string(eventKind) +
            "_reason_" + StatusToken(reason && reason[0] ? std::string(reason) : std::string("-"));
        return;
    }
    if (eventKind != CoopProtocol::kAreaObjectEventInteractiveObjectActive &&
        eventKind != CoopProtocol::kAreaObjectEventInteractiveObjectDisabled)
    {
        m_lastAreaObjectEvent = "area_object_skip_unknown_interactive_object_kind_" + std::to_string(eventKind);
        return;
    }

    uint64_t guid = 0;
    std::string guardReason;
    if (!TryGuardedCall(
            "area object interactive IEntity::GetGuid",
            [entity]() { return entity->GetGuid(); },
            guid,
            &guardReason) || guid == 0)
    {
        m_lastAreaObjectEvent =
            "area_object_interactive_missing_guid_kind_" + std::to_string(eventKind) +
            "_reason_" + StatusToken(guardReason.empty() ? std::string("-") : guardReason);
        return;
    }
    if (CoopPtrHygiene::Enabled())
    {
        char extra[96];
        std::snprintf(extra, sizeof(extra), "guid=%llu kind=%u value=%d",
            static_cast<unsigned long long>(guid), static_cast<unsigned>(eventKind), value ? 1 : 0);
        CoopPtrHygiene::LogPtrWith("area_interactive_state_changed", entity, extra);
    }
    QueueLocalAreaObjectEventForHook(eventKind, guid, value ? 1u : 0u, 0, reason);
}

