void ModMain::OnLocalAreaObjectCargoContainerMotionStarted(
    ArkCargoContainer* cargo,
    bool docking,
    EArkDockingBay bay,
    EntityId dockingStationId,
    bool changed,
    const char* reason)
{
    if (!changed || !cargo || dockingStationId == INVALID_ENTITYID ||
        (bay != EArkDockingBay::bay1 && bay != EArkDockingBay::bay2))
    {
        return;
    }
    if ((m_applyingRemoteAreaObjectEvent || m_remoteAreaObjectEchoSuppressSeconds > 0.0f) &&
        m_localAreaObjectCommandMutationDepth == 0)
    {
        ++m_reentrantAreaObjectEventSkips;
        m_lastAreaObjectEvent =
            "area_object_skip_remote_cargo_motion_echo_reason_" +
            StatusToken(reason && reason[0] ? std::string(reason) : std::string("-"));
        return;
    }

    IEntity* cargoEntity = nullptr;
    IEntityClass* cargoClass = nullptr;
    const char* cargoClassName = nullptr;
    IEntity* stationEntity = nullptr;
    uint64_t cargoGuid = 0;
    uint64_t stationGuid = 0;
    std::string guardReason;
    const bool valid =
        TryGuardedCall("area cargo GetEntity", [cargo]() { return cargo->GetEntity(); }, cargoEntity, &guardReason) && cargoEntity &&
        TryGuardedCall("area cargo GetClass", [cargoEntity]() { return cargoEntity->GetClass(); }, cargoClass, &guardReason) && cargoClass &&
        TryGuardedCall("area cargo class GetName", [cargoClass]() { return cargoClass->GetName(); }, cargoClassName, &guardReason) &&
        cargoClassName && std::strcmp(cargoClassName, "ArkCargoContainer") == 0 &&
        TryGuardedCall("area cargo GetGuid", [cargoEntity]() { return cargoEntity->GetGuid(); }, cargoGuid, &guardReason) && cargoGuid != 0 &&
        gEnv && gEnv->pEntitySystem &&
        TryGuardedCall(
            "area cargo station GetEntity",
            [dockingStationId]() { return gEnv->pEntitySystem->GetEntity(dockingStationId); },
            stationEntity,
            &guardReason) && stationEntity &&
        TryGuardedCall("area cargo station GetGuid", [stationEntity]() { return stationEntity->GetGuid(); }, stationGuid, &guardReason) &&
        stationGuid != 0;
    if (!valid)
    {
        m_lastAreaObjectEvent =
            "area_object_cargo_motion_identity_missing_reason_" +
            StatusToken(guardReason.empty() ? std::string("-") : guardReason);
        return;
    }

    const uint16_t desiredState = static_cast<uint16_t>(
        docking ? EArkDockingState::docked : EArkDockingState::undocked);
    const uint16_t value = desiredState | (static_cast<uint16_t>(bay) << 8);
    QueueLocalAreaObjectEventForHook(
        CoopProtocol::kAreaObjectEventCargoContainerMotion,
        cargoGuid,
        value,
        static_cast<uint32_t>(stationGuid >> 32),
        reason,
        static_cast<int32_t>(static_cast<uint32_t>(stationGuid)));
}

