void ModMain::OnLocalAreaObjectKioskPresentationChanged(
    ArkKiosk* kiosk,
    uint16_t eventKind,
    int button,
    uint16_t value,
    const char* textValue,
    bool changed,
    const char* reason)
{
    if (!changed || !kiosk)
        return;
    if (m_applyingRemoteAreaObjectEvent &&
        m_localAreaObjectCommandMutationDepth == 0)
    {
        ++m_reentrantAreaObjectEventSkips;
        m_lastAreaObjectEvent =
            "area_object_skip_remote_kiosk_presentation_echo_kind_" +
            std::to_string(eventKind);
        return;
    }

    const bool buttonField =
        eventKind == CoopProtocol::kAreaObjectEventKioskButtonHeader ||
        eventKind == CoopProtocol::kAreaObjectEventKioskButtonBody ||
        eventKind == CoopProtocol::kAreaObjectEventKioskButtonVisible;
    const bool textField =
        eventKind == CoopProtocol::kAreaObjectEventKioskButtonHeader ||
        eventKind == CoopProtocol::kAreaObjectEventKioskButtonBody ||
        eventKind == CoopProtocol::kAreaObjectEventKioskHeader ||
        eventKind == CoopProtocol::kAreaObjectEventKioskBody;
    if ((!buttonField && eventKind != CoopProtocol::kAreaObjectEventKioskHeader &&
            eventKind != CoopProtocol::kAreaObjectEventKioskBody) ||
        (buttonField && (button < 0 || button >= 3)) ||
        (!buttonField && button != 0) ||
        (eventKind == CoopProtocol::kAreaObjectEventKioskButtonVisible && value > 1) ||
        (textField && (!textValue ||
            std::strlen(textValue) >= CoopProtocol::kAreaObjectWireTextValueCapacity)))
    {
        m_lastAreaObjectEvent =
            "area_object_skip_invalid_kiosk_presentation_kind_" +
            std::to_string(eventKind) + "_button_" + std::to_string(button);
        return;
    }

    std::string detail;
    uint64_t entityGuid = 0;
    const uint64_t stableId = GetArkInteractiveScreenStableIdForCoop(
        static_cast<ArkInteractiveScreen*>(kiosk), &entityGuid, &detail);
    if (stableId == 0)
    {
        m_lastAreaObjectEvent =
            "area_object_kiosk_presentation_missing_stable_id_" +
            StatusToken(detail);
        return;
    }

    QueueLocalAreaObjectEventForHook(
        eventKind,
        stableId,
        value,
        0,
        reason,
        button,
        textField ? textValue : nullptr);
}

void ModMain::OnLocalAreaObjectKioskButtonPressed(
    ArkKiosk* kiosk,
    int button,
    const char* reason)
{
    if (!kiosk)
        return;
    if (m_applyingRemoteAreaObjectEvent &&
        m_localAreaObjectCommandMutationDepth == 0)
    {
        ++m_reentrantAreaObjectEventSkips;
        m_lastAreaObjectEvent =
            "area_object_skip_remote_echo_kind_" +
            std::to_string(CoopProtocol::kAreaObjectEventKioskButtonPressed);
        return;
    }
    if (button < 0 || button >= 3)
    {
        m_lastAreaObjectEvent =
            "area_object_skip_invalid_kiosk_press_" + std::to_string(button);
        return;
    }

    std::string detail;
    uint64_t entityGuid = 0;
    const uint64_t stableId = GetArkInteractiveScreenStableIdForCoop(
        static_cast<ArkInteractiveScreen*>(kiosk), &entityGuid, &detail);
    if (stableId == 0)
    {
        m_lastAreaObjectEvent =
            "area_object_kiosk_press_missing_stable_id_" + StatusToken(detail);
        return;
    }
    QueueLocalAreaObjectEventForHook(
        CoopProtocol::kAreaObjectEventKioskButtonPressed,
        stableId,
        1,
        0,
        reason,
        button);
    if (m_networkMode == CoopNetworkMode::Host || IsClientAreaAuthorityActive())
        ArmArkElevatorTransitScan(reason);
    ArmKnownKioskActionRecovery(kiosk, button, reason);
}

bool ModMain::ShouldRouteLocalKioskPressToAreaAuthorityForHook(
    ArkKiosk* kiosk,
    ArkGenericElevatorKiosk* elevatorKiosk) const
{
    if (m_replayingRemoteMainLiftKioskPress)
        return false;
    if (m_networkMode != CoopNetworkMode::Client || IsClientAreaAuthorityActive())
        return false;

    // The Lobby main lift is deterministic ScriptControlledPhysics. The peer
    // that physically presses its in-cabin control must start that exact
    // vanilla graph in the original UI callback; replaying the press later
    // from packet dispatch corrupts the mover's physics bounds. The input is
    // still sent to Area Authority, whose typed transit commit acknowledges
    // this local run and starts it once on peers that did not press locally.
    if (elevatorKiosk)
    {
        uint64_t entityGuid = 0;
        std::string detail;
        const uint64_t stableId = GetArkInteractiveScreenStableIdForCoop(
            static_cast<ArkInteractiveScreen*>(elevatorKiosk),
            &entityGuid,
            &detail);
        if (stableId == kCoopLobbyMainLiftKioskGuid ||
            entityGuid == kCoopLobbyMainLiftKioskGuid ||
            IsNativeFanoutGenericElevatorKiosk(stableId, entityGuid))
        {
            // These authored movers need the process-local Vanilla graph on
            // the physically interacting peer. The reliable button command
            // remains the one-shot/deduplication source for all other peers.
            return false;
        }
        return true;
    }

    // The Hardware Labs Moon Door control owns shared moving geometry, so its
    // input belongs on current Area Authority. An ordinary ArkKiosk (including
    // Loading Bay's breaker) still runs locally once and converges only its
    // typed committed results.
    if (!kiosk)
        return true;

    static constexpr uint64_t kMoonDoorKioskGuid = 4643078995735641999ull;
    uint64_t entityGuid = 0;
    std::string detail;
    const uint64_t stableId = GetArkInteractiveScreenStableIdForCoop(
        static_cast<ArkInteractiveScreen*>(kiosk), &entityGuid, &detail);
    return stableId == kMoonDoorKioskGuid || entityGuid == kMoonDoorKioskGuid;
}

bool ModMain::ShouldSuppressUnownedKioskOutputForHook() const
{
    return m_networkMode != CoopNetworkMode::Off && IsSessionGameplayReady();
}

void ModMain::RecordSuppressedUnownedKioskOutputForHook(ArkKiosk* kiosk, int button)
{
    ++m_suppressedUnownedKioskOutputs;
    uint64_t entityGuid = 0;
    std::string detail;
    const uint64_t stableId = kiosk
        ? GetArkInteractiveScreenStableIdForCoop(
            static_cast<ArkInteractiveScreen*>(kiosk), &entityGuid, &detail)
        : 0;
    m_lastAreaObjectEvent =
        "suppressed_unowned_kiosk_output_button_" + std::to_string(button) +
        "_stable_" + std::to_string(stableId) +
        "_guid_" + std::to_string(entityGuid) +
        "_detail_" + StatusToken(detail.empty() ? std::string("-") : detail);
    LogCoop(m_lastAreaObjectEvent);
}

void ModMain::ArmArkElevatorTransitScan(
    const char* reason,
    uint64_t preferredElevatorGuid)
{
    if (m_networkMode != CoopNetworkMode::Host && !IsClientAreaAuthorityActive())
        return;

    const bool scanWasIdle = m_pendingArkElevatorTransitScanSeconds <= 0.0f;
    if (scanWasIdle)
    {
        m_pendingArkElevatorTransitScanGuid = preferredElevatorGuid;
    }
    else if (preferredElevatorGuid == 0 ||
        (m_pendingArkElevatorTransitScanGuid != 0 &&
            m_pendingArkElevatorTransitScanGuid != preferredElevatorGuid))
    {
        // Concurrent unknown/different elevator inputs require the bounded
        // fallback scan. A repeated input for one known elevator remains O(1).
        m_pendingArkElevatorTransitScanGuid = 0;
    }

    // The Lobby lift's authored doors and mission graph may not publish
    // m_transitRequest until several seconds after the UI callback. Observe
    // that exact Vanilla entity long enough to see the real request rather
    // than synthesizing one from the pressed button.
    const float observationSeconds =
        preferredElevatorGuid != 0 ? 8.0f : 1.5f;
    m_pendingArkElevatorTransitScanSeconds =
        std::max(m_pendingArkElevatorTransitScanSeconds, observationSeconds);
    m_arkElevatorTransitScanAccumulator = 0.1f;
    (void)reason;
}

void ModMain::ArmKnownKioskActionRecovery(ArkKiosk* kiosk, int button, const char* reason)
{
    // Arboretum's Loading Bay breaker is authored as ButtonOnePressed ->
    // Processing -> one-second FlowGraph delay -> ArkDoor PowerOn/PowerOff ->
    // Default. Some runtime loads lose the delayed callback after Processing.
    // Let vanilla finish first and recover only this extracted authored pair.
    static constexpr uint64_t kLoadingBayKioskGuid = 5697454515655116208ull;
    static constexpr uint64_t kLoadingBayDoorGuid = 5087184143287464001ull;
    if (!kiosk || button != 0 || m_networkMode == CoopNetworkMode::Off ||
        !IsSessionGameplayReady() || !gEnv || !gEnv->pEntitySystem)
    {
        return;
    }

    uint64_t kioskGuid = 0;
    std::string guardReason;
    IEntity* kioskEntity = nullptr;
    const bool kioskIdentityOk =
        TryGuardedCall(
            "known kiosk recovery GetEntity",
            [kiosk]() { return kiosk->GetEntity(); },
            kioskEntity,
            &guardReason) &&
        kioskEntity &&
        TryGuardedCall(
            "known kiosk recovery GetGuid",
            [kioskEntity]() { return kioskEntity->GetGuid(); },
            kioskGuid,
            &guardReason) &&
        kioskGuid == kLoadingBayKioskGuid;
    if (!kioskIdentityOk)
        return;

    EntityId doorEntityId = INVALID_ENTITYID;
    IEntity* doorEntity = nullptr;
    if (!TryGuardedCall(
            "known kiosk recovery FindEntityByGuid",
            []()
            {
                return gEnv->pEntitySystem->FindEntityByGuid(
                    static_cast<EntityGUID>(kLoadingBayDoorGuid));
            },
            doorEntityId,
            &guardReason) ||
        doorEntityId == INVALID_ENTITYID ||
        !TryGuardedCall(
            "known kiosk recovery GetEntity door",
            [doorEntityId]() { return gEnv->pEntitySystem->GetEntity(doorEntityId); },
            doorEntity,
            &guardReason) ||
        !doorEntity)
    {
        LogCoop(
            "known kiosk recovery arm missing Loading Bay door reason=" +
            StatusToken(guardReason.empty() ? std::string("-") : guardReason));
        return;
    }

    ArkDoor* door = GetArkDoorExtensionFromEntity(doorEntity);
    bool powered = false;
    if (!door ||
        !TryReadArkDoorBool(
            door,
            &ArkDoor::m_bPowered,
            powered,
            "known kiosk recovery door powered before",
            &guardReason))
    {
        LogCoop(
            "known kiosk recovery arm unreadable Loading Bay door reason=" +
            StatusToken(guardReason.empty() ? std::string("-") : guardReason));
        return;
    }

    m_pendingKioskActionRecovery.active = true;
    m_pendingKioskActionRecovery.dueTickMs = GetTickCount64() + 1500ull;
    m_pendingKioskActionRecovery.kioskGuid = kLoadingBayKioskGuid;
    m_pendingKioskActionRecovery.doorGuid = kLoadingBayDoorGuid;
    m_pendingKioskActionRecovery.button = button;
    m_pendingKioskActionRecovery.initialDoorPowered = powered;
    m_pendingKioskActionRecovery.desiredDoorPowered = !powered;
    m_pendingKioskActionRecovery.worldEpoch = m_localWorldEpoch;
    LogCoop(
        "known kiosk recovery armed kiosk=" +
        std::to_string(kLoadingBayKioskGuid) +
        " door=" + std::to_string(kLoadingBayDoorGuid) +
        " initialPowered=" + std::to_string(powered ? 1 : 0) +
        " desiredPowered=" + std::to_string(powered ? 0 : 1));
    (void)reason;
}

void ModMain::TickKnownKioskActionRecovery(float frameTime)
{
    if (!m_pendingKioskActionRecovery.active)
        return;

    if (m_networkMode == CoopNetworkMode::Off || !IsSessionGameplayReady() ||
        m_pendingKioskActionRecovery.worldEpoch != m_localWorldEpoch ||
        !gEnv || !gEnv->pEntitySystem)
    {
        LogCoop("known kiosk recovery canceled session changed");
        m_pendingKioskActionRecovery = {};
        return;
    }

    if (GetTickCount64() < m_pendingKioskActionRecovery.dueTickMs)
        return;
    (void)frameTime;

    const PendingKioskActionRecovery recovery = m_pendingKioskActionRecovery;
    m_pendingKioskActionRecovery = {};

    EntityId kioskEntityId = INVALID_ENTITYID;
    uint64_t kioskGuid = 0;
    float kioskDistance = -1.0f;
    std::string lookupDetail;
    ArkKiosk* kiosk = FindArkKioskByStableIdForCoop(
        recovery.kioskGuid,
        &kioskEntityId,
        &kioskGuid,
        &kioskDistance,
        &lookupDetail);

    EntityId doorEntityId = INVALID_ENTITYID;
    IEntity* doorEntity = nullptr;
    std::string reason;
    const bool doorIdentityOk =
        TryGuardedCall(
            "known kiosk recovery FindEntityByGuid tick",
            [&recovery]()
            {
                return gEnv->pEntitySystem->FindEntityByGuid(
                    static_cast<EntityGUID>(recovery.doorGuid));
            },
            doorEntityId,
            &reason) &&
        doorEntityId != INVALID_ENTITYID &&
        TryGuardedCall(
            "known kiosk recovery GetEntity tick",
            [doorEntityId]() { return gEnv->pEntitySystem->GetEntity(doorEntityId); },
            doorEntity,
            &reason) &&
        doorEntity;
    ArkDoor* door = doorIdentityOk ? GetArkDoorExtensionFromEntity(doorEntity) : nullptr;
    if (!kiosk || !door)
    {
        LogCoop(
            "known kiosk recovery canceled missing runtime object kiosk=" +
            std::to_string(recovery.kioskGuid) +
            " door=" + std::to_string(recovery.doorGuid));
        return;
    }

    EArkKioskButtonState kioskState = EArkKioskButtonState::Disabled;
    bool doorPowered = recovery.initialDoorPowered;
    const bool stateOk =
        TryReadArkKioskButtonState(
            kiosk,
            recovery.button,
            kioskState,
            nullptr,
            "known kiosk recovery button state",
            &reason) &&
        TryReadArkDoorBool(
            door,
            &ArkDoor::m_bPowered,
            doorPowered,
            "known kiosk recovery door powered tick",
            &reason);
    if (!stateOk)
    {
        LogCoop(
            "known kiosk recovery canceled unreadable state reason=" +
            StatusToken(reason.empty() ? std::string("-") : reason));
        return;
    }

    if (doorPowered != recovery.initialDoorPowered)
    {
        // The authored delayed FlowGraph produced the toggle. Never overwrite
        // a real vanilla result.
        return;
    }

    // The extracted Sequentializer can complete a stale/no-op branch after a
    // different peer used its own local copy. The authored control is still a
    // binary breaker: if this press produced no power mutation, complete the
    // opposite branch locally and publish that typed vanilla-equivalent result.

    ++m_localAreaObjectCommandMutationDepth;
    const bool powerCallOk = TryGuardedVoidCall(
        "known kiosk recovery ArkDoor OnPower",
        [door, &recovery]() { door->OnPower(recovery.desiredDoorPowered); },
        &reason);
    const bool buttonCallOk = TryGuardedVoidCall(
        "known kiosk recovery ArkKiosk SetButtonState",
        [kiosk, &recovery]()
        {
            kiosk->SetButtonState(recovery.button, EArkKioskButtonState::Default);
        },
        &reason);
    const char* const desiredHeader = recovery.desiredDoorPowered
        ? "@fg_LS_powerbreakerheader2"
        : "@fg_LS_powerbreakerheader1";
    const bool headerCallOk = TryGuardedVoidCall(
        "known kiosk recovery ArkKiosk SetButtonHeader",
        [kiosk, &recovery, desiredHeader]()
        {
            kiosk->SetButtonHeader(recovery.button, string(desiredHeader));
        },
        &reason);
    const bool bodyCallOk = TryGuardedVoidCall(
        "known kiosk recovery ArkKiosk SetButtonBody",
        [kiosk, &recovery]()
        {
            kiosk->SetButtonBody(
                recovery.button,
                string("@FG_LOC_AR_PowerKiosk_Loading_Bay_Door"));
        },
        &reason);
    const bool refreshCallOk = TryGuardedVoidCall(
        "known kiosk recovery ArkKiosk RefreshUI",
        [kiosk]() { kiosk->RefreshUI(false); },
        &reason);
    if (m_localAreaObjectCommandMutationDepth > 0)
        --m_localAreaObjectCommandMutationDepth;

    ForceArkDoorRuntimeUpdate(door, "known kiosk recovery door update");
    TryGuardedVoidCall(
        "known kiosk recovery UpdateNavigation",
        [door]() { door->UpdateNavigation(); },
        &reason);
    TryGuardedVoidCall(
        "known kiosk recovery UpdateDisplayName",
        [door]() { door->UpdateDisplayName(); },
        &reason);

    EArkKioskButtonState finalKioskState = EArkKioskButtonState::Disabled;
    std::string finalKioskHeader;
    bool finalDoorPowered = recovery.initialDoorPowered;
    const bool finalStateOk =
        TryReadArkKioskButtonState(
            kiosk,
            recovery.button,
            finalKioskState,
            nullptr,
            "known kiosk recovery final button state",
            &reason) &&
        TryReadArkDoorBool(
            door,
            &ArkDoor::m_bPowered,
            finalDoorPowered,
            "known kiosk recovery final door powered",
            &reason) &&
        TryGuardedCall(
            "known kiosk recovery final button header",
            [kiosk, &recovery]()
            {
                return std::string(
                    kiosk->m_buttons[static_cast<size_t>(recovery.button)].m_header.c_str());
            },
            finalKioskHeader,
            &reason);
    LogCoop(
        std::string("known kiosk recovery ") +
        (powerCallOk && buttonCallOk && headerCallOk && bodyCallOk &&
                refreshCallOk && finalStateOk &&
                finalDoorPowered == recovery.desiredDoorPowered &&
                finalKioskState == EArkKioskButtonState::Default &&
                finalKioskHeader == desiredHeader
            ? "applied"
            : "failed") +
        " kiosk=" + std::to_string(recovery.kioskGuid) +
        " door=" + std::to_string(recovery.doorGuid) +
        " powered=" + std::to_string(finalDoorPowered ? 1 : 0) +
        " buttonState=" + std::to_string(static_cast<uint16_t>(finalKioskState)) +
        " buttonHeader=" + StatusToken(
            finalKioskHeader.empty() ? std::string("-") : finalKioskHeader) +
        " reason=" + StatusToken(reason.empty() ? std::string("-") : reason));
}

bool ModMain::ObserveArkElevatorTransitForAuthority(IEntity* entity)
{
    if (!entity)
        return false;

    IEntityClass* entityClass = nullptr;
    const char* className = nullptr;
    if (!TryGuardedCall(
            "elevator transit scan GetClass",
            [entity]() { return entity->GetClass(); },
            entityClass,
            nullptr) ||
        !entityClass ||
        !TryGuardedCall(
            "elevator transit scan class GetName",
            [entityClass]() { return entityClass->GetName(); },
            className,
            nullptr) ||
        !className || std::strcmp(className, "ArkElevator") != 0)
    {
        return false;
    }

    uint64_t guid = 0;
    IScriptTable* table = nullptr;
    std::string request;
    bool readRequest = false;
    const bool requestOk =
        TryGuardedCall(
            "elevator transit scan GetGuid",
            [entity]() { return entity->GetGuid(); },
            guid,
            nullptr) &&
        guid != 0 &&
        TryGuardedCall(
            "elevator transit scan GetScriptTable",
            [entity]() { return entity->GetScriptTable(); },
            table,
            nullptr) &&
        table &&
        TryGuardedCall(
            "elevator transit scan m_transitRequest",
            [table, &request]()
            {
                ScriptAnyValue value;
                const bool read = table->GetValueAny("m_transitRequest", value);
                if (read && value.type == ANY_TSTRING && value.str)
                    request = value.str;
                return read;
            },
            readRequest,
            nullptr) &&
        readRequest;
    if (guid == 0)
        return false;
    if (!requestOk || request.empty())
    {
        m_activeArkElevatorTransitByGuid.erase(guid);
        return false;
    }

    IEntityLink* links = nullptr;
    if (!TryGuardedCall(
            "elevator transit scan GetEntityLinks",
            [entity]()
            {
                return CEntity::FGetEntityLinks(static_cast<CEntity*>(entity));
            },
            links,
            nullptr))
    {
        return false;
    }

    bool authoredLink = false;
    for (IEntityLink* link = links; link; link = link->next)
    {
        if (link->entityId != INVALID_ENTITYID && request == link->name)
        {
            authoredLink = true;
            break;
        }
    }
    if (!authoredLink)
        return false;

    const auto activeIt = m_activeArkElevatorTransitByGuid.find(guid);
    if (activeIt != m_activeArkElevatorTransitByGuid.end() &&
        activeIt->second == request)
    {
        return false;
    }

    if (guid == kCoopLobbyMainLiftGuid &&
        request == kCoopMainLiftOutageLink)
    {
        // PhAmbush is not merely another lift destination. Its reliable
        // semantic event replays the complete authored RemoteEvent graph on
        // every peer, which includes this TransitToLink call. Sending a
        // second kind-29 transit would start the observer mover twice.
        m_activeArkElevatorTransitByGuid[guid] = request;
        return false;
    }

    if (!QueueLocalAreaObjectEventForHook(
            CoopProtocol::kAreaObjectEventElevatorTransit,
            guid,
            1,
            0,
            "AreaAuthority committed ArkElevator transit",
            0,
            request.c_str()))
    {
        return false;
    }

    m_activeArkElevatorTransitByGuid[guid] = request;
    if (guid == kCoopLobbyMainLiftGuid &&
        m_mainLiftOutageAwaitingContinuation)
    {
        // A remote native death can finalize the peer corpse without firing
        // the spawner-bound FlowGraph Dead output. The Area Authority's
        // authored post-outage request is the canonical continuation.
        m_mainLiftOutageAwaitingContinuation = false;
    }
    return true;
}

void ModMain::TickArkElevatorTransitScan(float frameTime)
{
    const bool localAreaAuthority =
        m_networkMode == CoopNetworkMode::Host || IsClientAreaAuthorityActive();
    if (!localAreaAuthority ||
        (m_pendingArkElevatorTransitScanSeconds <= 0.0f &&
            !m_mainLiftOutageAwaitingContinuation) ||
        !IsSessionGameplayReady() ||
        !gEnv || !gEnv->pEntitySystem)
    {
        return;
    }

    const float delta = std::max(0.0f, frameTime);
    const bool hadPendingScan =
        m_pendingArkElevatorTransitScanSeconds > 0.0f;
    const uint64_t preferredGuid =
        hadPendingScan ? m_pendingArkElevatorTransitScanGuid : 0;
    if (m_pendingArkElevatorTransitScanSeconds > 0.0f)
    {
        m_pendingArkElevatorTransitScanSeconds =
            std::max(0.0f, m_pendingArkElevatorTransitScanSeconds - delta);
    }
    m_arkElevatorTransitScanAccumulator += delta;
    if (m_arkElevatorTransitScanAccumulator < 0.1f)
        return;
    m_arkElevatorTransitScanAccumulator = 0.0f;

    // A known lift UI callback observes only that exact entity. The outage
    // continuation likewise needs only the Lobby lift. Whole-level iteration
    // remains a short fallback for generic ArkKiosk/unknown elevator graphs.
    const uint64_t exactGuid = preferredGuid != 0
        ? preferredGuid
        : (!hadPendingScan && m_mainLiftOutageAwaitingContinuation
            ? kCoopLobbyMainLiftGuid
            : 0);
    if (exactGuid != 0)
    {
        const EntityId entityId = gEnv->pEntitySystem->FindEntityByGuid(
            static_cast<EntityGUID>(exactGuid));
        IEntity* entity = entityId != INVALID_ENTITYID
            ? gEnv->pEntitySystem->GetEntity(entityId)
            : nullptr;
        const bool published =
            ObserveArkElevatorTransitForAuthority(entity);
        if (published && preferredGuid == exactGuid)
        {
            m_pendingArkElevatorTransitScanSeconds = 0.0f;
            m_pendingArkElevatorTransitScanGuid = 0;
        }
        else if (m_pendingArkElevatorTransitScanSeconds <= 0.0f)
        {
            m_pendingArkElevatorTransitScanGuid = 0;
        }
        return;
    }

    IEntityIt* rawIterator = nullptr;
    std::string reason;
    if (!TryGuardedCall(
            "elevator transit scan GetEntityIterator",
            []() { return gEnv->pEntitySystem->GetEntityIterator(); },
            rawIterator,
            &reason) ||
        !rawIterator)
    {
        return;
    }

    IEntityItPtr iterator = rawIterator;
    TryGuardedVoidCall("elevator transit scan MoveFirst", [&iterator]() { iterator->MoveFirst(); }, nullptr);
    while (true)
    {
        bool isEnd = false;
        if (TryGuardedCall(
                "elevator transit scan IsEnd",
                [&iterator]() { return iterator->IsEnd(); },
                isEnd,
                &reason) &&
            isEnd)
        {
            break;
        }
        IEntity* entity = nullptr;
        if (!TryGuardedCall(
                "elevator transit scan Next",
                [&iterator]() { return iterator->Next(); },
                entity,
                &reason) ||
            !entity)
        {
            break;
        }

        ObserveArkElevatorTransitForAuthority(entity);
    }

    if (m_pendingArkElevatorTransitScanSeconds <= 0.0f)
        m_pendingArkElevatorTransitScanGuid = 0;
}

bool ModMain::IsLocalPlayerInsideMainLiftShaft() const
{
    if (!gEnv || !gEnv->pEntitySystem || !ArkPlayer::GetInstancePtr())
        return false;

    IEntity* playerEntity = ArkPlayer::GetInstance().GetEntity();
    const EntityId liftId = gEnv->pEntitySystem->FindEntityByGuid(
        static_cast<EntityGUID>(kCoopLobbyMainLiftGuid));
    IEntity* liftEntity = liftId != INVALID_ENTITYID
        ? gEnv->pEntitySystem->GetEntity(liftId)
        : nullptr;
    if (!playerEntity || !liftEntity)
        return false;

    Vec3 playerPosition(ZERO);
    Vec3 liftPosition(ZERO);
    const bool playerPositionOk = TryGuardedCall(
        "main lift outage scope player position",
        [playerEntity]() { return playerEntity->GetWorldPos(); },
        playerPosition,
        nullptr);
    const bool liftPositionOk = TryGuardedCall(
        "main lift outage scope lift position",
        [liftEntity]() { return liftEntity->GetWorldPos(); },
        liftPosition,
        nullptr);
    if (!playerPositionOk || !liftPositionOk ||
        !IsFiniteVec3Trace(playerPosition) || !IsFiniteVec3Trace(liftPosition))
    {
        return false;
    }

    // The shaft spans all three authored stations, but not the floor
    // vestibules outside its doors. Only players physically in the cabin/shaft
    // receive the blackout and ambush presentation.
    constexpr float kShaftHalfExtentX = 5.0f;
    constexpr float kShaftHalfExtentY = 5.0f;
    constexpr float kShaftMinZ = 320.0f;
    constexpr float kShaftMaxZ = 920.0f;
    return std::fabs(playerPosition.x - liftPosition.x) <= kShaftHalfExtentX &&
        std::fabs(playerPosition.y - liftPosition.y) <= kShaftHalfExtentY &&
        playerPosition.z >= kShaftMinZ &&
        playerPosition.z <= kShaftMaxZ;
}

void ModMain::TickMainLiftOutageEvent(float frameTime)
{
    const float delta = std::max(0.0f, frameTime);
    m_mainLiftOutageEnemyCaptureSeconds =
        std::max(0.0f, m_mainLiftOutageEnemyCaptureSeconds - delta);

    if (m_networkMode == CoopNetworkMode::Off ||
        !IsSessionGameplayReady() ||
        m_saveLoadGuardActive ||
        !gEnv || !gEnv->pEntitySystem ||
        NormalizeLevelName(GetCurrentLevelName()) != "campaign/research/lobby")
    {
        return;
    }

    const EntityId liftId = gEnv->pEntitySystem->FindEntityByGuid(
        static_cast<EntityGUID>(kCoopLobbyMainLiftGuid));
    IEntity* liftEntity = liftId != INVALID_ENTITYID
        ? gEnv->pEntitySystem->GetEntity(liftId)
        : nullptr;
    IScriptTable* table = liftEntity ? liftEntity->GetScriptTable() : nullptr;
    if (!liftEntity || !table)
        return;

    if (m_mainLiftOutageAwaitingContinuation &&
        m_mainLiftOutageEnemyEntityId != INVALID_ENTITYID)
    {
        IEntity* outageEnemy = gEnv->pEntitySystem->GetEntity(
            m_mainLiftOutageEnemyEntityId);
        ArkNpc* outageNpc = outageEnemy
            ? EntityUtils::GetArkNpc(outageEnemy)
            : nullptr;
        if (outageEnemy && outageNpc && !outageNpc->IsDead())
        {
            const Vec3 liftPosition = liftEntity->GetWorldPos();
            const Vec3 enemyPosition = outageEnemy->GetWorldPos();
            const bool outsideCabin =
                std::fabs(enemyPosition.x - liftPosition.x) > 4.0f ||
                enemyPosition.y < liftPosition.y + 0.5f ||
                enemyPosition.y > liftPosition.y + 4.0f ||
                enemyPosition.z < liftPosition.z - 0.25f ||
                enemyPosition.z > liftPosition.z + 5.5f;
            if (outsideCabin)
            {
                const Vec3 cabinPosition(
                    std::clamp(
                        enemyPosition.x,
                        liftPosition.x - 3.8f,
                        liftPosition.x + 3.8f),
                    std::clamp(
                        enemyPosition.y,
                        liftPosition.y + 0.7f,
                        liftPosition.y + 3.7f),
                    liftPosition.z + 0.01f);
                TryGuardedVoidCall(
                    "main lift outage enemy keep inside cabin",
                    [outageEnemy, cabinPosition]()
                    {
                        outageEnemy->SetPos(cabinPosition, 0, true, true);
                    },
                    nullptr);
            }
        }
    }

    m_mainLiftOutageScanAccumulator += delta;
    if (m_mainLiftOutageScanAccumulator < 0.05f &&
        !m_pendingMainLiftOutagePresentation)
    {
        return;
    }
    m_mainLiftOutageScanAccumulator = 0.0f;

    std::string request;
    ScriptAnyValue requestValue;
    const bool requestRead = table->GetValueAny("m_transitRequest", requestValue);
    if (requestRead && requestValue.type == ANY_TSTRING && requestValue.str)
        request = requestValue.str;

    if (request == kCoopMainLiftOutageLink)
    {
        if (m_mainLiftOutageSuppressedForLocalPlayer ||
            !IsLocalPlayerInsideMainLiftShaft())
        {
            if (!m_mainLiftOutageSuppressedForLocalPlayer)
            {
                m_mainLiftOutageSuppressedForLocalPlayer = true;
                ++m_mainLiftOutageScopeSkips;
                m_lastMainLiftOutageEvent =
                    "suppressed observed main-lift outage outside shaft";
                LogCoop(m_lastMainLiftOutageEvent);
            }
            m_mainLiftOutsideOutageAwaitingNativeContinuation = true;
            return;
        }

        m_mainLiftOutageAwaitingContinuation = true;
        if (!m_mainLiftOutagePresented)
        {
            m_mainLiftOutagePresented = true;
            ++m_mainLiftOutagePresentations;
            m_mainLiftOutageEnemyCaptureSeconds = 30.0f;
            m_lastMainLiftOutageEvent =
                "observed native main-lift outage request PhAmbush";
            LogCoop(m_lastMainLiftOutageEvent);
        }

        if (!m_mainLiftOutageAnnounced)
        {
            if (QueueLocalAreaObjectEventForHook(
                    CoopProtocol::kAreaObjectEventMainLiftOutage,
                    kCoopLobbyMainLiftGuid,
                    1,
                    0,
                    "native ArkElevator PhAmbush observed",
                    1,
                    kCoopMainLiftOutageRemoteEventWireValue))
            {
                m_mainLiftOutageAnnounced = true;
                ++m_mainLiftOutageAnnouncements;
                m_mainLiftOutageEventId = m_lastAreaObjectEventId;
                m_mainLiftOutageEnemyStableId =
                    BuildMainLiftOutageEnemyStableId(m_mainLiftOutageEventId);
                m_lastMainLiftOutageEvent =
                    "announced decentralized main-lift outage event=" +
                    std::to_string(m_mainLiftOutageEventId) +
                    " enemyStable=" +
                    std::to_string(m_mainLiftOutageEnemyStableId);
                LogCoop(m_lastMainLiftOutageEvent);
            }
        }
    }

    if (!m_pendingMainLiftOutagePresentation)
        return;
    if (m_pendingMainLiftOutagePresentationDelayFrames > 0)
    {
        --m_pendingMainLiftOutagePresentationDelayFrames;
        return;
    }

    std::string reason;
    m_replayingMainLiftOutageRemoteEvent = true;
    const bool callOk = ActivateRegisteredMainLiftOutageRemoteEvent(reason);
    m_replayingMainLiftOutageRemoteEvent = false;

    ++m_pendingMainLiftOutagePresentationAttempts;
    if (!callOk)
    {
        if (m_pendingMainLiftOutagePresentationAttempts < 3)
        {
            m_pendingMainLiftOutagePresentationDelayFrames = 2;
            m_lastMainLiftOutageEvent =
                "retry decentralized main-lift outage presentation reason=" +
                StatusToken(reason.empty() ? std::string("-") : reason);
        }
        else
        {
            m_pendingMainLiftOutagePresentation = false;
            m_lastMainLiftOutageEvent =
                "failed decentralized main-lift outage presentation reason=" +
                StatusToken(reason.empty() ? std::string("-") : reason);
            LogCoop(m_lastMainLiftOutageEvent);
        }
        return;
    }

    Vec3 destinationPosition = liftEntity->GetWorldPos();
    if (IEntityLink* links = CEntity::FGetEntityLinks(
            static_cast<CEntity*>(liftEntity)))
    {
        for (IEntityLink* link = links; link; link = link->next)
        {
            if (link->entityId == INVALID_ENTITYID ||
                std::strcmp(link->name, kCoopMainLiftOutageLink) != 0)
            {
                continue;
            }
            if (IEntity* destination = gEnv->pEntitySystem->GetEntity(link->entityId))
                destinationPosition = destination->GetWorldPos();
            break;
        }
    }

    m_pendingMainLiftOutagePresentation = false;
    if (!m_mainLiftOutagePresented)
    {
        m_mainLiftOutagePresented = true;
        ++m_mainLiftOutagePresentations;
    }
    m_mainLiftOutageEnemyCaptureSeconds = 30.0f;
    if (m_networkMode == CoopNetworkMode::Client &&
        !IsClientAreaAuthorityActive())
    {
        m_remoteMainLiftPresentationActive = true;
        m_remoteMainLiftPresentationSettleSeconds = 0.0f;
        m_remoteMainLiftTargetPosition = destinationPosition;
    }
    m_lastMainLiftOutageEvent =
        "started decentralized main-lift outage presentation event=" +
        std::to_string(m_mainLiftOutageEventId) +
        " remoteEvent=" + std::to_string(kCoopMainLiftOutageRemoteEventId) +
        " source=" + StatusToken(reason) +
        " target=" + FormatVec3Trace(destinationPosition);
    LogCoop(m_lastMainLiftOutageEvent);
}

void ModMain::TickMainLiftPassengerCarry(float frameTime)
{
    // ScriptControlledPhysics moves the Talos I main lift without attaching
    // player character controllers to the mover hierarchy. Preserve only a
    // player who was physically inside the cabin when it started moving. A
    // player waiting on a floor remains completely local and untouched.
    static constexpr uint64_t kLobbyMainLiftGuid = 5617616201710343076ULL;
    constexpr float kCabinMinX = -4.25f;
    constexpr float kCabinMaxX = 4.25f;
    constexpr float kCabinMinY = 0.35f;
    constexpr float kCabinMaxY = 4.45f;
    constexpr float kCabinMinZ = -0.75f;
    constexpr float kCabinMaxZ = 4.25f;
    constexpr float kMovingEpsilon = 0.0025f;
    constexpr float kCorrectionEpsilon = 0.075f;
    constexpr float kNativeObserverCorrectionEpsilon = 2.0f;
    constexpr float kReleaseFloorClearance = 0.08f;
    constexpr uint32_t kStationaryReleaseFrames = 90;

    auto resetTracking = [this](const char* reason)
    {
        if (m_mainLiftPassengerAttached)
            ++m_mainLiftPassengerReleases;
        m_mainLiftPassengerEntityId = INVALID_ENTITYID;
        m_mainLiftHasLastPosition = false;
        m_mainLiftPassengerAttached = false;
        m_mainLiftPassengerRelativeZ = 0.0f;
        m_mainLiftPassengerStationaryFrames = 0;
        m_lastMainLiftPassengerEvent = reason && reason[0] ? reason : "main lift passenger reset";
    };

    if (m_networkMode == CoopNetworkMode::Off ||
        !IsSessionGameplayReady() ||
        m_saveLoadGuardActive ||
        !gEnv ||
        !gEnv->pEntitySystem ||
        !ArkPlayer::GetInstancePtr() ||
        NormalizeLevelName(GetCurrentLevelName()) != "campaign/research/lobby")
    {
        if (m_mainLiftHasLastPosition || m_mainLiftPassengerAttached)
            resetTracking("main lift passenger unavailable");
        return;
    }

    IEntity* liftEntity = m_mainLiftPassengerEntityId != INVALID_ENTITYID
        ? gEnv->pEntitySystem->GetEntity(m_mainLiftPassengerEntityId)
        : nullptr;
    if (!liftEntity || liftEntity->GetGuid() != kLobbyMainLiftGuid)
    {
        const EntityId liftId = gEnv->pEntitySystem->FindEntityByGuid(
            static_cast<EntityGUID>(kLobbyMainLiftGuid));
        liftEntity = liftId != INVALID_ENTITYID
            ? gEnv->pEntitySystem->GetEntity(liftId)
            : nullptr;
        m_mainLiftPassengerEntityId = liftEntity ? liftId : INVALID_ENTITYID;
    }

    IEntity* playerEntity = ArkPlayer::GetInstance().GetEntity();
    if (!liftEntity || !playerEntity)
    {
        if (m_mainLiftHasLastPosition || m_mainLiftPassengerAttached)
            resetTracking("main lift passenger entity missing");
        return;
    }

    if (m_pendingRemoteMainLiftTransit &&
        m_pendingRemoteMainLiftTransitDelayFrames == 0 &&
        !m_pendingRemoteMainLiftObserverReplay &&
        m_pendingRemoteMainLiftTransitLink == "Arboretum" &&
        m_mainLiftOutageAwaitingContinuation &&
        !m_mainLiftOutageSuppressedForLocalPlayer)
    {
        // The peer-local outage graph normally consumes its own Phantom Dead
        // output and requests Arboretum before this fallback expires. Observe
        // that native request instead of pressing the kiosk a second time,
        // which would run two mover/door graphs against one compound body.
        IScriptTable* liftTable = liftEntity->GetScriptTable();
        std::string activeRequest;
        ScriptAnyValue requestValue;
        const bool requestRead =
            liftTable &&
            liftTable->GetValueAny("m_transitRequest", requestValue);
        if (requestRead &&
            requestValue.type == ANY_TSTRING &&
            requestValue.str)
        {
            activeRequest = requestValue.str;
        }
        if (activeRequest == "Arboretum")
        {
            m_pendingRemoteMainLiftTransit = false;
            m_mainLiftOutageAwaitingContinuation = false;
            m_remoteMainLiftPresentationActive = true;
            m_remoteMainLiftPresentationSettleSeconds = 0.0f;
            m_remoteMainLiftTargetPosition =
                m_pendingRemoteMainLiftTransitTargetPosition;
            m_lastRemoteMainLiftPresentationEvent =
                "acknowledged shaft-local outage Arboretum continuation";
            LogCoop(m_lastRemoteMainLiftPresentationEvent);
        }
    }

    if (m_pendingRemoteMainLiftTransit &&
        ((m_networkMode == CoopNetworkMode::Client &&
            !IsClientAreaAuthorityActive()) ||
            m_pendingRemoteMainLiftObserverReplay))
    {
        if (m_pendingRemoteMainLiftTransitDelayFrames > 0)
        {
            --m_pendingRemoteMainLiftTransitDelayFrames;
        }
        else
        {
            const bool outageContinuationReplay =
                m_mainLiftOutsideOutageAwaitingNativeContinuation;
            const std::string pendingLink = m_pendingRemoteMainLiftTransitLink;
            std::string transitDetail;
            const bool previousApplying = m_applyingRemoteAreaObjectEvent;
            m_applyingRemoteAreaObjectEvent = true;
            bool applied = false;
            int button = -1;
            bool eventResult = false;
            bool activationResult = false;
            std::string lookupDetail;

            {
                button =
                    pendingLink == "Lobby" ? 1 :
                    pendingLink == "Arboretum" ? 0 :
                    m_pendingRemoteMainLiftTransitTargetPosition.z <
                            liftEntity->GetWorldPos().z
                        ? 1
                        : 0;
                EntityId kioskEntityId = INVALID_ENTITYID;
                uint64_t kioskGuid = 0;
                float kioskDistance = -1.0f;
                ArkGenericElevatorKiosk* kiosk =
                    FindArkGenericElevatorKioskByStableIdForCoop(
                        kCoopLobbyMainLiftKioskGuid,
                        &kioskEntityId,
                        &kioskGuid,
                        &kioskDistance,
                        &lookupDetail);
                IEntity* kioskEntity =
                    kiosk && kioskEntityId != INVALID_ENTITYID
                    ? gEnv->pEntitySystem->GetEntity(kioskEntityId)
                    : nullptr;
                IScriptTable* kioskTable = kioskEntity
                    ? kioskEntity->GetScriptTable()
                    : nullptr;
                const char* output =
                    ArkKioskPressedOutputFromButton(button);
                m_replayingRemoteMainLiftKioskPress = true;
                const bool eventCallOk =
                    kioskEntity && kioskTable && output &&
                    TryGuardedCall(
                        "deferred main lift kiosk DispatchScriptOutputEvent",
                        [kioskEntity, output]()
                        {
                            return s_funcArkEntityDispatchScriptOutputEvent(
                                kioskEntity, output);
                        },
                        eventResult,
                        &transitDetail);
                const bool activationCallOk = eventCallOk &&
                    TryGuardedCall(
                        "deferred main lift kiosk ActivateScriptOutput",
                        [kioskEntity, kioskTable, output]()
                        {
                            return s_funcArkEntityActivateScriptOutput(
                                kioskEntity, kioskTable, output);
                        },
                        activationResult,
                        &transitDetail);
                m_replayingRemoteMainLiftKioskPress = false;
                applied = eventCallOk && activationCallOk;
            }
            m_applyingRemoteAreaObjectEvent = previousApplying;
            ++m_pendingRemoteMainLiftTransitAttempts;

            if (applied)
            {
                m_pendingRemoteMainLiftTransit = false;
                m_pendingRemoteMainLiftObserverReplay = false;
                m_remoteMainLiftPresentationActive = true;
                m_remoteMainLiftPresentationSettleSeconds = 0.0f;
                m_remoteMainLiftTargetPosition =
                    m_pendingRemoteMainLiftTransitTargetPosition;
                ++m_remoteMainLiftPresentationFrames;
                m_lastRemoteMainLiftPresentationEvent =
                    "started deferred native kiosk transit link=" + pendingLink +
                    " button=" + std::to_string(button) +
                    " event=" + std::to_string(eventResult ? 1 : 0) +
                    " activation=" +
                        std::to_string(activationResult ? 1 : 0) +
                    " target=" +
                    FormatVec3Trace(m_remoteMainLiftTargetPosition);
                if (outageContinuationReplay)
                {
                    m_mainLiftOutageSuppressedForLocalPlayer = false;
                    m_mainLiftOutsideOutageAwaitingNativeContinuation = false;
                    m_lastMainLiftOutageEvent =
                        "started deferred outside-observer native "
                        "Arboretum continuation after outage outcome";
                    LogCoop(m_lastMainLiftOutageEvent);
                }
                LogCoop(m_lastRemoteMainLiftPresentationEvent);
            }
            else if (m_pendingRemoteMainLiftTransitAttempts < 3)
            {
                m_pendingRemoteMainLiftTransitDelayFrames = 2;
                m_lastRemoteMainLiftPresentationEvent =
                    "retry deferred native kiosk transit detail=" +
                    (transitDetail.empty() ? lookupDetail : transitDetail);
            }
            else
            {
                m_pendingRemoteMainLiftTransit = false;
                m_pendingRemoteMainLiftObserverReplay = false;
                m_lastRemoteMainLiftPresentationEvent =
                    "failed deferred native kiosk transit detail=" +
                    (transitDetail.empty() ? lookupDetail : transitDetail);
                LogCoop(m_lastRemoteMainLiftPresentationEvent);
            }
        }
    }

    const Vec3 liftPosition = liftEntity->GetWorldPos();
    Vec3 playerPosition = playerEntity->GetWorldPos();
    if (!IsFiniteVec3Trace(liftPosition) || !IsFiniteVec3Trace(playerPosition))
    {
        resetTracking("main lift passenger invalid transform");
        return;
    }

    if (m_remoteMainLiftPresentationActive)
        ++m_remoteMainLiftPresentationFrames;

    if (m_remoteMainLiftPresentationActive &&
        !m_pendingRemoteMainLiftTransit)
    {
        if ((liftPosition - m_remoteMainLiftTargetPosition).GetLengthSquared() <= 0.01f)
        {
            // TransitComplete and its kiosk/global-fact callbacks run just
            // after the mover reaches its exact target. Keep the observer
            // presentation guard alive through that tail so none of those
            // duplicate outputs can rewind Area Authority.
            m_remoteMainLiftPresentationSettleSeconds +=
                std::max(0.0f, frameTime);
            if (m_remoteMainLiftPresentationSettleSeconds >= 2.0f)
            {
                m_remoteMainLiftPresentationActive = false;
                m_remoteMainLiftPresentationSettleSeconds = 0.0f;
                m_remoteMainLiftVelocity = Vec3(ZERO);
                m_lastRemoteMainLiftPresentationEvent =
                    "completed deferred native transit target=" +
                    FormatVec3Trace(m_remoteMainLiftTargetPosition);
            }
        }
        else
        {
            m_remoteMainLiftPresentationSettleSeconds = 0.0f;
        }
    }

    if (!m_mainLiftHasLastPosition)
    {
        m_mainLiftLastPosition = liftPosition;
        m_mainLiftHasLastPosition = true;
        return;
    }

    const float liftDeltaZ = liftPosition.z - m_mainLiftLastPosition.z;
    const bool liftMoving = std::fabs(liftDeltaZ) > kMovingEpsilon;

    const Vec3 previousLiftPosition(
        liftPosition.x,
        liftPosition.y,
        m_mainLiftLastPosition.z);
    const Vec3 previousRelative = playerPosition - previousLiftPosition;
    const Vec3 currentRelative = playerPosition - liftPosition;
    const bool wasInsideCabin =
        previousRelative.x >= kCabinMinX && previousRelative.x <= kCabinMaxX &&
        previousRelative.y >= kCabinMinY && previousRelative.y <= kCabinMaxY &&
        previousRelative.z >= kCabinMinZ && previousRelative.z <= kCabinMaxZ;

    if (!m_mainLiftPassengerAttached &&
        (liftMoving || m_remoteMainLiftPresentationActive) &&
        wasInsideCabin)
    {
        m_mainLiftPassengerAttached = true;
        m_mainLiftPassengerStationaryFrames = 0;
        // If vanilla mover collision already carried the character this frame,
        // preserve that current offset instead of adding the lift delta again.
        m_mainLiftPassengerRelativeZ = currentRelative.z;
        ++m_mainLiftPassengerAttachments;
        m_lastMainLiftPassengerEvent =
            "attached main lift passenger relativeZ=" +
            std::to_string(m_mainLiftPassengerRelativeZ);
    }

    if (m_mainLiftPassengerAttached)
    {
        if (liftMoving || m_remoteMainLiftPresentationActive)
            m_mainLiftPassengerStationaryFrames = 0;
        else
            ++m_mainLiftPassengerStationaryFrames;

        const bool atAuthoredFloor =
            std::fabs(liftPosition.z - 338.0f) <= 0.35f ||
            std::fabs(liftPosition.z - 478.0f) <= 0.35f ||
            std::fabs(liftPosition.z - 898.0f) <= 0.35f;
        if (m_mainLiftPassengerStationaryFrames >=
                kStationaryReleaseFrames &&
            atAuthoredFloor)
        {
            // Per-frame mover correction can leave the controller's feet a
            // few centimetres inside the final cabin plane (the observed
            // upper-floor offset is about -0.07 m). Keep the attachment through
            // the mover/door graph's two-second settle tail; releasing earlier
            // can put the capsule below a temporarily absent cabin floor and
            // make void recovery bounce it back repeatedly. Place the feet just
            // above the settled floor and clear residual velocity on release.
            const float safeReleaseZ = liftPosition.z + kReleaseFloorClearance;
            if (playerPosition.z < safeReleaseZ)
            {
                playerPosition.z = safeReleaseZ;
                TeleportLocalPlayer(
                    playerPosition,
                    playerEntity->GetWorldRotation());
            }
            ApplyEntityPhysicsVelocity(*playerEntity, Vec3(ZERO));
            m_mainLiftPassengerAttached = false;
            m_mainLiftPassengerRelativeZ = 0.0f;
            m_mainLiftPassengerStationaryFrames = 0;
            ++m_mainLiftPassengerReleases;
            m_lastMainLiftPassengerEvent = "released main lift passenger at stop";
        }

        const bool horizontallyInside =
            currentRelative.x >= kCabinMinX && currentRelative.x <= kCabinMaxX &&
            currentRelative.y >= kCabinMinY && currentRelative.y <= kCabinMaxY;
        if (m_mainLiftPassengerAttached && !horizontallyInside)
        {
            m_mainLiftPassengerAttached = false;
            m_mainLiftPassengerRelativeZ = 0.0f;
            m_mainLiftPassengerStationaryFrames = 0;
            ++m_mainLiftPassengerReleases;
            m_lastMainLiftPassengerEvent = "released main lift passenger outside cabin";
        }
        else if (m_mainLiftPassengerAttached)
        {
            const float targetZ = liftPosition.z + m_mainLiftPassengerRelativeZ;
            // The observer is running the real local mover, so its character
            // controller normally rides the floor by itself. Only recover a
            // genuine separation there; per-frame centimetre teleports feed
            // the contact back into CryPhysics and inflate the cabin bounds.
            const bool nativeObserverRide =
                m_networkMode == CoopNetworkMode::Client &&
                !IsClientAreaAuthorityActive() &&
                m_remoteMainLiftPresentationActive;
            const float correctionEpsilon = nativeObserverRide
                ? kNativeObserverCorrectionEpsilon
                : kCorrectionEpsilon;
            if (std::fabs(playerPosition.z - targetZ) > correctionEpsilon)
            {
                playerPosition.z = targetZ;
                if (TeleportLocalPlayer(playerPosition, playerEntity->GetWorldRotation()))
                {
                    ++m_mainLiftPassengerCorrections;
                    m_lastMainLiftPassengerEvent =
                        "carried main lift passenger z=" + std::to_string(targetZ);
                }
            }
        }
    }

    m_mainLiftLastPosition = liftPosition;
}

void ModMain::OnLocalAreaObjectOperatorDispenserStateChanged(ArkOperatorDispenser* dispenser, uint16_t eventKind, uint16_t value, bool changed, const char* reason)
{
    if (!changed || !dispenser)
        return;

    if ((m_applyingRemoteAreaObjectEvent || m_remoteAreaObjectEchoSuppressSeconds > 0.0f) &&
        m_localAreaObjectCommandMutationDepth == 0)
    {
        ++m_reentrantAreaObjectEventSkips;
        m_lastAreaObjectEvent =
            "area_object_skip_remote_echo_kind_" + std::to_string(eventKind) +
            "_window_" + std::to_string(m_remoteAreaObjectEchoSuppressSeconds) +
            "_reason_" + StatusToken(reason && reason[0] ? std::string(reason) : std::string("-"));
        return;
    }

    if (eventKind != CoopProtocol::kAreaObjectEventOperatorDispenserLocked &&
        eventKind != CoopProtocol::kAreaObjectEventOperatorDispenserState)
    {
        m_lastAreaObjectEvent =
            "area_object_skip_unknown_operator_dispenser_kind_" + std::to_string(eventKind);
        return;
    }

    std::string detail;
    const uint64_t stableId = GetArkOperatorDispenserStableIdForCoop(dispenser, &detail);
    if (stableId == 0)
    {
        m_lastAreaObjectEvent =
            "area_object_operator_dispenser_missing_stable_id_kind_" + std::to_string(eventKind) +
            "_detail_" + StatusToken(detail.empty() ? std::string("-") : detail);
        return;
    }

    QueueLocalAreaObjectEventForHook(eventKind, stableId, value, 0, reason);
}

static uint64_t BuildOperatorDispenserStableSpawnId(uint64_t dispenserGuid, uint64_t archetypeId, uint32_t slotIndex)
{
    if (dispenserGuid == 0)
        return 0;

    uint64_t hash = 14695981039346656037ull;
    auto mix64 = [&hash](uint64_t value)
    {
        for (int index = 0; index < 8; ++index)
        {
            hash ^= (value >> (index * 8)) & 0xffu;
            hash *= 1099511628211ull;
        }
    };
    mix64(0x4f50444953504e57ull); // "OPDISPNW"
    mix64(dispenserGuid);
    mix64(archetypeId);
    mix64(slotIndex);
    return hash == 0 ? 1 : hash;
}

void ModMain::RegisterOperatorDispenserAssignedOperatorForHook(
    ArkOperatorDispenser* dispenser,
    EntityId operatorId,
    int slotIndex,
    const char* reason)
{
    if (!dispenser || operatorId == INVALID_ENTITYID || slotIndex < 0 || !gEnv || !gEnv->pEntitySystem)
        return;

    std::string stableDetail;
    const uint64_t dispenserGuid = GetArkOperatorDispenserStableIdForCoop(dispenser, &stableDetail);
    if (dispenserGuid == 0)
        return;

    IEntity* operatorEntity = nullptr;
    std::string guardReason;
    if (!TryGuardedCall(
            "operator dispenser stable spawn GetEntity",
            [operatorId]() { return gEnv->pEntitySystem->GetEntity(operatorId); },
            operatorEntity,
            &guardReason) ||
        !operatorEntity)
    {
        return;
    }

    uint64_t archetypeId = 0;
    const IEntityArchetype* archetype = nullptr;
    if (TryGuardedCall(
            "operator dispenser stable spawn GetArchetype",
            [operatorEntity]() { return operatorEntity->GetArchetype(); },
            archetype,
            &guardReason) &&
        archetype)
    {
        TryGuardedCall(
            "operator dispenser stable spawn archetype GetId",
            [archetype]() { return archetype->GetId(); },
            archetypeId,
            &guardReason);
    }

    const uint64_t stableSpawnId = BuildOperatorDispenserStableSpawnId(
        dispenserGuid,
        archetypeId,
        static_cast<uint32_t>(slotIndex));
    if (stableSpawnId == 0)
        return;

    m_enemyStableSpawnIdsByEntity[operatorId] = stableSpawnId;
    if (const auto netIt = m_enemyNetIdsByEntity.find(operatorId); netIt != m_enemyNetIdsByEntity.end())
    {
        if (auto authorityIt = m_enemyAuthorities.find(netIt->second); authorityIt != m_enemyAuthorities.end())
            authorityIt->second.entityGuid = stableSpawnId;
    }

    m_lastAreaObjectEvent =
        "operator_dispenser_linked_spawn_guid_" + std::to_string(dispenserGuid) +
        "_slot_" + std::to_string(slotIndex) +
        "_operator_" + std::to_string(operatorId) +
        "_arch_" + std::to_string(archetypeId) +
        "_stable_" + std::to_string(stableSpawnId) +
        "_reason_" + StatusToken(reason && reason[0] ? std::string(reason) : std::string("-"));
}

uint32_t ModMain::RefreshOperatorDispenserStableSpawnIdsForHook(ArkOperatorDispenser* dispenser, const char* reason)
{
    if (!dispenser)
        return 0;

    size_t count = 0;
    if (!TryGuardedCall(
            "operator dispenser stable spawn vector size",
            [dispenser]() { return dispenser->m_spawnedOperators.size(); },
            count,
            nullptr))
    {
        return 0;
    }

    uint32_t linked = 0;
    for (size_t index = 0; index < count; ++index)
    {
        EntityId operatorId = INVALID_ENTITYID;
        if (!TryGuardedCall(
                "operator dispenser stable spawn vector entry",
                [dispenser, index]() { return dispenser->m_spawnedOperators[index].m_operatorId; },
                operatorId,
                nullptr) ||
            operatorId == INVALID_ENTITYID)
        {
            continue;
        }

        RegisterOperatorDispenserAssignedOperatorForHook(
            dispenser,
            operatorId,
            static_cast<int>(index),
            reason);
        if (m_enemyStableSpawnIdsByEntity.find(operatorId) != m_enemyStableSpawnIdsByEntity.end())
            ++linked;
    }
    return linked;
}

uint64_t ModMain::ResolveOperatorDispenserStableSpawnIdForEnemy(EntityId operatorId, const char* reason)
{
    if (operatorId == INVALID_ENTITYID || !gEnv || !gEnv->pEntitySystem)
        return 0;

    if (const auto existing = m_enemyStableSpawnIdsByEntity.find(operatorId); existing != m_enemyStableSpawnIdsByEntity.end())
        return existing->second;

    IEntityItPtr iterator = gEnv->pEntitySystem->GetEntityIterator();
    if (!iterator)
        return 0;

    iterator->MoveFirst();
    while (!iterator->IsEnd())
    {
        IEntity* entity = iterator->Next();
        ArkOperatorDispenser* dispenser = GetArkOperatorDispenserExtensionFromEntity(entity);
        if (!dispenser)
            continue;

        size_t count = 0;
        if (!TryGuardedCall(
                "operator dispenser stable resolve vector size",
                [dispenser]() { return dispenser->m_spawnedOperators.size(); },
                count,
                nullptr))
        {
            continue;
        }

        for (size_t index = 0; index < count; ++index)
        {
            EntityId candidateId = INVALID_ENTITYID;
            if (!TryGuardedCall(
                    "operator dispenser stable resolve vector entry",
                    [dispenser, index]() { return dispenser->m_spawnedOperators[index].m_operatorId; },
                    candidateId,
                    nullptr) ||
                candidateId != operatorId)
            {
                continue;
            }

            RegisterOperatorDispenserAssignedOperatorForHook(
                dispenser,
                operatorId,
                static_cast<int>(index),
                reason);
            const auto linked = m_enemyStableSpawnIdsByEntity.find(operatorId);
            return linked != m_enemyStableSpawnIdsByEntity.end() ? linked->second : 0;
        }
    }
    return 0;
}

void ModMain::OnLocalAreaObjectKeypadStateChanged(ArkKeypad* keypad, uint16_t eventKind, bool value, bool changed, const char* reason)
{
    if (!changed || !keypad)
        return;

    if ((m_applyingRemoteAreaObjectEvent || m_remoteAreaObjectEchoSuppressSeconds > 0.0f) &&
        m_localAreaObjectCommandMutationDepth == 0)
    {
        ++m_reentrantAreaObjectEventSkips;
        m_lastAreaObjectEvent =
            "area_object_skip_remote_echo_kind_" + std::to_string(eventKind) +
            "_window_" + std::to_string(m_remoteAreaObjectEchoSuppressSeconds) +
            "_reason_" + StatusToken(reason && reason[0] ? std::string(reason) : std::string("-"));
        return;
    }

    if (eventKind != CoopProtocol::kAreaObjectEventKeypadLocked)
    {
        m_lastAreaObjectEvent =
            "area_object_skip_unknown_keypad_kind_" + std::to_string(eventKind);
        return;
    }

    IEntity* entity = nullptr;
    std::string guardReason;
    if (!TryGuardedCall("area object keypad GetEntity", [keypad]() { return keypad->GetEntity(); }, entity, &guardReason) ||
        !entity)
    {
        m_lastAreaObjectEvent =
            "area_object_keypad_missing_entity_kind_" + std::to_string(eventKind) +
            "_reason_" + StatusToken(guardReason.empty() ? std::string("-") : guardReason);
        return;
    }

    uint64_t guid = 0;
    TryGuardedCall("area object keypad IEntity::GetGuid", [entity]() { return entity->GetGuid(); }, guid, &guardReason);
    uint64_t keycode = 0;
    if (guid == 0)
        TryGuardedCall("area object keypad keycode", [keypad]() { return keypad->m_keycode; }, keycode, &guardReason);

    const uint64_t stableId = guid != 0 ? guid : keycode;
    if (stableId == 0)
    {
        m_lastAreaObjectEvent =
            "area_object_keypad_missing_stable_id_kind_" + std::to_string(eventKind) +
            "_reason_" + StatusToken(guardReason.empty() ? std::string("-") : guardReason);
        return;
    }

    QueueLocalAreaObjectEventForHook(eventKind, stableId, value ? 1u : 0u, 0, reason);
}

