void ModMain::OnLocalAreaObjectContainerStateChanged(ArkInventory* inventory, bool open, const char* reason)
{
    if (!inventory)
        return;
    if ((m_applyingRemoteAreaObjectEvent || m_remoteAreaObjectEchoSuppressSeconds > 0.0f) &&
        m_localAreaObjectCommandMutationDepth == 0)
    {
        ++m_reentrantAreaObjectEventSkips;
        return;
    }

    unsigned ownerId = INVALID_ENTITYID;
    std::string guardReason;
    if (!TryGuardedCall("area container GetOwnerId", [inventory]() { return inventory->GetOwnerId(); }, ownerId, &guardReason) ||
        ownerId == INVALID_ENTITYID || !gEnv || !gEnv->pEntitySystem)
    {
        return;
    }
    if (ArkPlayer::GetInstancePtr() && ownerId == ArkPlayer::GetInstance().GetEntityId())
        return;

    IEntity* owner = nullptr;
    uint64_t guid = 0;
    if (!TryGuardedCall("area container GetEntity", [ownerId]() { return gEnv->pEntitySystem->GetEntity(ownerId); }, owner, &guardReason) || !owner ||
        !TryGuardedCall("area container GetGuid", [owner]() { return owner->GetGuid(); }, guid, &guardReason) || guid == 0)
    {
        m_lastAreaObjectEvent = "area_container_missing_stable_guid_owner_" + std::to_string(ownerId);
        return;
    }

    QueueLocalAreaObjectEventForHook(
        CoopProtocol::kAreaObjectEventContainerOpen,
        guid,
        open ? 1u : 0u,
        0,
        reason);
}

