        TryReadArkKeypadLocked(keypad, after, &afterState, "area object apply keypad read after", &reason);
        detail = callOk && after == desired
            ? ("applied_keypad_locked_" + std::to_string(desired ? 1 : 0) +
                "_state_" + std::to_string(afterState) +
                "_result_" + std::to_string(result ? 1 : 0) +
                "_id_" + std::to_string(keypadEntityId) +
                "_guid_" + std::to_string(keypadGuid) +
                "_keycode_" + std::to_string(keypadKeycode) +
                "_dist_" + std::to_string(keypadDistance))
            : ("failed_keypad_locked_after_" + std::to_string(after ? 1 : 0) +
                "_state_" + std::to_string(afterState) +
                "_result_" + std::to_string(result ? 1 : 0) +
                "_detail_" + StatusToken(lookupDetail.empty() ? std::string("-") : lookupDetail) +
                "_reason_" + StatusToken(reason.empty() ? std::string("-") : reason));
